import type { MeaningPack } from '../../types';

export const mlLib10: MeaningPack = {
  lang: 'ml',
  texts: {
    "sumadhva-vijaya-07": {
      "verses": {
        "0.0": "അപ്പോൾ, ഹിമാലയത്തിന്റെ മറ്റൊരു ചരിവിൽ, സർവ്വജ്ഞനായവൻ ബദരീവൃക്ഷങ്ങളാൽ അലങ്കൃതമായ, ശ്രീയുടെ വാസസ്ഥലമായ, പ്രസിദ്ധമായ പരമോന്നത ആശ്രമം കണ്ടു.",
        "0.1": "അവിടെ അദ്ഭുതകരമായ വൃക്ഷങ്ങളും ബ്രാഹ്മണരും ഒരുപോലെ തിളങ്ങി: മഞ്ഞും മഴയും സൂര്യതാപവും സഹിക്കുന്നവർ, വിപുലമായ തണലിന് (അഥവാ: മഹായജ്ഞങ്ങൾക്ക്) പ്രസിദ്ധർ, പക്ഷികൾക്ക് (അഥവാ: ദ്വിജന്മാർക്ക്) അഭയം നൽകുന്നവർ, ആകാശത്തെ തൊടുന്നവർ (അഥവാ: വിഷ്ണുവിന്റെ പാദങ്ങളെ തൊടുന്നവർ).",
        "0.2": "തത്തകൾ നയിക്കുന്ന മനോഹരമായ പക്ഷികളാൽ അത് നിറഞ്ഞിരുന്നു; അവയുടെ പാട്ട് കാതിന് അമൃത് പോലെയായിരുന്നു (അഥവാ: ശുകനെപ്പോലുള്ള ഋഷിമാരോടുകൂടി). നിർമ്മലമായ വെണ്മയുള്ള ഉത്തമ അരയന്നങ്ങളും അവിടെയുണ്ടായിരുന്നു; ഉറച്ച മനസ്സുള്ള അവ കമലയ്ക്ക് (ലക്ഷ്മിക്ക്) പ്രിയമായിരുന്നു (അഥവാ: ലക്ഷ്മിക്ക് പ്രിയരായ പരമഹംസ സന്യാസിമാർ).",
        "0.3": "പൂക്കളുടെ കൂട്ടങ്ങൾ നിറഞ്ഞതും (അഥവാ: നല്ല മനസ്സുള്ളവരാൽ നിറഞ്ഞതും), ഹൃദയാഭിലാഷം സാധിപ്പിക്കുന്നതും, ചെറിയവർക്ക് എത്താൻ പ്രയാസമുള്ളതും, ജീവികൾ പരസ്പരം ശത്രുത പുലർത്താത്തതുമായ ആ സ്ഥലം ശരിക്കും അച്യുതന്റെ വാസസ്ഥലമായ വൈകുണ്ഠംപോലെയായിരുന്നു.",
        "0.4": "ആശ്രമത്തിൽ പ്രവേശിക്കുന്ന, മുപ്പത്തിരണ്ട് ഉത്തമലക്ഷണങ്ങൾ വഹിക്കുന്ന അദ്ദേഹത്തെ കണ്ട്, ഗുണങ്ങളുടെ സാരം അറിയുന്ന ഋഷിമാർ ഇങ്ങനെ അദ്ഭുതപ്പെട്ടു:",
        "0.5": "“സമാനതയില്ലാത്ത സ്വർണ്ണ ഈന്തപ്പനപോലെ, താമരക്കണ്ണുള്ള, നിർമ്മലമായ ചന്ദ്രസമാനമായ മുഖമുള്ള, രാജകീയ ആനയുടെ നടത്തമുള്ള, ശക്തമായ കൈകളുള്ള ഈ അസാധാരണ പുരുഷൻ ആരാണ്, അടുത്തുവരുന്നത്?”",
        "0.6": "“ചന്ദ്രൻ സൗമ്യനാണ്, പക്ഷേ അത്ര തെളിച്ചമില്ല; സൂര്യൻ തെളിച്ചമുള്ളവനാണ്, പക്ഷേ പൂർണ്ണമായും ഉഗ്രനാണ്; അതിനാൽ ഗുണങ്ങളുടെ ഈ സമുദ്രത്തിന് ലോകങ്ങളിൽ സദൃശ്യം കണ്ടെത്താനാവില്ല.”",
        "0.7": "“ഉറച്ച മനസ്സുള്ള, ക്ഷീണമില്ലാത്ത ഈ മഹാത്മാവ് പരമഹംസ സന്യാസിമാരുടെ ലക്ഷണങ്ങൾ വഹിക്കുന്നു; മനുഷ്യരൂപത്തിലാണെങ്കിലും അദ്ദേഹം ഞങ്ങളിൽ വലിയ വിസ്മയം നിറയ്ക്കുന്നു.”",
        "0.8": "“തീർച്ചയായും ഇത് ജ്ഞാനിയായ നാലുമുഖനായ ബ്രഹ്മാവ് തന്നെയോ, അല്ലെങ്കിൽ വേദങ്ങളുടെ നാഥനെ കാണാൻ ആഗ്രഹിച്ച് സന്യാസിവേഷത്തിൽ വന്ന വായുവോ ആണ്; അല്ലെങ്കിൽ ഇത്രയും ഉത്തമ ലക്ഷണങ്ങൾ ഇയാൾക്ക് വഹിക്കാനാവില്ലല്ലോ.”",
        "0.9": "കൗതുകമുള്ള ഋഷിമാർ അദ്ദേഹത്തിന്റെ ലക്ഷണങ്ങൾ കണ്ട് ഇങ്ങനെ ചിന്തിക്കുമ്പോൾ, താമസമില്ലാതെ നടന്നുനീങ്ങിയ അദ്ദേഹം അടുത്തൊരു വൃക്ഷം കണ്ടു — സ്വർഗ്ഗീയ വൃക്ഷങ്ങളിൽ ഏറ്റവും ഉത്തമമായത്.",
        "0.10": "മിനുസമുള്ള തൊലിയും ഉയരവും വിസ്തൃതിയുമുള്ളതും, ഫണങ്ങൾപോലെ അനേകം ശാഖകളും, രത്നങ്ങൾപോലെ പൂക്കളുമുള്ളതുമായ ആ വൃക്ഷം, ഭഗവാനെ സേവിക്കാൻ അടുത്തുനിൽക്കുന്ന അനന്തൻ (ശേഷൻ) തന്നെപ്പോലെയായിരുന്നു.",
        "0.11": "അദ്ഭുതകരമായ വൈവിധ്യവും അനേകം നിറങ്ങളുമുള്ള ഇലകളോടുകൂടി (അഥവാ: തൂവലുകളോടുകൂടി), സൂര്യരശ്മികളിൽ നിന്ന് തണൽ നൽകി (അഥവാ: സർപ്പങ്ങളെ അകറ്റി), ഋഷിമാർക്ക് സന്തോഷം നൽകി, ഇന്ദിരയുടെ നാഥന് ഏറ്റവും പ്രിയമായ ആ വൃക്ഷം പക്ഷികളുടെ രാജാവായ ഗരുഡനെപ്പോലെയായിരുന്നു.",
        "0.12": "ഹരിയിൽ ഭക്തിയില്ലാത്തവർക്ക് നേടാൻ പ്രയാസമുള്ള അമരത്വമെന്ന മഹാഫലം നൽകുന്നതും, നല്ല പുരാണങ്ങളെയും ഭാരതത്തെയും (അഥവാ: പഴയ പക്ഷികളെയും) സംരക്ഷിക്കുന്നതും, അനേകം ശാഖകളുള്ളതുമായ ആ വൃക്ഷം ശരീരധാരിയായ വേദംപോലെയായിരുന്നു.",
        "0.13": "അതിന്റെ തട്ടിൽ, വളരെ വിശാലവും നിർമ്മലവും മനോഹരവുമായ അവിടെ, അനന്തബുദ്ധിയുള്ളവൻ സ്വർഗ്ഗത്തിലെ ദേവന്മാരെപ്പോലെ ഉത്തമരായ തപസ്വികളെ കണ്ടു.",
        "0.14": "ചിലർ ഏഴ് പേരുടെ സംഘങ്ങളായി തിളങ്ങുന്നവർ, എണ്ണമറ്റവർ, ഗുണസമ്പന്നർ, എന്നാൽ മൂന്ന് ഗുണങ്ങൾക്കും അപ്പുറമുള്ളവർ, കോപവും അഹങ്കാരവും മറ്റുള്ളവയുമില്ലാത്തവർ, ഭോഗങ്ങളില്ലാത്തവർ, എന്നും വായു മാത്രം ഭക്ഷിച്ചു ജീവിക്കുന്നവർ.",
        "0.15": "അവിടെ ഋഷിമണ്ഡലത്തിന് നടുവിൽ, മൂന്നു ലോകങ്ങളുടെ മുഴുവൻ ആഭരണമായ പൂർണ്ണപ്രജ്ഞൻ, സത്യവതിയുടെ പുത്രനായി വന്ന ഹരിയെ — വ്യാസനെ — കണ്ടു.",
        "0.16": "തന്റെ ഹൃദയത്താമരയിൽ എപ്പോഴും അദ്ദേഹത്തെ വ്യക്തമായി കണ്ടിരുന്നെങ്കിലും, ഇപ്പോൾ വീണ്ടും വീണ്ടും, എന്നും പുതുമയോടെ കണ്ടപ്പോൾ അദ്ദേഹം അദ്ഭുതത്തോടെ ചിന്തിച്ചു:",
        "0.17": "“ഇത് തീർച്ചയായും എണ്ണമറ്റ ഗുണങ്ങളുടെ നിർമ്മല സമുദ്രമായ നാരായണൻ തന്നെയാണ്; വിധിപ്രകാരം സത്യവതി ഇവിടെ പരാശരനിൽ പ്രസവിച്ചത് ഇദ്ദേഹത്തെയാണ്.”",
        "0.18": "“സജ്ജനങ്ങളോടുള്ള മഹത്തായ കാരുണ്യമെന്ന മഹാപർവതംകൊണ്ട് കടഞ്ഞ, അവിടുത്തെ മനസ്സെന്ന വെൺപാൽക്കടലിൽ നിന്ന്, അസുരശത്രുവിന്റെ (വിഷ്ണുവിന്റെ) പ്രിയയായ ലക്ഷ്മിയെപ്പോലെ മനോഹരമായ ത്രിവേദം ഉദിച്ചു.”",
        "0.19": "“അതേ സമുദ്രത്തിൽ നിന്നാണ് വെളുത്ത കാമധേനുപോലെ പുരാണങ്ങളും, പാരിജാതവൃക്ഷംപോലെ മഹാഭാരതവും ഉണ്ടായത്; പിന്നീട് സ്വയം ഉദിച്ചു പരമോത്കൃഷ്ട അമൃതായി ബ്രഹ്മസൂത്രങ്ങളും.”",
        "0.20": "“പാണ്ഡവപുത്രന്മാരെപ്പോലെയുള്ള സജ്ജനങ്ങൾക്ക് തടസ്സമില്ലാത്ത, സമൃദ്ധമായ കൃപ നൽകി, മനോഹരമായ വാക്കുള്ള ഇദ്ദേഹം യഥാർത്ഥ ജ്ഞാനം സംരക്ഷിക്കാൻ ദീർഘകാലം ഭൂമിയിൽ സഞ്ചരിച്ചു.”",
        "0.21": "“ഇനി കലിയുഗം അതിന്റെ വഴിക്ക് നടക്കാൻ അനുവദിക്കാൻ — സൂര്യൻ പിൻവാങ്ങി രാത്രി വരാൻ അനുവദിക്കുന്നതുപോലെ — ഭഗവാൻ ഈ ആശ്രമത്തിൽ വസിക്കുന്നു; ജനങ്ങളുടെ കണ്ണുകൾക്ക് അദ്ദേഹം ദൃശ്യനല്ലാതായിരിക്കുന്നു.”",
        "0.22": "“ഇവിടെ കാണാനുള്ള അവിടുത്തെ ശരീരം ഇതാ — വിരിഞ്ഞ നീലത്താമരപോലെ തിളക്കമുള്ളത്, പരമമായ യോഗാസനമായ മാൻതോൽ പീഠത്തിലിരിക്കുന്നത് — എന്റെ ഹൃദയത്തെയും കണ്ണുകളെയും സന്തോഷിപ്പിക്കുന്നു.”",
        "0.23": "“എണ്ണമറ്റ ഗുണങ്ങൾ നിറഞ്ഞത് — അവിടുത്തേതായ പൂർണ്ണവും അനന്തവുമായ മഹിമകൾ; എല്ലാ കുറവുകളിൽ നിന്നും മുക്തം; ശുദ്ധമായ സത്ത, ചിത്ത്, ആനന്ദം കൊണ്ടുമാത്രം നിർമ്മിതം.”",
        "0.24": "“അവിടുത്തെ താമരപ്പാദങ്ങളിലെ ധൂളി കമല (ലക്ഷ്മി), താമരയിൽ ജനിച്ച ബ്രഹ്മാവ്, വായു, ഗരുഡൻ, ശേഷൻ, ശിവൻ, ഇന്ദ്രൻ തുടങ്ങിയവർ തലയിൽ വഹിക്കുന്നു — ആഹാ, ഞാനും അത് വീണ്ടും വീണ്ടും വഹിക്കുന്നു!”",
        "0.25": "“കൊടി, വജ്രം, അങ്കുശം, താമര എന്നിവയാൽ അടയാളപ്പെട്ട ഭഗവാന്റെ രണ്ടു പാദങ്ങളെ ഞാൻ വണങ്ങുന്നു — സ്വഭാവത്താൽ ചുവന്നത്; ഭക്തരുടെ ഹൃദയത്തിലെ സ്നേഹത്തിൽ അമർത്തുന്നതിനാൽ ചുവന്നതുപോലെ തോന്നുന്നത്.”",
        "0.26": "“വിഷ്ണുവിന്റെ പാദത്തിൽ മാത്രം വിശ്രമിക്കുന്ന (സൂര്യൻ ആകാശത്ത് വിശ്രമിക്കുന്നതുപോലെ, വിഷ്ണുവിന്റെ ചുവടുപോലെ) അവിടുത്തെ കാൽനഖങ്ങൾ, സ്വന്തം പ്രഭകൊണ്ട് ബാഹ്യവും ആന്തരവുമായ രണ്ട് ഇരുട്ടുകളെയും നീക്കി, പുതുതായി ഉദിച്ച സൂര്യനെപ്പോലും തോൽപ്പിക്കുന്നു.”",
        "0.27": "“മൃദുവായ അടിഭാഗവും വിരലുകളും ഒളിഞ്ഞിരിക്കുന്ന കണങ്കാലുകളുമുള്ള അവിടുത്തെ പാദങ്ങൾക്ക്, മികച്ച കവികൾക്കുപോലും പരസ്പരമല്ലാതെ മറ്റൊരു സാദൃശ്യം കണ്ടെത്താനാവില്ല.”",
        "0.28": "“ഉചിതമായ തൂക്കമുള്ള (അഥവാ: മൂല്യമുള്ള), ക്രമേണ ചുരുങ്ങുന്ന, നിർമ്മലമായ, തിളങ്ങുന്ന, നല്ല വൃത്താകൃതിയുള്ള (അഥവാ: നല്ല നടപ്പുള്ള) അവിടുത്തെ രണ്ടു കാൽവണ്ണകൾ, ഇവിടെ അവയെ ആരാധിക്കുന്നവർക്ക് അവിടുത്തേതുപോലെയുള്ള രൂപം നൽകുന്നു.”",
        "0.29": "“ചലിക്കാത്ത അവിടുത്തെ ആസനത്തെ ബന്ധിക്കുന്ന യോഗബന്ധവും, ഒരിക്കൽ നേടിയാൽ എല്ലാ ആഗ്രഹങ്ങളും നൽകുന്ന മനോഹരമായ അരഞ്ഞാണവും ഹരിയെ ചുറ്റും ഇടവിടാതെ ആലിംഗനം ചെയ്യുന്നു; തീർച്ചയായും ഇത് ഏറ്റവും ഭാഗ്യമുള്ളതാണെന്ന് ഞാൻ കരുതുന്നു.”",
        "0.30": "“മനോഹരവും ഉത്തമവുമായ മാൻതോൽ, അതിന്റെ മനോഹരമായ തിളക്കത്തോടെ, വിശാലവും ഉന്നതവുമായ അരക്കെട്ടിൽ പറ്റിപ്പിടിച്ച്, അദ്ഭുതകരമായി പ്രകാശിക്കുന്നു.”",
        "0.31": "“മനോഹരവും ആഴമുള്ള പൊക്കിളോടുകൂടിയതും, മൃദുവായ മടക്കുകളുള്ളതും, മൃദുവും സുന്ദരവുമായ ഈ ഉദരത്തിൽ, താമരപ്പൊക്കിളുള്ള ഭഗവാൻ മുഴുവൻ ബ്രഹ്മാണ്ഡ അണ്ഡത്തെയും വഹിക്കുന്നു.”",
        "0.32": "“സജ്ജനങ്ങളുടെ ക്ഷേമം ഉദ്ഭവിക്കുന്ന അവിടുത്തെ വിശാലമായ മാറിൽ, ഋഷിവംശത്തിന്റെ ചൂഡാമണിയായവൻ രണ്ടു വസ്തുക്കൾ ധരിക്കുന്നു: മൂന്നു വേദങ്ങളാൽ നിർമ്മിതമായ നിർമ്മല ത്രിവിധ യജ്ഞോപവീതവും, പരമമായ ബ്രഹ്മസൂത്രവും (ഈ വാക്കിന്റെ രണ്ട് അർത്ഥങ്ങളും).”",
        "0.33": "“അതുല്യനും അപരാജിതനുമായ തന്റെ പിതാവായ ഭഗവാന് ബ്രഹ്മാവ് ഈ ആഭരണം സമർപ്പിച്ചു — അവിടുത്തെ കഴുത്തിൽ പറ്റിച്ചേർന്ന ഇത് സൂര്യന്മാരുടെ കൂട്ടംപോലെ പ്രകാശിക്കുന്നു, മൂന്നു ലോകങ്ങളുടെ മേലുള്ള വിജയക്കൊടിയാണ്.”",
        "0.34": "“മൃദുവും ചുവപ്പും ഉള്ള അവിടുത്തെ രണ്ടു താമരക്കൈകൾക്കും, ചക്രവും താമരയും അടയാളപ്പെട്ടവയ്ക്കും, വിശാലവും പുഷ്ടവും വൃത്താകൃതിയുള്ളതുമായ ബാഹുക്കൾക്കും സാദൃശ്യമൊന്നും കണ്ടെത്താനാവില്ല.”",
        "0.35": "“അവിടുത്തെ ഒരു കൈ ഉപദേശമുദ്രയിൽ പിടിച്ച്, ഭക്തരുടെ അജ്ഞാനത്തെ മുറിച്ചുകളയുന്നു; മറ്റേ കൈ മുട്ടിന്മേൽ വച്ചിരിക്കുന്നു, അത് എല്ലാ വലിയ ഭയങ്ങളെയും തകർത്തതിനാൽ പരമമംഗളമാണ്.”",
        "0.36": "“ഗുരുവിന്റെ കഴുത്തിൽ, മൂന്നു വേദങ്ങൾ സ്വയമേവ അതിൽ നിന്ന് ഒഴുകുന്നതുപോലെ അടയാളപ്പെട്ട, ശംഖിനോട് മത്സരിക്കുന്ന മൂന്നു നേർത്ത രേഖകൾ കാണാം.”",
        "0.37": "“ദേവന്മാരുടെ ചൂഡാമണിയായ ഈ മുഖം, സ്വന്തം സൗന്ദര്യത്താൽ, കറയും നിഴലും പൂർണ്ണമായി നീങ്ങിയ അനേകം ചന്ദ്രന്മാരുടെ ഭംഗിയെ മറികടക്കുന്നു.”",
        "0.38": "“അവിടുന്ന് പുഞ്ചിരിക്കുമ്പോൾ, ചുവന്ന ചുണ്ടുകളുടെ തിളക്കത്തിൽ അടുക്കിയ വെളുത്ത പല്ലുകളുടെ നിര — പരമസൗന്ദര്യം — ചുവന്ന രത്നങ്ങൾക്കിടയിൽ തിളങ്ങുന്ന പുതിയ മുത്തുമാലയെ ലജ്ജിപ്പിക്കും.”",
        "0.39": "“ആഹാ, വേദങ്ങളുടെ നാഥന്റെ ഈ വാക്ക്, ബ്രാഹ്മണസദസ്സുകൾ കൗതുകത്തോടെ ചോദിച്ച ആയിരം ഉത്തമ ചോദ്യങ്ങൾക്ക് ഒരൊറ്റ വാക്കിൽ ഉത്തരം നൽകുന്നു!”",
        "0.40": "“ലോകത്തെ സന്തോഷിപ്പിക്കുന്ന ചിരിയോടുകൂടിയ, നീണ്ട താമരക്കണ്ണുള്ളവന്റെ നോട്ടം എന്നിലേക്ക് വരുന്നു, എന്നെ തലോടുന്നു, ആലിംഗനം ചെയ്യുന്നു, എന്നെ പൂർണ്ണനാക്കുന്നു.”",
        "0.41": "“അടുത്ത്, ചെവിക്കരികിൽ സ്നേഹപൂർവ്വം വച്ചിരിക്കുന്ന തുളസി തിളങ്ങി മന്ത്രിക്കുന്നതുപോലെ തോന്നുന്നു: ‘താമരയും മറ്റു പൂക്കളും എന്റെ നാഥന്റെ അരികിലുള്ള എന്റെ സ്ഥാനം അസൂയയോടെ കവർന്നെടുക്കരുതേ.’”",
        "0.42": "“ലോകങ്ങളുടെ പോഷണവും സംഹാരവും ഉത്ഭവവും മറ്റെല്ലാം — ശിവന്റെയും താമരയിൽ ജനിച്ച ബ്രഹ്മാവിന്റെയും പോലും — ലോകനാഥന്റെ ഈ പുരികങ്ങളുടെ ചെറിയ ചലനത്തിൽ നിന്നാണ്.”",
        "0.43": "“മൂന്നു ലോകങ്ങളുടെ ആഭരണമായവന്റെ നെറ്റിയിലെ അടയാളം, നീലരത്നമലയുടെ മുകളിൽ ചുവന്ന തിളങ്ങുന്ന രത്നങ്ങളുടെ നിരപോലെ അസാധാരണമായ സൗന്ദര്യം നേടിയിരിക്കുന്നു.”",
        "0.44": "“ലോകഗുരുവിന്റെ ശരീരം, നേർത്ത മിന്നലുകൾ ചുറ്റിയ പുതിയ മഴമേഘംപോലെ, ജടകളുടെ വലയം കൊണ്ട് അലങ്കരിച്ചിരിക്കുന്നത് കണ്ട് ഞാൻ പൂർത്തീകരണം നേടിയിരിക്കുന്നു.”",
        "0.45": "“ഇടവിടാതെ എണ്ണുന്ന രാമനുപോലും, പാദനഖങ്ങളുടെ ധൂളിയിൽ തിളങ്ങുന്ന അനന്തമായ നല്ല ഗുണങ്ങളെ എണ്ണിത്തീർക്കാനാവില്ല; അവിടുത്തെ പരമമായ ഗുണങ്ങൾ മറ്റാർക്കാണ് പറയാനാവുക?”",
        "0.46": "“ഒമ്പത് ആവരണങ്ങളുള്ള ബ്രഹ്മാണ്ഡ അണ്ഡത്തെ വെറുമൊരു വീടായി കണ്ട്, അദ്ഭുതം തോന്നാതിരുന്ന ഞാൻ, ഇപ്പോൾ — അതിൽ അദ്ഭുതമില്ല — എന്റെ യഥാർത്ഥ ഗുരുവിന്റെ ഈ രൂപം കണ്ട് അദ്ഭുതപ്പെടുന്നു.”",
        "0.47": "മഹാമനസ്കനായവൻ ഇങ്ങനെ ചിന്തിച്ച്, പുറമേയുള്ള വഴി കടന്ന്, തന്റെ മനസ്സും കണ്ണുകളും നേരത്തേ എത്തിയിരുന്ന വേദരാജാവിന്റെ അടുത്ത് ശരീരംകൊണ്ടും എത്തി.",
        "0.48": "ഗുരുവിനോടുള്ള ഭക്തിയുടെ ഭാരത്താൽ ശരീരം വളഞ്ഞ്, ഉടൻ കൈകൂപ്പി, ഒരു നിമിഷം കണ്ണുകൾ പകുതി അടച്ച്, അദ്ദേഹം ഗുരുവിനെ ആരാധിച്ചു.",
        "0.49": "വിനയമെന്ന ആഭരണമണിഞ്ഞ്, എട്ട് അംഗങ്ങളോടുകൂടിയ സാഷ്ടാംഗ പ്രണാമം വ്യക്തമായി ചെയ്ത്, ആ ഭാഗ്യവാൻ പൂജ്യനായ ഗുരുവിന്റെ താമരപ്പാദങ്ങളിൽ വണങ്ങി.",
        "0.50": "സർവ്വഗുണസമ്പന്നനായ പ്രിയശിഷ്യൻ തനിക്കുമുന്നിൽ വണങ്ങുന്നത് കണ്ട പരാശരപുത്രൻ, വേഗം തന്റെ രണ്ടു മനോഹരമായ കൈകൾകൊണ്ട് അദ്ദേഹത്തെ എഴുന്നേൽപ്പിച്ചു.",
        "0.51": "സ്നേഹത്തിന്റെ അമൃത് നിറഞ്ഞ ഹൃദയത്തോടെയും, സന്തോഷത്താൽ വിടർന്ന കണ്ണുകളോടെയും പുഞ്ചിരിക്കുന്ന മുഖത്തോടെയും വേദങ്ങളുടെ നാഥൻ, അളവില്ലാത്ത ബുദ്ധിയുള്ളവനെ വേഗം അടുപ്പിച്ച് ആലിംഗനം ചെയ്തു.",
        "0.52": "യമന്റെ സഹോദരിയായ യമുനയിൽ നിന്ന് ഉയർന്ന ഒരു മഹാകാർമേഘം, സ്വർണ്ണനിറമുള്ള ജംബുനദിയുടെ ഒരു ധാരയുമായി ചേർന്നാൽ, സ്വർണ്ണവർണ്ണനായ മധ്വനെ ആലിംഗനം ചെയ്യുന്ന ഇരുണ്ടനിറമുള്ള വ്യാസനെ അതിനോട് ഉപമിക്കാം.",
        "0.53": "ഉത്തമ ബ്രാഹ്മണകുലങ്ങളിൽ ജനിച്ച ഈ രണ്ടു ഹരികൾ രാജകീയ ആഭരണങ്ങൾ ധരിച്ചിരുന്നെങ്കിൽ, രാജവംശങ്ങളിൽ പണ്ട് ജനിച്ച തങ്ങളുടെ മുൻ രൂപങ്ങളായ കൃഷ്ണനും ഭീമനും പരസ്പരം ആലിംഗനം ചെയ്യുന്ന അതേ രൂപമാകുമായിരുന്നു.",
        "0.54": "“ലോകപിതാവിന്റെയും പിതാവായവനിൽ നിന്നുപോലും ശുകന് ഇത്രയും പൂർണ്ണമായ വാത്സല്യം ലഭിച്ചിട്ടില്ലല്ലോ, ഈ ഭാഗ്യവാൻ ലഭിച്ചതുപോലെ!” എന്ന് ഋഷിമാർ വലിയ അദ്ഭുതം പൂണ്ടു.",
        "0.55": "വിദ്വാന്മാരായ ശിഷ്യന്മാർ ഗുരുവിന്റെ ഇച്ഛ അറിഞ്ഞ്, വിനയത്തോടെ അദ്ദേഹത്തിന് യോഗ്യമായ ആസനം നൽകി — മുകുന്ദന്റെ ദാസന്മാർ നാലുമുഖനായ ബ്രഹ്മാവിന് ആസനം നൽകുന്നതുപോലെ.",
        "0.56": "സത്യവതിയുടെ സത്യവാനായ പുത്രൻ “ഇരിക്കൂ” എന്ന് പറഞ്ഞ് സ്വയം ഇരുന്നപ്പോൾ, അവിടെയുള്ള മഹാഋഷിമാരെ മൃദുവായ പുഞ്ചിരിയോടും നോട്ടത്തോടും കൂടി ആദരിച്ച് മധ്വൻ ആസനസ്ഥനായി.",
        "0.57": "ഉചിതമായ നടപ്പറിയുന്ന ഋഷിസംഘങ്ങൾ അദ്ദേഹത്തെ ശ്രേഷ്ഠനായി തിരിച്ചറിഞ്ഞ് യഥായോഗ്യം ആദരിച്ചു; കവികളിൽ പ്രഗത്ഭരായ ഈ രണ്ടു ഗുരുക്കന്മാരുടെ സംഭാഷണം കേട്ടപ്പോൾ — ചെവിക്ക് മധുരമായത് — അവർ പരമാനന്ദം നിറഞ്ഞു.",
        "0.58": "നന്മയ്ക്കുവേണ്ടി ആനന്ദത്തിന്റെയും ജ്ഞാനത്തിന്റെയും രൂപങ്ങളായി ഭൂമിയിൽ അവതരിച്ച വിഷ്ണുവും വായുവും എന്ന രണ്ടു ദേവന്മാർ — വേദവ്യാസനും ആനന്ദതീർത്ഥനുമെന്ന പേരുകളിൽ — ആ ആശ്രമത്തിൽ തിളങ്ങി.",
        "0.59": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട ഏഴാം സർഗ്ഗം സമാപിച്ചു — ശ്രീമത് സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "ബദരീകാശ്രമത്തിൽ, ഹിമാലയത്തിൽ, മധ്വൻ വേദവ്യാസന്റെ ആശ്രമം കാണുന്നു. വേദങ്ങളുടെ മഹാവൃക്ഷംപോലെ തലമുതൽ പാദം വരെയുള്ള വ്യാസരൂപം ഈ സർഗ്ഗം വർണ്ണിക്കുന്നു. ശുകനുപോലും പൂർണ്ണമായി അറിയാനാകാത്ത സ്നേഹത്തോടെ ഗുരു സ്വീകരിക്കുമ്പോൾ മധ്വൻ ഗുരുവിനെ വന്ദിക്കുന്നു."
    },
    "sumadhva-vijaya-08": {
      "verses": {
        "0.0": "സ്വന്തം ഗുണമഹിമകളാൽ, വിശേഷിച്ച് പ്രതിഭയുടെ തിളക്കത്താൽ, തപസ്വികളുടെ മനസ്സുകളെ മഹത്തായ അദ്ഭുതത്തിലേക്ക് നയിച്ച വിശാലബുദ്ധിയുള്ളവൻ, ഒരിക്കൽ കാട്ടിലെ ഏകാന്തസ്ഥലത്ത് വേദങ്ങളുടെ നാഥനെ നിശ്ശബ്ദം സമീപിച്ചു.",
        "0.1": "ആ സമീപനം ഉചിതമെന്ന് ദേവന്മാർ വിധിച്ചു: പഠിപ്പിക്കപ്പെടുന്നതെല്ലാം ശേഷനെക്കാൾ നന്നായി ഗ്രഹിക്കുന്നവന് ശിഷ്യത്വം യോജിക്കും; മഹാമനസ്കനെ പഠിപ്പിക്കുന്ന സജ്ജനനാഥന് ഗുരുത്വവും യോജിക്കും.",
        "0.2": "കൃഷ്ണൻ (ദ്വൈപായനൻ) നിറഞ്ഞിരുന്ന മനസ്സിനെ ഒരിക്കൽക്കൂടി പരമസത്യങ്ങളാൽ നിറച്ചു; നീണ്ടകാലം തന്റെ വാസസ്ഥലമായിരുന്ന, നഗരംപോലെ വിശാലമായ ഭഗവാന്റെ മനസ്സിനെ മധ്വൻ ഉൾക്കൊണ്ടു — ഇത് അദ്ഭുതം തന്നെ!",
        "0.3": "അതിരില്ലാത്ത ഹൃദയമുള്ളവൻ അനന്തനിൽ നിന്ന് അസംഖ്യം ശാസ്ത്രങ്ങളുടെ പരമാർത്ഥം കേട്ടു; ഇതിഹാസങ്ങളിലെ യഥാർത്ഥ അർത്ഥവും, മനോഹര പുരാണങ്ങളും, സൂത്രങ്ങളും, പ്രിയപ്പെട്ട പാഞ്ചരാത്രവും അതിൽ ഉൾപ്പെട്ടിരുന്നു.",
        "0.4": "“ഋജു”ക്കളിൽ ഉത്തമനായ ഇദ്ദേഹം അനേകം ജന്മങ്ങളിലൂടെ ഇതെല്ലാം സ്വയം അറിഞ്ഞിരുന്നെങ്കിലും, ശേഷശായിയായ ഭഗവാൻ തന്റെ മഹത്തായ കൃപയുടെ ശക്തിയാൽ അദ്ദേഹത്തിന്റെ ബുദ്ധിയെ ഇനിയും കൂടുതൽ നിർമ്മലമാക്കി.",
        "0.5": "പിന്നീട് ബാദരായണന്റെ (വ്യാസന്റെ) സഹവാസത്താൽ സമ്പന്നനായ, അളവില്ലാത്ത മനസ്സുള്ളവൻ, മറ്റൊരു ആശ്രമത്തിൽ തിളങ്ങുന്ന ഹരിയുടെ മറ്റൊരു രൂപമായ നാരായണനെ വന്ദിക്കാൻ മുന്നോട്ടു പോയി.",
        "0.6": "ആ ഉത്തമ ആശ്രമത്തിൽ വിവേകസമ്പന്നൻ ആദിപുരുഷനെ കണ്ടു — പുകയില്ലാത്ത ജ്വലിക്കുന്ന അഗ്നിപോലെ, നേർത്ത മരവുരി ധരിച്ച്, മുഞ്ജപ്പുല്ലിന്റെ അരഞ്ഞാണം അണിഞ്ഞ്, തിളങ്ങുന്ന ജടാവലയത്തോടെ.",
        "0.7": "ജയിക്കാനാവാത്ത ഇന്ദ്രിയങ്ങളെ ജയിക്കുന്ന തപസ്സിൽ അദ്ദേഹം എപ്പോഴും കാട്ടിൽ വസിക്കുന്നതുപോലെ തോന്നി; എന്നാലും അദ്ദേഹം തന്റെ സ്വഭാവമായ, സമൃദ്ധവും നിർമ്മലവും സ്വയംപൂർണ്ണവുമായ ആനന്ദത്തിൽ നിരന്തരം സന്തോഷിക്കുന്നു.",
        "0.8": "വിടർന്ന താമരപോലെ വിശാലമായ കണ്ണുകളോടെ, അധർമ്മികൾക്ക് എത്താനാവാത്ത ധർമ്മപുത്രനെ അദ്ഭുതത്തോടെ നോക്കി, വിശാലമനസ്സുള്ളവൻ ഉള്ളിൽ ഇങ്ങനെ ചിന്തിച്ചു:",
        "0.9": "“ഇത് തീർച്ചയായും പരമപുരുഷൻ, ആദികാരണൻ തന്നെയാണ്; നാലുമുഖനായ ബ്രഹ്മാവിനൊപ്പം പതിനാലു ലോകങ്ങളെയും സംഹരിച്ചിട്ട്, കമലയോടൊപ്പം മാത്രം പ്രകാശിച്ചുനിൽക്കുന്നവൻ.”",
        "0.10": "“മൂന്നു ഗുണങ്ങളുള്ള പ്രകൃതിയിൽ നിന്ന് ഈ ഭഗവാൻ മഹത്തത്വത്തെ സൃഷ്ടിച്ചു; അതിൽ നിന്ന് ത്രിവിധമായ അഹങ്കാരം; അതിൽ നിന്ന് ദേവന്മാരും ഇന്ദ്രിയങ്ങളും; പിന്നെ പഞ്ചഭൂതങ്ങൾ; അവയിൽ നിന്ന് ബ്രഹ്മാണ്ഡ അണ്ഡം; ഇവിടെ അവൻ ലോകങ്ങളെ സൃഷ്ടിച്ചു.”",
        "0.11": "“ബ്രഹ്മാവ്, വായു, ഗരുഡൻ, ഇന്ദ്രൻ, ശിവൻ, മറ്റ് നാഥന്മാരും പ്രജാപതികളും, ദേവന്മാരും അവരുടെ ഗണങ്ങളും, മനുഷ്യർ, അസുരന്മാർ തുടങ്ങിയവരെ — ലീലയായി അവൻ എപ്പോഴും സൃഷ്ടിക്കുന്നു, പാലിക്കുന്നു, സംഹരിക്കുന്നു; ഓരോരുത്തരെയും അവരവരുടെ വിധിയിലേക്ക് നയിക്കുന്നു.”",
        "0.12": "“എണ്ണമറ്റ ഗുണസമൂഹങ്ങളോടുകൂടിയവനും എല്ലാ കുറവുകളിൽ നിന്നും മുക്തനും, എല്ലാം തന്റെ ശക്തിയിൽ അലങ്കാരമായിട്ടല്ല, യാഥാർത്ഥ്യമായിത്തന്നെ പിടിച്ചുനിർത്തുന്നവനും, തന്നെ ഓർക്കുന്നതിലൂടെയും സ്തുതിക്കുന്നതിലൂടെയും വണങ്ങുന്നതിലൂടെയും സ്വന്തക്കാർ മോചനം നേടാൻ അനേകം രൂപങ്ങൾ സ്വീകരിക്കുന്നു.”",
        "0.13": "“ഈ ദേവനാഥൻ ഒരിക്കൽ വേദം മോഷ്ടിച്ച പണ്ടത്തെ സജ്ജനശത്രുവിനെ ഹയഗ്രീവ രൂപത്തിൽ വധിച്ച്, നാലുമുഖനായ ബ്രഹ്മാവിന് നാല് വേദങ്ങൾ നൽകി.”",
        "0.14": "“വരാഹമായി, ഇന്ദ്രന്റെ ശത്രുവായ ഹിരണ്യാക്ഷന്റെ ശക്തമായ കൈകളാൽ വലിച്ചുതാഴ്ത്തപ്പെട്ട് വെള്ളത്തിൽ മുങ്ങിപ്പോയ ഭൂമിയെ അവൻ ഉയർത്തി; കൂർമ്മമായി, തിരമാലകൾ ഉയരുന്ന സമുദ്രത്തിൽ തന്റെ ഭക്തരെ സംരക്ഷിച്ചു.”",
        "0.15": "“നരസിംഹമായി, തന്റെ പ്രിയ ഭക്തരുടെ ഭയം നീക്കുന്നവനായി, കോപം ഉച്ചത്തിലായപ്പോൾ തന്റെ ഭയങ്കരനും ശക്തനുമായ ശത്രുവിനെ നഖങ്ങളുടെ ജ്വലിക്കുന്ന ചക്രങ്ങളാൽ ഒരു നിമിഷം കൊണ്ട് കീറിമുറിച്ചു.”",
        "0.16": "“വാമനനായി, ബാല്യത്തിൽ മനോഹരനായി, തന്റെ തേജസ്സുകൊണ്ട് അസുരന്മാരെ സന്തോഷിപ്പിച്ചു; ഒരു ഉപായത്താൽ ഇന്ദ്രന്റെ ശത്രുവായ ബലിയെ താഴ്ത്തി, പരമമായ സ്ഥാനം തന്റേതിന് നൽകി.”",
        "0.17": "“ശക്തരായ മഹർഷിമാരുടെ വംശത്തിൽ ജനിച്ച പരശുരാമനായി അവനെ വീണ്ടും വീണ്ടും പറയുന്നു; ലോകനന്മയ്ക്കായി രണ്ടാം സൂര്യനെപ്പോലെ, തന്റെ മഴുവിന്റെ തിളക്കത്താൽ അഹങ്കാരികളായ രാജാക്കന്മാർ എന്ന ഇരുട്ടിനെ നശിപ്പിച്ചവൻ.”",
        "0.18": "(ഇവിടെനിന്ന് കവി രാമന്റെയും കൃഷ്ണന്റെയും ജീവിതങ്ങൾ ഇരട്ട അർത്ഥങ്ങളിലൂടെ ഒരുമിച്ച് വിവരിക്കുന്നു.) “വസുദേവന് (അഥവാ: ദേവന്മാർക്ക്) സന്തോഷം നൽകുന്ന ആ കരുണാമയനായ ഭഗവാൻ പണ്ട് ചന്ദ്രവംശത്തിൽ (അഥവാ: സൂര്യവംശത്തിൽ) ജനിച്ചു; ഭൂമിയിലെ അദ്ദേഹത്തിന്റെ പിതാവ് ശത്രുക്കളെ വധിക്കുന്നവനും ദിക്കുകളെ ജയിച്ചവനും ഭയങ്കര ശക്തനുമായ ദശരഥനായിരുന്നു.”",
        "0.19": "“ലോകനാഥന് പ്രിയനായ സർപ്പനാഥൻ ശേഷനും ജനിച്ചു; ചന്ദ്രനെ സൗന്ദര്യത്താൽ തോൽപ്പിക്കുന്ന ആ മനോഹരനെ മൂത്ത സഹോദരനെന്ന് വിളിക്കുന്നു, ബലരാമൻ എന്ന പേരിൽ (കൃഷ്ണകഥയിൽ), രാമൻ എന്ന പേരിൽ (രാമകഥയിൽ ലക്ഷ്മണന്റെ ജ്യേഷ്ഠനായ രാമൻ തന്നെ).”",
        "0.20": "“പിന്നീട്, പിരിയാൻ സഹിക്കാത്ത പിതാവ് വീണ്ടും വീണ്ടും നോക്കിക്കൊണ്ടിരിക്കെ, ദുഷ്ടരെ ഭയപ്പെട്ടിരുന്ന ഒരു തപസ്വി (വിശ്വാമിത്രൻ; അഥവാ: കംസനിൽ നിന്ന് അകറ്റി വ്രജത്തിലേക്ക്) അവനെ കാട്ടിലേക്ക് കൊണ്ടുപോയി; അവിടെ രാത്രിയിലെ ഒരു രാക്ഷസിയെ (താടക; അഥവാ: പൂതന) അവൻ വധിച്ചു.”",
        "0.21": "“തപസ്വികളുടെ യജ്ഞങ്ങൾക്ക് ശത്രുത ചെയ്ത ദുഷ്ടന്മാരെ അവൻ നശിപ്പിച്ചപ്പോൾ ദേവഗണങ്ങളും സജ്ജനങ്ങളും അവനിൽ സന്തോഷിച്ചു — യുദ്ധത്തിൽ കൈകൾ ഉയർത്തിയ സുബാഹുവിനെ (രാമകഥയിൽ), ക്രൂരനായ കേശി, അരിഷ്ടൻ തുടങ്ങിയവരെ (കൃഷ്ണകഥയിൽ).”",
        "0.22": "“തന്നെ സ്തുതിക്കുന്ന പക്ഷികളാൽ നിറഞ്ഞ കാടുകളിൽ (അഥവാ: യജ്ഞങ്ങളിൽ വേദം ചൊല്ലുന്ന ബ്രാഹ്മണരാൽ), ഗോകുലം മുഴുവൻ പ്രിയപ്പെട്ടവനായി അലഞ്ഞു; ലൗകികാഗ്രഹമില്ലാത്ത സ്നേഹത്താൽ മനസ്സും വാക്കും ആർദ്രമായ മനോഹരികളായ ഗോപികമാരെ (ഗോപിമാരെ) പരിപാലിക്കുന്നതിൽ അവൻ സന്തോഷിച്ചു.”",
        "0.23": "“സഹോദരനോടും എല്ലാ സഖാക്കളോടും ഒപ്പം പിതാവിന് പ്രിയപ്പെട്ട മധുര നഗരത്തിലേക്ക് (മഥുര; അഥവാ: ജനകന്റെ നഗരമായ മിഥിള) അവൻ പോയി; ലോകത്തിലെ ഏകസൗന്ദര്യമായ അവൻ നഗരത്തിൽ പ്രവേശിച്ചപ്പോൾ സ്ത്രീപുരുഷന്മാരുടെ കണ്ണുകൾക്ക് ഉത്സവമായി.”",
        "0.24": "“പിന്നെ കളിയായി ശിവന്റെ മഹാധനുസ്സ് (അഥവാ: കംസന്റെ വില്ല്) ഒടിച്ച്, ഉഗ്രസേനന്റെ പുത്രനായ കംസന്റെ ശക്തി തകർത്തു; തന്റെ ബ്രാഹ്മണഗുരുവിനെ സേവിച്ചുകൊണ്ട്, താമരയിൽ ജനിച്ച ബ്രഹ്മാവിന്റെ ഗുരുവായവൻ തന്റെ അളവില്ലാത്ത തേജസ്സാൽ ജനങ്ങളെ സന്തോഷിപ്പിച്ചു.”",
        "0.25": "“രാജപുത്രിയെ (സീതയെ; അഥവാ: രുക്മിണിയെ) അവൻ നേടി — താമരക്കണ്ണുള്ള, ഭൂമിയിലിറങ്ങിയ കമല തന്നെ; കളിയായി ശത്രുരാജാക്കന്മാരെ തോൽപ്പിച്ച്, സന്തോഷിച്ചു, സമുദ്രംപോലെ ശത്രുക്കൾക്ക് എത്താനാവാത്ത തന്റെ നഗരത്തിലെത്തി.”",
        "0.26": "“അമ്മമാരുടെ ആഗ്രഹം നിറവേറ്റാൻ അവൻ വേഗത്തിൽ കാട്ടിലേക്ക് പോയി; സജ്ജനങ്ങളുടെ ആഗ്രഹങ്ങൾ സഫലമാക്കി, മംഗളവതിയായ ഭാര്യയോടും വിജയക്കൊടി വഹിക്കുന്ന പ്രധാന സഖാവായ ലക്ഷ്മണനോടും ഒപ്പം.”",
        "0.27": "“പർവതങ്ങൾ നയിക്കുന്ന ദുർഘടസ്ഥലങ്ങൾ കടന്ന്, ഖരൻ, ദൂഷണൻ തുടങ്ങി സജ്ജനങ്ങളുടെ അനേകം ശത്രുക്കളെ അവൻ വധിച്ചു; യഥാസമയം ലോകത്തിന്റെ അസഹനീയമായ ഭീകരനെ മഹാനരകത്തിന്റെ ഇരുട്ടിലേക്ക് അയച്ചു (അഥവാ: നരകാസുരനെ വധിച്ചു).”",
        "0.28": "“ലോകം ആദരിക്കുന്ന തന്റെ പ്രിയതമയോടൊപ്പം, അവളുടെ തേജസ്സ് മനോഹരമായ ആശ്രമമുറ്റത്തെ അലങ്കരിച്ച നാഥൻ വീട്ടിലെത്തി — ദേവന്മാരുടെ പാരിജാതവൃക്ഷം കവർന്നെടുത്ത്, അതിന്റെ ഉടമസ്ഥരുടെ അഹങ്കാരവും അശ്രദ്ധയും തകർത്തവൻ.”",
        "0.29": "“മറ്റുള്ളവർക്ക് ഭയങ്കരനും, പത്തു ദിക്പാലകരെയും രാജാക്കന്മാരുടെ വൃന്ദങ്ങളെയും വീണ്ടും വീണ്ടും കീഴടക്കിയവനുമായ വെറുക്കപ്പെട്ടവനെ (രാവണനെ) — ഇവിടെ തിളങ്ങിയ തന്റെ പ്രിയ ശ്രീയെ കവർന്നുകൊണ്ടുപോകാൻ ഭഗവാൻ അനുവദിച്ചു.”",
        "0.30": "“വായുപുത്രനായ ഹനുമാനും മറ്റുള്ളവരും വണങ്ങി സ്തുതിക്കെ, ഇന്ദ്രപുത്രനെ (വാലിയെ) തന്റെ അമ്പുകൊണ്ട് അവൻ വീഴ്ത്തി; ശത്രുക്കളില്ലാതാക്കിയ രാജ്യം സൂര്യപുത്രനായ തന്റെ പ്രിയ സഖാവ് സുഗ്രീവന് നൽകി.”",
        "0.31": "“വായുപുത്രന്റെ വായിൽ നിന്ന് തന്റെ പ്രിയന്റെ വിവരം അറിഞ്ഞ മധുസൂദനൻ സന്തോഷിച്ചു; ഉഗ്രമായ കപിസൈന്യത്തോടൊപ്പം (അഥവാ: മൂർച്ചയുള്ള സുദർശനചക്രത്തോടെ) തിളങ്ങി, രാക്ഷസന്മാർ വസിക്കുന്ന സമുദ്രമധ്യത്തിലെ നഗരത്തിലേക്ക് പോയി (അഥവാ: സജ്ജനങ്ങൾ വസിക്കുന്ന ദ്വാരകയിലേക്ക്).”",
        "0.32": "“മൂർച്ചയുള്ള അമ്പുകളുടെ ചക്രംകൊണ്ട് (അഥവാ: മൂർച്ചയുള്ള സുദർശനചക്രംകൊണ്ട്) തന്റെ പരാക്രമം കാട്ടി, ഭൂമിയെ ഭാരപ്പെടുത്തിയ വലിയ സൈന്യത്തെ ഭഗവാൻ നശിപ്പിച്ചു — ഗജരാജനെപ്പോലെ വലിയ, അഹങ്കാരിയായ കുംഭകർണനെയും, സഹോദരനെയും, ഇന്ദ്രന്റെ ശത്രുവിനെയും (അഥവാ: കുവലയാപീഡം എന്ന ആനയെയും).”",
        "0.33": "“പിന്നെ അഗ്നിയിൽ പ്രവേശിച്ച പത്നിയോടും മുന്നിൽ നടക്കുന്ന സഹോദരന്മാരോടും ഒപ്പം, സജ്ജനങ്ങൾക്ക് ആഗ്രഹങ്ങൾ നൽകുന്നവൻ ഒടുവിൽ തന്റെ വാസസ്ഥലത്ത് തിരിച്ചെത്തി, തന്റെ യഥാർത്ഥ രൂപവുമായി പരമമായ ഏകത്വം പ്രാപിച്ചു.”",
        "0.34": "“മഹീദാസൻ എന്ന് പാദങ്ങൾ ആരാധിക്കപ്പെടുന്നവൻ, പ്രസിദ്ധനും ശുദ്ധമനസ്സുള്ളവനുമായ വിഷ്ണുയശസ്സ് എന്ന ബ്രാഹ്മണനിൽ ജനിച്ചു (കൽക്കിയായി); ലോകത്തിന്റെ പാപം ശമിപ്പിക്കാൻ മഹത്തായ തേജസ്സുള്ള വാൾ ധരിക്കുന്നു, പ്രകാശിക്കുന്ന വേദവചനം ഉയർത്തിപ്പിടിക്കുന്നു.”",
        "0.35": "“ഈ ദേവനാഥൻ മനുവിന്റെ പുത്രിയായ ദേവഹൂതിയുടെയും തപസ്സിൽ തിളങ്ങുന്ന കർദ്ദമന്റെയും പുത്രനായി (കപിലനായി) ജനിച്ചു; കാലക്രമേണ, തന്നോടുള്ള ഭക്തികൊണ്ട് നിറഞ്ഞ സജ്ജനാത്മാക്കളെ ഉണർത്തി.”",
        "0.36": "“ഏറ്റവും മനോഹരിയായ സ്ത്രീയുടെ രൂപം (മോഹിനി) സ്വീകരിച്ച്, വലിയ മുലകൾ പരസ്പരം ചേർന്നമർന്ന് തന്റെ നിറഞ്ഞ യൗവനസൗന്ദര്യം തെളിയിച്ച്, അസുരശത്രുവായ അവൻ ദേവന്മാർക്ക് അമൃത് നൽകി.”",
        "0.37": "“സജ്ജനങ്ങൾക്ക് സ്ഥാനം നൽകുന്നതും ആത്മശുദ്ധി പകരുന്നതുമായ ഈ ശാശ്വതൻ, ഉത്തമ മുനിയായ അത്രിയുടെ പത്നി അനസൂയയുടെ ശുദ്ധമനസ്സിൽ സ്നേഹത്തോടെ വഹിക്കപ്പെട്ട ഒരു മൃദു ശിശുവായി (ദത്താത്രേയൻ) ജനിച്ചു.”",
        "0.38": "“സജ്ജനപ്രിയനായ ഋഷഭനായി, ഭൂമിയുടെ ഭരണാധികാരിയായി, പരമഹംസ ലക്ഷണങ്ങളുള്ള ശരീരം ധരിച്ച് എല്ലാ ബന്ധങ്ങളിൽ നിന്നും മുക്തനായി അലഞ്ഞു; പരമസത്യം തേടിയ സനകാദികളാൽ അദ്ദേഹം ആരാധിക്കപ്പെട്ടു.”",
        "0.39": "“ഈ ഹരി ധർമ്മന്റെ പുത്രനും നരന്റെ സഹോദരനുമായി ഉത്തമ വീര്യത്തോടെ ജനിച്ചു; സജ്ജനങ്ങളെ സന്തോഷിപ്പിക്കാൻ അദ്ദേഹത്തിന്റെ സഹോദരനായി കൃഷ്ണൻ എന്ന പേരിലും, സ്വയം അവനിൽ നിന്നുതന്നെ ജനിച്ചു.”",
        "0.40": "“പരമാത്മാവിന് നമസ്കാരം, നമസ്കാരം — രൂപത്തിൽ എപ്പോഴും ഏകനായിരിക്കെ പത്തു രൂപങ്ങളായും നൂറായിരം രൂപങ്ങളായും, മാറ്റമില്ലാത്തവനും വ്യക്തമായി അനന്തരൂപങ്ങളുള്ളവനും, അവന്റെ ഓരോ ശരീരവും ആനന്ദവും ചിത്തും കൊണ്ട് നിർമ്മിതവുമാണ്.”",
        "0.41": "ഇങ്ങനെ ചിന്തിച്ച്, നിറഞ്ഞ ഹൃദയത്തോടെ അദ്ദേഹം ഹരിയെ സ്നേഹത്തോടെ വണങ്ങി, ഹരിയാൽ ആദരിക്കപ്പെട്ടു; പരസ്പരം ആദരിച്ച്, അരികിൽ ഇരുന്ന ജയിക്കാനാവാത്ത രണ്ടുപേരുടെ മുന്നിൽ അദ്ദേഹം ഇരുന്നു.",
        "0.42": "അവിടെ പലതരം സംഭാഷണങ്ങൾക്കുശേഷം, ലോകനാഥനായ നാരായണൻ ഋഷിപുത്രന്റെ (വ്യാസന്റെ) മനോഹരമായ മുഖത്തേക്ക് നോക്കി, തന്റെ മുന്നിൽ വണങ്ങിനിന്ന മഹാനായ ആനന്ദതീർത്ഥരോട് രഹസ്യമായി ഈ വാക്കുകൾ പറഞ്ഞു.",
        "0.43": "“ദൃഢമനസ്സുള്ളവനേ, ദേവന്മാരുടെ ഉദ്ദേശ്യം ഓർത്ത്, ഞാൻ ഇപ്പോൾ പറയുന്നത് കേൾക്കൂ, ഉത്തമന്മാർ അംഗീകരിക്കുന്നത് തന്നെ: നിന്റെ ഈ അവതാരം ഇപ്പോൾ യൗവനത്തിലാണ്; മറ്റുള്ളവർക്ക് ഏതാണ്ട് അസാധ്യമായത് സാധിച്ചുകൊണ്ട് അത് വലിയ ഫലം നൽകും.”",
        "0.44": "“സജ്ജനങ്ങൾക്ക് പ്രിയമായ സൂത്രങ്ങളുടെ ഹൃദയം മറച്ചുവെച്ച്, ഇപ്പോൾ തങ്ങൾക്ക് ഇഷ്ടമുള്ളതുപോലെ വ്യാഖ്യാനങ്ങൾ രചിച്ചുകൊണ്ട്, ശ്രുതിയുടെയും സ്മൃതിയുടെയും യഥാർത്ഥ അർത്ഥം വികലമാക്കുന്ന മറ്റുള്ളവർ യഥാർത്ഥ ജ്ഞാനത്തെ തകർത്തു; അത് ഏതാണ്ട് പൂർണ്ണമായും മാഞ്ഞുപോയിരിക്കുന്നു.”",
        "0.45": "“ദുഷ്ടന്മാർ ചെയ്ത ഈ അനീതി തിരുത്താനും, നിന്റെ സ്വന്തം ജനങ്ങളെ നല്ല വഴിയിലേക്ക് തിരിച്ചുകൊണ്ടുവരാനും, താമസമില്ലാതെ സൂത്രങ്ങൾക്ക് വ്യാഖ്യാനം രചിക്കൂ; ഹേ ജ്ഞാനിയായ കവേ, ശ്രുതിയെയും സ്മൃതിയെയും യഥാർത്ഥ സിദ്ധാന്തവുമായി യോജിപ്പിക്കൂ.”",
        "0.46": "ലോകഗുരുവിന്റെ ഈ വാക്കുകൾ — അല്പമേ ആണെങ്കിലും അളവില്ലാത്ത അർത്ഥമുള്ളവ — കേട്ട്, വാഗ്മികളിൽ ഉത്തമനായവൻ, ചലിക്കുന്നതും നിശ്ചലമായതുമായ സർവ്വത്തിന്റെയും ആ രണ്ട് നാഥന്മാരിൽ നിന്ന് വേർപിരിയാൻ സഹിക്കാനാവാതെ, മനസ്സ് നിറഞ്ഞ് അവരോട് പറഞ്ഞു:",
        "0.47": "“നാഥാ, ഇനി നിങ്ങൾ രണ്ടുപേരെയും നിരന്തരം സേവിക്കുന്ന അമൃതിൽ മുങ്ങാൻ എനിക്ക് കൃപ നൽകണമേ; മൂന്നു ലോകങ്ങളിലും ഇത്ര പ്രിയമായ ഒരു സന്തോഷം എനിക്ക് കണ്ടെത്താനാവില്ല — ലോകത്തിന്റെ ഏകാനുഗ്രഹം തന്നെയാണിത്.”",
        "0.48": "“കലിയുഗം ഗുണങ്ങളെ വിഴുങ്ങുന്ന ഈ ഭൂമിയിൽ, യോഗ്യമനസ്സുള്ള സജ്ജനങ്ങൾ ഇപ്പോൾ തീർച്ചയായും ഇല്ല; യോഗ്യതയില്ലാത്തവർക്ക് പരമസത്യം വിവരിക്കുന്നത് നായയ്ക്ക് പവിത്രമായ ഹവിസ്സ് നൽകുന്നതുപോലെ നിന്ദ്യമാണ്.”",
        "0.49": "ഇങ്ങനെ പറഞ്ഞവനോട് ഭഗവാൻ പറഞ്ഞു: “സൗമ്യനായവനേ, ഭൂമിയിൽ പുണ്യത്തിന് യോഗ്യരായവരുണ്ട്; കോർത്തിടാതെ കിടക്കുന്ന മനോഹരമായ രത്നങ്ങൾപോലെ അവരെ ശേഖരിച്ച്, നിന്റെ നിർമ്മല വാക്കുകളാൽ (അഥവാ: രശ്മികളാൽ) കരുണയോടെ ശുദ്ധീകരിക്കൂ.”",
        "0.50": "“എന്റെ പരമമായ കൽപ്പനയാൽ, നിന്റെ കീർത്തി നിരന്തരം ദുഷ്ടന്മാർക്ക് പരമദുഃഖം നൽകട്ടെ — മൂങ്ങകൾക്ക് സൂര്യപ്രകാശം പോലെ; സജ്ജനങ്ങളെ ഉണർത്തട്ടെ — താമരക്കുളങ്ങൾ വിടർത്തുന്നതുപോലെ.”",
        "0.51": "ഇങ്ങനെ, ലോകസുഖത്തിനായി ഭൂമി ധരിക്കുന്നവന്റെ (പർവതത്തിന്റെ) വായിൽ നിന്ന് നദി ഒഴുകുന്നതുപോലെ, ആ തെളിഞ്ഞ വാക്കുകൾ ഒഴുകി, ചന്ദ്രകിരണങ്ങളിൽ കടൽപോലെ നിറഞ്ഞിരുന്ന മധ്വന്റെ വിശാല ബുദ്ധിയുടെ സമുദ്രത്തിൽ പ്രവേശിച്ചു.",
        "0.52": "ആ രണ്ടു മഹാത്മാക്കളുടെ ആദരണീയമായ ഇഷ്ടം മനസ്സിലാക്കി, “അങ്ങനെ തന്നെ” എന്ന് പറഞ്ഞ്, ഉറച്ച മനസ്സുള്ളവൻ വണങ്ങി, മറ്റാർക്കും വഹിക്കാനാവാത്ത അവരുടെ കൽപ്പന തലയിൽ വഹിച്ചു.",
        "0.53": "സത്യം വെളിപ്പെടുത്തുന്ന മൂന്നു വേദങ്ങൾപോലെ, ജനങ്ങളുടെ പാപം നശിപ്പിക്കുന്ന മൂന്നു പുണ്യാഗ്നികൾപോലെ, എല്ലാം താങ്ങുന്ന മൂന്നു ലോകങ്ങൾപോലെ — മൂവരും, മുനിപുത്രനായ വ്യാസനും, ധർമ്മപുത്രനായ നാരായണനും, മധ്വനും, അവിടെ ആനന്ദത്തിൽ തിളങ്ങി.",
        "0.54": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട എട്ടാം സർഗ്ഗം സമാപിച്ചു — ശ്രീമത് സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "വ്യാസനോടൊപ്പം മധ്വൻ ബദരിയിലെ നാരായണന്റെ അടുത്ത് ചെല്ലുന്നു. ഭഗവാനെയും രാമകൃഷ്ണാദി അവതാരങ്ങളെയും ഈ സർഗ്ഗം സ്തുതിക്കുന്നു. കലിയുഗത്തിൽ പരമസത്യത്തിന് യോഗ്യർ അപൂർവ്വമാണെന്ന് നാരായണൻ മധ്വനോട് പറയുന്നു; എങ്കിലും അത് തന്റെ കൃതികളിലൂടെ പ്രചരിപ്പിക്കാൻ അദ്ദേഹം കൽപ്പിക്കുന്നു."
    },
    "sumadhva-vijaya-09": {
      "verses": {
        "0.0": "അപ്പോൾ ജ്ഞാനികളുടെ നേതാവായ ആനന്ദതീർത്ഥർ, ധർമ്മപുത്രനും ജന്മരഹിതനുമായ നാരായണനെ അവിടെ വണങ്ങി; സ്നേഹത്തോടെ യാത്ര തിരിക്കാൻ പ്രേരിപ്പിച്ച ഭഗവാനോട് യാത്ര ചോദിച്ച്, വേദങ്ങളുടെ നാഥനായ വേദവ്യാസനെ മുന്നിൽ നിർത്തി മുന്നോട്ടു പോയി.",
        "0.1": "മറ്റേ ആശ്രമത്തിൽ (വ്യാസന്റെ) എത്തി, കൃഷ്ണനിൽ (വേദവ്യാസനിൽ) നിന്ന് കേൾക്കേണ്ടതെല്ലാം കേട്ടു; ഗുരുവിന്റെ ഇഷ്ടം പിന്തുടർന്ന്, അത് നന്നായി മനസ്സിലാക്കി, യാത്രയ്ക്ക് തയ്യാറായി.",
        "0.2": "ജ്ഞാനികളിൽ ശിരോമണിയായ മഹാമനസ്കൻ, സൗമ്യമായ പുഞ്ചിരിയാൽ മൃദുവായ മനോഹര മുഖമുള്ള, ആരാധ്യനായ സജ്ജനനാഥനെ വണങ്ങി, അനുവാദം വാങ്ങി തന്റെ വഴിക്ക് പോയി.",
        "0.3": "വിശാലമനസ്സുള്ള മധ്വന്റെ മനസ്സായിരുന്നു അവന്റെ പ്രിയവാസസ്ഥലം; വ്യാസൻ ഒരു നിമിഷം പോലും അതിനെ വിട്ടുപോയില്ല; അതിനാൽ മധ്വൻ തന്റെ നാഥനിൽ നിന്ന് യഥാർത്ഥത്തിൽ വേർപെട്ടില്ല.",
        "0.4": "തന്റെ വീരനോട്ടത്താൽ അദ്ദേഹം കാട്ടുമൃഗങ്ങൾക്ക് സിംഹമെന്നപോലെയും, ശാന്തനോട്ടത്താൽ സൗമ്യർക്ക് സമാധാനസന്തോഷം നൽകുന്നവനായും തോന്നി; ഇവിടെയും അവിടെയും വഴികളിലൂടെ മനോഹരമായി നീങ്ങി, സർവ്വജ്ഞനായവൻ പർവതത്തിൽ നിന്ന് ഇറങ്ങി വന്നു.",
        "0.5": "സമുദ്രം കടന്ന് മടങ്ങിയെത്തിയ വാനരരാജാവ് ഹനുമാനെപ്പോലെയും, സ്യമന്തകരത്നം തിരിച്ചുകൊണ്ടുവന്ന കൃഷ്ണനെപ്പോലെയും, ഏറ്റവും ഉത്തമമായ പൂക്കൾ കൊണ്ടുവന്ന ഭീമസേനനെപ്പോലെയും അദ്ദേഹം സ്വജനങ്ങൾക്ക് സന്തോഷം നൽകി.",
        "0.6": "അഗ്നിശർമ്മാവ് തലവനായ അഞ്ചോ ആറോ ബ്രാഹ്മണർ വെവ്വേറെയും പൂർണ്ണമായ അളവിലും കൊണ്ടുവന്ന ഭക്ഷണം അദ്ദേഹം ഇളകാതെ മുഴുവൻ ഭക്ഷിച്ചു; പ്രളയകാലത്ത് ലോകം മുഴുവൻ വിഴുങ്ങാൻ കഴിയുന്നവന് ഇതിൽ അദ്ഭുതമില്ല.",
        "0.7": "(ശ്ലോകങ്ങൾ 7 മുതൽ 11 വരെ ഒരൊറ്റ വാക്യമാണ്.) വ്യാസന്റെ ഹൃദയത്തിന് പ്രിയനായ വാസുദേവനെ സ്ഥാപിക്കുന്ന, എണ്ണമറ്റ നല്ല ഗുണങ്ങളുള്ള, എല്ലാ കുറവുകളുമില്ലാത്ത, ജ്ഞാനവും ഭക്തിയും അനന്തമായ ആനന്ദവും നൽകുന്ന ഒരു വ്യാഖ്യാനം അദ്ദേഹം രചിച്ചു;",
        "0.8": "ആ പരമവസ്തുവിനെ പ്രഖ്യാപിക്കുന്ന ഉത്തമ വേദവാക്യങ്ങൾ വീണ്ടും വീണ്ടും ഉദ്ധരിക്കുന്നതും, സ്മൃതിവചനങ്ങളാൽ അവയുടെ അർത്ഥം വ്യക്തമാക്കുന്നതും, യുക്തമായ വാദങ്ങളോടുകൂടിയതുമായ ഒരു വ്യാഖ്യാനം.",
        "0.9": "അത് യുവാക്കളെയും ലളിതമനസ്സുള്ളവരെയും പഠിപ്പിക്കുന്നു, എന്നാൽ അതിന്റെ വാക്കുകൾ പണ്ഡിതന്മാർക്കുപോലും ഗ്രഹിക്കാൻ പ്രയാസമാണ്; അതിന്റെ ഹൃദയം അളവില്ലാത്തതാണ്, തെളിഞ്ഞതും സൗമ്യസൗന്ദര്യമുള്ളതുമാണ്, എന്നിട്ടും എതിരാളികൾക്ക് ഭയങ്കരവുമാണ്;",
        "0.10": "എല്ലാ കുറവുകളുമില്ലാത്തതും, അതിന്റെ വാക്കുകൾ ഒരിക്കലും ഫലശൂന്യമല്ലാത്തതും, (നല്ല വ്യാഖ്യാനത്തിന്റെ) എല്ലാ ലക്ഷണങ്ങളുമുള്ളതും, സ്വർഗ്ഗാധിപന്മാർപോലും ആദരിക്കുന്നതും, രചയിതാവിന്റെ തന്നെ മറ്റൊരു അനുഗൃഹീത രൂപംപോലെയുള്ളതുമായ ഒന്ന്.",
        "0.11": "ഇങ്ങനെ അനന്തജ്ഞാനിയായവൻ ബ്രഹ്മസൂത്രങ്ങൾക്ക് അദ്ഭുതകരമായ തന്റെ വ്യാഖ്യാനം രചിച്ചു; ഇരുപത്തൊന്ന് തെറ്റായ വ്യാഖ്യാനങ്ങളെ ഖണ്ഡിക്കുന്നതും, ഭൂതത്തിലോ വർത്തമാനത്തിലോ ഭാവിയിലോ ആരാലും ഖണ്ഡിക്കപ്പെടാനാവാത്തതുമായ ഒന്ന്.",
        "0.12": "അതിലെ ഒരക്ഷരം പോലും എഴുതിയെടുക്കുന്നവന് ഗംഗയുടെ തീരത്ത്, അവളുടെ മംഗളതരംഗങ്ങളാൽ കഴുകപ്പെട്ട കരയിൽ ഹരിക്ക് ഒരു മനോഹര ക്ഷേത്രം പണിയുന്നതിന് തുല്യമായ പുണ്യം ലഭിക്കും; ഇവിടെ സത്യതീർത്ഥർ മുഴുവൻ വ്യാഖ്യാനവും എഴുതി.",
        "0.13": "അവിടെ ഭഗവാനെ വണങ്ങി, ഗുരുവിന്റെ വാക്കിനോടുള്ള ആദരവിനാൽ, അനുയായികളോടൊപ്പം വേഗം പുറപ്പെട്ടു; പല ദേശങ്ങളും കടന്ന്, കളങ്കമില്ലാത്ത മനസ്സുള്ളവൻ ഗോദാവരിയുടെ തീരത്തെത്തി.",
        "0.14": "പണ്ഡിതരുടെ ബഹുമാനം നേടാൻ പതിനെട്ട് വേദശാഖകളിൽ പ്രവീണരായ പണ്ഡിതന്മാർ അവിടെ എത്തിയിരുന്നു; ആ പരിശോധകർക്ക് അവർ മുന്നോട്ടുവെച്ച വേദവാക്യങ്ങൾ അദ്ദേഹം വിശദീകരിച്ചു, ആറ് (എതിർ) ദർശനങ്ങളെ ഖണ്ഡിച്ചു.",
        "0.15": "അവർ ഓരോരുത്തരായി അവരവരുടെ ശാഖയിലും അവരവരുടെ ദർശനത്തിലും അദ്ദേഹത്തെ പരീക്ഷിച്ചു; തോറ്റുപോയി അവർ പറഞ്ഞു: “ഹേ ഋഷേ, അങ്ങ് യഥാർത്ഥത്തിൽ സർവ്വജ്ഞനാണ്; അങ്ങേക്ക് തുല്യനായി ആരുമില്ല.”",
        "0.16": "ശോഭന ഭട്ടൻ എന്ന പേരുള്ള ഒരാൾ — മൂന്നു വേദങ്ങളുടെ എല്ലാ ശാഖകളിലും അധ്യാപകനും ആ സദസ്സിൽ പ്രമുഖനായി കരുതപ്പെട്ടവനും — സന്തോഷത്തോടെ പൂർണ്ണപ്രജ്ഞന് വീണ്ടും വീണ്ടും വണങ്ങി.",
        "0.17": "തന്റെ കാലത്തെ ദർശനങ്ങളെ ഖണ്ഡിക്കുകയും വേദങ്ങളിലും മഹാഭാരതത്തിലും പുരാണങ്ങളിലും ഉറച്ചുനിൽക്കുകയും ചെയ്ത ആ ജ്ഞാനി, തർക്കശാസ്ത്രജ്ഞരുടെ ശിരോമണി, ഈ വ്യാഖ്യാനം മധ്വനിൽ നിന്ന് കേട്ടു.",
        "0.18": "ഈ അദ്ഭുതകരമായ വ്യാഖ്യാനം കേട്ടശേഷം അദ്ദേഹം മറ്റൊന്നിലും ആനന്ദം കണ്ടില്ല; താമരത്തേൻ രുചിച്ച വെള്ളച്ചിറകുള്ള അരയന്നം മറ്റൊന്നും ആഗ്രഹിക്കാത്തതുപോലെ.",
        "0.19": "ഓരോ സദസ്സിലും തിളങ്ങി, ആനന്ദതീർത്ഥരുടെ സിദ്ധാന്തത്തിൽ നിരത്തിയ യുക്തികളാൽ എതിരാളികളെ ചിതറിച്ചു, അവരെ തോൽപ്പിച്ചു, യോജിച്ച ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.20": "“അയ്യോ! എല്ലാത്തരം ശംഖുകളും പൊടിക്കുന്ന ഒരു ചുണ്ണാമ്പുകാരൻ, അമൂല്യമായ വലംപിരി ശംഖ് (ദക്ഷിണാവർത്തം) പല ശ്രമങ്ങൾക്ക് ശേഷവും പൊടിക്കാനാവാതെ, അത് ഉപയോഗശൂന്യമെന്ന് കരുതി എറിഞ്ഞുകളഞ്ഞു.",
        "0.21": "അളവില്ലാത്ത ജ്ഞാനമുള്ള, നേടാൻ പ്രയാസമുള്ള ഇത്തരമൊരു ശാസ്ത്രം കൈയെത്തുംദൂരത്ത് വന്നപ്പോൾ അത് ഉപേക്ഷിക്കുന്നവൻ, ആ ചുണ്ണാമ്പുകാരന്റെ അതേ മനസ്സുള്ള ദുഷ്ടനാണ്; അല്ല, അവനെക്കാൾ താഴ്ന്ന മനസ്സുള്ള ആരുമില്ല.",
        "0.22": "അതിന്റെ പ്രത്യേക മൂല്യം അറിഞ്ഞ മറ്റൊരാൾ അത് വിറ്റ് ധാരാളം സമ്പത്ത് നേടി; എന്നിട്ടും അതിന്റെ അമൂല്യമായ ഗുണത്തിന്റെ വില അവന് ലഭിച്ചില്ല; ഇവിടെ ഭാഗ്യം യോഗ്യതയെ പിന്തുടരുന്നതാണല്ലോ.",
        "0.23": "അതുപോലെ, ഇതിൽ നിന്ന് പ്രകടമായ ചില പുരോഗതി നേടിയിട്ടും, മനസ്സിന്റെ ചെറുപ്പം കാരണം അതിന്റെ പൂർണ്ണഫലം നേടാത്തവൻ, അയ്യോ, ആ മനുഷ്യനെപ്പോലെയാകുന്നു.",
        "0.24": "ഒരു ഉദാരനായ രാജാവ് വലിയ വില നൽകി അത് വാങ്ങി, ഭക്തിയോടെ അതിനെ നിരന്തരം ആരാധിച്ച്, വാക്കിനും ചിന്തയ്ക്കും എത്തിപ്പിടിക്കാനാവാത്ത സമ്പത്ത് നേടി.",
        "0.25": "ആഗ്രഹങ്ങൾ സാധിപ്പിക്കുന്ന ഈ ശാസ്ത്രവൃക്ഷത്തിന്റെ പൂർണ്ണഫലം, ആ ഉത്തമ രാജാവിനെ അനുകരിക്കുന്നവനല്ലാതെ മറ്റാർക്കാണ് നേടാനാവുക?” ഇങ്ങനെ പറഞ്ഞ് അദ്ദേഹം ജനങ്ങളെ സന്തോഷിപ്പിച്ചു.",
        "0.26": "അത്തരം കവികൾ മാത്രമല്ല, ആദരണീയമായ പാദങ്ങളുള്ളവനെ ആദരിച്ചത്; സത്യസിദ്ധാന്തത്തിന്റെ ഉദയത്തിലുള്ള സന്തോഷത്താൽ ശിവൻ, ഇന്ദ്രൻ, ബൃഹസ്പതി, മറ്റു ദേവന്മാരും ധാരാളമായി ആദരിച്ചു.",
        "0.27": "യാത്ര ചെയ്യുമ്പോൾ, വലിയ വേദന നീക്കുന്ന തന്റെ ഉപദേശജലത്താൽ സജ്ജനങ്ങൾ വേഗം നിറഞ്ഞു — മഴക്കാലത്ത് താഴ്ന്ന നിലം നിറയുന്നതുപോലെ; എന്നാൽ ദുഷ്ടന്മാർ ഉയർന്ന നിലംപോലെ നിറഞ്ഞില്ല.",
        "0.28": "ലോകം മുഴുവൻ അദ്ഭുതപ്പെടുത്തിയ തന്റെ പ്രവൃത്തികൾ കാരണം ജനങ്ങൾ വഴിയിൽ തിങ്ങിക്കൂടി ആദരിച്ചു; രജതപീഠപുരത്ത് (ഉഡുപ്പിയിൽ) തിളങ്ങുന്നവനും ശിവൻ (മംഗളസ്വരൂപൻ, അനന്തശായി) എന്ന് സ്തുതിക്കപ്പെടുന്നവനുമായ ഭഗവാനെ അദ്ദേഹം വണങ്ങി.",
        "0.29": "അച്യുതന് പ്രിയനായ ദശപ്രമതി (മധ്വൻ) എത്തി തന്നെ വണങ്ങുന്നത് അച്യുതപ്രേക്ഷർ കണ്ടപ്പോൾ, ഉള്ളിൽ തോന്നിയ സന്തോഷത്തിന് അതിരില്ലായിരുന്നു.",
        "0.30": "തുല്യതയില്ലാത്ത വ്യാഖ്യാനം മുൻകൂട്ടി അയച്ചത് കണ്ടപ്പോൾ ആ ശ്രേഷ്ഠ തപസ്വിക്ക് പരമസന്തോഷം തോന്നി; ഇപ്പോൾ, നിർമ്മലമായി പുഞ്ചിരിക്കുന്ന, ദീർഘകാലം കാണാൻ ആഗ്രഹിച്ചവനെ കണ്ടപ്പോൾ അതിലും വലിയ സന്തോഷം.",
        "0.31": "ദർശനസമുദ്രമായ പൂർണ്ണപ്രജ്ഞനിൽ നിന്ന് തപസ്വികളുടെ രാജാവ് ഭാഷ്യം എന്ന ആനന്ദദായകമായ അമൃത് സ്വീകരിച്ചു; അദ്ഭുതകരമായി, ഈ മേഘം മറ്റുള്ളവരെ അത് കുടിപ്പിക്കുമ്പോഴും സ്വയം അത് നഷ്ടപ്പെടുത്തിയില്ല.",
        "0.32": "പിന്നീട് സൗജന്യവും ബുദ്ധിമാനുമായ മധ്വൻ, സ്വഭാവത്താൽ ഉത്തമനെങ്കിലും കാലക്രമേണ തെറ്റായ സിദ്ധാന്തത്തിൽ മനസ്സ് ആണ്ടുപോയ തന്റെ ഗുരുവിനോട്, സൗമ്യമായ ബോധ്യപ്പെടുത്തലോടെ ഭാഷ്യത്തിന്റെ പല ഗുണങ്ങളും വിവരിച്ചു.",
        "0.33": "വൈദ്യനെപ്പോലെ, സമയോചിതമായി ശരിയായ വാക്കുകളും യുക്തികളും കൊണ്ട് വീണ്ടും വീണ്ടും ഉപദേശിച്ച്, ആ ജ്ഞാനി, ഗുരുവിന്റെ ഹൃദയത്തിൽ ആഴത്തിൽ വേരൂന്നിയ, ഇപ്പോഴും നിലനിൽക്കുന്ന വെറുപ്പിന്റെ മൂലകാരണം ചിന്തിച്ചു.",
        "0.34": "ഹംസരാജാവ് മാനസസരസ്സിൽ നിന്ന് കാക്കയെ വേഗത്തിൽ ചിറകടിച്ചും ഉച്ചത്തിൽ ശബ്ദിച്ചും ഓടിക്കുന്നതുപോലെ, ഹംസരാജാവായ ഋഷി തന്റെ ഗുരുവിന്റെ മനസ്സിൽ നിന്ന് കലിയുടെ കറ — ഏകപക്ഷീയമായ കാഴ്ചപ്പാട് — യുക്തിവാദങ്ങളാലും ഗംഭീരമായ ശബ്ദത്താലും ഓടിച്ചു.",
        "0.35": "അപ്പോൾ അച്യുതപ്രേക്ഷരുടെ മനസ്സ് വളരെ തെളിഞ്ഞു തിളങ്ങി — കളങ്കമില്ലാത്ത ചന്ദ്രബിംബംപോലെ, പൂർണ്ണമായി വിരിഞ്ഞ താമരപോലെ, ശരത്കാലത്തെ ജലംപോലെ.",
        "0.36": "മുൻപ് തെറ്റായ സിദ്ധാന്തത്തിൽ മുറുകെപ്പിടിച്ചിരുന്നവൻ, മധ്വന്റെ ഉപദേശം കേട്ട് സന്തോഷിച്ചു; ഭ്രമത്താൽ ഉപ്പുവെള്ളം കുടിച്ച ദാഹാർത്തൻ വീണ്ടും വീണ്ടും അമൃത് കുടിക്കുന്നതുപോലെ.",
        "0.37": "ഹൃദയമെന്ന വിശാലമായ ആകാശത്ത് നിലകൊള്ളുന്ന ആ രണ്ടു തപസ്വികൾ, സത്യസിദ്ധാന്തം പ്രകാശിപ്പിച്ച്, മനുഷ്യരെ മോഹിപ്പിക്കുന്ന മഹാന്ധകാരത്തെ അകറ്റി — രാത്രിയിൽ ചന്ദ്രനും പകൽ സൂര്യനും എന്നപോലെ.",
        "0.38": "വലിയ സ്നേഹത്തോടെ അദ്ദേഹം സജ്ജനങ്ങളെ സത്യസിദ്ധാന്തവും (സുദർശനം) സുദർശനചക്രമുദ്രയും (ചക്രാങ്കനം) സ്വീകരിപ്പിച്ചു; ദുഷ്ടന്മാർക്ക് സ്വഭാവത്താൽ വെറുപ്പുള്ളവയായ അവ ഭയങ്കര പാപങ്ങളുടെ സൈന്യങ്ങളെ തകർക്കുന്നു.",
        "0.39": "ഒരിക്കൽ രജതപീഠപുരത്ത് വസിക്കുമ്പോൾ, ഭഗവാനല്ലാതെ മറ്റൊരു അഭയവുമില്ലാത്ത സജ്ജനങ്ങൾക്ക്, അവരുടെ ആത്മീയ വിജയത്തിനുള്ള തടസ്സങ്ങൾക്കും മറ്റ് ദുരിതങ്ങൾക്കുമുള്ള പരിഹാരം നൽകണമെന്ന് കപടമല്ലാത്ത കാരുണ്യത്താൽ അദ്ദേഹം ആഗ്രഹിച്ചു.",
        "0.40": "ദശമതി (മധ്വൻ) ഗോപികമാർക്ക് പ്രിയനായ ശ്രീയുടെ നാഥന്റെ കല്ലുവിഗ്രഹം മൂന്നോ നാലോ ശിഷ്യന്മാരെക്കൊണ്ട് ഒരു കുളത്തിൽ വൃത്തിയാക്കിച്ചു; പിന്നീട് അത് സ്നാനത്തിനായി സ്വയം അവിടെ മുക്കി.",
        "0.41": "എല്ലാം ശുദ്ധമാക്കുന്ന ഭഗവാന്റെ സ്പർശനത്താൽ ഹരിയുടെ സാന്നിധ്യത്തിന്റെ ഇരിപ്പിടമായി മാറിയ ആ വിഗ്രഹം, ഒന്നിച്ചു വലിച്ചാൽപ്പോലും മുപ്പതു പേർക്ക് ഉയർത്താൻ പ്രയാസമുണ്ടായിരുന്നത്, അദ്ദേഹം അനായാസം മഠത്തിലേക്ക് കൊണ്ടുപോയി.",
        "0.42": "അവിടെ, ശുദ്ധവും ഉചിതവുമായ പ്രതിഷ്ഠയോടെ, മൃദുവായ പുഞ്ചിരിയുള്ള മനോഹര മുഖമുള്ള, ഇന്ദ്രിയങ്ങൾക്ക് അതീതമായ യഥാർത്ഥ രൂപമുള്ള നന്ദപുത്രന്റെ മനോഹര ആരാധനാ വിഗ്രഹം അദ്ദേഹം സ്ഥാപിച്ചു.",
        "0.43": "(ശ്ലോകങ്ങൾ 43 മുതൽ 46 വരെ ഒരൊറ്റ വാക്യമാണ്.) ദേവതാനുഗ്രഹമായ ഒരു കഴിവിനാൽ അഭിമാനികളായവരെപ്പോലും തന്റെ അധീനതയിലാക്കിയ ഒരു ദുഷ്ടൻ ഉണ്ടായിരുന്നു; യാഗകർത്താവെന്ന തന്റെ നിലയെക്കുറിച്ച് ബോധവാനായ അവൻ, പേരിൽ ‘വാർദ്ധക്യം’ (ജര) എന്ന വാക്ക് അടങ്ങിയവൻ (പണ്ടത്തെ ജരാസന്ധനെപ്പോലെ).",
        "0.44": "തനിക്ക് പ്രിയമായ യാഗം നശിപ്പിക്കാൻ ഒരുങ്ങിയ ആ പാപിയെ കണ്ട മധ്വൻ, രാജാവിന്റെയും മറ്റു യോഗ്യരുടെയും സാന്നിധ്യത്തിൽ അവനെയും അവൻ നിയോഗിച്ച ആളുകളെയും തോൽപ്പിച്ചോടിച്ചു;",
        "0.45": "സ്വന്തം തേജസ്സാൽ ലോകത്തെ അദ്ഭുതപ്പെടുത്തിയവനും, ജനങ്ങൾ വീണ്ടും വീണ്ടും പാദങ്ങളെ ആരാധിച്ചവനും, എല്ലാ ദിക്കുകളിലും അദ്ഭുതകരമായ വിജയങ്ങളുടെ കീർത്തിയുള്ളവനും, ദിവസവും സ്വന്തക്കാരെ സന്തോഷിപ്പിച്ചവനുമായ അദ്ദേഹം,",
        "0.46": "വാസുദേവന് പ്രിയനായ ഏറ്റവും ജ്ഞാനിയായവൻ, പണ്ട് ഭീമരൂപത്തിൽ ജരാസന്ധനെ വധിച്ചശേഷം ധർമ്മപുത്രനെക്കൊണ്ട് (യുധിഷ്ഠിരനെക്കൊണ്ട്) യാഗം നടത്തിച്ചതുപോലെ, ഭക്തനായ ബ്രാഹ്മണൻ വാസുദേവനെക്കൊണ്ട് (ഗുരുവിന്റെ പുത്രൻ) യാഗം ശരിയായി നടത്തിച്ചു.",
        "0.47": "ഈ യാഗത്തിൽ സർവ്വജ്ഞന്റെ അനുജൻ (ഭാവിയിലെ വിഷ്ണുതീർത്ഥർ) ഹോതാവായി, യാജ്യവും ഉചിതമായ അനുവാക്യവും സ്തോത്രങ്ങളും പ്രവർഗ്യകർമ്മത്തിന്റെ തേജസ്സുമായി ദേവഗണങ്ങളെ സന്തോഷിപ്പിച്ചു.",
        "0.48": "തീക്ഷ്ണബുദ്ധിയോടെ, ഉത്തമമായ വൈശ്വദേവശാസ്ത്ര സൂക്തങ്ങളുടെ മൂർച്ചയുള്ള ശ്രേണി അദ്ദേഹം ചൊല്ലി; രാക്ഷസന്മാരെയും അസുരന്മാരെയും അകറ്റി, ഒരു മഹാവീരനെപ്പോലെ ദേവന്മാർക്ക് അവരുടെ ഭാഗങ്ങൾ സ്വീകരിക്കാൻ ഇടയാക്കി.",
        "0.49": "ദൃശ്യമായ ശരീരത്തോടെ വായു പോലും ആഗ്രഹിച്ച ആ മഹായജ്ഞം ആർക്ക് വിവരിക്കാനാകും — മഹാബലനായ വായു, സോമം ആദ്യം മൂന്നു തവണ കുടിച്ച്, എല്ലാ ദേവന്മാരെയും ജയിച്ചവൻ?",
        "0.50": "ബ്രഹ്മത്തെ അറിയാൻ മനസ്സുറപ്പിച്ചവർക്ക് കർമ്മം ഒരു സഹായകോപാധിയായി മാറുന്നു എന്ന് കാണിക്കാൻ, പരമത്തെ അറിയുന്നവൻ യജ്ഞകർമ്മവും ധർമ്മാചരണവും നടത്തിച്ചു.",
        "0.51": "അദ്ദേഹം ചെയ്ത കർമ്മങ്ങളും പറഞ്ഞ മനോഹര വാക്കുകളും, എല്ലാം, പറയാൻ തന്നെ അദ്ഭുതകരമായി, ലോകത്തെ മുഴുവൻ അമ്പരപ്പിച്ച് തിളങ്ങുന്നു; അദ്ദേഹത്തിന്റെ മനസ്സ് വിശാലമായിരുന്നു.",
        "0.52": "കുലപാരമ്പര്യത്തിനപ്പുറം പോയ വിശാലജ്ഞാനി, ജീവികളെ താങ്ങുന്ന അനേകം നദികൾ കടന്നു (ശ്ലേഷത്താൽ, ലൗകിക നേട്ടങ്ങളെക്കുറിച്ച് സംസാരിക്കുന്നതായി തോന്നുന്ന അനേകം വേദവാക്യങ്ങൾക്കപ്പുറം പോയി); പണ്ടത്തെപ്പോലെ, ക്ഷീണമില്ലാതെ, കൃഷ്ണന് പ്രിയമായ ആ പരമ ആശ്രമത്തിൽ (ബദരിയിൽ) വീണ്ടും എത്തി.",
        "0.53": "പണ്ട് ഹനുമാൻ രൂപത്തിൽ ഹരി അദ്ദേഹത്തിന് മറ്റാർക്കും ലഭിക്കാത്ത സഹഭോഗത്തിന്റെ സഖ്യം നൽകിയിരുന്നു; തന്റെ ആഗ്രഹം സാധിപ്പിച്ചവന് തിരികെ നൽകാൻ അതിലും വലിയത് ഒന്നും കാണാതെ, ഹരി ആ ദാനം തന്നെ വർദ്ധിപ്പിച്ചു.",
        "0.54": "പിന്നെ, ലോകങ്ങളുടെ ക്ഷേമം ചെയ്യുന്ന തന്റെ ഗുരുവിനെ (വ്യാസനെ) ആദരപൂർവ്വം വണങ്ങി, യോജിച്ച കൽപ്പനപ്രകാരം അനുയായികളോടൊപ്പം അദ്ദേഹം പുറപ്പെട്ടു; സ്വജനങ്ങൾ സന്തോഷത്തോടെ എതിരേറ്റ മഹാമനസ്കനായ കീർത്തിസമുദ്രം, രജതപീഠത്തിൽ (ഉഡുപ്പിയിൽ) വസിക്കുന്ന ഹരിയെ വണങ്ങി.",
        "0.55": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട ഒമ്പതാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "ബദരിയിൽ നിന്ന് മടങ്ങിയ മധ്വൻ ബ്രഹ്മസൂത്രഭാഷ്യം രചിക്കുന്നു; സത്യതീർത്ഥർ അത് എഴുതിയെടുക്കുന്നു, അതിന്റെ ഉപദേശം പ്രചരിക്കുന്നു. കേൾക്കുന്ന പണ്ഡിതന്മാർ വശീകരിക്കപ്പെടുന്നു; പഴയ ഗുരു സന്തോഷിക്കുന്നു. നന്ദപുത്രനായ ശ്രീകൃഷ്ണവിഗ്രഹം ഉഡുപ്പിയിൽ പ്രതിഷ്ഠിക്കുന്നു; യജ്ഞത്തോടെ സർഗ്ഗം അവസാനിക്കുന്നു, മധ്വൻ കൂടുതൽ സഞ്ചാരങ്ങൾക്കായി യാത്ര തിരിക്കുന്നു."
    },
    "sumadhva-vijaya-10": {
      "verses": {
        "0.0": "പിന്നെ മാധവന്റെ ഗുണങ്ങൾ സ്ഥാപിക്കുന്നവനും പാപപഥങ്ങളിലൂടെ പോകുന്നവരെ ചുട്ടെരിക്കുന്നവനുമായ മധ്വനാകുന്ന സൂര്യൻ, വസന്തത്തിൽ സൂര്യൻ വൃഷഭരാശിയെ അലങ്കരിക്കുന്നതുപോലെ, ശുക്രന്റെ ഇരിപ്പിടമായ ഭൃഗുവംശത്തിന്റെ ആഭരണമായ നാടിനെ (പരശുരാമന്റെ നാടായ തുളുനാടിനെ) ഉടൻ സമൃദ്ധമായി അലങ്കരിച്ചു.",
        "0.1": "ദശമതിയുടെ ഒരു ശിഷ്യൻ, ആകാംക്ഷയോടെ വണങ്ങി നിന്ന സജ്ജനങ്ങൾക്കുവേണ്ടി, വീരനെ സ്തുതിച്ചുകൊണ്ട് വിവിധ മനോഹര വൃത്തങ്ങളിൽ കാവ്യംപോലെ വാക്കുകൾ പറഞ്ഞു.",
        "0.2": "“ഒരു ദേവന്റെ ആയുസ്സുകൊണ്ടുപോലും മധ്വന്റെ ലോകത്തെ അദ്ഭുതപ്പെടുത്തുന്ന പ്രവൃത്തികൾ മുഴുവൻ പറയാനാവില്ല; എങ്കിലും കേൾക്കാൻ ആഗ്രഹിക്കുന്നവർക്കായി അല്പം ഇപ്പോൾ വിവരിക്കാം.",
        "0.3": "ഒരിക്കൽ യാത്രക്കാരെക്കൊണ്ട് (ഒരു കുളം) കുഴിപ്പിച്ചുകൊണ്ടിരുന്ന ഈശ്വരദേവൻ അദ്ദേഹത്തോടും അതുപോലെ ചെയ്യാൻ പറഞ്ഞു; മധ്വൻ അദ്ദേഹത്തോട് പറഞ്ഞു: ‘ഞങ്ങൾക്ക് പരിചയമില്ലാത്തതിനാൽ, അത് ചെയ്ത് ഞങ്ങൾക്ക് കാണിച്ചുതരൂ.’",
        "0.4": "രീതി കാണിക്കാനായി ദുഷ്ടൻ കുഴിക്കാൻ തുടങ്ങി; എന്നാൽ വിശാലമനസ്സുള്ളവന്റെ ശക്തിയാൽ അവന് നിർത്താനായില്ല; നിസ്സഹായനായി അവൻ കുഴിച്ചുകൊണ്ടേയിരുന്നു.",
        "0.5": "(‘ന’ എന്ന അക്ഷരം മാത്രം കൊണ്ടുള്ള ശ്ലോകം.) കുറവില്ലാത്ത, അനേകം ഗുണങ്ങളുള്ള ഇവനാൽ പ്രേരിതനാകാത്ത ആരുമില്ല; എന്നാൽ ഇവനാൽ പ്രേരിതനാകാത്തവൻ, തീർച്ചയായും, ഈശ്വരനും ജീവന്മാരുടെ നേതാക്കളുടെ നേതാവും തന്നെയാണ്.",
        "0.6": "ഓർക്കുന്നവർക്ക് സകല ജന്മങ്ങളിൽ നിന്നുമുണ്ടാകുന്ന ദുഃഖസമുദ്രം നീങ്ങിപ്പോകുന്നു; അദ്ഭുതമില്ല — അത്തരം വായുവിനെ സ്തുതിക്കുന്നതിൽ ശേഷൻ, ശിവൻ (ഭവൻ), ബ്രഹ്മാവ് തുടങ്ങിയവരും സന്തോഷിക്കുന്നു. (ആദ്യ പാദവും അവസാന പാദവും ഒരുപോലെ ശബ്ദിക്കുന്ന യമകശ്ലോകം.)",
        "0.7": "ഒരിക്കൽ സഞ്ചരിക്കുമ്പോൾ, വൈഷ്ണവരിൽ ശ്രേഷ്ഠനായ ആരാധ്യനായ ഗുരു, വിശ്വസ്തരായ ശിഷ്യന്മാർ ചുറ്റിനിൽക്കെ, ശത്രുഭയത്താൽ എല്ലാ തോണികളും ഉപേക്ഷിക്കപ്പെട്ട ഗംഗയുടെ തീരത്തെത്തി.",
        "0.8": "വിലക്കിയവരെ അവഗണിച്ച്, കാരുണ്യവാനായ, സ്വയം അടിസ്ഥാനമായവൻ, തന്റെ വാക്കനുസരിച്ച് ഓരോരുത്തരും മുന്നിലുള്ളവനെ പിടിച്ചുകൊണ്ട് മറ്റുള്ളവർക്ക് കടക്കാനാവാത്ത ആ നദി, തന്റെ അനുയായികളെ സംസാരസാഗരം കടത്തുന്നതുപോലെ, കളിയായി കടത്തി.",
        "0.9": "“ഇവർ ശത്രുക്കളുടെ സുഹൃത്തുക്കളാണ്; തടയൂ, തടയൂ! മറുകരയിലെത്തുന്നതിനുമുമ്പ് കൊല്ലൂ, കൊല്ലൂ!” എന്ന് നിലവിളിച്ചുകൊണ്ട് രാജാവിന്റെ തുർക്കി സൈനികർ ഓടിയെത്തിയപ്പോൾ, അദ്ദേഹം അവരുടെ സ്വന്തം ഭാഷയിൽ ഉച്ചത്തിൽ അവരെ വിളിച്ചു:",
        "0.10": "“വിഡ്ഢികളേ, അവിവേകത്തോടെ വെള്ളത്തിലേക്ക് ചാടരുത്! നിങ്ങൾക്ക് ഭയം വേണ്ട; നിങ്ങൾ അനേകരാണ്, ഞങ്ങൾ കുറച്ചുപേരേയുള്ളൂ. നിങ്ങളുടെ യജമാനനായ രാജാവിനെ കാണാനാണ് ഞങ്ങൾ വരുന്നത്; എന്തിനാണ് നിങ്ങൾ വഴക്കിടാൻ ആഗ്രഹിക്കുന്നത്?”",
        "0.11": "ഈ വാക്കുകളാൽ അദ്ദേഹം ശത്രുക്കളെ തടഞ്ഞുനിർത്തി, മന്ത്രശക്തിയാൽ പാമ്പാട്ടി സർപ്പങ്ങളെ തടഞ്ഞുനിർത്തുന്നതുപോലെ; മരണഭയമാകുന്ന നദിയും ദിവ്യനദിയും ഒരുമിച്ച് കടന്ന് തന്റെ ജനങ്ങളെ മറുകരയിലെത്തിച്ചു.",
        "0.12": "ആയിരക്കണക്കിന് ക്രൂരസൈനികർ വളഞ്ഞിട്ടും, നടപ്പിൽ ഇളകാത്ത ലോകനാഥൻ, കുറുക്കന്മാരുടെ കൂട്ടത്തിനിടയിലെ സിംഹംപോലെ നടന്നുനീങ്ങി തിളങ്ങി.",
        "0.13": "സിംഹത്തിന്റെ ശരീരഘടനയും ഉയരവുമുള്ള, ദേവന്മാർക്കോ അസുരന്മാർക്കോ ഇളക്കാനാവാത്ത ശരീരമുള്ള അദ്ദേഹം തന്റെ നഗരത്തിനടുത്തെത്തുന്നത് കണ്ട രാജാവ്, കൊട്ടാരത്തിന്റെ മുകളിൽ നിന്ന് പറഞ്ഞു:",
        "0.14": "“ഹേ കരുണാമയനേ, ശത്രുരാജാക്കന്മാരുടെ ചാരന്മാരെന്ന് സംശയിച്ച് യാത്രക്കാരെ വെട്ടിവീഴ്ത്താൻ പ്രതിജ്ഞയെടുത്ത യമദൂതന്മാരെപ്പോലെയുള്ള എന്റെ കഠിന സൈനികരാൽ അങ്ങ് എങ്ങനെ കൊല്ലപ്പെട്ടില്ല?",
        "0.15": "തോണിയില്ലാതെ ദിവ്യനദി എങ്ങനെ കടന്നു? അങ്ങ് എന്ത് ചെയ്യാനാഗ്രഹിക്കുന്നു?” ഇങ്ങനെ പറഞ്ഞ രാജാവിനോട് പുരുഷോത്തമന്റെ മഹത്തായ ദാസൻ മറുപടി പറഞ്ഞു:",
        "0.16": "“പ്രപഞ്ചത്തിന്റെ പ്രകാശമായ തേജസ്വിയായ ആ ദൈവത്തിന്റെ കൃപയാൽ ഞങ്ങൾ എല്ലാം ചെയ്യുന്നു; ഇപ്പോൾ ഞങ്ങൾ വേഗത്തിൽ വടക്കൻ ദിക്കിലേക്ക് പോകുന്നു.” രാജാവിന്റെ സ്വന്തം ഭാഷയിൽ അദ്ദേഹം ഇങ്ങനെ അദ്ഭുതകരമായ വാക്കുകൾ പറഞ്ഞു.",
        "0.17": "അദ്ദേഹത്തിന്റെ ആഴവും സ്ഥൈര്യവും മഹാധൈര്യവും ഉത്കൃഷ്ടതയും പരമമായ തേജസ്സും കാലദേശങ്ങൾക്ക് യോജിച്ച വാക്കുകളും വ്യക്തമായി തിരിച്ചറിഞ്ഞ രാജാവ് അദ്ഭുതപ്പെട്ടു; ഉടൻ തന്നെ തന്റെ രാജ്യത്തിന്റെ പകുതി അദ്ദേഹത്തിന് വാഗ്ദാനം ചെയ്തു.",
        "0.18": "ശിക്ഷയ്ക്ക് യോഗ്യനെന്ന് രാജാവിന്റെ ആളുകൾ കരുതിയവൻ, രാജ്യത്തിന് യോഗ്യനെന്ന് കരുതപ്പെട്ടു. തനിക്ക് വഴി ബലമായി കടക്കാമായിരുന്നിട്ടും, അപകടസമയത്ത് പിന്തുടരേണ്ട നയം പഠിപ്പിക്കാൻ മാത്രമാണ് അദ്ദേഹം അങ്ങനെ പ്രവർത്തിച്ചത്.",
        "0.19": "ഒരിക്കൽ തങ്ങളുടെ നേരെ പാഞ്ഞടുക്കുന്ന കവർച്ചക്കാരെ കണ്ട് അദ്ദേഹം സ്വന്തം ജനങ്ങളെ മാറ്റിനിർത്തി, അത് സമ്പത്താണെന്ന് അവർ കരുതുന്നതിനായി കൈയിൽ ഒരു വസ്ത്രക്കെട്ടുമായി അവർക്കിടയിൽ നീങ്ങി; അവരെ കുഴപ്പത്തിലാക്കി, അർജുനൻ (വിജയൻ) ഒരിക്കൽ സംശപ്തകരോട് ചെയ്തതുപോലെ, അവരെ പരസ്പരം അടിപ്പിച്ചു.",
        "0.20": "മറ്റൊരിടത്ത്, തങ്ങളെ കൊല്ലാൻ വന്ന നൂറ് ധീരരായ കവർച്ചക്കാർക്കെതിരെ, അനുഗൃഹീതരിൽ ശ്രേഷ്ഠനായവൻ, അവരുടെ മഴുവൻ പിടിച്ചെടുത്ത് സംഘത്തെ അടിച്ച ഒരൊറ്റ ശിഷ്യനിലൂടെ വേഗം അവരെ ഓടിച്ചു.",
        "0.21": "ഒരിടത്ത് കവർച്ചക്കാർ, അദ്ദേഹത്തെയും കൂട്ടരെയും പാറക്കൂട്ടമെന്ന് തെറ്റിദ്ധരിച്ച്, കടന്നുപോയി; പിന്നീട് അവരെ വീണ്ടും കണ്ടപ്പോൾ അവർ അദ്ഭുതത്തോടെ അദ്ദേഹത്തെ വണങ്ങി.",
        "0.22": "ഹിമാലയത്തിനടുത്ത്, സത്യതീർത്ഥരെ നശിപ്പിക്കാൻ ഇഷ്ടം പോലെ കടുവയുടെ രൂപത്തിൽ ഒരു അസുരൻ വന്നപ്പോൾ, ജ്ഞാനി ഒരു കളിയായ കൈത്തൊടലിനാൽ തന്നെ അവനെ വീഴ്ത്തി.",
        "0.23": "നാരായണനിൽ (വ്യാസനിൽ) നിന്ന് അദ്ദേഹത്തിന് ശുദ്ധശിലയാൽ നിർമ്മിച്ച ശാലഗ്രാമങ്ങൾ ലഭിച്ചു; അവയിൽ ദേവശത്രുക്കളുടെ എതിരാളിയായ ഭഗവാൻ പത്മയോടൊപ്പം (ലക്ഷ്മിയോടൊപ്പം) എപ്പോഴും സന്നിഹിതനാണ്.",
        "0.24": "ലോകത്തിലെ ഏകപുണ്യവാനായി അദ്ദേഹത്തെ കണ്ട പരാശര്യൻ (വ്യാസൻ), പരമസത്യം സ്ഥാപിക്കുന്നതിനായി മഹാഭാരതത്തിന്റെ പരമതാൽപ്പര്യം വ്യക്തമായി അവതരിപ്പിക്കാൻ വ്യക്തിപരമായി അദ്ദേഹത്തെ നിയോഗിച്ചു.",
        "0.25": "പുണ്യസ്ഥലങ്ങൾ അറിയുന്നവരിൽ ഉത്തമനായ സൗഖ്യതീർത്ഥർ (ആനന്ദതീർത്ഥർ), പുണ്യജലങ്ങളിലും പുണ്യസ്ഥലങ്ങളിലും ഓരോന്നായി ഗോവിന്ദനെ വണങ്ങി; ഉയർന്ന തിരമാലമാലകൾ അണിഞ്ഞ ഗംഗയുടെ അടുത്ത് അനുയായികളോടൊപ്പം വീണ്ടും വന്നു.",
        "0.26": "തോണിയില്ലാത്ത നദി കണ്ടപ്പോഴും, തീരത്തിരിക്കുന്ന ശിഷ്യന്മാർ അത്യന്തം വിഷമത്തിലിരിക്കുന്നത് കണ്ടപ്പോഴും, താമരയുടെ സുഹൃത്തായ സൂര്യൻ സമുദ്രത്തിൽ എത്തിയ സമയത്ത്, അദ്ദേഹം കാൽനടയായി നദി കടന്നു.",
        "0.27": "സമുദ്രം ചാടിക്കടന്ന വാനരരാജാവിനെയോ, ഈ നദിയിൽത്തന്നെ കളിച്ച മനുഷ്യരാജാവിനെയോ (ഭീമനെയോ) അവർ ഓർത്തില്ല; അല്ലെങ്കിൽ ഇത്രയും കഴിവുള്ള ഒരാൾക്ക് എങ്ങനെ ദോഷം ഭയക്കാനാവും?",
        "0.28": "ആകാശത്തിലെ സൂര്യനും മധ്വനാകുന്ന സൂര്യനും — ഇരുവരും ലോകത്തെ പ്രകാശിപ്പിക്കുന്ന രശ്മികളാൽ (അഥവാ: വാക്കുകളാൽ) സമ്പന്നർ — കണ്ണിൽ നിന്ന് മറഞ്ഞപ്പോൾ, ശിഷ്യന്മാരുടെ താമരക്കണ്ണുകളും താമരകളും ഒരുമിച്ച് തിളക്കം നഷ്ടപ്പെടുത്തി.",
        "0.29": "വിനതാസുതനായ ഗരുഡൻ പശുവിന്റെ കുളമ്പടയാളം കടക്കുന്നതുപോലെ അനായാസം, ഭയമില്ലാതെ അദ്ദേഹം നദി കടന്നു; വസ്ത്രംപോലും നനഞ്ഞില്ല; അദ്ഭുതത്താൽ ഉരുകിയ രാജാക്കന്മാരും ബ്രാഹ്മണരും മറ്റുള്ളവരും അദ്ദേഹത്തെ വണങ്ങി.",
        "0.30": "പിന്നെ, ശത്രുവിനെ ഭയന്ന് ആരെയും കടത്താൻ ധൈര്യപ്പെടാതിരുന്ന തോണിക്കാരെക്കൊണ്ട്, അദ്ദേഹത്തിന്റെ തേജസ്സിൽ അദ്ഭുതപ്പെട്ട രാജാവ് അയച്ചതനുസരിച്ച്, അദ്ദേഹം ശിഷ്യന്മാരെ തോണിയിൽ നദി കടത്തി.",
        "0.31": "ഗുരുവിനെ കാണാൻ ഹൃദയം കൊതിച്ച ശിഷ്യന്മാർ, ദിവ്യനദിയുടെ വിശാലമായ തീരം വിളക്കുകളാൽ ജ്വലിക്കുന്നതും, ജനത്തിരക്കുള്ളതും, ചോദ്യങ്ങൾ ചോദിക്കുന്ന പണ്ഡിതസംഘങ്ങളാൽ സമൃദ്ധവുമായി കണ്ടു.",
        "0.32": "അവിടെ അവർ സുഖതീർത്ഥരെത്തന്നെ കണ്ടു — ദേവസഭയിൽ ബ്രഹ്മാവ് എന്നപോലെ, വേദജ്ഞരുടെ മുന്നിൽ അർത്ഥങ്ങളോടും വിശേഷങ്ങളോടും കൂടി വേദം വിശദീകരിക്കുന്നത്.",
        "0.33": "പിന്നെ അദ്ദേഹം ഭരണതലസ്ഥാനമായ ഹസ്തിനപുരത്ത് എത്തി; അവിടെ, അനന്ത ഗുണങ്ങളാൽ സമ്പന്നനായി, നദിയിൽ നിന്ന് അകലെ ഏകാന്തസ്ഥലത്ത് മറ്റൊരു മഠത്തിൽ വാസയോഗ്യമായ (നാല്) മാസങ്ങൾ കഴിച്ചു.",
        "0.34": "ദിവ്യനദി ഭൂമിയെ പിളർന്ന് ഒരു പ്രത്യേക ശാഖയിലൂടെ അദ്ദേഹത്തെ സേവിക്കാൻ അവിടെ എത്തി; അദ്ഭുതമില്ല — ശിവൻ തുടങ്ങിയവർ ആരാധിക്കുന്ന വാണിയും (ഭാരതിയും) അദ്ദേഹത്തിന്റെ സേവകയായിരിക്കുന്നതിൽ സഫലയാകുന്നു.",
        "0.35": "ശരീരധാരിണിയായി അവൾ ആ ശ്രേഷ്ഠ ഗുരുവിന്റെ താമരപ്പാദങ്ങളെ ദൂരെനിന്ന് വണങ്ങി; കൃപയും സൗന്ദര്യവുമുള്ള അവളുടെ രൂപം കണ്ട ശിഷ്യന്മാർ പൂർണ്ണമായും അദ്ഭുതപ്പെട്ടു.",
        "0.36": "പിന്നീട് ഒരിക്കൽ വാരാണസിയിൽ എത്തിയ പാപനാശകൻ, കളിസമയത്ത് അഹങ്കാരം കയറിയ തന്റെ ശക്തരായ ശിഷ്യന്മാരെ കണ്ട്, ഇങ്ങനെ പറഞ്ഞു:",
        "0.37": "“നിങ്ങൾ വീരന്മാരെന്ന് കരുതുന്നവരേ, ഗുസ്തിക്കായി ഇപ്പോൾത്തന്നെ, ഒരുമിച്ച് എന്റെ മേൽ വീഴൂ; ഇവിടെ തന്റെ മുഴുവൻ ശക്തിയും പ്രയോഗിക്കാത്തവൻ എന്റെ കൽപ്പന ലംഘിക്കുന്നു.”",
        "0.38": "ഇങ്ങനെ പറഞ്ഞിട്ട്, തന്നോട് യുദ്ധം ചെയ്യാൻ വന്ന പതിനഞ്ച് യുവാക്കളെയും അദ്ദേഹം ഉടനെ വീഴ്ത്തി; “ശക്തിയുള്ളവൻ എഴുന്നേൽക്കട്ടെ!” എന്ന് പറഞ്ഞ് അദ്ദേഹം മൃദുവായി ചിരിച്ചു.",
        "0.39": "അപ്പോൾ അവർ പറഞ്ഞു: “അങ്ങയുടെ അവയവങ്ങൾ — ഞങ്ങളുടെ ശരീരത്തിൽ അങ്ങയുടെ വിരലുകൾപോലും — മേരുപർവതംപോലെ ഭാരമുള്ളതാണ്; ഞങ്ങൾ താമസിയാതെ നശിച്ചുപോകും. ദയയുള്ള ഗുരോ, ഞങ്ങളെ വിടൂ!”",
        "0.40": "അദ്ദേഹം അവരെ വിട്ടപ്പോൾ അവർ പൂർണ്ണമായി അദ്ഭുതപ്പെട്ടു; കാരണം, ശംഭുവും ശക്രനും ഉൾപ്പെടെ ലോകം മുഴുവൻ, അദ്ദേഹത്തിന്റെ പുരികത്തിന്റെ വെറും കളിയിൽ തന്നെ പൂർണ്ണമായി ഭരിക്കപ്പെടുന്നു എന്ന് അവർ ചിന്തിച്ചിരുന്നില്ല.",
        "0.41": "അമരാവതി (ഇന്ദ്രപുരി) എന്ന് പേരുള്ള ഒരു തപസ്വി, സമർത്ഥനായിരുന്നു; എല്ലാ നിലപാടുകളും തള്ളിക്കളഞ്ഞവൻ, ഗുരുവിനെ പരാജയപ്പെടുത്താൻ ആഗ്രഹിച്ച് പറഞ്ഞു: “ജ്ഞാനത്താൽ സഹായിക്കപ്പെടുന്ന കർമ്മമാണ് (മോക്ഷത്തിനുള്ള) മാർഗ്ഗമെന്ന് തെളിയിക്കൂ.”",
        "0.42": "ഭഗവാനെ സംബന്ധിച്ച് അത് സ്ഥാപിക്കപ്പെട്ടപ്പോൾ, ആക്രോശമുള്ള മനസ്സുള്ള അവൻ യുക്തികൾ തീർന്ന് ‘ജ്ഞാനം’ എന്നാൽ എന്താണെന്ന് ചോദിച്ചു. അവനെ നിശ്ശബ്ദനാക്കി: “നീ ജ്ഞാനിയാണെങ്കിൽ അത് നിനക്ക് അറിയാം; അല്ലെങ്കിൽ നിന്റെ ചോദ്യം തന്നെ ഉയരാനാവില്ല.”",
        "0.43": "വ്യാസന്റെ ശിഷ്യൻ, വ്യാപകമായ അന്ധകാരത്തെ പൂർണ്ണമായി അകറ്റുന്ന വ്യാഖ്യാനത്താൽ ഓരോ സദസ്സിലും തിളങ്ങി; തർക്കിച്ചവരെല്ലാം താമരപോലെ കൈകൂപ്പിയപ്പോൾ സന്തോഷിച്ചു; ശരത്കാലംതോറും ചന്ദ്രൻ താമരകളെ അടച്ചുകൊണ്ട് തന്റെ നിലാവിന്റെ സമ്പത്തോടെ തിളങ്ങുന്നതുപോലെ.",
        "0.44": "(യമകശ്ലോകം; സാരം:) എല്ലാ ശാസ്ത്രങ്ങളിലും പ്രസിദ്ധനായ ഭഗവാൻ, മായയാൽ അല്ലാതെ സ്വന്തം ഇച്ഛയാൽ, ഓരോ യുഗത്തിലും ലോകത്തിന്റെ സൃഷ്ടി, പരിപാലനം, സംഹാരം നടത്തുന്നു; അവൻ മാറ്റമില്ലാതെ നിലകൊള്ളുന്നു, അവന്റെ രൂപം ശുദ്ധജ്ഞാനമാണ് — എന്ന് അദ്ദേഹം പഠിപ്പിച്ചു.",
        "0.45": "“സ്വതന്ത്രനായ വിഷ്ണു എല്ലാറ്റിനെയും നിയന്ത്രിക്കുന്നു, ഈ ലോകത്ത് എപ്പോഴും ലീല ചെയ്യുന്നു; ദുഷ്ടന്മാരെ വീഴ്ത്തുന്നു, സജ്ജനങ്ങളെ ശുദ്ധീകരിക്കുന്നു; എല്ലാ ഗുണങ്ങളും നിറഞ്ഞവനാണെങ്കിലും (പ്രാകൃത) ഗുണങ്ങളിൽ നിന്ന് മുക്തനുമാണ്.”",
        "0.46": "“ശ്രീയുടെ നാഥന് തുല്യനോ ശ്രേഷ്ഠനോ ആരുമില്ലെന്നും, സ്വഭാവത്താൽ പ്രപഞ്ചത്തിൽ നിന്ന് പൂർണ്ണമായി വ്യത്യസ്തനാണെന്നും കരുതപ്പെടുന്നു” — ഈ പരമസത്യങ്ങളും മറ്റും അദ്ദേഹം പൂർണ്ണമായി വിവരിച്ചു.",
        "0.47": "(കുറച്ചു അക്ഷരങ്ങളുള്ള ശ്ലോകം; സാരം:) പ്രമാണങ്ങളിൽ അധിഷ്ഠിതമായ അദ്ദേഹത്തിന്റെ ഉപദേശം, വ്യാപകമായ മായാവാദത്താൽ ഒരിക്കലും തോൽപ്പിക്കപ്പെട്ടില്ല; അതിനെ എതിർക്കുന്നവർ പീഡനത്തിൽ എത്തിച്ചേരുന്നു.",
        "0.48": "ജ്ഞാനി രാജാക്കന്മാർക്ക് സ്വർഗ്ഗത്തിലേക്കുള്ള വഴിയായ കുരുക്ഷേത്രത്തിൽ എത്തി; ആനകൾ തന്റെ കളിയായി വീണ പഴയ ഉത്സവയുദ്ധങ്ങളെ (ഭീമനായി) ഓർത്തു. അദ്ദേഹത്തിന് ചുറ്റും സത്യതീർത്ഥരും മറ്റുള്ളവരും അദ്ഭുതപ്പെട്ടുനിന്നു; തന്റെ പണ്ടത്തെ രാജശരീരത്തിന്റെ ഗദ കാണിച്ചുകൊടുത്തതിൽ അവർ അത്യന്തം സന്തോഷിച്ചു.",
        "0.49": "ഹൃഷീകേശത്തിൽ, ശുഭ്രമായി തിളങ്ങുന്ന ഭഗവാൻ (രുദ്രൻ) ഒരു ബ്രാഹ്മണരൂപത്തിൽ ഒരു നിമിഷം അദ്ദേഹത്തെ വണങ്ങി; വ്യക്തമായി കണ്ടശേഷം ഉടൻ മറഞ്ഞു, എല്ലാവരെയും അദ്ഭുതപ്പെടുത്തി. സ്വപ്നത്തിൽ മറ്റൊരിടത്തുനിന്ന് തന്റെ ഒരാളെ അയച്ചു, അയാൾ സമൃദ്ധമായ ഭക്ഷണം കൊണ്ടുവന്നു; അങ്ങനെ എല്ലാവരുടെയും ഗുരുവായ തന്റെ ഗുരുവിന് സദ്യ നൽകി; മധ്വൻ വേദത്തിന്റെ യഥാർത്ഥ ബന്ധുവാണെന്ന് വെളിപ്പെടുത്തി.",
        "0.50": "വീണ്ടും, ഇഷുപതത്തിൽ എത്തിയപ്പോൾ, രാമന്റെ നാഥനായ പരശുരാമനെ ഭക്തിയോടെ ഓർത്തു; അവിടെ, ഭക്ഷണത്തിനായി രാജാവ് നൽകിയ ആയിരം ഉത്കൃഷ്ടമായ വലിയ രാജകേളി വാഴപ്പഴം കഴിച്ചു.",
        "0.51": "ഗോവ എന്ന ദേശത്ത് പോയി, ശങ്കരൻ എന്ന ബ്രാഹ്മണൻ നൽകിയ നാലായിരം ഭാരമുള്ള, മനോഹരമായ വാഴപ്പഴം കഴിച്ചു, മുപ്പതു കുടം പാൽ കുടിച്ചു; അദ്ദേഹത്തെ തടയാൻ പുറപ്പെട്ടിരുന്ന രാജാവിന്റെ ആളുകൾക്ക് കാണാതെ അദ്ദേഹം കടന്നുപോയി.",
        "0.52": "അതേ ഗോവാപ്രദേശത്ത്, ഒരു സദസ്സിൽ, ജനങ്ങളുടെ അഭ്യർത്ഥനപ്രകാരം, ജനങ്ങളെ ഉറക്കുന്ന തന്റെ അതുല്യമായ ഗാനമാധുര്യത്താൽ, വൃക്ഷങ്ങളിൽ പെട്ടെന്ന് പൂക്കളും ഫലങ്ങളും പ്രത്യക്ഷമാക്കി.",
        "0.53": "അനുഗൃഹീതനായ മധ്വൻ ആദരിക്കപ്പെട്ടു: ദേവശത്രുക്കളുടെ ഹൃദയത്തിൽ തറയ്ക്കുന്ന അമ്പ്, ബ്രഹ്മാവിന് തുല്യൻ, തെറ്റായ സിദ്ധാന്തങ്ങളെ നശിപ്പിക്കുന്നവൻ, തണുത്ത ചന്ദ്രനെപ്പോലെ തിളങ്ങുന്നവൻ, ആഗ്രഹവും മോഹവും അകറ്റുന്നവൻ; എല്ലാറ്റിനും മീതെ വിജയം നൽകുന്ന വിഷ്ണുവിനെയും, ആരാധനയ്ക്ക് യോഗ്യനും ആനന്ദപൂർണ്ണനുമായ ശ്രീധരനെയും എപ്പോഴും സന്തോഷത്തോടെ വണങ്ങുന്നവൻ; രോഗങ്ങളില്ലാത്ത യോഗിയും എല്ലാ സമയത്തും എല്ലാവരുടെയും സുഹൃത്തും.",
        "0.54": "“ലോകത്തിന്റെ ഈ അലങ്കാരത്തിന്റെ മറ്റനേകം പ്രവൃത്തികൾ കേൾക്കുമ്പോഴും, ചിന്തിക്കുമ്പോഴും, പാടുമ്പോഴും ആഗ്രഹിച്ചത് നൽകുന്നു” എന്ന് അമരന്മാർ പ്രഖ്യാപിക്കുന്നു.",
        "0.55": "ഹരിയുടെ പാദങ്ങളിൽ ഭക്തിയുള്ള ആ സമർത്ഥനായ മേഘം (ശിഷ്യൻ), പാണ്ഡിത്യത്തിന്റെ മിന്നലാൽ ദിക്കുകളെ പ്രകാശിപ്പിച്ച്, വൈവിധ്യമാർന്ന വാക്കുകളുടെ മഴയാൽ, സംസാരഭയത്തിന്റെ വലിയ ചൂടേറ്റ് കരിഞ്ഞ സജ്ജനങ്ങളാകുന്ന നല്ല വൃക്ഷങ്ങളുടെ തോട്ടം — ഫലങ്ങളും പൂക്കളുമായ (നല്ല മനസ്സുകൾ) നിറഞ്ഞതും, ഇടതൂർന്ന ആനന്ദമുള്ളതും, ഉപദ്രവമില്ലാത്തതുമായി — വളർത്തി.",
        "0.56": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പത്താം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "വടക്കോട്ടുള്ള രണ്ടാം യാത്ര. ശത്രുസൈനികർക്കിടയിലൂടെ മധ്വൻ ഒരു പോറലുമേൽക്കാതെ കടന്നുപോകുന്നു; ശിഷ്യരോടൊപ്പം ഗംഗ കടക്കുന്നു; ആദ്യം ശിക്ഷിക്കാൻ ആലോചിച്ച രാജാവ് അദ്ദേഹത്തെ ആദരിക്കുന്നു; മഹാഭാരതത്തിന്റെ യഥാർത്ഥ താൽപ്പര്യം വിശദീകരിക്കാൻ വ്യാസൻ അദ്ദേഹത്തെ നിയോഗിക്കുന്നു. വാരാണസിയിലും മറ്റിടങ്ങളിലും അഹങ്കാരികളായ തർക്കവാദികളെ അദ്ദേഹം താഴ്ത്തുന്നു; കുരുക്ഷേത്രത്തിൽ ഭീമനായിരുന്ന കാലത്തെ പ്രവൃത്തികൾ അദ്ദേഹം ഓർക്കുന്നു."
    },
    "sumadhva-vijaya-11": {
      "verses": {
        "0.0": "ശേഷനാഗരാജാവ്, സനകാദി ഋഷിമാരോടൊപ്പം, ആഴമുള്ള അർത്ഥങ്ങൾ നിറഞ്ഞ അദ്ദേഹത്തിന്റെ പ്രഭാഷണം ശ്രവിച്ചു; ഇവിടെയുള്ള ജനങ്ങൾക്ക് ആകാശത്ത് മങ്ങിയേ കാണാനായുള്ളൂ; അദ്ദേഹം തന്റെ തേജസ്സ് വേഗം പിൻവലിച്ച് തന്റെ വാസസ്ഥലത്തേക്ക് മടങ്ങി.",
        "0.1": "തന്റെ സ്വന്തം അദ്ഭുത വാസസ്ഥലത്ത് സന്തോഷിക്കുന്ന ആ സഹസ്രശീർഷനായ അനന്തനെ ഋഷിമാർ വിനയത്താൽ അലങ്കരിച്ച്, വണങ്ങി, അതിനെക്കുറിച്ച് ഈ ഉത്തമ ചോദ്യം ചോദിച്ചു:",
        "0.2": "“ലോകനാഥാ, അളവില്ലാത്ത ജ്ഞാനമുള്ള ആ പരമഭാഗ്യവാന്റെ സിദ്ധാന്തം ലോകത്തിലെ ഏറ്റവും മനോഹരമാണ്; അങ്ങുപോലും അത് ആദരിക്കുന്നു. അത് വീണ്ടും വീണ്ടും പഠിക്കുന്നവർക്ക് എന്ത് ഫലമാണ് ലഭിക്കുക?",
        "0.3": "യോഗ്യരായവർ ഫലമറിഞ്ഞാൽ അവരുടെ പ്രയത്നം വളരെ ശക്തമാകുന്നു. അതിനാൽ വാക്കുകൾ ഫലം നൽകുന്ന കരുണാമയനായ നാഥൻ അതിന്റെ ഫലം പൂർണ്ണമായി വിശദീകരിക്കണമേ.”",
        "0.4": "അവർ പറഞ്ഞ ഈ വാക്കുകൾ കേട്ട്, ഉദാരമനസ്കനായവൻ പറഞ്ഞു: “ആദരണീയമായ പാദങ്ങളുള്ളവന്റെ സിദ്ധാന്തത്തിന്റെ ഏറ്റവും മഹത്തായ ഫലം ഭക്തിയോടെ കേൾക്കൂ.",
        "0.5": "സ്വർഗ്ഗാദികൾ അതിലൂടെ നേടാവുന്നതാണെങ്കിലും, കൃഷിയുടെ ഫലം വൈക്കോൽ അല്ലാത്തതുപോലെ അവയെ അതിന്റെ ഫലമെന്ന് വിളിക്കുന്നില്ല; അതിന്റെ സ്വന്തം ഫലം മോക്ഷാവസ്ഥയാണ് — എന്ന് ശുകനും സരസ്വതിയും പരമസത്യമറിയുന്ന മറ്റു ജ്ഞാനികളും പറയുന്നു.",
        "0.6": "മാനുഷികസാമർത്ഥ്യത്തെ മറികടന്ന ഒരാളാൽ രചിക്കപ്പെട്ടതും, ഉത്തമ വേദങ്ങളുടെ അർത്ഥം വഹിക്കുന്നതുമായ ഈ ശ്രേഷ്ഠ ശാസ്ത്രത്തിൽ സമർപ്പിക്കുന്നവർക്ക്, അങ്ങനെ പരമവൈഷ്ണവരായിത്തീരുന്നവർക്ക്, അജയ്യനായ ഹരി അവരുടെ ആനന്ദത്തിനായി തന്റെ സ്വന്തം ലോകം നൽകുന്നു.",
        "0.7": "അവിടെ പരമപുരുഷന്റെ നഗരം തിളങ്ങുന്നു — പ്രപഞ്ചത്തിലെ സകല മഹത്വത്തിന്റെയും ഏകവേദി; അതിനു തുല്യമായത് അതിന്റെ രത്നകോട്ടകളിലെ തന്നെ പ്രതിബിംബം മാത്രം.",
        "0.8": "ചുറ്റുമുള്ള വെണ്മയേറിയ മാളികകളുടെ പ്രഭയ്ക്കിടയിൽ തിളങ്ങുന്ന മാണിക്യവീടുകളുടെ നിര, എന്റെ വെളുത്ത ശരീരത്തിനുള്ളിൽ പ്രകാശിക്കുന്ന അസുരഹന്താവായ ഹരിയുടെ രൂപത്തോട് സദൃശമാണ്.",
        "0.9": "ഓരോ വീട്ടിലും മരതകമേൽക്കൂരകൾ, വിവിധ നിരകളിൽ തിളങ്ങുന്ന സ്ഫടികം പതിച്ചത്, വെളുത്ത ഗംഗാജലവുമായി കലർന്ന യമുനപോലെ തോന്നുന്നു.",
        "0.10": "വീടുകളുടെ നിരകളുടെ മേൽക്കൂരകളിൽ കൊത്തിയ പക്ഷികൾ അത്രമേൽ ജീവനുള്ളവയാണ്; ആ ലോകത്തിന്റെ നിയമപ്രകാരം അവിടെയുള്ള ജനങ്ങൾ മോഹമില്ലാത്തവരല്ലായിരുന്നെങ്കിൽ, അവയെ കൃത്രിമമെന്ന് അവർ ഒരിക്കലും കാണില്ലായിരുന്നു.",
        "0.11": "ഉത്തരങ്ങളിൽ ഉറപ്പിച്ച ചിത്രപ്പണിയുള്ള നേർത്ത മേലാപ്പുകളിൽ നിന്ന് തൂങ്ങുന്ന രത്നമാലകൾ വീടുകൾക്കുള്ളിൽ അത്രയേറെ സമൃദ്ധമായി നിറയുന്നു; പ്രകാശംതന്നെ ഒഴുകിപ്പരക്കുന്നതുപോലെ അവ തിളങ്ങുന്നു.",
        "0.12": "അവിടെ പ്രകൃതിതന്നെ ശുദ്ധരൂപത്തിൽ, വലിയ രത്നങ്ങളും സ്വർണ്ണവും കൊണ്ട് എല്ലാ വസ്തുക്കളുമായി മാറുന്നു; അതുകൊണ്ട് സൗന്ദര്യത്തിന്റെ സാരമെല്ലാം യഥാർത്ഥത്തിൽ ഇവിടെയാണ് കാണുന്നത്; മറ്റിടങ്ങളിൽ കവികൾ അതിശയോക്തിയിൽ വർണ്ണിക്കുന്നത് ഇവിടെ പ്രത്യക്ഷ സത്യമാണ്.",
        "0.13": "ആദിയില്ലാത്ത കാലം മുതൽ മോചിതരായ ശംഭുവും മറ്റുള്ളവരുമായ എണ്ണമറ്റ സൈന്യങ്ങൾ അവിടെ വസിക്കുന്നുണ്ടെങ്കിലും, ഉപനഗരങ്ങളോടൊപ്പമുള്ള ആ മഹാനഗരം ഒരിക്കലും തിങ്ങിനിറയുന്നില്ല. ഭഗവാന്റെ മഹത്വം ഇതാണ്!",
        "0.14": "മൂന്നു ലോകങ്ങളെയും അദ്ഭുത ഗുണങ്ങളിൽ കവിയുന്ന ഏകലോകനാഥന്റെ കൊട്ടാരം, നക്ഷത്രവലയത്തിനിടയിൽ ചന്ദ്രബിംബംപോലെ, മനോഹര മാളികകളുടെ നടുവിൽ തിളങ്ങുന്നു.",
        "0.15": "ആയിരം പരിചാരികമാർ ചുറ്റിയിരിക്കുമ്പോഴും, ഇന്ദിര (ലക്ഷ്മി) തന്നെ തന്റെ നാഥനെ ആദരിച്ച് ഭവനകാര്യങ്ങൾ ഉത്സാഹത്തോടെ ചെയ്യുന്നു; ആ ഭവനത്തിന്റെ തേജസ്സ് ആർക്കാണ് വർണ്ണിക്കാനാവുക?",
        "0.16": "അവിടെ കമലയുടെ നാഥനായ പരമൻ, സ്വയം ആനന്ദിക്കുമ്പോഴും, അനശ്വരനായ സർപ്പരാജാവിന്റെ മൃദുവായ ചുരുളുകളിൽ ചാരിക്കിടന്ന്, ശുദ്ധവും മനോഹരവും താമരക്കണ്ണുള്ള കമലയോടൊപ്പം ലീല ചെയ്യുന്നു.",
        "0.17": "അദ്ദേഹത്തെ ഓർക്കുക: ആയിരം ഉദയസൂര്യന്മാരെപ്പോലെ തിളങ്ങുന്ന, സ്വർണ്ണവസ്ത്രം ധരിച്ച്, രത്നാഭരണങ്ങളാൽ അലങ്കരിച്ച്, ചന്ദ്രസമാനമായ മുഖത്ത് പുഞ്ചിരിയോടെ, താമരക്കണ്ണുള്ള, ചക്രരാജൻ ധരിക്കുന്നവൻ.",
        "0.18": "അവന്റെ ഗുണങ്ങൾ രാമനും എണ്ണിത്തീർക്കാനാവില്ല; വാക്ചാതുരിയുള്ള നാലുമുഖനായ ബ്രഹ്മാവിനും കഴിയില്ല; ആയിരം വായുള്ള ഞങ്ങൾക്കും, മറ്റുള്ളവർ പറഞ്ഞതിനപ്പുറം അവയെക്കുറിച്ച് പറയാനാവില്ല.",
        "0.19": "എണ്ണമറ്റ ബ്രഹ്മാക്കന്മാരും ഗരുഡന്മാരും ശേഷന്മാരും ഇന്ദ്രന്മാരും മറ്റുള്ളവരും തങ്ങളുടെ പത്നിമാരോടൊപ്പം, പരമനോടുള്ള ഐക്യത്തിന്റെ സമൃദ്ധമായ ആനന്ദം നേടി, അവനെ ദർശിക്കുകയും ആനന്ദസത്തയാൽ നിറയുകയും ചെയ്യുന്നു.",
        "0.20": "ഇവിടെ തങ്ങളുടെ നാഥന്റെ സൗന്ദര്യം പങ്കിടുന്ന പുരുഷന്മാർ സഞ്ചരിക്കുന്നു: നാലു കൈകളുള്ള, താമരക്കണ്ണുള്ള, മഞ്ഞവസ്ത്രം നന്നായി ധരിച്ച, ചിലർ പ്രഭാതത്തിന്റെ തിളക്കമുള്ളവർ, ചിലർ പുതുമഴമേഘം പോലെ ഇരുണ്ടവർ.",
        "0.21": "ഭഗവാന് സമീപം എത്തിയവർക്കു മാത്രമല്ല അതുല്യമായ സന്തോഷം; ഗുണങ്ങൾ എല്ലാ ലോകങ്ങളെയും കവിയുന്ന അവന്റെ ലോകത്ത് വസിക്കുന്നവരും, അല്പപുണ്യമുള്ളവർക്ക് ലഭിക്കാൻ പ്രയാസമുള്ള ആനന്ദം അനുഭവിക്കുന്നു.",
        "0.22": "അവിടെ മരണമില്ല, ജനനമില്ല, വാർദ്ധക്യമില്ല, ത്രിവിധ ഭയങ്ങളുമില്ല; ദുഃഖങ്ങളുടെ കൂട്ടം പോകട്ടെ; മറ്റൊരു അശുഭവുമില്ല, അതിന്റെ മൂലമായ (പ്രാകൃത) ഗുണങ്ങൾപോലുമില്ല.",
        "0.23": "അനന്തന്റെ സ്നേഹിതരായ അവരെല്ലാം എപ്പോഴും പൂർണ്ണ തൃപ്തിയോടെ ആനന്ദം അനുഭവിക്കുന്നു; പദവികളിൽ (താരതമ്യത്താൽ) ഭേദമുണ്ടെങ്കിലും, അവർ മേലുള്ളവരോട് ഭക്തിയുള്ളവരും ആഴമുള്ള സ്നേഹത്താൽ പരസ്പരം ബന്ധിതരുമാണ്.",
        "0.24": "ഇവിടെ ഈ മനുഷ്യർ, എപ്പോഴും യൗവനമുള്ളവർ, അതിസുന്ദരർ, പുതുനിലാവുപോലെ തിളങ്ങുന്ന ഹരിചന്ദനത്തിന്റെ സുഗന്ധമുള്ളവർ, മനോഹരമായി വീശുന്ന ചാമരങ്ങൾ പിടിച്ച ഭൃത്യന്മാരോടൊപ്പം സഞ്ചരിക്കുന്നു.",
        "0.25": "മനോഹര നൃത്തങ്ങളാൽ കണ്ണുകൾ സന്തോഷിക്കുന്നവരും, മൃദുഗീതങ്ങളും സംഗീതവുംകൊണ്ട് കാതുകൾ ആനന്ദിക്കുന്നവരുമായ ഈ താമരക്കണ്ണുള്ള കാമുകന്മാർ, സ്വന്തം യുവ പത്നിമാരെ സന്തോഷിപ്പിക്കുന്നു.",
        "0.26": "ഭർത്താക്കന്മാരെ അനുഗമിച്ച് ഉദ്യാനത്തിലേക്ക് പോകുന്ന മാൻമിഴിയാളുകൾ, കളങ്കമില്ലാത്ത വിമാനവലയത്തിൽ നിന്ന് ചന്ദ്രബിംബത്തിൽ നിന്ന് മനോഹരകിരണങ്ങൾ പുറപ്പെടുന്നതുപോലെ, സാവധാനം പുറത്തുവരുന്നു.",
        "0.27": "അവരിൽ പവിഴത്തിന്റെ നിറമുള്ള ദേഹമുള്ള മെലിഞ്ഞവർ പ്രത്യക്ഷരാകുന്നു; മറ്റു ചിലർ നല്ല മുത്തുമാലകൾപോലെ തിളങ്ങുന്നവർ, വേറെ ചിലർ നീലക്കല്ലുപോലെ ഇരുണ്ടനീലയുള്ളവർ — വിവിധ ആഭരണങ്ങളാൽ അലങ്കരിച്ചവർ.",
        "0.28": "അവർക്ക് നിലനിൽക്കുന്ന തിളക്കമുണ്ട്, അവർ ഏറ്റവും മനോഹരമായ വസ്ത്രം ധരിക്കുന്നു; തത്തകൾപോലെ മധുരമായ സ്വരവും മനോഹരമായ സ്തനങ്ങളുമുള്ള അവർ, തീർച്ചയായും മഴമേഘങ്ങളുടെ മറ്റൊരു നിരപോലെ തോന്നുന്നു (എന്നാൽ മേഘങ്ങളുടെ മിന്നൽ ക്ഷണികമാണ്, ഇവരുടേത് അങ്ങനെയല്ല).",
        "0.29": "സുന്ദര കണ്ണുകളുള്ള ഈ സ്ത്രീകളുടെ മൃദുവായ പാദങ്ങളിലെ നഖങ്ങളുടെ ചുവന്ന തിളക്കം, പവിഴനിലത്തിലൂടെ നടക്കുമ്പോൾ ശ്രദ്ധിക്കപ്പെടാതെ പോകുന്നു; സ്ഫടികനിലത്തിൽ അത് വൈരുദ്ധ്യത്താൽ വെളിപ്പെടുന്നു.",
        "0.30": "മാൻമിഴിയാളുകളുടെ മനോഹര അരക്കെട്ടിന്റെയും തുടകളുടെയും തിളക്കത്താൽ വിവിധ വർണ്ണങ്ങളുള്ള അവരുടെ നേർത്ത വസ്ത്രങ്ങൾ, ലോകത്തെ മദനൻ നേടിയ വിജയത്തിന്റെ കൊടികളായി നാം കരുതുന്നു.",
        "0.31": "(ശ്ലോകങ്ങൾ 31 മുതൽ 33 വരെ അവരെ ഒന്നിച്ച് വിവരിക്കുന്നു.) മൃദുവും ലളിതവുമായ കൈകളാൽ, സ്വർണ്ണവളകൾ വീണ്ടും വീണ്ടും കിലുങ്ങുമ്പോൾ ചലിപ്പിച്ച്, നേർത്ത രോമരേഖയാൽ മനോഹരമായ മൃദുവായ മെലിഞ്ഞ അരക്കെട്ടോടെ, വളരെ ലഘുവായി ആടിക്കൊണ്ട്;",
        "0.32": "ഓരോ ചുവടിലും മനോഹരമായ മുത്തുമാലകൾ മാറിൽ മൃദുവായി ആടിക്കൊണ്ട്, സ്തനങ്ങളുടെ നിറഞ്ഞ സൗന്ദര്യത്തിൽ നിന്ന് തുളുമ്പിയൊഴുകുന്ന അമൃതത്തുള്ളികൾപോലെ തിളങ്ങിക്കൊണ്ട്;",
        "0.33": "മറ്റേ കൈകളിൽ ആനന്ദത്തോടെ താമരകൾ പിടിച്ചോ കൂട്ടുകാരികളുടെ മേൽ ചാരിയോ, ശുദ്ധമായ പുഞ്ചിരിയും ചെരിഞ്ഞ നോട്ടവും നിറഞ്ഞ മുഖത്തോടെ, ആടുന്ന കമ്മലുകൾ കൊണ്ട് കവിളുകൾ തിളങ്ങിക്കൊണ്ട്;",
        "0.34": "അവർ മുന്നോട്ടു പോകുമ്പോൾ, രത്നമേഖലയുടെയും കണങ്കാൽ തളകളുടെയും കിലുക്കത്താൽ വിളിക്കപ്പെട്ടതുപോലെ, യുവഭർത്താക്കന്മാർ അവരുടെ ശരീരത്തിന്റെ ഈ മനോഹര ചലനം കാണാൻ മുഖം തിരിക്കുന്നു.",
        "0.35": "പ്രിയന്മാരാൽ കാത്തിരിക്കപ്പെട്ട സ്ത്രീകൾ, സ്തനഭാരത്താൽ വളഞ്ഞ്, എങ്ങനെയോ അവരിലേക്ക് എത്തുന്നു; പിന്നെ അവരുടെ താങ്ങിൽ ചാരി, പരമോദ്യാനത്തിലേക്ക് സാവധാനം പ്രവേശിക്കുന്നു.",
        "0.36": "പുഞ്ചിരിക്കുന്ന പൂക്കളുടെ ഭാരത്താൽ വളഞ്ഞ സ്വർണ്ണ-രത്നവൃക്ഷങ്ങളെ, അമൃതസമുദ്രത്തിന്റെ സുഹൃത്തായ കാറ്റ് ആലിംഗനം ചെയ്യുമ്പോൾ, ആരുടെ സന്തോഷമാണ് വർദ്ധിക്കാത്തത്?",
        "0.37": "സ്വർഗ്ഗീയ ഉദ്യാനം (ഇന്ദ്രന്റെ നന്ദനം) ‘ആനന്ദിപ്പിക്കുന്നത്’ എന്ന് ലക്ഷണാർത്ഥത്തിൽ മാത്രമേ വിളിക്കപ്പെടുന്നുള്ളൂ, കാരണം അത് എല്ലാവരെയും സാധാരണയായി ആനന്ദിപ്പിക്കുന്നില്ല; യഥാർത്ഥ നന്ദനം ഉപേന്ദ്രന്റെ (വിഷ്ണുവിന്റെ) ഉദ്യാനമാണ്, അത് എപ്പോഴും എല്ലാവരെയും ആനന്ദിപ്പിക്കുന്നു.",
        "0.38": "അദ്ഭുതം! എല്ലാ ഋതുക്കളും ചേർന്ന് അതിനെ തങ്ങളുടെ വൃക്ഷങ്ങളാൽ അലങ്കരിക്കുന്നു — മനോഹരമായ പാരിഭദ്രകം, കൽപവൃക്ഷങ്ങൾ, പാരിജാതം, ഹരിചന്ദനം തുടങ്ങിയവ.",
        "0.39": "മധുവും മാധവവുമെന്ന രണ്ടു വസന്തമാസങ്ങൾ, പുഞ്ചിരിക്കുന്ന മാധവീപുഷ്പങ്ങളാൽ മനോഹരമായും, പുതിയ ചമ്പകം മുതലായ പൂക്കളാൽ പ്രകാശിച്ചും, വണ്ടുകളുടെ മുരളിച്ചയാൽ മധുരമായും, മധുസൂദനന് പ്രിയമായവർക്ക് സന്തോഷം നൽകുന്നു.",
        "0.40": "സ്നേഹമുള്ള ഭർത്താവ്, വേനൽമാസത്തിൽ വിരിഞ്ഞ പുതിയ മുല്ലപ്പൂമാല സ്വന്തം പ്രിയയുടെ തലയിൽ വെക്കുന്നതിനിടെ, ‘നിനക്ക് ഇത് ശരിയായി ചെയ്യാനാവില്ല’ എന്ന് കളിയായി പറഞ്ഞ്, അവളുടെ നിറഞ്ഞ സ്തനങ്ങൾ തന്റെ മാറിനോട് ചേർത്തമർത്തുന്നു.",
        "0.41": "മഴക്കാലത്ത്, മധുരസ്വരമുള്ള മയിലുകൾ, വിടർത്തിയ വാലിലെ കണ്ണടയാളങ്ങൾ വ്യക്തമായി കാണിച്ച്, മഴക്കാലത്തിന്റെ ചിഹ്നമായ ആയിരം കണ്ണുള്ള ഇന്ദ്രനെ തങ്ങളുടെ നൃത്തോത്സവത്തിൽ അനുകരിക്കുന്നു.",
        "0.42": "ശരത്കാലത്ത് ഒരാൾ തന്റെ പ്രിയയോടൊപ്പം കളിക്കുന്നു; അവളുടെ കണ്ണുകൾ വെള്ളത്താമരകളാണ്, മനോഹര മുഖം വിരിഞ്ഞ താമരയാണ്, സ്വരം മധുരമുള്ള തത്തയുടേത്, കണങ്കാൽ തളകൾ ഹംസങ്ങളെപ്പോലെ കിലുങ്ങുന്നു.",
        "0.43": "മഞ്ഞുകാലത്തിന്റെ നല്ല സുഹൃത്തായ ശിശിരം അതിനെ സ്വാഗതം ചെയ്യുന്നു; സ്ഫടികമലപോലെ മഞ്ഞ് കിടക്കുന്ന ആ മഞ്ഞുകാലം; പുതിയ കുന്ദപ്പൂക്കളുടെ തിളക്കത്തോടെ വള്ളികളെ പൂവിടിച്ച്, അത് ചിരിക്കുന്നതുപോലെ തോന്നുന്നു.",
        "0.44": "ഇവിടെ അദ്ഭുതകരമായി, മഞ്ഞ്, തണുപ്പ്, മഴ, ചൂട് എന്നിവപോലെ മറ്റിടങ്ങളിൽ രോഗങ്ങളുടെ മൂലമാകുന്ന ഋതുഗുണങ്ങൾ എപ്പോഴും സന്തോഷം മാത്രം നൽകുന്നു; മുക്തരായവർക്ക് ഋതുക്കളും മോക്ഷം നേടിയതുപോലെ.",
        "0.45": "അവിടെ ജനങ്ങൾ അമരനായ (ഹരിക്ക്) അമൃതമാലകളും ഏറ്റവും മികച്ച ഫലങ്ങളും പുഷ്പങ്ങളും സമർപ്പിക്കുന്നു; ഒരു നിയമത്താലും ബന്ധിതരല്ലെങ്കിലും, ആനന്ദം അനുഭവിക്കാൻ ആഗ്രഹിക്കുന്ന എല്ലാവരും എപ്പോഴും തങ്ങളുടെ സ്വഭാവം (ഭക്തി) പിന്തുടരുന്നു.",
        "0.46": "ഭർത്താക്കന്മാരോടൊപ്പം ഉദ്യാനത്തിൽ സഞ്ചരിക്കുമ്പോൾ ആനന്ദം നിറഞ്ഞ സ്ത്രീസംഘങ്ങൾ, മധുസൂദനന്റെ ചരിതങ്ങൾ മധുരമായും നിരന്തരമായും പാടുന്നു.",
        "0.47": "ചില മനോഹരികൾ ഭർത്താക്കന്മാർക്കരികിൽ കളിക്കുന്നു; മറ്റു ചിലർ പൂക്കൾ പറിക്കുന്നു, ചിലർ മാലകൾ തൊടുക്കുന്നു; ഭർത്താവിന് സന്തോഷം നൽകാത്തവളായി ആരുമില്ല.",
        "0.48": "ഉദ്യാനത്തിലെ വിവിധ ലീലകളാൽ സന്തോഷിച്ച യുവാക്കൾ, വള്ളിക്കുടിലുകളിൽ പൂർണ്ണമായ മാറിന്റെ ഭാരത്താൽ വളഞ്ഞ യുവഭാര്യമാരെ ആലിംഗനം ചെയ്യുന്നു; താമരമുഖങ്ങളിൽ വണ്ടുകളെപ്പോലെ അവർ പ്രണയത്തിൽ ആനന്ദിക്കുന്നു.",
        "0.49": "പിന്നെ സുഖം ആഗ്രഹിക്കുന്ന സ്ത്രീകൾ, അവരുടെ കണങ്കാൽ തളകളുടെ ശബ്ദം ആവർത്തിക്കുന്ന ക്രൗഞ്ചപ്പക്ഷികളോടൊപ്പം, അമൃതജലമുള്ള തടാകങ്ങളിൽ മുങ്ങി, ജലത്തിൽ കൈകൊണ്ടടിച്ചുള്ള രസകരമായ കളിയിൽ മുഖം ചിരിച്ച്, ഭർത്താക്കന്മാരോടൊപ്പം അവിടെ കളിക്കുന്നു.",
        "0.50": "വെള്ളത്തിലെ വിവിധ കളികൾക്ക് ശേഷം, സ്ത്രീകൾ വിശാലമായ പവിഴക്കരകളിലേക്ക് പോയി, കൂട്ടുകാരികളുടെ കൈകളിൽ നിന്ന് സുഗന്ധമുള്ള സ്വർണ്ണപ്പൊടി വാങ്ങുന്നു.",
        "0.51": "താമരക്കണ്ണുള്ളവർ പരസ്പരം പൂർണ്ണമായി അലങ്കരിക്കുന്നു: അരയിൽ വസ്ത്രം, അവയവങ്ങളിൽ ആഭരണങ്ങൾ, മാറിൽ കുങ്കുമം, മുടിയിൽ നല്ല മാലകൾ, കണ്ണുകളിൽ കണ്മഷി.",
        "0.52": "മെലിഞ്ഞ അരക്കെട്ടുള്ള സ്ത്രീകൾ വീട്ടിലേക്ക് പോകുന്നു; ജീവൻ പോലെ പ്രിയരും എന്നാൽ തുല്യതയില്ലാത്തവരുമായ തങ്ങളുടെ ഭർത്താക്കന്മാരോടൊപ്പം, സ്വർണ്ണവും രത്നവും കൊണ്ടുള്ള പാനപാത്രങ്ങളിൽ നിന്ന് ലൗകിക ജീവികൾക്ക് അപൂർവ്വമായി ലഭിക്കുന്ന അമൃത് കുടിക്കുന്നു.",
        "0.53": "യഥാസമയം, അലങ്കരിച്ച കണ്ണുകളുള്ള സ്ത്രീകൾ, നിർബന്ധിച്ചാലും, തങ്ങളുടെ പ്രിയഭർത്താക്കന്മാരുടെ രത്നമയ പീഠത്തിലെ മൃദുവും മനോഹരവുമായ കട്ടിലിൽ സാവധാനം കയറുന്നു; കാരണം ലജ്ജ ഓരോ വികാരത്തിനും അലങ്കാരമാണ്.",
        "0.54": "പൂക്കളാൽ അലങ്കരിച്ച ജടമുടി കെട്ടുമ്പോൾ ഭർത്താവിനെ അഭിമുഖീകരിക്കുന്ന സുന്ദരമുഖിയായവൾ, ഉയർന്ന മനോഹരമായ സ്തനങ്ങളും കൈമുട്ടിന് താഴെയുള്ള മടക്കുകളും വ്യക്തമായി കാണിച്ച്, ഭർത്താവിന്റെ വലിയ സന്തോഷത്താൽ ആലിംഗനം ചെയ്യപ്പെടുന്നു.",
        "0.55": "ഇവിടെ ഏത് സന്തുഷ്ടനായ കാമുകനാണ് തന്റെ പ്രിയയ്ക്ക് സന്തോഷം നൽകാതിരിക്കുക — അവളുടെ നിറഞ്ഞ ദൃഢ സ്തനങ്ങളാൽ അവരുടെ സാമീപ്യം അകറ്റപ്പെട്ടിട്ടും, രണ്ടു കൈകൊണ്ടും അവളെ ആലിംഗനം ചെയ്യുന്നത്?",
        "0.56": "കാമുകൻ തന്റെ സുന്ദരിയുടെ മുഖത്തേക്ക് ദീർഘനേരം ശാന്തമായി നോക്കുന്നു — പുഞ്ചിരിയാൽ വിടർന്ന, തിളങ്ങുന്ന രത്നക്കമ്മലുകളാൽ പ്രകാശിക്കുന്ന, മൃദുവായ ചെരിഞ്ഞ നോട്ടങ്ങളിൽ നിപുണമായ ആ മുഖം; പിന്നെ അതിൽ ചുംബിക്കുന്നു.",
        "0.57": "നാണത്താൽ താഴ്ത്തിയ തന്റെ താമരക്കണ്ണുള്ളവളുടെ മുഖമാകുന്ന ചന്ദ്രനെ ഉയർത്തി, ആലിംഗനത്തിന്റെ സന്തോഷം നിറഞ്ഞ യുവാവ്, അവളുടെ മധുരമുള്ള അധരങ്ങളിലെ അമൃത് പാനം ചെയ്ത്, വേഗം നിർത്തുന്നില്ല.",
        "0.58": "പ്രണയോത്സവത്തിനായുള്ള ആവേശത്തിൽ, അവളുടെ വസ്ത്രം അഴിക്കാൻ കൈ വേഗത്തിലാക്കുന്നു; വിശാലമിഴിയാളുടെ കൈ തടയുമ്പോൾ പ്രിയൻ ഇരട്ടി വേഗത്തിൽ മുന്നേറുന്നു.",
        "0.59": "സ്വഭാവത്താൽ ലജ്ജാശീലരായ യുവതികളാകട്ടെ, ഉടൻ തന്നെ ധീരരായി, പ്രണയകലയുടെ വിവിധ വിദ്യകളിൽ നിപുണരായി, ഉത്സാഹത്തോടെ ഭർത്താക്കന്മാരെ ആലിംഗനം ചെയ്ത് അവർക്ക് സന്തോഷം നൽകുന്നു.",
        "0.60": "അമാനുഷഗുണമുള്ള സ്ത്രീകൾ, തങ്ങളെ സന്തോഷിപ്പിക്കുന്ന അമാനുഷ കാമുകന്മാരെ സന്തോഷിപ്പിക്കുന്നു; സൗന്ദര്യത്തിൽ യോജിച്ച, ലൗകിക സുഖങ്ങളെ മറികടക്കുന്ന ആ അമാനുഷ പ്രണയം അവിടെ പ്രകാശിക്കുന്നു.",
        "0.61": "അവിടെ വധൂവരന്മാർക്ക് പ്രണയം ക്ഷീണം മുതലായവയാൽ ഒരിക്കലും മുറിയുന്നില്ല; വേർപാടിന്റെ വേദനയും ഒരിക്കലുമില്ല, എതിരാളികളോടുള്ള അസൂയയാലുള്ള കലഹവുമില്ല; ആ ലോകം എല്ലാ കുറ്റങ്ങളിൽ നിന്നും മുക്തമാണ്.",
        "0.62": "അവരുടെ ശരീരം ആനന്ദവും ജ്ഞാനവും സ്വഭാവമായവയായതിനാൽ, അകത്തും പുറത്തും സുഗന്ധമുള്ളവർ; അതിനാൽ ഹരിയുടെ വാസസ്ഥലത്ത് ദമ്പതികളുടെ പ്രണയം ഋഷിമാർ പോലും അംഗീകരിക്കുന്നു.",
        "0.63": "ഈ ലോകത്തിനപ്പുറമുള്ളതിനെക്കുറിച്ചും കേൾക്കൂ — മുക്തരായവരുടെ കണ്ണുകളുടെ ലക്ഷ്യമായത്: ഇന്ദിരയുടെ നാഥൻ തന്റെ മനോഹര രൂപം എപ്പോഴും വെളിപ്പെടുത്തുന്നു, തീവ്രമായ ആനന്ദം നിറഞ്ഞ്.",
        "0.64": "(ശ്ലോകങ്ങൾ 64 മുതൽ 73 വരെ ആ രൂപത്തെ വർണ്ണിക്കുന്നു.) രത്നനിരകൾ തിളങ്ങുന്ന വലിയ കിരീടം ധരിക്കുന്നു; ആയിരക്കണക്കിന് മിനുസമുള്ള കറുത്ത ചുരുളുകൾ; അർദ്ധചന്ദ്രസമാനമായ നെറ്റിയിൽ തിളങ്ങുന്ന തിലകം; ചെവികളിൽ തിളങ്ങുന്ന മകരകുണ്ഡലങ്ങൾ.",
        "0.65": "മുഖം പൂർണ്ണചന്ദ്രനെ പരിഹസിക്കുന്നു; കണ്ണുകൾ താമരപോലെ നീണ്ടത്; ചുണ്ടുകൾ ചുവന്നത്; അതുല്യവും മനോഹരവുമായ പുഞ്ചിരിനോട്ടങ്ങളാൽ തന്റെ മുന്നിൽ വണങ്ങുന്ന സ്വജനങ്ങളെ അത് സന്തോഷിപ്പിക്കുന്നു.",
        "0.66": "പുതിയ ശംഖുപോലെയുള്ള കഴുത്ത്; സൂര്യനെപ്പോലെ തിളങ്ങുന്ന രത്നരാജാവായ കൗസ്തുഭവും മനോഹരമായ മാലയും ധരിക്കുന്നു; രത്നം പതിച്ച മനോഹര വളകൾ, മോതിരങ്ങൾ, തോൾവളകൾ.",
        "0.67": "നീണ്ടതും വൃത്താകൃതിയുള്ളതും ചുവന്ന കൈത്തലമുള്ളതുമായ കൈകളിൽ: ഒരു കൂട്ടം സൂര്യന്മാരെപ്പോലെ തിളങ്ങുന്ന ചക്രം, ചന്ദ്രബിംബംപോലെ വെളുത്ത ശംഖ്, മനോഹര താമര, തീജ്വാലപോലെ ജ്വലിക്കുന്ന ഗദ, ശക്തമായ വില്ല്.",
        "0.68": "മനോഹരമായ വിശാല തോളുകൾ; രത്നമണ്ഡപംപോലെ കമല തിളങ്ങുന്ന മാറ്; പതിന്നാലു ലോകങ്ങളെ വഹിക്കുന്ന മെലിഞ്ഞ ഉദരം; ഭൃംഗമായ ബ്രഹ്മാവ് അവന്റെ സ്തുതി പാടിയിരിക്കുന്ന മനോഹരമായ താമരപ്പൊക്കിൾ.",
        "0.69": "തിളങ്ങുന്ന അരഞ്ഞാണമുള്ള മനോഹര അരക്കെട്ട്; സ്വർണ്ണവരകളാൽ തിളങ്ങുന്ന മഞ്ഞനിറ വസ്ത്രം; മികച്ച ആനയുടെ തുമ്പിക്കൈപോലെയുള്ള തുടകൾ; ഒതുങ്ങി മെലിഞ്ഞ കണങ്കാലുകൾ.",
        "0.70": "മനോഹര കണങ്കാൽ തളകൾ, തിളങ്ങുന്ന പാദമുകൾ, പുതിയ പവിഴംപോലെ തിളങ്ങുന്ന കാൽവിരൽനഖങ്ങൾ, ചക്രം, താമര, കൊടി എന്നിവയാൽ അടയാളപ്പെട്ട പാദങ്ങൾ — അവയുടെ ധൂളി മൂന്നു ലോകങ്ങളെയും ശുദ്ധമാക്കുന്നു.",
        "0.71": "എല്ലാ ശാസ്ത്രങ്ങളും വെളിപ്പെടുത്തുന്ന ആനന്ദം, ജ്ഞാനം തുടങ്ങിയ അനന്തവും അളവില്ലാത്തതുമായ ഗുണങ്ങളാണ് അത്; പാദം മുതൽ ശിരസ്സുവരെ ഓരോ അവയവവും അവയോടൊപ്പം ഒന്നായിരിക്കുന്നു; അത് ഒരു കുറവിൽ നിന്നും മുക്തമാണ്.",
        "0.72": "യോഗ്യരായവർക്ക് അവരവരുടെ പ്രത്യേക പുണ്യമനുസരിച്ച് അത് പ്രത്യക്ഷമാകുന്നു — രണ്ടു പാദങ്ങളോടെയോ അനന്തമായ പാദങ്ങളോടെയോ; ഓരോരുത്തർക്കും യോജിച്ച മറ്റു മനോഹര അവയവങ്ങളോടെയും, സാന്ദ്രമായ ഗുണങ്ങളാൽ നിർമ്മിതമായി.",
        "0.73": "ചിലപ്പോൾ പുതിയ സൂര്യന്റെ പ്രഭയോടെ, ചിലപ്പോൾ സ്വർണ്ണത്തെ കവിഞ്ഞ്, ചിലപ്പോൾ മനോഹര മുത്തുമാലപോലെ, ചിലപ്പോൾ നീലക്കല്ലുപോലെ ഇരുണ്ട്, ചിലപ്പോൾ പലതരം മിശ്രവർണ്ണങ്ങളിൽ — ആനന്ദവും ജ്ഞാനവും സുഗന്ധവുമാകുന്ന ഗുണങ്ങളുള്ള മനോഹര രൂപം.",
        "0.74": "രാമന്റെ നാഥന്റെ രൂപം — സൗന്ദര്യത്തിന്റെ ഏകസാരം, മൂന്നു ലോകങ്ങളിലെയും അദ്ഭുതങ്ങൾക്കപ്പുറമുള്ള അദ്ഭുതം; വീണ്ടും വീണ്ടും കാണുന്തോറും അത് കൂടുതൽ അദ്ഭുതകരമാകുന്നു; ഇവിടെ മുക്തരെ അത് എപ്പോഴും ആനന്ദിപ്പിക്കുന്നു.",
        "0.75": "യജ്ഞത്തിൽ ഭക്തിയുള്ളവർ അദ്ദേഹത്തെ യജ്ഞനായി ആരാധിക്കുന്നു; ജ്ഞാനികൾക്കിടയിൽ മറ്റുള്ളവർ അവനെ പരമനെന്ന് പ്രഖ്യാപിക്കുന്നു; ആരുടെ മഹത്വം പാടേണ്ടതാണോ, അവനെ നല്ല ഗായകർ പാടുന്നു — വിധിയുടെ ബന്ധനങ്ങളിൽ നിന്ന് മുക്തനായി, എപ്പോഴും ആനന്ദം നിറഞ്ഞവനായി.",
        "0.76": "(യമകശ്ലോകം.) വൈകുണ്ഠത്തിലെ ജനങ്ങളുടെ ആ പ്രത്യേക തേജസ്സുകൾ മനസ്സിനും വാക്കിനും അപ്പുറമുള്ള മഹാ അദ്ഭുതമാണ്; എങ്കിലും ആ ലോകത്തിന് അത്തരം ശ്രേഷ്ഠത യോജിക്കുന്നു; ശ്രീ, അജൻ (ബ്രഹ്മാവ്), ഗരുഡൻ, ശേഷൻ, മുക്തർ എന്നിവർ അത് സ്തുതിക്കുന്നു.",
        "0.77": "ആനന്ദഭരിതനായ ഒരു ആത്മാവ് ഇവിടെ ആഗ്രഹിക്കുന്ന ഏത് വസ്തുവും, കേവലം ഇച്ഛയാൽ തന്നെ, സംഭവിക്കുന്നു; മോക്ഷത്തെക്കുറിച്ച് വേദങ്ങളും ഇങ്ങനെ പ്രഖ്യാപിക്കുന്നു. ഇതിനപ്പുറം എന്ത് മഹത്വമുണ്ടാകാൻ?",
        "0.78": "ദേവന്മാർമുതൽ മനുഷ്യർവരെ, തങ്ങളുടെ ശേഷിപോലെ മനസ്സും വാക്കും കൊണ്ട്, മഹാനായ ആനന്ദതീർത്ഥരുടെ ഭാഷ്യത്തിന്റെ അർത്ഥം വീണ്ടും വീണ്ടും ധ്യാനിക്കുന്നവർ, മുകുന്ദന്റെ കൃപയാൽ ഈ മോക്ഷം എന്നേക്കുമായി നേടുന്നു.” (ഇങ്ങനെ ശേഷൻ പറഞ്ഞു.)",
        "0.79": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പതിനൊന്നാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "മോക്ഷത്തെക്കുറിച്ചുള്ള സർഗ്ഗം. മധ്വന്റെ പ്രഭാഷണം കേൾക്കാൻ ശേഷനും ഋഷിമാരും എത്തുന്നു; വൈകുണ്ഠത്തെ കവി വർണ്ണിക്കുന്നു: ശേഷശയ്യയിൽ ലക്ഷ്മിയോടൊപ്പം വിശ്രമിക്കുന്ന ഭഗവാൻ, തോട്ടങ്ങളിലും മന്ദിരങ്ങളിലും മുക്തരായ ജീവന്മാരുടെ ആനന്ദം, ഹരിയുടെ തേജസ്വിയായ രൂപം, പുണ്യമനുസരിച്ച് മുക്തരുടെ ശ്രേണീഭേദം."
    },
    "sumadhva-vijaya-12": {
      "verses": {
        "0.0": "അനന്തത്തിൽ മനസ്സുറപ്പിച്ച ആ വേദാന്തസിംഹം തന്റെ പ്രധാന വ്യാഖ്യാനത്തോടെ ഗർജ്ജിച്ചപ്പോൾ, അഹങ്കാരത്താൽ ആനകൾപോലുള്ള തർക്കവാദികളെ ഉടനെ ഭയപ്പെടുത്തി; മായാവാദികളുടെ കുറുനരിക്കൂട്ടങ്ങൾ പരിഭ്രമത്തിലായി.",
        "0.1": "ചോളദേശത്തുനിന്നും പുണ്ഡരീകപുരത്തുനിന്നുമുള്ള രണ്ടു നേതാക്കളെ ചുറ്റി ഈ ക്രൂരരും പാപികളുമായവർ ഒത്തുകൂടി ആലോചിച്ചു; ഭൂമിയുടെ ആഭരണമായ വായുദേവനോട് അസൂയപ്പെട്ട്, ധൃതരാഷ്ട്രപുത്രന്മാരെ ചുറ്റിയ വിഡ്ഢികളെപ്പോലെ.",
        "0.2": "അവരിൽ ഒരാൾ, നീചമായ തന്ത്രത്തിൽ ഗാന്ധാരീപുത്രൻ ശകുനിയെപ്പോലെ വാചാലനായവൻ, ദുഷ്ടരുടെ പക്ഷക്കാരനോട് അസ്വസ്ഥമായ വാക്കുകൾ പറഞ്ഞു, സജ്ജനങ്ങളോടുള്ള അസൂയ ഉറപ്പിക്കാൻ. (യമകശ്ലോകം.)",
        "0.3": "“ഈ മായാവാദം ഒരേയൊരു യാഥാർത്ഥ്യമുണ്ടെന്നും, പുരാതനമായ വേദവാക്യങ്ങൾക്കുപോലും വിവരിക്കാനാവാത്തതാണെന്നും പറയുന്നു. പഴയതെങ്കിലും എപ്പോഴും പുതിയത്, പ്രയാസത്താൽ അലങ്കരിക്കപ്പെട്ടത്; നമ്മുടെ ആചാര്യന്റെ (ശങ്കരന്റെ) സിദ്ധാന്തം അദ്ഭുതകരം തന്നെ!",
        "0.4": "അതില്ലാതെ, അറിവിന്റെ മാർഗ്ഗങ്ങൾ ഭേദം നിറഞ്ഞതായി കാണിക്കുന്ന ഈ ദൃശ്യലോകം — ദേവന്മാർ, മനുഷ്യർ, അസുരന്മാർ, ബ്രാഹ്മണൻ, ചണ്ഡാലൻ — യഥാർത്ഥത്തിൽ ഭേദമില്ലാത്തതാണെന്ന് ആർക്കാണ് തെളിയിക്കാനാവുക?",
        "0.5": "അജ്ഞാനത്തിൽ അത് എല്ലാത്തിനെയും പ്രായോഗിക യാഥാർത്ഥ്യമുള്ളതാക്കി സർവ്വം നിയന്ത്രിക്കുന്നു; ജ്ഞാനം ഉദിക്കുമ്പോൾ ലോകം കരിഞ്ഞ തുണിപോലെ തെളിയുന്നു; ജ്ഞാനം പക്വമാകുമ്പോൾ ചുവന്നുതുടുത്ത ഇരുമ്പിൽ ഒഴിച്ച വെള്ളംപോലെ അത് മറയുന്നു.",
        "0.6": "ഇപ്പോൾ ജ്ഞാനികളിൽ ഉത്തമരായ നമ്മുടെ ശ്രേഷ്ഠ അറിവുള്ളവർ നിർഗുണാവസ്ഥയിൽ പ്രവേശിച്ചിരിക്കുന്നു; നിങ്ങൾ ഞങ്ങളുടെ നേതാക്കളായവർ, എന്റെ വിലാപം കേൾക്കൂ: അയ്യോ, അയ്യോ, ഈ മായാവാദം നശിക്കുകയാണ്!",
        "0.7": "ഭട്ടർ നഷ്ടപ്പെട്ടിടത്ത്, പ്രഭാകരന്റെ പ്രകാശം മങ്ങിയിടത്ത്, മഹായാനികളും മറ്റുള്ളവരും ഭയന്ന് ഓടിയിടത്ത്, തത്ത്വവാദത്തിന്റെ അഗ്നിജ്വാല മായാവാദത്തിന്റെ കോട്ടക്കാടിനെ ദഹിപ്പിക്കാൻ ശ്രമിക്കുന്നു: അത് അവഗണിക്കരുത്.",
        "0.8": "നമ്മുടെ മാന്യൻ, അദ്ദേഹം ചെല്ലുന്ന എല്ലാ ദേശങ്ങളിലും അദ്ദേഹത്തിന്റെ വരവ് തടയുമെന്ന് പരസ്യമായി പ്രതിജ്ഞ ചെയ്തിരുന്നു; എന്നിട്ടും അവൻതന്നെ അവരുടെ പക്ഷത്തേക്ക് പോയി. അയ്യോ, നമ്മൾ എത്ര ഭാഗ്യദോഷികൾ!",
        "0.9": "അദ്ദേഹത്തോട് ആരെന്ത് ചോദ്യം ചോദിച്ചാലും അദ്ദേഹം തീർച്ചയായും അത് ഖണ്ഡിക്കുന്നുവെന്നും, ശരിയും ഖണ്ഡിക്കാനാവാത്തതുമായ യുക്തികൾ അദ്ദേഹം പറയുന്നുവെന്നും, ഒരു വിമർശകനെന്ന നിലയിൽ തർക്കവാദികളുടെ സൈന്യങ്ങളെ, വിശേഷിച്ച് നമ്മെ, ലജ്ജിപ്പിക്കുന്നുവെന്നും നാം കേൾക്കുന്നു. നമ്മൾ എന്ത് ചെയ്യണം?",
        "0.10": "നൂറ്റിയിരുപത്തിയഞ്ചായിരം (ഗ്രന്ഥങ്ങൾ) വരുന്ന പഴയ സിദ്ധാന്തത്തെ ആനന്ദതീർത്ഥർ ഒറ്റ വാക്യംകൊണ്ട് ഖണ്ഡിച്ചു എന്ന് യാത്രക്കാരിൽ നിന്ന് കേട്ട്, ആകുലമനസ്സോടെ ഞാൻ നിങ്ങളുടെ അടുത്തേക്ക് വന്നു.",
        "0.11": "അദ്ദേഹത്തെ കാണുന്നവർ, സൗമ്യമായ പുഞ്ചിരിയും ദിവ്യരൂപവുമുള്ള അദ്ദേഹത്തെക്കുറിച്ച് പറയുന്നു: “ഇത് വേദവ്യാസനോ, അതോ ശരീരം ധരിച്ച വേദമോ?” അവരുടെ വാക്കുകൾ മായാവാദപക്ഷത്തിന്റെ വേരറുക്കുന്ന വാൾ തന്നെയാണ്.",
        "0.12": "നമ്മുടെ തന്നെ ചിലർ ലജ്ജയില്ലാതെ പറയുന്നു: “അദ്ദേഹത്തിന്റെ സൂത്രഭാഷ്യം വ്യക്തവും ശക്തവും പ്രമാണങ്ങളിൽ അധിഷ്ഠിതവുമാണ്; അങ്ങനെയെങ്കിൽ നമുക്ക് എന്ത് ദോഷം?” അങ്ങനെ അവർ നമ്മെ സഹിക്കാനാവാത്ത ലജ്ജയുടെ സമുദ്രത്തിൽ മുക്കി.",
        "0.13": "വലപോലെ എല്ലായിടത്തും വ്യാപിച്ച, ഗുണങ്ങൾ നിറഞ്ഞ, ശംഖും ചക്രവും അടയാളമുള്ള അദ്ദേഹത്തിന്റെ ശിഷ്യന്മാർ, മീനുകളെ വല പിടിക്കുന്നതുപോലെ, സഭകളാകുന്ന സമുദ്രത്തിൽ എല്ലാ ജീവികളുടെയും ഹൃദയം പിടിക്കുന്നു; നമ്മുടെ ക്ഷേമം ഉറപ്പാക്കാൻ ഒരു നയം ആലോചിക്കൂ.",
        "0.14": "ഗുണങ്ങളെക്കുറിച്ചുള്ള യുക്തികളാലും, ഗുണങ്ങളെക്കുറിച്ചുള്ള വാക്യങ്ങളാൽ സംരക്ഷിക്കപ്പെട്ടും, അവർ ജനങ്ങളിൽ ഗുണങ്ങളുള്ള ബ്രഹ്മത്തിലുള്ള വിശ്വാസം വർദ്ധിപ്പിക്കുന്നു; നമ്മളായ ‘ഹംസങ്ങളുടെ’ (പരമഹംസന്മാരുടെ) വാക്ക് നിശ്ശബ്ദമാക്കുന്നതിൽ സമർത്ഥർ — മേഘങ്ങൾ മഴകൊണ്ട് കടലിനെ നിറയ്ക്കുന്നതുപോലെ അവർ അതിനെ വർദ്ധിപ്പിക്കുന്നു.",
        "0.15": "ഏറെ പറഞ്ഞാൽ മതി: നമ്മുടെ സിദ്ധാന്തത്തിന്റെ നാശകാലത്ത്, ലോകനാശത്തിൽ പ്രളയജലം പരക്കുന്നതുപോലെ, അവർ തടസ്സമില്ലാതെ ലോകം മുഴുവൻ വേഗത്തിൽ പരക്കുന്നു.”",
        "0.16": "അദ്ദേഹത്തിന്റെ വാക്കുകൾ കേട്ട്, അഹങ്കാരികളുടെ മനസ്സറിയുന്ന മറ്റൊരാൾ — ഗർവ്വുള്ളവനും മന്ദബുദ്ധിയും ദുഷ്ടനുമായവൻ — തന്റെ ജനങ്ങളെ പ്രസാദിപ്പിക്കാൻ ഉച്ചത്തിൽ ധീരവാക്കുകൾ പറഞ്ഞു:",
        "0.17": "“ശത്രുവിന്റെ തീയെക്കുറിച്ചുള്ള സംശയമാത്രയിൽ ഉരുകുന്ന ഭീരുക്കളുടെ നിർവീര്യമനസ്സുകൾക്ക് ധിക്കാരം! തീയുടെ അടുത്ത് വെക്കുമ്പോൾ മാത്രം ഉരുകുന്ന പുതിയ വെണ്ണയാണ് നല്ലത്.",
        "0.18": "ശങ്കരന്റെ വിദ്യയുള്ള, ശുഭകരമായ, ദേവന്മാർ മുതലായവരുടെ പോലും ബാധിതത്വം തെളിയിക്കുന്ന, ശുക്രന്റെ ശാസ്ത്രം ചെയ്തതുപോലെ ദേവന്മാർ ആരാധിക്കുന്ന ബൃഹസ്പതിയെപ്പോലും ലജ്ജിപ്പിക്കാൻ കഴിയുന്ന ഈ മനുഷ്യരുടെ മുന്നിൽ എന്തിന് ദുഃഖിക്കണം?",
        "0.19": "ഗുണങ്ങളെക്കുറിച്ചുള്ള കടുത്ത യുക്തികളാൽ തടസ്സപ്പെട്ട അദ്വൈതം തെളിയിക്കാനാവില്ലെന്ന് തോന്നിയാലും, ഇരിക്കട്ടെ; ആറ് (മാന്ത്രിക) കർമ്മങ്ങളിൽ പ്രവീണരും ദിവ്യമന്ത്രങ്ങളും ഔഷധങ്ങളും സമൃദ്ധമായുള്ള ഈ മനുഷ്യർ നമ്മെ സംരക്ഷിക്കുമ്പോൾ ആർക്കും നമ്മെ ജയിക്കാനാവില്ല.",
        "0.20": "എന്നാലും എതിരാളിയെ അവഗണിക്കരുത്; പക്ഷേ ഇപ്പോൾ വിലപിക്കേണ്ട സമയമല്ല; ദ്വൈതത്തിനപ്പുറമുള്ള ആത്മാവിനെ സാക്ഷാത്കരിച്ച ശങ്കരാദി നമ്മുടെ ആചാര്യന്മാർക്കുപോലും അതിനെക്കുറിച്ച് സംശയം ഉണ്ടായിരുന്നു.",
        "0.21": "“അയ്യോ, നമുക്ക് കൈമാറിക്കിട്ടിയ പരമ്പരാഗത തത്ത്വചിന്ത ഒരു പുതിയതിനാൽ നശിപ്പിക്കപ്പെടുകയാണ്” എന്ന് വിളിച്ചുപറഞ്ഞ്, നമ്മുടെ സമർത്ഥരായവർ നിഷ്പക്ഷരായ ജനങ്ങളുടെ മുന്നിൽ, യഥാർത്ഥമോ അയഥാർത്ഥമോ ആയ അവരുടെ കുറ്റങ്ങൾ വിവരിക്കണം.",
        "0.22": "നമ്മുടെ യഥാർത്ഥ ഉദ്ദേശ്യം ബ്രഹ്മംപോലെ വിവരിക്കാനാവാത്തതായി നിലനിൽക്കട്ടെ; മായയുടെ ശക്തിയാൽ എല്ലാം നിയന്ത്രിക്കാം. ഇത്തരമൊരു നയത്താലും നമ്മുടെ ശാസ്ത്രീയ രീതിയാലും നമ്മെ എതിർക്കുന്ന ലോകം മുഴുവൻ ഖണ്ഡിക്കപ്പെടണം.",
        "0.23": "ഗ്രാമംതോറും, അവർക്കു നൽകുന്ന ആദരം സമാധാനമാർഗ്ഗത്തിലൂടെയും മറ്റു മാർഗ്ഗങ്ങളിലൂടെയും മുൻകൂട്ടി തടയട്ടെ; അവർ എത്തുമ്പോൾ, അവരുടെ ഗ്രന്ഥങ്ങളും മറ്റും പിടിച്ചെടുക്കാൻ തയ്യാറായ നമ്മുടെ ആളുകൾ അവരെ താഴ്ത്താൻ പ്രവർത്തിക്കട്ടെ.”",
        "0.24": "എന്തുചെയ്യണമെന്ന് ഇങ്ങനെ ആലോചിച്ച ആ വക്രബുദ്ധികൾ കാലക്രമേണ ചക്രധാരിയുടെ ഭക്തനെതിരെ പ്രവർത്തിച്ചു; അല്ലെങ്കിൽ, കണ്ണുകളെ മൂടുന്ന അന്ധകാരസമുദ്രത്തിൽ — അതിന്റെ ജലം കടുത്ത ദുഃഖമാണ് — മുങ്ങിപ്പോകാൻ അവർ എങ്ങനെ യോഗ്യരാകുമായിരുന്നു?",
        "0.25": "തർക്കത്തിന്റെ മറവിൽ അദ്ദേഹത്തെ അപകീർത്തിപ്പെടുത്താൻ ആഗ്രഹിച്ച്, ദുരുപദേശങ്ങളാൽ, രജതപീഠത്തിൽ (ഉഡുപ്പിയിൽ) വാസുദേവന്റെ ശത്രുവായ, സന്യാസിവേഷത്തിൽ, താൻ ജ്ഞാനിയെന്ന് കരുതിയ പുണ്ഡരീകനെ (പുരിയെ) അവർ പ്രതിഷ്ഠിച്ചു.",
        "0.26": "ചീഞ്ഞ മാലിന്യം ആഗ്രഹിക്കുന്ന ഗ്രാമത്തിലെ നായ സിംഹത്തെ വെല്ലുവിളിക്കുന്നതുപോലെ, ഒറ്റക്കണ്ണുള്ള കാക്ക ഹംസത്തെ വെല്ലുവിളിക്കുന്നതുപോലെ, കുതന്ത്രക്കാരനായ കുറുനരി കഴുതപ്പുലിയെ വെല്ലുവിളിക്കുന്നതുപോലെ, ആ വിഡ്ഢി പണ്ഡിതശ്രേഷ്ഠനെ വെല്ലുവിളിച്ചു.",
        "0.27": "നിസ്സാരനായിരുന്നെങ്കിലും, സ്വഭാവത്താൽ ജയിക്കാൻ പ്രയാസമുള്ള മധ്വൻ അവനെ അവഗണിച്ചില്ല; ജ്വലിക്കുന്ന തീ, ദുർബലമായ ചിറകുള്ള ചഞ്ചലശലഭത്തിന് ദയ കാണിക്കാത്തതുപോലെ.",
        "0.28": "വേദജ്ഞനായ പ്രീതിതീർത്ഥർ (ആനന്ദതീർത്ഥർ), ആദരണീയവും അതുല്യവുമായ പ്രമാണങ്ങളാൽ തിളങ്ങിക്കൊണ്ട്, അവനെ ഖണ്ഡിച്ചു, തന്റെ സിദ്ധാന്തം സ്ഥാപിച്ചു, വിഷ്ണുവിന്റെ പ്രീതിക്കായി വേദത്തിന്റെ വ്യാഖ്യാനം നൽകി.",
        "0.29": "പരമ്പരാഗത രീതിയിൽ വേദം പഠിച്ച ബ്രാഹ്മണർ കൗതുകത്താൽ അവിടെ വലിയ സംഖ്യയിൽ എത്തി, ചുറ്റും ഇരുന്നു, കാണേണ്ട കാഴ്ചയായ ആ ഉത്തമ ആചാര്യനെ നോക്കിനിന്നു.",
        "0.30": "ക മുതലായ വ്യഞ്ജനങ്ങളെ അവയുടെ ശരിയായ ഉച്ചാരണസ്ഥാനങ്ങളിൽ നിന്ന് പുറത്തുകൊണ്ടുവരുന്നതും, മാത്രയിലും ഉച്ചാരണത്തിലും നിപുണനും, മൂന്നു സ്വരാവസ്ഥകളെ അവയുടെ ഗുണങ്ങളോടെ അവതരിപ്പിക്കുന്നവനുമായ അദ്ദേഹത്തെ കണ്ട്, ദേവന്മാർ അത്രയേറെ മതിമറന്നു, ദേവദേവനെപ്പോലും മറന്നുപോയി.",
        "0.31": "ആദ്യം ഹ്രസ്വസ്വരങ്ങളുള്ള ‘കിടാവിനെ പിന്തുടരുന്ന’ രീതിയിൽ, മാത്രകളും പാദങ്ങളും ചലിപ്പിച്ച്, പിന്നെ മറ്റു മികച്ച പാരായണ രീതികളിൽ, ഗോവിന്ദന്റെ ഭക്തൻ ഗോവിന്ദന്റെ സ്വന്തം ചാരുതയെ (ശ്ലേഷത്താൽ: കിടാങ്ങളെ പിന്തുടർന്ന് ഓടുന്ന ബാലകൃഷ്ണനെപ്പോലെ) കൊണ്ടുവന്നു.",
        "0.32": "ഭംഗിയുള്ള സ്വരത്തിലുള്ള മധ്വന്റെ വൈദിക വാക്ക്, വേദാംഗങ്ങളാൽ വെളിപ്പെടുന്ന അർത്ഥത്തോടെ, വേദിയിൽ കയറി മൂന്നു ലോകങ്ങളെയും അദ്ഭുതപ്പെടുത്തി, ബഹുമാനപ്പെട്ട ക്രമത്തിൽ അതിന്റെ പാദങ്ങൾ സ്ഥാപിച്ചുകൊണ്ട്, സ്വയംവരത്തിൽ മറ്റൊരു കൃഷ്ണയായ (ദ്രൗപദിയെപ്പോലെ) തിളങ്ങി.",
        "0.33": "ആഴവും മഹാമനസ്കതയുടെ ഫലങ്ങളും, വിവിധ സ്വരങ്ങൾക്കായി പ്രശംസിക്കപ്പെടുന്നതുമായ ആ പുണ്യമനസ്കന്റെ പാരായണം, ശിക്ഷാശാസ്ത്രത്തിന്റെ നിയമങ്ങൾ ലക്ഷ്യം വെക്കുന്ന മാതൃകതന്നെയാണെന്ന് ഞാൻ കരുതുന്നു; ആദരണീയവും അതുല്യവുമാണത്.",
        "0.34": "കല്പത്തിന്റെയും ഛന്ദസ്സിന്റെയും ക്രമീകരണങ്ങൾ കാണിച്ചും, വ്യാകരണശാസ്ത്രം വീണ്ടും വീണ്ടും വ്യക്തമാക്കിയും, നിരുക്തത്തിന്റെ രീതി പിന്തുടർന്നും, ജ്യോതിഷം അറിയുന്നവരിൽ ഏറ്റവും ശ്രേഷ്ഠനായവൻ ഇങ്ങനെ വേദം വിശദീകരിച്ചു.",
        "0.35": "എന്നെപ്പോലെയുള്ള ശരീരധാരികളിൽ ആർക്കാണ് അദ്ദേഹത്തിന്റെ മനോഹരമായ വൈദിക വ്യാഖ്യാനവും പാരായണവും വിവരിക്കാനാവുക? വാക്കിന്റെ നാഥന്മാർ — വാക് (ഭാരതി), പക്ഷികളുടെ നാഥൻ (ഗരുഡൻ), ജീവൻ (ബൃഹസ്പതി) — അവയെ വണങ്ങി വലിയ അദ്ഭുതത്തോടെ വർണ്ണിച്ചിട്ടുള്ളതാണല്ലോ.",
        "0.36": "ബ്രഹ്മാവുതന്നെയെന്നപോലെ അദ്ദേഹം അർത്ഥസഹിതം വിശദീകരിച്ച വേദം കേട്ട്, ആരു വിജയിക്കുമെന്നറിയാൻ ആഗ്രഹിച്ച സൗമ്യരായ ബ്രാഹ്മണരെല്ലാം ചിത്രകായൻ (പുണ്ഡരീകൻ) എന്ന പേരുള്ളവന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു:",
        "0.37": "“മഹാജ്ഞാനിയായവൻ, മഹാജ്ഞാനത്തോടെ മന്ത്രാക്ഷരങ്ങളുടെ അർത്ഥം വിശദീകരിച്ചിരിക്കുന്നു. കേൾക്കാൻ ആഗ്രഹിക്കുന്ന ഞങ്ങൾ, അങ്ങയോട് — അദ്ദേഹത്തിന്റെ എതിരാളിയായ അങ്ങയോട്, ജ്ഞാനിയേ — ഇതും വിശദീകരിക്കാൻ അപേക്ഷിക്കുന്നു.”",
        "0.38": "ഇങ്ങനെ പറയപ്പെട്ടപ്പോൾ ആ ദുഷ്ടൻ വിശാലബുദ്ധിയുള്ളവനോട് തുല്യനാകാൻ പുറപ്പെട്ടു; വാസുദേവന്റെ തേജസ്സ് മോഹിച്ച പൗണ്ഡ്രകവാസുദേവനെപ്പോലെ അവൻ പരിഹാസ്യനായി.",
        "0.39": "അവർ കേട്ടപ്പോൾ, ഐതരേയം മുതലായ സൂക്തങ്ങൾ വിശദീകരിക്കാനുള്ള ആവേശത്തിൽ, ‘ര’ അക്ഷരത്തിൽ തുടങ്ങുന്ന വാക്ക് പിന്തുടരുന്നിടത്ത് (അഗ്നിനാ രയിം) ‘ന’ എന്നാക്കി വായിച്ചപ്പോൾ, ബ്രാഹ്മണർ നിന്ദ്യനായവനെ നിന്ദിച്ചു.",
        "0.40": "മുമ്പ് ലോകത്തിൽ ‘ശാർദ്ദൂലൻ’ (കടുവ) എന്ന പദവി നേടിയ ഈ മായാവാദിയായ കുറുനരി, തർക്കവാദികളായ പുള്ളിപ്പുലികളെ നശിപ്പിക്കുന്ന മധ്വസിംഹത്തെ കണ്ടപ്പോൾ പേരിൽ മാത്രം കടുവയായി.",
        "0.41": "പാർത്ഥനായ (അർജുനനായ) ഉത്തമ ആനന്ദതീർത്ഥർ, തന്റെ സ്വന്തം നിധിയായ, കൃഷ്ണന് (വ്യാസന്) പ്രിയപ്പെട്ട, ‘ശാസ്ത്രം’ എന്ന് വ്യക്തമായി പേരുള്ള, നല്ല ബ്രാഹ്മണൻ സംരക്ഷിച്ചിരുന്ന ഗ്രന്ഥശാല, സൈന്ധവനായ പത്മൻ (പദ്മതീർത്ഥൻ) കവർന്നെടുത്തു എന്ന് കേട്ടു — അർജുനൻ ദ്രൗപദി (കൃഷ്ണ) സിന്ധുരാജാവ് ജയദ്രഥൻ കവർന്നെടുത്തത് കേട്ടപോലെ.",
        "0.42": "നീണ്ട വഴി വേഗത്തിൽ താണ്ടി, ശ്രേഷ്ഠനായ (മൂത്ത ഗുരുവായ) അദ്ദേഹത്തോടൊപ്പം അവൻ എത്തി, വാക്കുകളുടെ പ്രവാഹങ്ങളാൽ ആ മനുഷ്യനെ ഭയപ്പെടുത്തി (അർജുനൻ അമ്പുകളുടെ പ്രവാഹത്താലെന്നപോലെ), വിജയം നേടി, അന്തര്യാമിയെക്കുറിച്ചുള്ള ചോദ്യത്തിൽ കുടുങ്ങിയപ്പോൾ സ്വയം പരിഹാസ്യനാക്കിയ തോറ്റവനെ പരിഹസിച്ചു.",
        "0.43": "ആ ദുഷ്ടൻ, ‘സുഖം നൽകുന്നവൻ’ (ശങ്കരപണ്ഡിതൻ) എന്ന പേരുള്ള ഏകനായ സജ്ജനത്തിനെതിരായ അപമാനത്തിന് കാരണക്കാരനായിരുന്നു; ഈ ഹരിയുടെ ഭാഗം (മധ്വൻ) അവനോട് വീണ്ടും ക്ഷമിച്ചില്ല — ഒരു സിംഹം തന്റെ കുട്ടിക്ക് ഉപദ്രവമേറ്റാൽ പന്നിയോട് ക്ഷമിക്കാത്തതുപോലെ.",
        "0.44": "മുമ്പ് പരാജയപ്പെട്ടെങ്കിലും ഭയത്താൽ രക്ഷ തേടി അവന്റെ പുറകിൽ നിന്ന മനുഷ്യനെ (പുണ്ഡരീകനെ), വിജയി അഞ്ചോ ആറോ പ്രത്യേക വാക്കുകളാൽ ജയിച്ചു; മറ്റുള്ളവരുടെ ഇടയിൽ അവൻ എറിഞ്ഞ വാക്പ്രവാഹങ്ങളെ മുറിച്ചുകളഞ്ഞു.",
        "0.45": "ഓരോന്നും വിഷ്ണുവിന്റെ പാദങ്ങളെത്തന്നെ അലങ്കരിക്കുന്ന, തടുക്കാനാവാത്ത വാക്കുകളുടെ തുടർച്ചയാൽ (അമ്പുകളാൽ), മധ്വനാകുന്ന പാർത്ഥൻ, ജയദ്രഥനെ അർജുനൻ എന്നപോലെ, കഞ്ജൻ (പദ്മൻ) എന്ന സൈന്ധവരാജാവിനെ തുളച്ചു കീഴടക്കി.",
        "0.46": "(സജ്ജനങ്ങൾ പ്രഖ്യാപിച്ചു:) “മതി, മതി, ലോകത്തെ ഈ കൊള്ളയടിക്കൽ! ഹേ മായാവാദി കള്ളന്മാരേ, ഓടൂ! ദർശകൻ, ദർശകൻ ഇതാ വന്നിരിക്കുന്നു; നിങ്ങളെ തീർച്ചയായും പിടികൂടും; നിങ്ങളുടെ ഗുഹകളിലേക്ക് വേഗം ഒളിക്കേണ്ട സമയമായി.",
        "0.47": "പണ്ഡിതരുടെ വലയത്തിലെ ചന്ദ്രന്റെ പ്രകാശം മങ്ങി; തർക്കവാദികളായ നക്ഷത്രങ്ങളുടെ തേജസ്സ് പൂർണ്ണമായി നശിച്ചു; ലോകത്തിൽ വ്യാപിച്ചതും, അവയുടെ പ്രകാശത്തിന്റെ മൂലമായതുമായ, നിങ്ങൾ വളർത്തിയ ഇരുട്ട് അകന്നുപോയി.",
        "0.48": "എല്ലാമറിയുന്ന, എല്ലാവരുടെയും വിളക്കായ, കിഴക്കൻ ദിക്ക് നിറച്ച്, സപ്തശാസ്ത്രങ്ങളുടെ ഏഴു കുതിരകൾ വലിക്കുന്ന രഥത്തിൽ, തന്റെ കിരണങ്ങളാൽ (വാക്കുകളാൽ) ലോകത്തെ പ്രകാശിപ്പിക്കുന്ന സൂര്യനായി ഈ ദൈവം തന്നെ ജ്വലിക്കുന്നത് നിങ്ങൾ കണ്ടില്ലേ?",
        "0.49": "സർവ്വാധാരമായ, ബ്രഹ്മം എന്ന ആകാശത്ത് വസിക്കുന്ന, മനോഹര രൂപമുള്ള, ശരത്കാലത്തെ നീലത്താമരപോലെ തിളങ്ങുന്ന, വ്യത്യസ്ത വാക്കുകളാൽ (ശാസ്ത്രവാക്യങ്ങളാൽ) ഗുണസമ്പൂർണ്ണനെന്ന് ഉറപ്പിക്കപ്പെട്ട മധ്വനാകുന്ന സൂര്യനെ ആർക്ക് മറയ്ക്കാനാവും?",
        "0.50": "ഓടൂ, ഓടൂ, തെറ്റായ സിദ്ധാന്തത്തിലെ അസുരന്മാരേ, വേഗം ഓടൂ! ‘വിശാലബുദ്ധി’ (പൂർണ്ണപ്രജ്ഞൻ) എന്ന പേരുള്ള നരസിംഹം ഇവിടെ ജ്വലിക്കുന്നു; ഉച്ചത്തിൽ വാവിടുന്ന വിഡ്ഢികളിൽ വേദന മുളപ്പിക്കുന്ന തന്റെ യുക്തികളുടെ മൂർച്ചയുള്ള നഖങ്ങളാലും, തന്റെ പ്രഭാഷണത്തിന്റെ ഭയങ്കര ഗർജ്ജനത്താലും, അദ്ദേഹം ശത്രുക്കളെ കീറിമുറിക്കുന്നു.",
        "0.51": "ഇതാ മറ്റൊരു പക്ഷിരാജാവ് (ഗരുഡൻ): ലോകനാഥന്റെ അനന്തമായ രൂപങ്ങൾ തന്റെ ഹൃദയത്തിൽ വഹിക്കുന്നവൻ, ഭക്തിയിൽ ഏകാഗ്രനായവൻ, സമർത്ഥൻ, ഇവിടെ സജ്ജനങ്ങൾക്കെല്ലാം അമൃത് നൽകിയവൻ — (ഗരുഡനെപ്പോലെ) തന്റെ അമ്മയ്ക്ക് മാത്രമല്ല; ജ്ഞാനികൾ അവന്റെ പാദങ്ങളിൽ വണങ്ങുന്നു; അവൻ നിങ്ങളുടെ നാശമാകും. ഹേ ഇരുനാവുള്ള മായാവാദി സർപ്പങ്ങളേ, അഹങ്കരിക്കരുത്: വേഗം നിങ്ങളുടെ മാളങ്ങളിലേക്ക് ഓടൂ!",
        "0.52": "വേദങ്ങളുടെ സമൂഹമെന്ന സുദർശനചക്രം, യുക്തിയുടെ മുഴങ്ങുന്ന ശംഖ്, തിളങ്ങുന്ന പുരാണസമൂഹങ്ങളുടെ ഗദ, മന്ത്രസമൂഹമായ പഞ്ചരാത്രത്തിന്റെ ശാർങ്ഗം വില്ല്, യഥാർത്ഥ സൂത്രങ്ങളെ താങ്ങുന്ന ഇതിഹാസങ്ങളുടെ നന്ദകം വാൾ — ഇവ വഹിച്ച്, മധ്വൻ എന്ന പേരിലുള്ള നാരായണൻ നിങ്ങളെ പിടികൂടാൻ വന്നിരിക്കുന്നു: ഓടൂ, ദൈവത്തിന്റെ മായാവാദി ശത്രുക്കളേ!”",
        "0.53": "മായാവാദികൾക്ക് എതിരായി സജ്ജനങ്ങൾ ഇങ്ങനെ പറയുമ്പോൾ, ഭക്തിനിറഞ്ഞ മനസ്സുള്ളവൻ തന്റെ ആ പിൻവാങ്ങൽസ്ഥലം വിട്ട്, ആനന്ദരൂപനായ ഭഗവാനിൽ സന്തോഷിച്ച്, പ്രഗ്യവാടം എന്ന പേരിലുള്ള ക്ഷേത്രത്തിൽ വസിച്ചു.",
        "0.54": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പന്ത്രണ്ടാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "മധ്വന്റെ വിജയത്തിൽ പരിഭ്രാന്തരായ മായാവാദികൾ വിലപിക്കുന്നു; ഗ്രാമംതോറും അദ്ദേഹത്തെയും ശിഷ്യന്മാരെയും ഉപദ്രവിക്കാനും അദ്ദേഹത്തിന്റെ ഗ്രന്ഥങ്ങൾ പിടിച്ചെടുക്കാനും അവർ തീരുമാനിക്കുന്നു. അതിനിടെ മധ്വൻ പഠിപ്പിക്കുന്നത് തുടരുന്നു; വേദമന്ത്രങ്ങളും അവയുടെ ഛന്ദസ്സും അദ്ദേഹം വിശദീകരിക്കുന്നു; ഉദിക്കുന്ന സൂര്യനെപ്പോലെ അദ്ദേഹത്തിന്റെ കീർത്തി തിളങ്ങുന്നു."
    },
    "sumadhva-vijaya-13": {
      "verses": {
        "0.0": "ഒരിക്കൽ, കാര്യം നിർവ്വഹിച്ച്, രാജാവിന്റെ ആദരം സ്വീകരിച്ച ദൂരദർശിയായവൻ ശിഷ്യന്മാരുടെ സന്തോഷത്തിനായി സഹ്യപർവതങ്ങളിലേക്ക് പോയപ്പോൾ, ഒരാൾ അദ്ദേഹത്തെ സമീപിച്ചു.",
        "0.1": "അദ്ദേഹത്തെ വണങ്ങി അയാൾ പറഞ്ഞു: “രാജാവ് അപേക്ഷിക്കുന്നു: ‘തന്റെ ദാസരായ ഞങ്ങളെ അനുഗ്രഹിക്കാൻ ഭഗവാൻ വേഗം ഇവിടെ വരട്ടെ’ — ഒരു കാര്യം നിറവേറ്റാനാണ് അദ്ദേഹത്തിന്റെ ആഗ്രഹം.”",
        "0.2": "അപ്പോൾ, ഇന്ദ്രന്റെ ദിക്ക് വിട്ട്, വളരുന്ന തേജസ്സോടെ ജ്ഞാനികളുടെ സൂര്യൻ പടിഞ്ഞാറോട്ട് സഞ്ചരിച്ചു; തന്റെ പാദസ്പർശത്താൽ ഭൂമിയെ ശുദ്ധമാക്കി അദ്ദേഹം പ്രകാശിച്ചു.",
        "0.3": "(ശ്ലോകങ്ങൾ 3 മുതൽ 7 വരെ അദ്ദേഹത്തിന്റെ യാത്രയെ ഗംഗയോട് ഉപമിക്കുന്നു.) നദി താഴ്ന്ന കുന്നുകളെ ഒഴിവാക്കുന്നതുപോലെ, മായാവാദികൾ പതിവായി വരുന്ന അശുഭ ജനങ്ങളെ അദ്ദേഹം ഒഴിവാക്കി; പർവതങ്ങളിൽ നിന്നുള്ള അരുവികൾ ചേരുന്നതുപോലെ, ഉത്തമകുലങ്ങളിൽ പെട്ട സജ്ജനങ്ങൾ ആഴമേറിയ സ്നേഹത്താൽ പടിപടിയായി സന്തോഷിച്ച് വേഗം അദ്ദേഹത്തെ സമീപിച്ചു.",
        "0.4": "പൂക്കളും ഫലങ്ങളും നിറഞ്ഞ ഉയരമുള്ള വൃക്ഷങ്ങളെ ഗംഗ തന്റെ ജലംകൊണ്ട് വളയ്ക്കുകയും, വളയാത്തവയെ ഒടിക്കുകയും ചെയ്യുന്നതുപോലെ, തടുക്കാനാവാത്ത ശക്തിയുള്ള അദ്ദേഹം തന്റെ വാക്കുകൾകൊണ്ട് നല്ല മനസ്സും പുണ്യവുമുള്ളവരെ വണങ്ങിച്ചു; അഭിപ്രായത്തിൽ ദൃഢമായവരെ തകർത്തു.",
        "0.5": "തന്റെ യാത്രയുടെ ഉത്സവത്തിൽ അദ്ഭുതപ്പെട്ട പലതരം ഗ്രാമീണരാൽ എപ്പോഴും ചുറ്റപ്പെട്ടും, കീർത്തി മുന്നിൽ ഓടിക്കൊണ്ടിരിക്കെയും, ദൂരദേശങ്ങളിൽ നിന്നുള്ള ആളുകൾ തങ്ങളുടെ ദുഃഖങ്ങളിൽ നിന്ന് മോചനം തേടി അദ്ദേഹത്തെ സമീപിച്ചു.",
        "0.6": "ദേവന്മാരും അവരുടെ പരിചാരകരും, മറ്റാർക്കും കാണാനാകാത്ത മഹർഷിമാരും സേവിക്കുന്നവനായി, ഹരിയുടെ താമരപ്പാദങ്ങളുമായുള്ള ബന്ധമാണ് അദ്ദേഹത്തിന്റെ സത്തയെങ്കിൽ, അദ്ദേഹം ലോകത്തിലെ പവിത്രീകരിക്കുന്നവരിൽ പവിത്രീകരിക്കുന്നവനായി; വിഷ്ണുവിന്റെ പാദത്തിൽ നിന്ന് ഒഴുകുന്ന ഗംഗപോലെ.",
        "0.7": "വഴിയിൽ തടസ്സമില്ലാതെ, ജ്ഞാനികളുടെ രാജാവായ പരമാനന്ദതീർത്ഥർ, ശുദ്ധരൂപമുള്ളവൻ, സ്വർഗ്ഗഗംഗയുടെ മുറിയാത്ത പ്രവാഹംപോലെ അതിശയമായി പ്രകാശിച്ചു.",
        "0.8": "യഥാസമയം അദ്ദേഹം ‘സ്തംഭം’ എന്ന പേരുള്ള (കബേനാടു) പ്രദേശത്ത് എത്തി, ലോകം മുഴുവൻ ആദരിക്കുന്ന മദനേശ്വരന്റെ പ്രകാശമുള്ള വാസസ്ഥലത്ത് പ്രവേശിച്ചു.",
        "0.9": "അവിടെ രാത്രി കഴിഞ്ഞ്, പുലരിക്ക് യോജിച്ച യോഗം ചെയ്തു; ഒരുക്കത്തിന്റെ അടയാളങ്ങളിൽ നിന്ന് യാത്രയ്ക്ക് തയ്യാറായെന്ന് ശിഷ്യന്മാർ പെട്ടെന്ന് മനസ്സിലാക്കി.",
        "0.10": "അവിടെയുള്ള സന്യാസിമാർ, ശാന്തമായ ധ്യാനത്തിനായി തങ്ങളുടെ മുന്നിൽ കാവിത്തുണി വിരിച്ചിരുന്നത് വേഗം എടുത്തു; തങ്ങളുടെ ദണ്ഡുകളും മറ്റു സാമഗ്രികളും അവയുടെ യഥാർത്ഥ അടയാളങ്ങളോടെ എടുക്കാൻ തിടുക്കം കൂട്ടി.",
        "0.11": "ഒരു ബുദ്ധിമാനായ ശിഷ്യൻ, അദ്ദേഹത്തിന്റെ ശരീരത്തിലെ ശംഖും മറ്റു ലക്ഷണങ്ങളും ഉണങ്ങിയതായി കണ്ട്, ഹരിയുടെ പ്രസാദംപോലെ യോജിച്ച, തിളങ്ങുന്ന തുളസിമാല കഴുത്തിൽ ചുറ്റി.",
        "0.12": "ആത്മനിയന്ത്രണമുള്ള ഒരു ശിഷ്യൻ, കൈകൾ ശുദ്ധമാക്കി, ശ്വാസവും വാക്കും നിയന്ത്രിച്ച്, ഗുരുവിന്റെ ചക്രധാരിയായ ഭഗവാന്റെ വിഗ്രഹങ്ങൾ നിറച്ച പെട്ടി ചരടുകളിൽ കെട്ടി, ഒരു തുണികൊണ്ട് മൂടി കൊണ്ടുപോയി.",
        "0.13": "യുവശിഷ്യന്മാരുടെ സംഘം തന്നെ, നിരനിരയായി തൂങ്ങുന്ന ജലപാത്രങ്ങളും ഗ്രന്ഥങ്ങൾ മുതലായവയുടെ ഭാരമേറിയ ചുമടുകളും, യാതൊരു ബുദ്ധിമുട്ടുമില്ലാതെ കൊണ്ടുപോയി; കാരണം കൗശലത്തിന് തുല്യമായ മറ്റൊരു പുണ്യമില്ല.",
        "0.14": "പുതിയ ഒരു ശിഷ്യൻ വലിയ തിടുക്കത്തിൽ ഓടിനടന്ന്, തന്റെ ചുമടിനുള്ള കയറുകൾ വളരെനേരം തിരഞ്ഞുകൊണ്ടിരുന്നു; അശ്രദ്ധമായി ചോദ്യങ്ങൾ ചോദിച്ചുകൊണ്ടിരുന്ന അവനെ ചിലർ അവിടെ പരിഹസിച്ചു.",
        "0.15": "പിന്നെ, ആ നിമിഷം അടിച്ച ഒരു വലിയ മണിയുടെ ഗംഭീര ശബ്ദം, പരമനാൽ പ്രേരിതനാണെന്നതിന്റെ അടയാളമായി സ്വീകരിച്ച്, അനന്തജ്ഞാനിയായവൻ തന്റെ ജനങ്ങൾ മുന്നോട്ടു പോകുമ്പോൾ പുറപ്പെട്ടു.",
        "0.16": "ഉയരത്തിൽ പിടിച്ച മനോഹരമായ കുടയോടെ, ഉദിക്കുന്ന സൂര്യനു മുകളിൽ പൂർണ്ണചന്ദ്രനുള്ളതുപോലെ, മുമ്പൊരിക്കലും കാണാത്ത തേജസ്സ് ആ ഉത്തമ സന്യാസിരാജാവിന് ഉണ്ടായിരുന്നു.",
        "0.17": "മൂന്നു ലോകങ്ങളുടെ ആധാരമായ മുകുന്ദനെ ഉള്ളിൽ വഹിക്കുന്ന ഗുരുവിനെ മറ്റൊരാൾ തന്നെ ചുമന്നു; അത് അദ്ഭുതമല്ല — പ്രാണന്റെ നാഥനായതിനാൽ അദ്ദേഹം ആ മനുഷ്യനെയും വഹിച്ചിരുന്നുവല്ലോ.",
        "0.18": "സന്യാസിമാരും ഗൃഹസ്ഥന്മാരും പ്രധാന ബ്രഹ്മചാരികളും, നിഷിദ്ധകർമ്മങ്ങളും കാമനാപ്രേരിത കർമ്മങ്ങളും ഉപേക്ഷിച്ച വേദാനുയായികളും, നൂറു ഗുണങ്ങളുള്ളവനെ നൂറുകണക്കിനായി അനുഗമിച്ചു — ശരീരധാരിയായ തങ്ങളുടെ തന്നെ ധർമ്മങ്ങളെപ്പോലെ.",
        "0.19": "നടപ്പാതയിൽ ആ മനുഷ്യരത്നത്തെ നോക്കിക്കൊണ്ട് പരിവാരങ്ങൾക്ക് ക്ഷീണം തോന്നിയില്ല — കാരണം അദ്ദേഹത്തെ സ്മരിക്കുന്നതുതന്നെ ലൗകികജീവിതത്തിൽ നിന്ന് മോചനം നൽകുന്നു.",
        "0.20": "അപ്പോൾ മദനേശ്വരന് പ്രിയമായ ദേശത്ത്, ഉത്തമ മനസ്സുള്ള രാജാക്കന്മാരിൽ ശ്രേഷ്ഠനായ ജയസിംഹൻ — ‘സിംഹം’ എന്നും ‘സ്തംഭം’ എന്നും ചേർന്ന പേരുള്ള (കംഭസിംഹൻ) — എത്തിയ ഗുരുവിനെ എതിരേൽക്കാൻ വേഗം മുന്നോട്ടു വന്നു.",
        "0.21": "തന്റെ രഥത്തിൽ നിന്ന് വളരെ മുമ്പേ ഇറങ്ങി, സൈനികരെ വഴിയിൽ നിന്ന് മാറ്റി, കുറച്ച് ബ്രാഹ്മണരോടൊപ്പം അദ്ദേഹം മുന്നോട്ടു വന്ന്, മൂന്നു ലോകങ്ങളിലും ആദരിക്കപ്പെടുന്നവന്റെ പാദങ്ങൾക്കരികിൽ വണങ്ങി.",
        "0.22": "ഭക്തികൊണ്ട് ഹൃദയം നനഞ്ഞ രാജാവ് വിനയത്തോടെ പിന്തുടർന്ന്, അദ്ദേഹം വേഗം വിഷ്ണുമംഗലത്തിലെ മനോഹര ക്ഷേത്രത്തിനരികിൽ എത്തി.",
        "0.23": "രണ്ടു ഗ്രാമങ്ങളിലെയും ജനങ്ങളും, രാജാവിനെ കാണാൻ ആഗ്രഹിച്ചു കൂടിയവരും, അനന്തമനസ്സുള്ളവൻ അടുത്തുവരുന്നത് അദ്ഭുതസമുദ്രത്തിൽ മുങ്ങി വീണ്ടും വീണ്ടും നോക്കി നിന്നു.",
        "0.24": "(ശ്ലോകങ്ങൾ 24 മുതൽ 36 വരെ അവർ കണ്ടത് വിവരിക്കുന്നു.) അദ്ദേഹത്തിന്റെ മുന്നിൽ വൈദഗ്ധ്യമുള്ള പുരുഷന്മാർ നടന്നു, അവർ രചിച്ച മുകുന്ദന്റെ ഗീതങ്ങൾ മധുര സ്വരത്തിൽ പാടി; കാതിന് ഇമ്പമുള്ള അവ പാടി നൃത്തം ചെയ്തു; താമരവിത്തുമാലകളും ചക്രമുദ്രകളും ധരിച്ചിരുന്നു;",
        "0.25": "രാജാവ് കൈകൂപ്പി പരസ്യമായി പിന്തുടർന്നു; ജനത്തിരക്കിന്റെ ഉന്തും തള്ളും സഹിച്ചുകൊണ്ട്, ആത്മാർത്ഥമായി ദാസ്യം ഏറ്റെടുത്തു; തന്നെ കരുണയുടെ വിഷയമാക്കാൻ ആഗ്രഹിച്ചുകൊണ്ട്;",
        "0.26": "അദ്ദേഹത്തിന്റെ മഹത്വവും രൂപവും ‘ഇത്’ എന്നോ ‘ഇങ്ങനെ’ എന്നോ മനുഷ്യരുടെ കണ്ണുകൾക്ക് പിടിക്കാവുന്നതല്ല; ഭൂമിയെ കൂടുതൽ അലങ്കരിക്കാൻ വ്യക്തമായി ഉദിക്കുന്ന മറ്റൊരു സ്വർഗ്ഗനാഥനെപ്പോലെ (സൂര്യൻ);",
        "0.27": "വേഗത്തിൽ നടക്കുന്നു, എന്നാൽ മന്ദഗതിയിലെന്ന് തോന്നുന്നു; ഉത്തമ യുവ സിംഹത്തിന്റെ ധീരമായ നടപ്പോടെ; തന്റെ അതിമൃദുവായ ചുവന്ന പാദങ്ങളാൽ ഭൂമിയെ പൂർണ്ണമായി പവിത്രമാക്കി;",
        "0.28": "കാൽവിരൽനഖങ്ങൾ മാണിക്യത്തിന്റെ ചുവപ്പിനെ കവിയുന്നു; പാദമുകൾ മനോഹരമായ ആമയുടെ പുറംപോലെ; കണങ്കാലുകൾ മറഞ്ഞിരിക്കുന്നു; കാൽവണ്ണകൾ ഉത്തമ ദേവന്മാരുടെ കൈകളാൽ സേവിക്കപ്പെടാൻ യോഗ്യമായത്; തുടകൾ ആനയുടെ വലിയ തുമ്പിക്കൈപോലെ;",
        "0.29": "വെളുത്ത ശുദ്ധമായ അരക്കെട്ടിൽ തിളങ്ങുന്ന പുതിയ പട്ടുവസ്ത്രം; മെലിഞ്ഞ ഉദരത്തിലും കഴുത്തിലും നെറ്റിയിലും മൂന്ന് വ്യക്തമായ രേഖകൾ അദ്ദേഹത്തെ അലങ്കരിക്കുന്നു;",
        "0.30": "പുതുതായി ഉദിച്ച സൂര്യന്റെ രശ്മിസമൂഹത്തിൽ മേരുപർവതത്തിന്റെ സ്വർണ്ണശിഖരംപോലെ, മൃദുവും സൂക്ഷ്മവും കട്ടിയുള്ളതും വ്യക്തമായ ചുവപ്പുമുള്ള കമ്പിളിമേൽമുണ്ട് ധരിച്ച്, തിളങ്ങി;",
        "0.31": "വിശാലമായ മാറും മതിൽപോലെ ഉയർന്ന തോളുകളും, ഭാരവും വൃത്താകൃതിയും നീളവുമുള്ള മനോഹര ബാഹുക്കളും; അതിചുവപ്പുള്ള മൃദുവായ കൈത്തലങ്ങളിൽ മുകളിലേക്കുള്ള രേഖകളും കൊടിയും മറ്റു മംഗളചിഹ്നങ്ങളും;",
        "0.32": "ആദ്യനോട്ടത്തിൽ പൂർണ്ണചന്ദ്രബിംബത്തെ ഓർമ്മിപ്പിക്കുന്ന മുഖം; എന്നാൽ അത് കളങ്കമില്ലാത്തതും ശുദ്ധമായ കാരുണ്യത്തിന്റെ സമുദ്രവുമായതിനാൽ അതിൽ നിന്ന് വ്യത്യസ്തമായി വേർതിരിഞ്ഞു നിൽക്കുന്നു;",
        "0.33": "മനോഹരമായ മൃദുപുഞ്ചിരിയിൽ പുതിയ മുല്ലപ്പൂപോലെ തിളങ്ങുന്ന പല്ലുകൾ; ചുണ്ടുകൾ മംഗളകരമായി ചുവന്നത്; നീണ്ട താമരക്കണ്ണുകളുടെ നോട്ടങ്ങളാൽ എല്ലാ ജനങ്ങളെയും സന്തോഷിപ്പിക്കുന്നവൻ;",
        "0.34": "പ്രകാശമുള്ള കാതിൽ തിളങ്ങുന്ന പുണ്യതുളസിക്കൂട്ടം; ഉജ്ജ്വലമായ കവിളുകൾ; മൂന്നു ലോകങ്ങൾക്ക് ഐശ്വര്യം നൽകാൻ കളിയിൽ സമർത്ഥമായ മനോഹരമായ പുരികങ്ങൾ; ഉത്തമമായ ശിരസ്സ്;",
        "0.35": "ഓരോ അവയവവും കൃത്യമായി അളന്ന്, സമർത്ഥരായ ശില്പികൾ പൂർണ്ണ വിഗ്രഹങ്ങളുടെ ലക്ഷണങ്ങൾക്ക് മാതൃകയായി സ്വീകരിച്ച ശരീരമുള്ളവൻ; അതിനാൽ ഇപ്പോൾ അദ്ദേഹം കേവലം ‘സുലക്ഷണൻ’ (നല്ല ലക്ഷണമുള്ളവൻ) എന്ന് മാത്രം വിളിക്കപ്പെടുന്നില്ല.",
        "0.36": "വലിയ ജനക്കൂട്ടത്തിന്റെ നടുവിലും, തിരക്കിനെ ഭയന്ന് ദൂരെ നിന്ന കണ്ണുകളിൽ ആകാംക്ഷയുള്ള ജനങ്ങൾക്ക് കരുണയോടെ, അദ്ദേഹം മാറിനു മുകളിലായി സ്വയം കാണിച്ചു.",
        "0.37": "വിടർന്ന കണ്ണുകളും കൂപ്പിയ കൈകളുമുള്ള ജനങ്ങളുടെ വലയത്താൽ ചുറ്റപ്പെട്ട്, അത്യന്ത ഭക്തിയോടെ വണങ്ങി, പരമജ്ഞാനിയായവൻ മുരാരിക്ക് പ്രിയമായ ക്ഷേത്രത്തിൽ പ്രവേശിച്ചു.",
        "0.38": "രാജാവിനോടൊപ്പം വിവിധ പ്രഭുക്കന്മാർക്കിടയിൽ ഇരുന്ന്, വേഷംമാറിയ ദേവനായ അദ്ദേഹം, നക്ഷത്രങ്ങൾക്കിടയിൽ പൂർണ്ണചന്ദ്രൻ എന്നപോലെ, ഭൂമിപുത്രനായ (ചൊവ്വ) കൂടെ നിൽക്കുമ്പോൾ തിളങ്ങി.",
        "0.39": "അദ്ദേഹത്തിന്റെ പ്രധാന ശിഷ്യൻ, ശബ്ദം മുതലായ യോജിച്ച ഗുണങ്ങളോടുകൂടിയവൻ, ഭാഗവതം വായിക്കുമ്പോൾ, ലൗകികബന്ധനം നശിപ്പിക്കുന്ന ചക്രധാരിയുടെ കഥ ഭഗവാൻ വ്യാഖ്യാനിച്ചു.",
        "0.40": "ആ പ്രഭാഷണം, ഉത്തമ സ്ഥൈര്യം നിറഞ്ഞതും, മധുരവും, സമൃദ്ധമായ അർത്ഥമുള്ളതും, തെളിഞ്ഞതുമായിരുന്നു; പഠിച്ചവരും പഠിക്കാത്തവരുമായ കേട്ടവരെല്ലാം ആനന്ദത്തിന്റെ സാരസമുദ്രത്തിൽ മുക്കപ്പെട്ടു.",
        "0.41": "നടക്കുക, ഇരിക്കുക, സംസാരിക്കുക തുടങ്ങിയ മധ്വന്റെ ലീലകൾ — കേവലം സ്മരണയാൽ തന്നെ ലൗകിക അസ്തിത്വത്തിൽ നിന്ന് മോചനം നൽകുന്നവ — അവയെ ദേവന്മാർക്കു മാത്രമേ എങ്ങനെയോ വർണ്ണിക്കാനാവൂ; എന്നെപ്പോലെ അല്പബുദ്ധികൾക്ക് സാധ്യമല്ല.",
        "0.42": "തപസ്സിനും കവിതയ്ക്കും മറ്റു ഗുണങ്ങൾക്കും പേരുകേട്ട ആംഗിരസ വംശത്തിലെ ലികുച കുടുംബത്തിൽ, ഗുഹൻ (സുബ്രഹ്മണ്യൻ) എന്ന പേരുള്ള ഒരു പണ്ഡിതനുണ്ടായിരുന്നു; എല്ലാ തർക്കവാദികളും ആദരിച്ച ഒന്നാംകിട കവി.",
        "0.43": "അദ്ദേഹത്തിന്റെ ഗുണങ്ങൾക്ക് യോഗ്യയായ സദ്ഗുണമുള്ള ഭാര്യ, വാസുദേവപുത്രനോട് (കൃഷ്ണനോട്) ഭക്തിയുള്ളവൾ — വിധിയുടെ ബലത്താൽ പലതവണ മക്കളെ നഷ്ടപ്പെട്ടിട്ടും — ഒരു പുത്രനെ ആഗ്രഹിച്ച്, ലോകനാഥന്മാരായ ഹരിയെയും ഹരനെയും ആരാധിച്ചു.",
        "0.44": "രണ്ടു മഹാനാഥന്മാരുടെ കൃപയാൽ, പണ്ഡിതന്റെ ഭാര്യ ഒരു രത്നസമാനനായ പുത്രനെ പ്രസവിച്ചു; അവന്റെ മൂല്യം സഭാനഗരങ്ങളിലെ മുൻനിര പരീക്ഷകർക്കുപോലും വിലയിരുത്താനായില്ല.",
        "0.45": "കുടുംബത്തെ ഉയർത്താൻ കഴിവുള്ള ലക്ഷണങ്ങളുള്ള മകന്റെ ചന്ദ്രമുഖം കണ്ട്, കവി കൃതകൃത്യനായി, ചടങ്ങുകൾ നടത്തി, അവന് യോജിച്ച ത്രിവിക്രമൻ എന്ന പേര് നൽകി.",
        "0.46": "ഇപ്പോഴും കൊച്ചുകുട്ടിയായിരിക്കെ തന്നെ പണ്ഡിതപുത്രൻ കുറ്റമറ്റ ശ്ലോകങ്ങൾ പറയുന്ന കവിയായിരുന്നു; ശരിക്കും, ഉദിച്ചുവന്നതേയുള്ളൂവെങ്കിലും തേജസ്സിൽ ശക്തമായ സൂര്യൻ തിളങ്ങുന്നുവല്ലോ.",
        "0.47": "യഥാസമയം, എല്ലാ അംഗങ്ങളാലും (വേദാംഗങ്ങളാലും) പ്രകാശിക്കുന്ന തന്റെ ശാഖകളും (പഠനശാഖകൾ), ഉത്തമ ‘പക്ഷികളാൽ’ (പണ്ഡിതന്മാരാൽ) സേവിക്കപ്പെടുന്ന ഈ ലികുച വൃക്ഷം, നല്ല സഞ്ചാരികളെ സഹായിക്കാൻ, രസം നിറഞ്ഞ കാവ്യഫലം നൽകി.",
        "0.48": "മായാവാദത്തിന്റെ വിശാലസിദ്ധാന്തത്തിന്റെ അസംബന്ധം അദ്ദേഹം യഥാർത്ഥത്തിൽ തെളിയിച്ചിരുന്നെങ്കിലും, അതിനെ പരിഹരിക്കാൻ സ്വന്തം ഗുരുവിനുപോലും കഴിഞ്ഞിരുന്നില്ല; എങ്കിലും, കൂട്ടുകാരുടെ പ്രേരണയാൽ, അദ്ദേഹം അത് സൂക്ഷ്മമായി പഠിച്ചു.",
        "0.49": "ഉത്തമനായ ത്രിവിക്രമൻ ബാല്യം വിട്ട്, വാക്കുകളുടെ കളിയാൽ മഹത്വത്തിൽ ഉയർന്നപ്പോൾ — വാമനനിൽ നിന്ന് ത്രിവിക്രമനായി ഭഗവാൻ വളർന്നതുപോലെ — ഭാനുവിനെ മുൻനിർത്തിയ എല്ലാ പണ്ഡിതന്മാരും വേഗം മിന്നാമിനുങ്ങുകൾ പോലെയായി (ഉദിച്ചുയർന്ന ഭഗവാന് മുന്നിൽ സൂര്യനും നക്ഷത്രങ്ങളും എന്നപോലെ).",
        "0.50": "വളരെ മൂർച്ചയുള്ള ബുദ്ധിയുള്ള, ഒരുലക്ഷത്തി ഇരുപത്തിയയ്യായിരം ഗ്രന്ഥങ്ങളുള്ള മായാവാദ സിദ്ധാന്തത്തിൽ തർക്കവീരനായ, തന്റെ മഹത്വത്താൽ ഭൂമിയിൽ ആദരിക്കപ്പെട്ട മകനോട് പിതാവ് രഹസ്യമായി പറഞ്ഞു:",
        "0.51": "“ഈ നന്നായി ആലോചിച്ച വാക്കുകൾ കേൾക്കൂ: കലിയുഗത്തിൽ ഗുണരഹിത ബ്രഹ്മധ്യാനം സന്തോഷത്തിലേക്ക് നയിക്കില്ല. അതിനാൽ, മകനേ, ഗുണങ്ങളുടെ ബന്ധനത്തിൽ നിന്ന് മോചനത്തിനായി, ഗുണസമ്പന്നനായ ദൈവം വാസുദേവനെ മാത്രം സ്മരിക്കൂ.”",
        "0.52": "പിതാവിന്റെ വാക്കുകൾ കേട്ട്, അല്പം അസ്വസ്ഥനായെങ്കിലും, അവൻ ശാസ്ത്രങ്ങളുടെ സാരം ചിന്തിച്ചു; എങ്കിലും മറുകര കടക്കാനുള്ള ആഗ്രഹത്താൽ, ഗുണരഹിത ധ്യാനത്തെക്കുറിച്ച് മറ്റുള്ളവരിൽ നിന്ന് കേൾക്കുന്നത് തുടർന്നു.",
        "0.53": "തന്റെ കടമകളിൽ സമർപ്പിതനായ ആ ഉത്തമ ഗൃഹസ്ഥൻ, മനസ്സ് കലിയുഗത്താൽ അസ്വസ്ഥമായിരുന്നെങ്കിലും, സ്വഭാവത്താൽ അതീവ ബുദ്ധിമാനായിരുന്നു; ഒരിക്കൽ അവൻ ഇങ്ങനെ വ്യക്തമായി ചിന്തിച്ചു:",
        "0.54": "“സത്യവതിയുടെ പുത്രൻ തന്നെ രചിച്ച സൂത്രങ്ങളാണ് പണ്ഡിതർക്ക് ഇവിടെ പ്രമാണം; വ്യാഖ്യാനങ്ങൾ തമ്മിൽ പൊരുത്തമില്ലാത്തവയാണ്; അവയെല്ലാം പ്രമാണമാകാൻ കഴിയില്ല.",
        "0.55": "മുൻവിധിയില്ലാതെ നോക്കിയാൽ അവയിൽ ഒന്നിനും യോജിപ്പ് കാണുന്നില്ല; എങ്കിലും പരമ്പരാഗതമായി നമ്മിലേക്ക് എത്തിയതിനാൽ മാത്രം ശങ്കരന്റേതിനെ ആദരവോടെ പഠിക്കുന്നു.",
        "0.56": "ചെറിയ ബുദ്ധിയുള്ളവന് ഉപനിഷത്തുകളെ യോജിപ്പിക്കുന്നത് എളുപ്പമല്ലെന്ന് സമ്മതിച്ചാലും, നമുക്ക് ആലോചിക്കാം: ശാസ്ത്രങ്ങൾ ഇവിടെ വിധിക്കുന്ന ആ ധ്യാനമില്ലാതെ ആരും മോക്ഷം നേടുന്നില്ല.",
        "0.57": "സത്യജ്ഞാനികൾ ധ്യാനത്തിനായി, സത്ത, ചിത്ത്, ആനന്ദം എന്നിവയായ സർവ്വവ്യാപിയും അദ്വൈതവുമായ ആത്മാവിനെ നിർദ്ദേശിക്കുന്നു; എന്നാൽ അതിന് ഏതെങ്കിലും രൂപമുണ്ടെന്ന് നിശ്ചയിക്കപ്പെട്ടിട്ടില്ലെങ്കിൽ, അത് വെറും പ്രകാശം പോലുമല്ല — അതാണ് ഇവിടത്തെ കടങ്കഥ.",
        "0.58": "അത് അങ്ങനെ രൂപമുള്ളതായി ധ്യാനിച്ചാൽ, നിഷേധത്താൽ അത് ഇരുട്ടായി തോന്നുന്നു; അപ്പോൾ ഫലമായ മോക്ഷവും അതേ സ്വഭാവമുള്ളതാകും. അതിനാൽ ഈ ധ്യാനം എന്നെ ഒട്ടും തൃപ്തിപ്പെടുത്തുന്നില്ല.",
        "0.59": "അതിനാൽ, വേദങ്ങളും പുരാണങ്ങളും മഹാഭാരതവും മറ്റും എന്റെ കഴിവുപോലെ ഞാൻതന്നെ പരിശോധിച്ച്, സ്മൃതികളുടെ കടമകൾ വിശ്വസ്തതയോടെ പാലിച്ചുകൊണ്ട്, ഗുണങ്ങളുള്ള മുകുന്ദനെ ധ്യാനിക്കാം.”",
        "0.60": "ഉത്തമനായവൻ ഇതിൽ ഉറച്ചു, വിവേകത്തോടെ അത് ചെയ്യാൻ തുടങ്ങിയപ്പോൾ, ലോകങ്ങളിലാകെ പരക്കുന്ന പൂർണ്ണമതിയായ (മധ്വന്റെ) പൂർണ്ണവും ശുദ്ധവുമായ കീർത്തി അദ്ദേഹം കേട്ടു.",
        "0.61": "(മായാവാദികൾ അദ്ദേഹത്തെ പ്രേരിപ്പിച്ചു:) “ഏതോ വാക്പടുവായ ഒരാൾ നമ്മുടെ പരമ്പരാഗത സിദ്ധാന്തത്തെ നശിപ്പിക്കുന്നു; അപരിമിത യുക്തികളുള്ള വീരനായ നീ അദ്ദേഹത്തെ ഖണ്ഡിക്കൂ; അതിന് മറ്റാർക്കും കഴിയില്ല.",
        "0.62": "നീ വേദങ്ങളുടെ നദികളിൽ മുങ്ങി, സിദ്ധാന്തങ്ങളുടെ സമുദ്രങ്ങളിൽ കളിക്കുന്നു; പുതിയ കാവ്യരസത്തിന്റെ പ്രേമി; തർക്കവാദികളിലെ ഗജരാജനായ നിന്നെ എതിർക്കാൻ ഇതുവരെ മറ്റൊരു ആനയും ജനിച്ചിട്ടില്ല.",
        "0.63": "ചന്ദ്രനെപ്പോലെ വെളുത്ത കീർത്തി നേടുക; നിന്റെ സ്വന്തം കൂട്ടത്തിന്റെ ഭയം നീക്കുക — വിധി നിന്റെ മുന്നിൽ കൊണ്ടുവന്ന ഈ എതിരാളിയായ ആനയെ ഇപ്പോൾ തടഞ്ഞുകൊണ്ട്.”",
        "0.64": "ഇങ്ങനെ മായാവാദികൾ തങ്ങളിൽ ഒരാളായി പലയിടങ്ങളിലും അപേക്ഷിച്ചപ്പോൾ, സംശയങ്ങൾ തീർക്കുന്നവനും വളരെ അഹങ്കാരിയുമായ അദ്ദേഹം സൗഹൃദപൂർവ്വം മറുപടി പറഞ്ഞു; എങ്കിലും മനസ്സിൽ അദ്ദേഹം സംശയത്തിൽ വീണു.",
        "0.65": "മധ്വന്റെ ശുദ്ധമായ വാക്കുകളാകുന്ന തോട്ടി പിടിച്ച മനുഷ്യരെ പീഡിപ്പിച്ച ഈ കവിയാന ഗജം, വിവിധ മറുപടികളുടെ പൊടി പറത്തി എതിർക്കുമ്പോൾ അവരുടെ കണ്ണുകളെ കൂടുതൽ മറച്ചു.",
        "0.66": "രാത്രിയിൽ, മറ്റാർക്കും അറിയാതെ, വിവേകമുള്ള അദ്ദേഹം അളവില്ലാത്ത ജ്ഞാനമുള്ളവന്റെ മനോഹര ശാസ്ത്രത്തിന്റെ സാരം പരിശോധിച്ചു; ഉള്ളിൽ ആനന്ദം നിറഞ്ഞ ഒരു വലിയ അദ്ഭുതം അനുഭവിച്ചു.",
        "0.67": "അദ്ദേഹവുമായി ചർച്ച ചെയ്ത്, അളവില്ലാത്ത ജ്ഞാനമുള്ളവന്റെ യഥാർത്ഥ ദർശനം കണ്ടപ്പോൾ അദ്ദേഹത്തിന് ബോധ്യമായി; എന്നാൽ ഉടൻ തന്നെ അദ്ദേഹം ആ സിദ്ധാന്തം സ്വീകരിച്ചില്ല; കാരണം ജ്ഞാനികൾ എല്ലാം ആലോചിച്ചശേഷമേ ചെയ്യൂ.",
        "0.68": "അപ്പോൾ ഉത്തമനായ ത്രിവിക്രമൻ (ആയുഗവിക്രമൻ) വിഷ്ണുമംഗലത്ത്, അളവില്ലാത്ത ജ്ഞാനമുള്ളവനെ സമീപിച്ച്, സത്യം പഠിക്കാൻ ദേവന്മാരുടെ നാഥനായ ഇന്ദ്രൻ നാലുമുഖങ്ങളുടെ പുഞ്ചിരിയാൽ തിളങ്ങുന്ന താമരയിൽ ജനിച്ച ബ്രഹ്മാവിന്റെ അടുത്ത് ചെല്ലുന്നതുപോലെ, ആനന്ദം നൽകുന്നവനെ വണങ്ങി.",
        "0.69": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പതിമൂന്നാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "മധ്വൻ ശിഷ്യന്മാരോടൊപ്പം യാത്ര ചെയ്യുന്നു; ഒരു രാജാവ് അദ്ദേഹത്തെ സ്വീകരിക്കുന്നു. പാദം മുതൽ ശിരസ്സുവരെയുള്ള ശരീരലക്ഷണങ്ങൾ ഈ സർഗ്ഗം വിവരിക്കുന്നു; ലികുച കുലത്തിലെ പ്രശസ്ത പണ്ഡിതനും കവിയുമായ ത്രിവിക്രമ പണ്ഡിതൻ, മധ്വനോട് വെല്ലുവിളിക്കാനായി എത്തുന്നതായി അവതരിപ്പിക്കപ്പെടുന്നു."
    },
    "sumadhva-vijaya-14": {
      "verses": {
        "0.0": "മേഘക്കൂട്ടങ്ങൾ വെള്ളം തീർന്നപ്പോൾ ഇരുട്ട് ഉപേക്ഷിക്കുന്നതുപോലെ, രാജാക്കന്മാരിൽ സിംഹമായവന്റെ ശക്തിയാൽ സമ്മേളിച്ച പ്രഭുക്കന്മാർ വൈരം ഉപേക്ഷിച്ചു; തിളങ്ങുന്ന മധ്വസൂര്യൻ വ്യക്തമായി ഉദിച്ചപ്പോൾ ലോകം മനോഹരമായി, സജ്ജനങ്ങളാകുന്ന താമരകൾ വിരിഞ്ഞു.",
        "0.1": "“ക്ഷമയാൽ അലങ്കരിക്കപ്പെട്ട ഉത്തമരേ, നടന്ന തെറ്റ് പൊറുക്കൂ” എന്ന് മൃദുവായി പറഞ്ഞ പ്രഭുക്കന്മാരുടെ അപേക്ഷയിൽ, ദശഹൃദയന്റെ (മധ്വന്റെ) കൽപ്പനപ്രകാരം ശങ്കരാര്യൻ (ശങ്കരപണ്ഡിതൻ), മറ്റുള്ളവർ കുതന്ത്രത്താൽ കവർന്നെടുത്ത ഗ്രന്ഥസമുച്ചയം തിരികെ നൽകി.",
        "0.2": "സഹോദരന്റെ വിജയത്തിൽ സന്തുഷ്ടനായ ശ്രേഷ്ഠ കവിയായ ത്രിവിക്രമൻ, തന്റെ അനുഗ്രഹത്താൽ മഹാമനസ്കനായ രാജാവിനെ (ജയസിംഹനെ) സന്തോഷിപ്പിച്ചു; ആ രാജാവ്, മനുഷ്യസിംഹം, ഗുരുവിന്റെ പാദങ്ങൾക്കരികിൽ വണങ്ങിയിരുന്നു, ഗ്രാമത്തലവന്മാരും വണങ്ങിനിൽക്കുന്ന ഗ്രാമവാസികളും ചുറ്റും.",
        "0.3": "“രാജാവേ, ഭാഗ്യഹീനർക്ക് നേടാൻ പ്രയാസമുള്ളതും, ഭക്തർക്ക് സഭയിൽ ദേവേന്ദ്രപദവി നൽകുന്നതുമായ പരമാനന്ദതീർത്ഥരുടെ പാദധൂളി അങ്ങയുടെ ഉള്ളിൽ എപ്പോഴും സുഖം നൽകട്ടെ.”",
        "0.4": "ഈ കവികളുടെ രാജാവ് അദ്ദേഹത്തെ ഇതുവരെ നന്നായി പരിചയപ്പെട്ടിട്ടില്ലെങ്കിലും, അദ്ദേഹത്തിന്റെ ഗുണങ്ങളുടെ ആഴമേറിയ സത്ത അറിഞ്ഞത് അദ്ഭുതമല്ല: പൂന്തേൻ ശേഖരിക്കാൻ പറക്കുന്ന വണ്ടുകളുടെ രാജാവ് പരിചയമില്ലാത്ത കാട്ടിലും യജമാനൻതന്നെയാണ്.",
        "0.5": "ഇങ്ങനെ ആ വിശാലമനസ്കൻ അവിടെ കുറച്ചു രാത്രികൾ താമസിച്ചു — ദുഷ്ടന്മാരിൽ വിദ്വേഷത്തിന്റെ കുറ്റം വർദ്ധിപ്പിച്ചും, മധ്യസ്വഭാവക്കാരിൽ അദ്ഭുതം ഉണർത്തിയും, സജ്ജനങ്ങൾക്ക് അവരുടെ ലക്ഷ്യത്തിന് യോജിച്ച ഐശ്വര്യം നൽകിയും.",
        "0.6": "(സർഗ്ഗത്തിന്റെ ശേഷഭാഗം അദ്ദേഹത്തിന്റെ ദിനചര്യ വിവരിക്കുന്നു.) പ്രശംസനീയമായ വേളയിൽ വിനതാപുത്രൻ (അരുണൻ) ഉദിച്ചപ്പോൾ, കടമകൾ അറിയുന്നവരിൽ ശ്രേഷ്ഠനായവൻ തന്റെ കടമകളെല്ലാം നിർവ്വഹിച്ച്, ചുവന്ന തിരശ്ശീലയ്ക്ക് പിന്നിൽ യോജിച്ച യോഗാസനത്തിലിരുന്ന്, ഗുണസമ്പന്നനായ നാരായണൻ എന്ന ബ്രഹ്മത്തെ ധ്യാനിച്ചു.",
        "0.7": "അനേകം മുഖ്യ സന്യാസിമാർ, അംഗീകൃത ദന്തശുദ്ധി കമ്പുകളാൽ പല്ലുകൾ വെളുപ്പിച്ച്, അവിടെ ഒന്നിച്ചു സ്നാനം ചെയ്തു; ഗുരു പഠിപ്പിച്ച ആചാരനിയമങ്ങളിലെ തങ്ങളുടെ ഉറപ്പ് അവരുടെ കർമ്മങ്ങളുടെ മികവിനാൽ വ്യക്തമായി കാണിച്ചു.",
        "0.8": "ഏറ്റവും അവസാനം ഉറങ്ങുകയും ആദ്യം ഉണരുകയും ചെയ്ത ശിഷ്യന്മാർ, ഗുരുക്കന്മാരുടെ കഠിനസേവ വലിയ ആദരവോടെയും സന്തോഷത്തോടെയും ചെയ്തു — അർദ്ധരാത്രി മുതൽ അതുവരെ; അല്ലെങ്കിൽ അവർ ആഗ്രഹിച്ച ഉത്തമലക്ഷ്യം എങ്ങനെ നേടും?",
        "0.9": "കേൾക്കാനും ചിന്തിക്കാനുമായി ദീർഘനേരം ഉണർന്നിരുന്ന ഒരു ശിഷ്യനെ പെട്ടെന്ന് ഉറക്കം കീഴടക്കി; ഉണർന്നപ്പോൾ ബഹുമാന്യനായ ഗുരു തന്നെ സ്വന്തം വസ്ത്രവും മറ്റും വേഗം എടുക്കുന്നത് കണ്ട് അവൻ പശ്ചാത്താപത്താൽ നിറഞ്ഞു.",
        "0.10": "“ഉണർന്നിരുന്നിട്ടും നീ ഇത് മുൻകൂട്ടി ചെയ്തില്ലല്ലോ?” എന്ന ഗുരുക്കന്മാരുടെ ശാസനയെ ഭയന്ന്, ശിഷ്യന്മാർ ശരീരം വളച്ച് നിശ്ശബ്ദരായി വഴി തെളിച്ചു നിന്നു; ഗുരുക്കന്മാർ അടുത്തുള്ളപ്പോൾ അവർ വളരെനേരം വെള്ളത്തിലേക്ക് ഇറങ്ങിയില്ല.",
        "0.11": "വിളക്കുവെളിച്ചത്തിൽ തിളങ്ങുന്ന ആ മഹാമനസ്കന്റെ അരികിൽ, പൂർണ്ണമായി നിയന്ത്രിച്ച മനസ്സുള്ള ഒരു സന്യാസി മനോഹരമായ ശംഖിൽ വെള്ളം നിറച്ച് അർഘ്യം മുതലായവ സമർപ്പിച്ചു; ചക്രധാരിയുടെ വിഗ്രഹങ്ങളിൽ നിന്ന് ഉത്തമമായ പുഷ്പക്കൂമ്പാരം ആദരപൂർവ്വം നീക്കി.",
        "0.12": "തലേദിവസത്തെ നിവേദ്യപ്പൂക്കളിൽ നിന്ന് അമൃത് ഒഴുകുന്നത് കണ്ട ശിഷ്യന്മാർ ആദ്യം അത് നെയ്യാണെന്ന് തെറ്റിദ്ധരിച്ചു; പിന്നീട് കൂടുതൽ വാക്കുകളിൽ നിന്ന് അത് അമൃതാണെന്ന് വിശ്വസിച്ചു — ഗുരുവിന്റെ ശക്തിയാൽ ഭഗവാന് ദിവസവും അമൃതമയ ആഹാരം നിവേദിക്കപ്പെടുന്നതിനാൽ.",
        "0.13": "പിന്നെ, സന്ധ്യാവന്ദനത്തിന് യോജിച്ച മന്ത്രങ്ങളാൽ പഞ്ചാംഗജ്ഞരാൽ അംഗീകരിക്കപ്പെട്ട്, ആറു ഗുണങ്ങളുടെ നാഥനായ, മൂന്നു ശക്തികളോടുകൂടിയ, രശ്മികളുടെ ചക്രവർത്തിയായ സൂര്യൻ ഉദിച്ചു; തന്റെ വിശാല ബിംബത്തിൽ സ്വന്തം ആത്മാവിന്റെ അന്തര്യാമി പ്രകാശം വഹിച്ചുകൊണ്ട്.",
        "0.14": "സിംഹം (ഹരി) നഖങ്ങളാൽ ആനക്കൂട്ടത്തെ ചിതറിക്കുന്നതുപോലെ, സൂര്യൻ തന്റെ ആദ്യ രശ്മിവലകളാൽ, ലോകത്തിന്റെ ഭവനം നിറച്ച്, സർവ്വജീവികളുടെ വഴി തടഞ്ഞ, കണ്മഷിപോലെ കറുത്ത, അതിഭീകരവും ഇടതൂർന്നതുമായ ഇരുട്ടിനെ അകറ്റി.",
        "0.15": "ചുവന്ന സൂര്യൻ, തെളിഞ്ഞ ആകാശം ധരിച്ച, താമരമുഖം പുഞ്ചിരിക്കുന്ന, പക്ഷികളുടെ ശബ്ദമാകുന്ന മധുരസ്വരമുള്ള, രാത്രിയിലെ മഞ്ഞുകണ്ണീർ ഉണങ്ങിയ, തന്റെ വരവിൽ സന്തോഷിച്ച് പ്രേമത്താൽ ചുവന്ന ദിക്സ്ത്രീകളെ തന്റെ രശ്മികളാകുന്ന കൈകളാൽ ആലിംഗനം ചെയ്തു.",
        "0.16": "ആയിരം രശ്മികളുള്ള സൂര്യന്റെ കിരണങ്ങൾ, ആവേശത്തോടെയുള്ള സാഷ്ടാംഗപ്രണാമങ്ങളിൽ ഉയർന്ന പൊടിയാൽ പ്രത്യേകം മനോഹരമായി, ജാലകങ്ങളിലൂടെ കടന്ന്, സമയമായി എന്ന് അറിയിക്കുന്ന സുഹൃത്തുക്കളെപ്പോലെ വിദ്യാർത്ഥികൾക്ക് ഉപകാരം ചെയ്തു.",
        "0.17": "നല്ല സ്വഭാവമുള്ളവർ വേഗം സഭാമണ്ഡപത്തിൽ ഗുരുവിന് യോജിച്ച ഉയർന്ന യോഗാസനം ഒരുക്കി; വേഗം കർമ്മങ്ങൾ പൂർത്തിയാക്കിയ സന്യാസിസംഘങ്ങളോടൊപ്പം, ശ്രവണമെന്ന ഏറ്റവും ഉത്തമകർത്തവ്യത്തിനായി എല്ലാവരും ചുറ്റും കൂടി.",
        "0.18": "മുരാരിയുടെ വാസസ്ഥലമായ വേദാന്തഗ്രന്ഥക്കെട്ടുകൾ, നിർമ്മലമായ ചരടുകളാലും മനോഹരമായ ആവരണങ്ങളാലും ബന്ധിച്ച്, വിവിധ പുറംചട്ടകളോടെ, വേഗം തുറന്നപ്പോൾ, തുറന്നുകാട്ടപ്പെട്ട മനസ്സുകളുടെ ആന്തരികാർത്ഥങ്ങൾപോലെ തിളങ്ങി.",
        "0.19": "അവയിൽ നിപുണമായ കൈകളാൽ എഴുതിയ അക്ഷരങ്ങൾ തിളങ്ങി — വളരെ അകന്നതോ പരസ്പരം തൊടുന്നതോ അല്ലാത്തവ; നേരായ നീണ്ട നിരകളുടെ സമത്വത്താൽ മനോഹരമായവ; ചിലത് ആനയുടെയും കുതിരയുടെയും രൂപത്തിലായവ; വിശാലമായ മാർജിനുകൾ വിട്ടവ.",
        "0.20": "ചിലർക്ക് പരിചയവും വൈദഗ്ധ്യവും കാരണം ഉടൻ വായിക്കാൻ കഴിഞ്ഞു; മറ്റുള്ളവർക്ക് കുറച്ചു സമയത്തിനുശേഷമേ കഴിഞ്ഞുള്ളൂ; ഇവർ വേഗം ഹരിയെയും ഗുരുവിനെയും വണങ്ങി, പ്രയത്നത്താൽ മറ്റുള്ളവരോടൊപ്പം എത്തി — പ്രയത്നം വിജയത്തിലേക്ക് നയിക്കുന്നതിനാൽ.",
        "0.21": "ജനങ്ങൾ വണങ്ങി നിശ്ശബ്ദരായപ്പോൾ, സൂര്യൻപോലും പാദങ്ങളെ ആരാധിക്കുന്നവൻ, സായംകാല മേഘംപോലെ ചുവന്ന തിരശ്ശീല നീക്കി; സഭയുടെ ആകാശത്ത് സൂര്യനെപ്പോലെ, എന്നാൽ അതിനെ കവിഞ്ഞ്, ആയിരം ഇരട്ടി പ്രകാശത്തോടെ അദ്ദേഹം തിളങ്ങി.",
        "0.22": "പിന്നെ, മൂന്നു വേദങ്ങളുടെ ത്രിവിധ സത്തയായി വിവരിക്കപ്പെടുന്ന, മൂന്നു ലോകങ്ങളുടെ ഉത്തമ തേജസ്സായ ആ അക്ഷരങ്ങളെ (അ, ഉ, മ) പൂർണ്ണമായി ഏകീകരിച്ച്, വിശാലമനസ്സുള്ള സമർത്ഥൻ, പ്രഭാഷണത്തിന്റെ പവിത്രതയ്ക്കായി പ്രണവം ഉച്ചരിച്ചു.",
        "0.23": "വായനക്കാർ ഉപനിഷത്ത് വ്യക്തമായി പാരായണം ചെയ്യുമ്പോൾ, തുടക്കത്തിൽ താഴ്ന്ന സ്വരം പാലിച്ചുകൊണ്ട്, അദ്ദേഹം ജീവജാലങ്ങൾക്ക് അമൃതായ, അമരത്വത്തിന്റെ കാരണമായ, അദ്ഭുതകരമായ പ്രഭാഷണം നൽകി.",
        "0.24": "സൂര്യപുത്രനായ കർണ്ണനെപ്പോലെ ദയാലുവും ആവശ്യക്കാർക്ക് ധനം നൽകുന്നവനും; പാർത്ഥനെപ്പോലെ ഉഗ്രനും യുദ്ധം തേടിയവർക്ക് നൂറ് അമ്പുകൾ നൽകുന്നവനും; ക്ഷീണമറിയാതെ, ചോദിച്ച എല്ലാവർക്കും ശക്തമായ മറുപടികൾ അദ്ദേഹം നിരന്തരം നൽകി.",
        "0.25": "പിന്നെ, ആയിരം രശ്മികളുള്ള സൂര്യൻ പടിഞ്ഞാറോട്ട് തിരിയുന്നതിന് മുമ്പ്, അദ്ദേഹം പ്രഭാഷണം അവസാനിപ്പിച്ച് സ്നാനത്തിനായി തടാകത്തിലേക്ക് വന്നു; അവിടെ ഉത്തമരുമായുള്ള സമ്പർക്കത്തിന് ആഗ്രഹിച്ച വിശുദ്ധ ജലങ്ങളും സ്വർഗ്ഗഗംഗയും മറ്റും വേഗം അദ്ദേഹത്തോടൊപ്പം ചേർന്നു.",
        "0.26": "ഉള്ളിൽ പൂർണ്ണമായി നിർമ്മലമായ ആ ജലസമൂഹം, സ്നേഹം നിറഞ്ഞ ഋഷിസംഘംപോലെ, ആദ്യം അദ്ദേഹത്തിന്റെ പ്രതിബിംബം പിടിച്ചിരുന്നു; ഇപ്പോൾ, മുങ്ങിയപ്പോൾ, സജ്ജനങ്ങൾക്ക് പ്രിയമായ തന്റെ യഥാർത്ഥ രൂപംതന്നെ നേരിട്ട് നേടി.",
        "0.27": "അളവില്ലാത്ത ജ്ഞാനമുള്ളവൻ, ശംഖണിഞ്ഞ കൈയോടെ, ചക്രമുദ്രയുള്ള ശാലഗ്രാമങ്ങൾക്ക് സ്നാനം ചെയ്തപ്പോൾ, അവയിൽ സന്നിഹിതനായ, പാഞ്ചജന്യശംഖിനെ സ്നേഹിക്കുന്നവന്റെ (വിഷ്ണുവിന്റെ) ശരീരംപോലെ, അവയിലെ അദ്ദേഹത്തിന്റെ ഉത്തമ പ്രതിബിംബങ്ങൾ തിളങ്ങി.",
        "0.28": "കുറ്റമറ്റ ജ്ഞാനമുള്ളവൻ വിഷ്ണുവിന്റെ പാദങ്ങൾ കഴുകിയ ജലം കുടിച്ചു — ഭക്തിയോടെ അത് സ്വീകരിക്കുന്നത് പന്ത്രണ്ടു വർഷത്തെ ഉപവാസത്തിന് തുല്യഫലം നൽകുമെന്ന് മഹർഷിമാർ പറയുന്നു; സ്വർഗ്ഗഗംഗയിലെയും മറ്റു പുണ്യജലങ്ങളിലെയും സ്നാനത്തെക്കാൾ ഭാഗ്യമുള്ളത്.",
        "0.29": "പന്ത്രണ്ടു സൂര്യന്മാരെപ്പോലെ പന്ത്രണ്ടു വെളുത്ത ഊർധ്വപുണ്ഡ്രങ്ങളോടെ, ശംഖും പരമചക്രമുദ്രകളും തിളങ്ങി, ഹരിക്ക് പ്രിയനും മുരശത്രുവിനോട് വിരോധമുള്ളവർക്ക് സഹിക്കാനാവാത്തവനുമായ, ബഹുമാനമുള്ള മനസ്സുള്ള അദ്ദേഹം, ലയകാലത്തെ മറ്റൊരു സൂര്യനെപ്പോലെ തിളങ്ങി.",
        "0.30": "അസാധാരണ ജ്ഞാനമുള്ളവന്റെ മുഖം — സ്വഭാവത്താൽ മധുരമുള്ളത്, വേഷം മാറിയ പൂർണ്ണചന്ദ്രബിംബം — നോക്കി ജനങ്ങൾ, കൂപ്പുകൈയോടെ, ശിഷ്യന്മാർ ‘വഴി മാറൂ!’ എന്ന് പറയുന്നതിന് മുമ്പുതന്നെ അദ്ദേഹത്തിന് വഴി ഒരുക്കി.",
        "0.31": "ഗുരുവിന്റെ രണ്ട് താമരപ്പാദങ്ങൾ കഴുകിയ വെള്ളം മുഴുവൻ ജനങ്ങൾ എടുത്തു; നിലത്തു വീണതുപോലും; ഭൂമി അതൃപ്തയായെങ്കിലും എങ്ങനെയോ അത് സഹിച്ചു; അല്ലെങ്കിൽ അവളെ ‘ക്ഷമ’ (സഹിഷ്ണുത) എന്ന് എങ്ങനെ വിളിക്കും?",
        "0.32": "ആത്മനിയന്ത്രണമുള്ള ഒരാൾ ശുദ്ധമായ കൈകളോടെ, ഏറ്റവും നല്ല വെള്ളം നിറച്ച കുടം കൊണ്ടുവന്നു — തണുത്തതും രുചിയില്ലാത്തതും ലഘുവായതും ഗന്ധമില്ലാത്തതും തെളിഞ്ഞതും നഖം തൊടാത്തതുമായ വെള്ളം; വായിൽ നിന്നുള്ള ശ്വാസം ഭയന്ന് അത് ഒരു വശത്ത് പിടിച്ചുകൊണ്ട്.",
        "0.33": "ഒടിഞ്ഞ താമരത്തണ്ടിനെ പരിഹസിക്കുന്ന വെണ്മയുള്ള മനോഹര ശംഖ് അദ്ദേഹം അമൃതസമാനമായ ജലത്തിന്റെ ധാരകൊണ്ടും സുഗന്ധപുഷ്പങ്ങൾകൊണ്ടും നിറച്ചു — ശുദ്ധപക്ഷത്തിന്റെ വ്യക്തമായ പോരാളിയും, സിദ്ധാന്തങ്ങളുടെ ഗുണം തൂക്കി നോക്കുന്നവർ പ്രിയംവെക്കുന്നവനും ആയവൻ.",
        "0.34": "ശുദ്ധമായ ചന്ദനജലത്തുള്ളികളാൽ വിഗ്രഹങ്ങൾ അഭിഷേകം ചെയ്ത ശേഷം, കരയിലെയും വെള്ളത്തിലെയും പൂക്കൾ, വള്ളികൾ, മരങ്ങൾ, ചെടികൾ എന്നിവയുടെയെല്ലാം മേൽ വിജയം നേടിയ മൂർത്തരൂപമായ തേജസ്സുപോലെ, അദ്ദേഹം ഇന്ദിരയുടെ നാഥനെ പുതിയ മൃദുവായ തുളസിയും പൂക്കളും നിരനിരയായി അർപ്പിച്ച് ആരാധിച്ചു.",
        "0.35": "ശ്രേഷ്ഠ ജ്ഞാനമുള്ളവൻ പതിനാറ് ഉപചാരങ്ങൾ അർപ്പിച്ചു; അപരാധം മുതലായ മുപ്പത്തിരണ്ട് തെറ്റുകൾ ഒഴിവാക്കി; അളവില്ലാത്ത ഗുണങ്ങളുള്ള, വില്ലാളിയായ ഭഗവാനെ വളരെ പ്രസാദിപ്പിച്ച്, പരമഭക്തിയോടെ അധികമായ ആറ് ഉപചാരങ്ങളും അർപ്പിച്ചു.",
        "0.36": "ഒരു തവണയല്ല, എപ്പോഴും അദ്ദേഹം ഹൃദയത്താമരയിൽ ഇരിക്കുന്ന, മാണിക്യവർണ്ണമുള്ള ആ ഭഗവാനെ ആരാധിക്കുന്നു — ദിവ്യശരീരമെന്ന ഗൃഹത്തിൽ, ശ്രദ്ധയുടെ മഹാനദിയിലെ ജലത്താൽ സ്നാനം ചെയ്യിച്ച്, ആന്തരഭക്തിയുടെ എട്ടു പൂക്കളോടെ.",
        "0.37": "പരമപൂജ നിർവ്വഹിച്ച ശേഷം, ഘനമുള്ള ചന്ദനജലത്താൽ തോളും മാറും കൈകളും സുഗന്ധമാക്കി, പുഞ്ചിരിയാൽ മുഖചന്ദ്രൻ മനോഹരമായി, മൃദുവായ പട്ടണിഞ്ഞ ആ ജ്ഞാനി, ദേവന്മാർക്കും മഹർഷിമാർക്കും മനുഷ്യർക്കും കണ്ണുകൾക്ക് ഉത്സവമായി.",
        "0.38": "പിന്നെ വേദപ്രഭാഷണത്തിൽ നിപുണനും അജിതനെ പരമഭക്തനുമായ ആചാര്യൻ, എളുപ്പത്തിൽ ലഭിച്ച ഉത്തമ ആഹാരം കഴിച്ചു; “ഈ ആഹാരത്താൽ ലോകനാഥനായ ശൗരി പ്രസാദിക്കട്ടെ” എന്ന് നിരന്തരം ചിന്തിച്ചുകൊണ്ട്.",
        "0.39": "സഖാക്കൾ ഒരുക്കിയ, നല്ല കമ്പിളിയും വെറ്റിവേരും ചേർന്ന ഇരിപ്പിടത്തിൽ, മനോഹരമായ തുണി വിരിച്ചിരുന്ന്, ഉത്തമസഭാമണ്ഡപത്തെ അദ്ദേഹം അലങ്കരിച്ചു; വിദ്യയുടെ പല മനോഹര ശാഖകളുടെ കളിയാൽ കവിസംഘത്തെ സന്തോഷിപ്പിച്ചു.",
        "0.40": "സമയം ഉപയോഗിച്ച്, പുരികത്തിന്റെ ചലനത്താൽ അദ്ദേഹം തന്റെ പ്രിയ ശിഷ്യനെ വിളിച്ചു; വായ്ക്കുമുന്നിൽ മൃദുവായ കൈ വെച്ച ആ ശിഷ്യൻ, പുഞ്ചിരിക്കുന്ന കണ്ണുകളിൽ നിന്ന് ഗുരുവിന്റെ ആഗ്രഹം മനസ്സിലാക്കി, വേഗം ചെവിയിൽ എന്തോ ജോലി മന്ത്രിച്ചു.",
        "0.41": "അടുത്തല്ലാതെ ഒന്നിച്ചു നിന്ന സജ്ജനങ്ങളുടെ തിരക്കിനെ മറികടന്ന്, വണങ്ങുന്നത് പരമകടമയായി കരുതിയ, പലരും മത്സരിച്ച് വേഗം അദ്ദേഹത്തിന്റെ അരികിൽ എത്തി വണങ്ങി; ആദ്യം സേവിക്കാൻ.",
        "0.42": "പലദേശങ്ങളിൽ നിന്നുള്ളവർ, കേട്ടതിനെക്കാൾ നൂറിരട്ടി ഗുണസമ്പന്നനായി അദ്ദേഹത്തെ കണ്ട് അദ്ഭുതപ്പെട്ട്, താമരക്കൈകൾ കൂപ്പി വന്നു; നിറഞ്ഞ ഹൃദയത്തോടെ അദ്ദേഹം “ഇരിക്കൂ” എന്ന് പറഞ്ഞ് അവരെ ആദരിച്ചു.",
        "0.43": "“മതി, മതി, ഇത് വീണ്ടും പറയുന്നത്; പിന്നീട് ആവർത്തിക്കാം. ഗുരുക്കന്മാർ ഇപ്പോൾ സംസാരിക്കാൻ പോകുന്നു; ഇത് ചിന്തിക്കാനുള്ള സമയമല്ല; വേഗം വരൂ!” എന്ന് പറഞ്ഞ് വിദ്യാർത്ഥികളുടെ തലവൻ, കേട്ടതു പുനരവലോകനം ചെയ്യുന്ന ശിഷ്യന്മാരെ വിളിച്ചു.",
        "0.44": "അളവില്ലാത്ത ബുദ്ധിയുള്ളവനെ — തന്റെ പ്രഭാഷണത്തിൽ ഹരിതന്നെയെന്നപോലെ തിളങ്ങുന്നവനെ — കണ്ണുചിമ്മാതെ നോക്കി, ശ്രേഷ്ഠ കവിയായ സത്യവതിപുത്രനെ (വ്യാസനെ) നോക്കിയ ജനങ്ങൾ, ഹൃദയം സന്തോഷം നിറഞ്ഞ്, സമയം കടന്നുപോയതുപോലും അറിഞ്ഞില്ല.",
        "0.45": "സൂര്യൻ അസ്തമിക്കുമ്പോഴും ഉദിക്കുമ്പോഴെന്നപോലെ പ്രകാശിച്ചു — വ്യക്തമായി നിർമ്മലവും മനോഹരവും തിളങ്ങുന്ന ചുവപ്പുമായി; സ്വന്തം പ്രകാശത്താൽ ഉയരുന്നവർക്കും ഹരിയുടെ നിർമ്മല പാദങ്ങളിൽ അഭയം തേടിയവർക്കും ദുരിതത്തിനും ഐശ്വര്യത്തിനും ഇടയിൽ വ്യത്യാസമില്ല.",
        "0.46": "മരതകവർണ്ണയും സമുദ്രവസ്ത്രവുമണിഞ്ഞ ഭൂമിദേവി, സൂര്യബിംബം പകുതി മുങ്ങിയ നിലയിൽ ഒരു നിമിഷം പിടിച്ചുനിർത്തിയപ്പോൾ, അത് തവിട്ടുനിറമുള്ള രശ്മിക്കൂട്ടങ്ങളുള്ള മാണിക്യമായി മാറി — കാണേണ്ട ഒരു കാഴ്ച.",
        "0.47": "ആഴമേറിയ ധ്യാനത്തിൽ ആ മഹാമനസ്കൻ, ഭൂമി, ജലം, അഗ്നി, വായു, ആകാശം, അഹങ്കാരം, മഹത്തത്വം എന്നിവയിലൂടെ വ്യാപിച്ച, പ്രകൃതിയുടെ ഗുണങ്ങളോടുകൂടിയ അവ്യക്തവും, ഏകനായ ഈശ്വരനെ, അസുരന്മാരിൽനിന്നും ദേവന്മാരിൽനിന്നും മനുഷ്യരിൽനിന്നും വേറിട്ടു, ഗുണസമ്പന്നനായ യഥാർത്ഥ സത്തയെ ധ്യാനിച്ചു.",
        "0.48": "ധർമ്മശാസ്ത്രങ്ങളിൽ പ്രവീണരായ, വിധിച്ചതനുസരിച്ച് പ്രവർത്തിക്കുന്ന ബ്രാഹ്മണർ നക്ഷത്രങ്ങൾ കണ്ടശേഷം സായാഹ്ന സന്ധ്യാവന്ദനം യഥാവിധി ചെയ്തു; സൂര്യനിൽ വസിക്കുന്ന മൂന്നു ലോകങ്ങളുടെ സവിതാവിനെ ധ്യാനിച്ചുകൊണ്ട്.",
        "0.49": "അഗ്നിയെ പരിപാലിക്കുകയും, അതിന്റെ ഭാഗങ്ങൾ (കലകൾ) അനുസരിച്ച് അതിൽ വസിക്കുന്നതായി പറയപ്പെടുന്ന പതിനാറു ദേവതകളെ, ഹരൻ മുതൽ ഇന്ദ്രൻ വരെ, നന്നായി അറിയുന്നവർ, ഗായത്രീലോകം നേടുന്ന അഗ്നിഹോത്രം ഹവിസ്സുകൾ നന്നായി അർപ്പിച്ച് യഥാവിധി ചെയ്തു.",
        "0.50": "പിന്നെ അതിമധുരമായി പൂർണ്ണചന്ദ്രൻ ഉദിച്ചു; ആകാശത്തിലൂടെ സഞ്ചരിക്കുന്ന ദേവാംഗനമാർ അതിനെ ലാളിച്ചുകൊണ്ടു പറഞ്ഞു: “ഇത് കളങ്കമില്ലാത്തതായിരുന്നെങ്കിൽ തീർച്ചയായും അതിന്റെ സഹോദരിയായ (ലക്ഷ്മിയുടെ) മനോഹരമുഖത്തോട് സാദൃശ്യമുണ്ടാകുമായിരുന്നു.”",
        "0.51": "താമരകളും ചക്രവാകപ്പക്ഷികളും സൂര്യനിൽ നിന്നുള്ള അസഹനീയമായ വേർപാട് കണ്ട് ദീർഘകാലം ദുഃഖിച്ചു; മൃദുവായ ആമ്പലുകളും ചകോരങ്ങളും, നേരത്തെ പൊള്ളിയവ, രാജാവിന്റെ (ചന്ദ്രന്റെ) രശ്മികളുടെ സ്പർശനത്തിൽ ആനന്ദിച്ചു. ഒന്നിനും എല്ലാ ഹൃദയങ്ങൾക്കും ഇഷ്ടമാകുന്ന വിധം വിധി നിശ്ചയിക്കുന്നില്ല.",
        "0.52": "(ശ്ലോകങ്ങൾ 52 മുതൽ 53 വരെ ചന്ദ്രികാരാത്രിയെയും, പിന്നീട് മധ്വൻ വ്യാഖ്യാനിച്ച കൃഷ്ണനെയും വിവരിക്കുന്നു.) പിളർന്ന നീലക്കല്ലിന്റെ ഇരുണ്ട നീലപ്രഭയോടെ, പുതിയ മുല്ലമൊട്ടുപോലെ വെളുത്ത പല്ലുകളുടെ നിരകളോടെ, പുഞ്ചിരിച്ച്, ഏറ്റവും ഉത്തമ പർവതത്തിൽ വളർന്ന സുഗന്ധമുള്ള വനമാലയാൽ അലങ്കരിച്ച്, അവൻ തിളങ്ങുന്നു;",
        "0.53": "ചലനത്തിൽ മൃദുവായവൻ, പുഞ്ചിരിക്കുന്ന ഗോപസുന്ദരിമാരെ സന്തോഷിപ്പിച്ചവൻ, ദിവ്യരഥങ്ങൾപോലെ സമൃദ്ധൻ; എല്ലാ പീഡകളിൽ നിന്നും മുക്തൻ, പ്രകാശമുള്ളവൻ, സർവ്വവ്യാപി, ഏറ്റവും മനോഹരമായ വസ്ത്രം ധരിക്കുന്നവൻ.",
        "0.54": "ചന്ദ്രൻ രശ്മികളാൽ അന്ധകാരം അകറ്റുന്നതുപോലെ, വാക്കുകളാൽ അന്ധകാരം അകറ്റിക്കൊണ്ട് ഭഗവാൻ (മധ്വൻ) ഈ ശ്ലോകങ്ങളുടെ മറ്റൊരു അർത്ഥം വെളിപ്പെടുത്തി: ജീവജാലങ്ങൾക്ക് ലക്ഷ്യം നൽകുന്ന, ആനന്ദവും ജ്ഞാനവും സകല ഗുണങ്ങളും നിറഞ്ഞ കൃഷ്ണൻ. ചന്ദ്രൻ ആ വാക്കുകൾക്ക് പേരിൽ മാത്രമേ യോജിക്കുന്നുള്ളൂ; വ്യത്യാസം അതുതന്നെയാണ്.",
        "0.55": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പതിനാലാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "ശ്രീ മധ്വാചാര്യരുടെ ഒരു ദിവസം: ഉണരൽ, സ്നാനം, പ്രഭാതസന്ധ്യാവന്ദനം, നാരായണപൂജ, ശിഷ്യന്മാർക്കും ഗൃഹസ്ഥന്മാർക്കും വേദാന്തോപദേശം, ഉച്ചഭക്ഷണം, സായാഹ്ന പ്രഭാഷണം, തന്നെ കാണാനെത്തുന്ന എല്ലാവരുടെയും ഭക്തി."
    },
    "sumadhva-vijaya-15": {
      "verses": {
        "0.0": "അപ്പോൾ ആ ഗ്രാമത്തിലെ ഗ്രാമവാസികൾക്ക് പൊതുവായുള്ള ഒരു ക്ഷേത്രത്തിൽ താമസിച്ച്, അളവില്ലാത്ത ജ്ഞാനമുള്ളവൻ തന്റെ അദ്ഭുതകരമായ ഭാഷ്യം വീണ്ടും വിശദീകരിച്ചു.",
        "0.1": "എതിരാളിയായ യോദ്ധാവിനെപ്പോലെ, എതിർസിദ്ധാന്തത്തിന്റെ രഥത്തിൽ കയറി, മൂർച്ചയുള്ള യുക്തിയുടെ മഹത്തായ ആയുധങ്ങളേന്തി നിൽക്കുന്ന ഉത്തമ ത്രിവിക്രമനെ അദ്ദേഹം മുന്നിൽ കണ്ടു.",
        "0.2": "അപ്പോൾ താമരവായിൽ നിന്ന് അദ്ദേഹത്തിന്റെ വാക്ക് പുറപ്പെട്ടു — സിദ്ധാന്തത്തിന്റെ വിശദീകരണം, പാളയത്തിൽ നിന്ന് സേനാപതിയോടൊപ്പം പുറപ്പെടുന്ന ദിവ്യസൈന്യംപോലെ.",
        "0.3": "അത് അധികം തിടുക്കമുള്ളതോ അതിവേഗമുള്ളതോ ആയിരുന്നില്ല; ഒരിക്കലും തട്ടിവീഴാതെ, മുറിയാതെ ഒഴുകി; ദൂരെയുള്ളവർ അതിന് പ്രത്യേക ഭാഗങ്ങൾ പോലുമില്ലെന്ന് തോന്നുംവിധം വിവരിച്ചു.",
        "0.4": "ആ വാക്കിന്റെ സൈന്യം സൂത്രങ്ങളെന്ന രഥങ്ങളാൽ സമൃദ്ധമായിരുന്നു; ശ്രുതികളെന്ന തടുക്കാനാവാത്ത ആനകളോടും, ശുദ്ധമായ യുക്തിയെന്ന വലിയ കാലാൾപ്പടയോടും, വിവിധ സ്മൃതികളെന്ന കുതിരപ്പടയോടും കൂടിയതായിരുന്നു.",
        "0.5": "സമുദ്രത്തിന്റെ മറ്റൊരു തേജസ്സുപോലെ (ലക്ഷ്മി), ഹരിക്ക് പ്രിയമായ അത്, അർത്ഥത്തിന്റെ തിരമാലകൾ ഉയർന്ന്, നല്ല മേഘംപോലെ ഗംഭീരസ്വരത്തിൽ, വിശാല വ്യാപ്തിയിൽ അർത്ഥങ്ങൾ തിളങ്ങിക്കൊണ്ടിരുന്നു.",
        "0.6": "പദ്മനാഭന്റെ താമരപ്പാദങ്ങളിൽ വിശ്രമിച്ച്, യോഗ്യർക്ക് താമരയിൽ ജനിച്ചവന്റെ (ബ്രഹ്മാവിന്റെ) സ്ഥാനം നൽകി, ഈശൻ (ശിവൻ) തന്റെ ശിരസ്സിൽ വഹിച്ച്, ഗംഗയെപ്പോലെ എല്ലാവരെയും ശുദ്ധമാക്കി.",
        "0.7": "(ശ്ലോകങ്ങൾ 7 മുതൽ 63 വരെ വാദത്തിന്റെ സംഗ്രഹമാണ്.) ശാസ്ത്രത്താലും യുക്തിയാലും, വേദങ്ങളാൽ അറിയപ്പെടുന്ന, ബ്രഹ്മം എന്ന് വിളിക്കപ്പെടുന്ന, അനന്തഗുണങ്ങളുള്ള നാരായണൻ പ്രപഞ്ചത്തിന്റെ സർവ്വജ്ഞനായ സൃഷ്ടികർത്താവാണെന്ന് അദ്ദേഹം സ്ഥാപിച്ചു.",
        "0.8": "പാൽപോലെ രൂപാന്തരപ്പെടുന്നതിനാൽ പ്രധാനം (പ്രധാനം) സ്വതന്ത്ര കാരണമാണെന്ന് വാദിച്ചാൽ, ആ ഉദാഹരണം തെളിയിക്കേണ്ടത് തെളിയിക്കുന്നതിൽ പരാജയപ്പെടുന്നു (കാരണം പാലിന്റെ മാറ്റം ഒരു കർത്താവിനെ ആശ്രയിക്കാതെയല്ല).",
        "0.9": "“തർക്കവിഷയമായ സൃഷ്ടി, ബോധമുള്ള ഒരു ചേതനത്തിന്റെ ഇച്ഛയെ പിന്തുടരുന്നു; കാരണം അത് ഒരു സൃഷ്ടിയാണ്, വസ്ത്രം നെയ്യുന്നതുപോലെ” എന്ന അനുമാനം നമ്മുടെ നിലപാടിനെ സ്ഥാപിക്കുന്നു.",
        "0.10": "സൃഷ്ടിയിൽ ചേതനവും അചേതനവും പ്രധാനവും ഉപവുമായി നിൽക്കുന്നു, ഈശ്വരനെ ആശ്രയിക്കാതെ എന്ന് പറയുന്നവരുടെ അഭിപ്രായം നിലനിൽക്കുന്നില്ല.",
        "0.11": "ഈശ്വരനുള്ള അനുമാനം: “എല്ലാം സർവ്വജ്ഞനാൽ നിർമ്മിതമാണ്, കാരണം അവ ചില സമയത്ത് മാത്രം ഉള്ളതാണ്; അങ്ങനെയല്ലാത്തത് (നിർമ്മിതമല്ലാത്തത്) അങ്ങനെ ചില സമയത്ത് മാത്രമുള്ളതല്ല, ആത്മാവുപോലെ.”",
        "0.12": "ശക്തിക്കായി എല്ലാ അനുമാനങ്ങൾക്കും വേദങ്ങളുടെ പിന്തുണ വേണം; അവയാൽ സംരക്ഷിക്കപ്പെടാതെ അവ, ഭർത്താവിനാൽ നിയന്ത്രിക്കപ്പെടാത്ത ഭാര്യമാരെപ്പോലെ, ഇഷ്ടമുള്ളിടത്തേക്ക് ഓടുന്നു.",
        "0.13": "“ബ്രഹ്മം രൂപാന്തരപ്പെടുന്ന കാരണമല്ല, കാരണം അത് ബോധമുള്ളതാണ്; അങ്ങനെയല്ലാത്തത് (ബോധമില്ലാത്തത്) രൂപാന്തരപ്പെടാത്തതല്ല, പാലും മറ്റും പോലെ.” (ബ്രഹ്മം ലോകമായി മാറുന്നു എന്ന വാദത്തെ ഖണ്ഡിക്കുന്നു.)",
        "0.14": "പശുപതി പ്രപഞ്ചത്തിന്റെ സൃഷ്ടികർത്താവല്ല, കാരണം ശാസ്ത്രം അവനെ (പരമഗുണങ്ങളുടെ) കുറവുള്ളവനായി പറയുന്നു; ചൈത്രനെപ്പോലെ. പിന്നെ വിഘ്നനും ബ്രധ്നനും (സൂര്യൻ) മറ്റും, കുട്ടികൾ സംശയിക്കുന്ന സൃഷ്ടികർത്താക്കളെക്കുറിച്ച് എന്ത് പറയാൻ?",
        "0.15": "(എതിർവാദം:) “ദുഃഖം മുതലായവയില്ലാത്തതിനാൽ ഭഗവാന് സുഖം മുതലായവ ഉണ്ടാകില്ല; അങ്ങനെയല്ലാത്തത് അങ്ങനെയല്ല, സംസാരത്തിലുള്ളവനെപ്പോലെ.”",
        "0.16": "(മറുപടി:) അതേ യുക്തിയാൽ ഇങ്ങനെയും അനുമാനിക്കാം: “തർക്കവിഷയമായ ഭഗവാൻ അറിവുള്ളവനല്ല, കാരണം അവൻ തെറ്റില്ലാത്തവനാണ്; അങ്ങനെയല്ലാത്തവൻ അങ്ങനെയല്ല, ലൗകികജീവിയെപ്പോലെ.”",
        "0.17": "വിശ്വസനീയമായ വേദം സർവ്വജ്ഞനിൽ അജ്ഞാനത്തെ വിലക്കുന്നുവെങ്കിൽ, അതേ വേദം അവനെ ആനന്ദമെന്ന് പ്രഖ്യാപിക്കുമ്പോൾ, അത് നിങ്ങൾ എങ്ങനെ ശ്രദ്ധിക്കാതിരിക്കും?",
        "0.18": "ഭഗവാനിൽ നിന്ന് ദുഃഖം നീക്കാൻ ആഗ്രഹിച്ച്, അവന് സുഖം നൽകാൻ വിസമ്മതിക്കുന്ന മന്ദബുദ്ധി മറന്നുപോയി — (അവന്റെ സ്വന്തം യുക്തിപ്രകാരം) അപ്പോൾ ദുഃഖം ഭഗവാനിൽ തന്നെ വീഴുമെന്ന്.",
        "0.19": "ചൈത്രനിലെ ദുഃഖത്തിന്റെ സമവായം, ഭഗവാനിലെ സമവായവുമായി ഒന്നാണ് (സമവായം ഒന്നാണെന്ന് കരുതപ്പെടുന്നതിനാൽ); അല്ലെങ്കിൽ സമവായം പലതാകും.",
        "0.20": "അതിന്റെ വ്യത്യാസം ഉപാധികൾ മൂലമാണെങ്കിൽ, ആ വ്യത്യാസം യഥാർത്ഥമോ അയഥാർത്ഥമോ എന്ന് പറയൂ: രണ്ടിലും നേരത്തേ പറഞ്ഞ കുറവുകൾ തന്നെയുണ്ട്; മായാവാദി പറയുന്നതുപോലെ സംസാരിക്കരുത്.",
        "0.21": "ആത്മാവിന്റെ ജ്ഞാനവും മറ്റു ഗുണങ്ങളും ഉപാധികൾ മൂലം മാത്രമാണ് വ്യത്യസ്തമെന്ന് പറഞ്ഞാൽ, അതും ഇതേ യുക്തിയാൽ ഖണ്ഡിക്കപ്പെടുന്നു; അതിനാൽ ഭഗവാന് (അവനുമായി ഒന്നായ) അനന്തഗുണങ്ങളുണ്ട്.",
        "0.22": "ഗുണങ്ങൾ (ദ്രവ്യത്തിൽ നിന്ന്) വ്യത്യസ്തമാണെങ്കിൽ ഒരു ബന്ധം കല്പിക്കേണ്ടിവരും; അത് അനന്ത പിന്നോട്ടുപോകലിലേക്ക് നയിക്കും; ഭഗവാന്റെ ഗുണങ്ങൾ വിശേഷം മാത്രത്താൽ (ഭേദമില്ലാത്ത വ്യത്യാസത്താൽ) അനന്തമാകുന്നത് യോജിക്കുന്നു.",
        "0.23": "ശാസ്ത്രത്തിന്റെ ശത്രുക്കളായ മറ്റുചിലർ ശൂന്യം മാത്രം യാഥാർത്ഥ്യമെന്ന് കരുതുന്നു; അവർ മാധ്യമികർ ആണ് — തുറന്നവരും ഒളിഞ്ഞവരുമായി രണ്ടു തരം.",
        "0.24": "പിന്നത്തെ വിഭാഗമായ ദുഷ്ടർ ശൂന്യത്തിന് ‘ബ്രഹ്മം’ എന്ന പേര് നൽകുന്നു, തങ്ങളെ വേദാന്തികളെന്ന് വിളിക്കുന്നു, വേദം സത്യം അറിയിക്കുന്നില്ല (അതത്ത്വവേദകം) എന്ന് പ്രഖ്യാപിക്കുന്നു.",
        "0.25": "ഇരുവർക്കും താഴ്ന്ന ലോകം മുഴുവൻ ഉയർന്ന യാഥാർത്ഥ്യത്തിലെ പ്രതിഭാസമാണ്; ആ യാഥാർത്ഥ്യമാകട്ടെ വ്യത്യസ്ത ലക്ഷണങ്ങളില്ലാത്തതാണ്; അതിനാൽ രണ്ടു പേർക്കും ഉള്ളിൽ വ്യത്യാസമില്ല.",
        "0.26": "അഖണ്ഡജ്ഞാനമുള്ളവൻ, ‘അഖണ്ഡഖണ്ഡനം’ എന്ന യുക്തിയെപ്പോലും ഖണ്ഡിച്ച്, ദേവശത്രുക്കളുടെ രണ്ടു വിഭാഗങ്ങളെയും തകർത്തു.",
        "0.27": "ഇവിടെ ഇങ്ങനെ അനുമാനിക്കുന്നു: “തർക്കവിഷയമായ (ശൂന്യം) കാരണമാകാൻ കഴിയില്ല, കാരണം അത് അസത്താണ്; അങ്ങനെയല്ലാത്തത് (അസത്) അങ്ങനെയല്ല (കാരണമല്ല), കുശവനെപ്പോലെ.”",
        "0.28": "(ബൗദ്ധൻ:) “സന്യാസീ, ശൂന്യം കുശവൻ പോലെ കാരണമല്ല; സംവൃതി സത്യത്താൽ (വ്യവഹാരസത്യത്താൽ) ലോകം അതിൽ നിന്ന് ഉദിക്കുന്നു എന്ന അർത്ഥത്തിലാണ് അതിനെ കാരണമെന്ന് വിളിക്കുന്നത്.”",
        "0.29": "“എങ്കിൽ, ഒരർത്ഥത്തിലും ശൂന്യത്തെ കാരണമെന്ന് വിളിക്കരുത്; ദീർഘായുസ്സുള്ളവനേ, നിന്റെ ഗുരുവിന്റെ വീട്ടിൽ പോയി ‘ആധാരം’ എന്ന വാക്കിന്റെ അർത്ഥം പഠിച്ചുവരൂ.”",
        "0.30": "“തർക്കവിഷയമായ (ശൂന്യം) ആധാരമാകാൻ കഴിയില്ല, കാരണം അത് അസത്താണ്” — ഇത് വിപരീത ദൃഷ്ടാന്തത്താൽ പറയപ്പെടുന്നു: (ആധാരമായത് സത്താണ്) വെള്ളി തെറ്റായി കാണപ്പെടുന്ന ശംഖുപോലെ.",
        "0.31": "“സത്യം അറിയിക്കാത്ത പ്രമാണം” എന്നത് സ്വയംവിരുദ്ധമായതിനാൽ, വേദത്തെക്കുറിച്ച് ഇങ്ങനെ പറയുന്നവൻ വാസ്തവത്തിൽ ഉദ്ദേശിക്കുന്നത്, വേദത്തിന് യാതൊരു പ്രാമാണ്യവുമില്ല എന്നാണ്.",
        "0.32": "വേദവിമർശകൻ സത്യം അറിയിക്കുന്നതായി കരുതുന്ന വേദാന്തഭാഗം: അവന്റെ സത്യം വിവരിക്കാനാവാത്തതാണെന്നിരിക്കെ അതെങ്ങനെ സത്യം അറിയിക്കും?",
        "0.33": "വാക്യങ്ങൾ മൂന്നു തരം ലക്ഷണങ്ങളാൽ (ലക്ഷണ) അതിൽ പ്രയോഗിക്കപ്പെടുന്നുവെങ്കിൽ, ബ്രഹ്മം ആ ലക്ഷണങ്ങളുടെ വിഷയമാകുന്നു — അതുതന്നെയാണ് അവൻ ആഗ്രഹിക്കാത്തത്.",
        "0.34": "മാത്രമല്ല, ഖണ്ഡമില്ലാത്ത ഈ വസ്തുവിനെക്കുറിച്ച് വാക്യങ്ങൾ ഒന്നും പ്രസ്താവിക്കുന്നില്ല; അചേതനത്വം മുതലായവയുടെ അഭാവത്തെ അവ പ്രകടിപ്പിക്കുന്നു എന്ന് പറഞ്ഞാലും അതും യോജിക്കുന്നില്ല,",
        "0.35": "കാരണം ഒരു ഭാവാത്മക വസ്തുവിന് അഭാവത്തിന്റെ സ്വഭാവം ഉണ്ടാകില്ല; അത് വ്യത്യാസമില്ലാത്തതായതിനാൽ, സത്ത്യ്ക്കോ അഭാവത്തിനോ ഉള്ള ഭേദകലക്ഷണങ്ങൾ അതിന് ഉണ്ടാകാനും കഴിയില്ല.",
        "0.36": "വേദം അറിയിക്കുന്ന യാഥാർത്ഥ്യങ്ങളെ ഉപേക്ഷിക്കുമെന്ന് നിരന്തരം പ്രതിജ്ഞയെടുക്കുന്നവനെ അതിനാൽ വേദത്തിന് പുറത്തുനിൽക്കുന്നവനായി ജ്ഞാനികൾ വിധിക്കണം.",
        "0.37": "മൂത്തവന്റെ (ബൗദ്ധന്റെ) ഖണ്ഡനത്താൽ, സ്വയം മിടുക്കനെന്ന് കരുതുന്നവനും ഖണ്ഡിക്കപ്പെടുന്നു; സജ്ജനങ്ങൾക്ക് എതിരായ ഈ രണ്ടു നിലപാടുകൾ തമ്മിൽ യാഥാർത്ഥ്യത്തിൽ വ്യത്യാസമില്ലാത്തതിനാൽ.",
        "0.38": "ബ്രഹ്മവാദി “അസത്താകയാൽ എന്ന ഹേതു എനിക്ക് ബാധകമല്ല” എന്ന് പറയരുത്; ബ്രഹ്മവും ശൂന്യവും എന്ന രണ്ടു യാഥാർത്ഥ്യങ്ങൾക്കിടയിൽ പറയാവുന്ന വ്യത്യാസമില്ല.",
        "0.39": "ബ്രഹ്മം സത്താണെന്ന് അദ്ദേഹം അംഗീകരിച്ചാൽ, ബ്രഹ്മത്തിന് ഒരു വിശേഷണഗുണം ഉണ്ട്; അല്ലെങ്കിൽ, ഒഴിവാക്കലിലൂടെ അത് അസത്താണ്; അത് അദ്ദേഹത്തിന് നിഷേധിക്കാനാവില്ല.",
        "0.40": "തർക്കവിഷയമായ അദ്വൈതബ്രഹ്മം അന്വേഷിക്കേണ്ടതോ, ധ്യാനിക്കേണ്ടതോ, ഫലം നൽകുന്നതോ ആയ ഒന്നല്ല — ശൂന്യത്തെപ്പോലെ — കാരണം അത് വിധിയുടെയോ ജ്ഞാനത്തിന്റെയോ പരിധിയിൽ വരുന്നില്ല.",
        "0.41": "കാരണം അത് ഖണ്ഡമില്ലാത്തതാണ്, ആകാശപുഷ്പംപോലെ; വിപരീത ദൃഷ്ടാന്തം അന്വേഷിക്കപ്പെടുന്ന പ്രമാണവും മറ്റുമാണ്. ഇങ്ങനെ എത്രവേണമെങ്കിലും യുക്തി നീട്ടാം.",
        "0.42": "വേദങ്ങൾ പ്രമാണമല്ലെങ്കിൽ, ധർമ്മം മുതലായവയ്ക്ക് പ്രാമാണ്യം ഉണ്ടാകില്ല; പ്രത്യക്ഷം മാത്രം പ്രമാണമായി സ്വീകരിക്കുന്നവന് (ചാർവാകൻ) ധർമ്മം മുതലായവ അറിയാൻ യാതൊരു മാർഗ്ഗവുമുണ്ടാകില്ല.",
        "0.43": "മനുഷ്യോത്പത്തിയുള്ള വാക്യം (അതീന്ദ്രിയ കാര്യങ്ങൾക്ക്) പ്രമാണമായി സ്ഥാപിക്കപ്പെടുന്നില്ല, കാരണം അത് മനുഷ്യനിർമ്മിതമാണ്; ഭ്രാന്തന്റെ വാക്കുകൾപോലെ.",
        "0.44": "“തർക്കവിഷയമായ വ്യക്തി അജ്ഞനായിരിക്കാം, അല്ലെങ്കിൽ വഞ്ചകനായിരിക്കാം, കാരണം അവൻ ഒരു വ്യക്തിയാണ്, ചൈത്രനെപ്പോലെ” — ഇങ്ങനെയുള്ള എതിരനുമാനങ്ങളാൽ ഒരു മനുഷ്യഗുരുവിന്റെ സർവ്വജ്ഞതയ്ക്കുള്ള അനുമാനങ്ങൾ മാത്രമായി നീക്കപ്പെടുന്നു.",
        "0.45": "വ്യാജശാസ്ത്രങ്ങളിലെ കഠിനമായ ദുശ്ശാഠ്യം ദൈവത്തെ അസന്തുഷ്ടനാക്കുന്നു; അതിനാൽ അവയിൽ മുറുകെപ്പിടിക്കുന്നവർക്ക് ഭയങ്കരമായ ദുഃഖലോകം ഉറപ്പാണ്.",
        "0.46": "ഞങ്ങൾ പിന്തുടരുന്ന നിലപാടിൽ, അധോക്ഷജൻ (വിഷ്ണു) മോക്ഷം നൽകുന്നു; അതിൽ സജ്ജനങ്ങൾ സ്വതവേ ആനന്ദസ്വരൂപരായി, അനേകം ആനന്ദവസ്തുക്കൾ അനുഭവിക്കുന്നു.",
        "0.47": "കേവലം ഗുണരാഹിത്യമായ മോക്ഷം ഉപേക്ഷിക്കേണ്ടതാണ്, കാരണം അത് സ്വയംവിരുദ്ധമാണ്; “എപ്പോൾ?” എന്നും മറ്റും അതിനെക്കുറിച്ച് ചോദിക്കുമ്പോൾ, ഏത് ഉത്തരവും അതിന് ഒരു ഗുണം നൽകുന്നു; ഉത്തരമില്ലെങ്കിൽ ഗുണവുമില്ല.",
        "0.48": "ബുദ്ധിയില്ലാത്തവൻ മനുഷ്യലക്ഷ്യത്തിന്റെ അന്വേഷകനാകുന്നതും ഒരു വിധത്തിലും സാധ്യമല്ല; കാരണം പാവകളെപ്പോലെയുള്ളവയ്ക്ക് എല്ലാ അനുഭവവും ഇല്ലല്ലോ.",
        "0.49": "ജ്ഞാനം, പ്രയത്നം, ഇച്ഛ എന്നിവയുള്ള ഈശ്വരൻ ഒരിക്കലും അശുഭമായതിൽ വീഴില്ല; അതേ ശക്തിയാൽ മോചിതനായ ജീവനെയും അവൻ അങ്ങനെ ആക്കാൻ കഴിയും.",
        "0.50": "ബന്ധനത്തിലെ സുഖം ദുഃഖം കലർന്നതാണെന്ന് കണ്ട്, മോചിതന് സുഖം നിഷേധിച്ചാൽ, അതേ യുക്തിയാൽ അവന്റെ സ്വഭാവം തന്നെ നിഷേധിക്കേണ്ടിവരും; അങ്ങനെ അവൻ നാസ്തികനായിത്തീരും.",
        "0.51": "(എതിർവാദം:) “തർക്കവിഷയമായ മോചിതൻ ശരീരമുള്ളവനായതിനാൽ, ചൈത്രനെപ്പോലെ വിശപ്പും ദാഹവും മുതലായ തിരമാലകൾക്ക് വിധേയനാകും.” (മറുപടി:) ഇവിടെ ‘അശുദ്ധശരീരമുള്ളവൻ’ എന്നതാണ് യഥാർത്ഥ ഉപാധി.",
        "0.52": "‘ശരീരമുള്ളവൻ’ എന്ന ഹേതു അനൈകാന്തികമാണ്, കാരണം അത് ഭഗവാന്റെ കാര്യത്തിൽ പരാജയപ്പെടുന്നു; ഭഗവാൻ ശരീരമില്ലാത്തവനാണെങ്കിൽ, മുയലിന്റെ കൊമ്പുപോലെ അവന് ആഗ്രഹം മുതലായവ ഇല്ലാതാകും.",
        "0.53": "മുയലിന്റെ കൊമ്പിൽ നിന്ന് അവനെ വേർതിരിക്കാൻ, അവന് ജ്ഞാനിയുടെ രൂപം മുതലായവ നൽകിയാൽ, ആ രൂപം തന്നെയാണ് നാം ‘ശരീരം’ എന്ന് വിളിക്കുന്നത്; അത് ഭൗതിക രൂപമല്ല.",
        "0.54": "അതുപോലെ, മോചിതർക്കും സ്വന്തം സ്വഭാവമായ ശരീരം അംഗീകരിക്കപ്പെടുന്നു; അതിനാൽ ഭൗതിക ശരീരത്തിൽ നിന്ന് അനിഷ്ടമായ അനുഭവമൊന്നും ഉണ്ടാകുന്നില്ല.",
        "0.55": "(എതിർവാദം:) “തർക്കവിഷയമായ മോചിതന് ഭാഗങ്ങളില്ല; അല്ലെങ്കിൽ വസ്ത്രംപോലെ അവൻ നശ്വരനാകും.” (മറുപടി:) ഇവിടെ എന്ത് തരം ഭാഗങ്ങളാണ് നിഷേധിക്കപ്പെടുന്നത്?",
        "0.56": "അവ അവനിൽ നിന്ന് വ്യത്യസ്തവും അചേതനവുമാണെങ്കിൽ, നിങ്ങളുടെ ഹേതു ഞങ്ങൾ നേരത്തേ അംഗീകരിച്ചതുതന്നെ തെളിയിക്കുന്നു; ആത്മാവിൽ നിന്ന് വ്യത്യസ്തമല്ലാത്ത ഭാഗങ്ങൾ തർക്കക്കാരും അംഗീകരിക്കണം.",
        "0.57": "ആത്മാവ് അണുവിന്റെ വലിപ്പമുള്ളതോ, ഒരു മുഴം നീളമുള്ളതോ ആയ സ്ഥലങ്ങളിൽ, അതിലൂടെ വ്യാപിക്കുന്ന ‘ഭാഗങ്ങൾ’ (പ്രദേശങ്ങൾ) നിങ്ങൾ അംഗീകരിക്കുന്നതുപോലെ, അവയുടെ ഭാഗങ്ങളും നമുക്ക് ഉണ്ട്.",
        "0.58": "“മോചിതൻ രൂപാദികൾ അറിയുന്നു, കാരണം അവൻ അചേതനത്തിൽ നിന്ന് വ്യത്യസ്തനായി നിലനിൽക്കുന്നു, ഈശ്വരനെപ്പോലെ” — ഈ ദൃഷ്ടാന്തത്തിൽ തെളിയിക്കേണ്ടത് കുറവില്ല; കാരണം ഈശ്വരന്റെ സർവ്വജ്ഞത അംഗീകൃതമാണ്.",
        "0.59": "“ഈശ്വരൻ രൂപാദികൾ അനുഭവിക്കുന്നുവെങ്കിലും അതിനാൽ സന്തോഷവാനല്ല, കാരണം അപ്പോൾ ദുഃഖം ഉണ്ടാകും” എന്ന് പറയരുത്: ആ വ്യാപ്തി (ബന്ധം) തെറ്റാണ്.",
        "0.60": "ഈ ദൃഷ്ടാന്തം (ഈശ്വരൻ) അംഗീകരിക്കാത്തവർക്ക്, ‘കല്ലുപോലെ’ എന്ന വിപരീത ദൃഷ്ടാന്തമുണ്ട്; അതിനാൽ മോചിതൻ ശുദ്ധ ചൈതന്യമുള്ള ശരീരത്തിലൂടെയും ഇന്ദ്രിയങ്ങളിലൂടെയും ആസ്വദിക്കുന്നു.",
        "0.61": "സഹജമായ ആനന്ദം നിറഞ്ഞ, വേദം പഠിപ്പിക്കുന്ന, യുക്തിയാൽ സ്ഥാപിക്കപ്പെട്ട ഈ മോക്ഷത്തെ തർക്കവാദികൾ എന്തിന് വെറുക്കുന്നു, അല്ലെങ്കിൽ അതിന്റെ വിപരീതം ശഠിക്കുന്നു?",
        "0.62": "അതിനാൽ, സ്വയംപ്രമാണമായ വേദത്തിലൂടെ മോക്ഷവും മറ്റെല്ലാം നൽകുന്നവനായി വിഷ്ണുദേവൻ അറിയപ്പെടുമ്പോൾ, ലോകം മുഴുവൻ നന്നായിരിക്കും.",
        "0.63": "ഇങ്ങനെ ഉത്തമനായ ത്രിവിക്രമൻ സർവ്വജ്ഞനിൽ നിന്ന് ഈ സത്യങ്ങളും മറ്റും വിശദീകരണത്തിലും യുക്തിയിലും കേട്ടു.",
        "0.64": "പിന്നെ അദ്ദേഹം (ത്രിവിക്രമൻ) തന്റെ പാണ്ഡിത്യത്തിന്റെ വില്ലിന്റെ ഞാൺവലിവിൽ പായിച്ച്, എതിർപക്ഷത്തിനു നേരെ ലക്ഷ്യമിട്ട്, യുക്തിയുടെ അനേകം മൂർച്ചയുള്ള അമ്പുകൾ ശക്തിയോടെ എയ്തു.",
        "0.65": "ചെറുതല്ലാത്ത ബുദ്ധിയുള്ളവൻ ചിരിച്ചുകൊണ്ട്, അവ പുറപ്പെട്ട നിമിഷം തന്നെ, തന്റെ മികച്ച യുക്തിയമ്പുകൾകൊണ്ട് കളിയായി അവയെ മുറിച്ചുകളഞ്ഞു.",
        "0.66": "ജയിക്കാൻ ആഗ്രഹിച്ച ബ്രാഹ്മണശ്രേഷ്ഠൻ പിന്നെ വേദത്തിന്റെ ആയുധങ്ങൾ എറിഞ്ഞു — മറ്റാർക്കും പ്രതിരോധിക്കാനാവാത്തവ, മനുഷ്യർക്ക് തിരിച്ചുവിടാനാവാത്തവ.",
        "0.67": "പ്രതിയന്ത്രങ്ങൾപോലെ, കൂടുതൽ ശക്തമായ വേദവാക്യങ്ങളാൽ അവയുടെ മറ്റൊരു (യഥാർത്ഥ) അർത്ഥം വെളിപ്പെടുത്തിക്കൊണ്ട്, അദ്ദേഹം ആ ആയുധങ്ങൾ തിരിച്ചുവിട്ടു.",
        "0.68": "ഇങ്ങനെ അദ്ദേഹവുമായി പതിനഞ്ചു ദിവസം (ഏഴും എട്ടും) വാദിച്ചപ്പോൾ, ചക്രധാരിയുടെ പ്രിയൻ അദ്ദേഹത്തെ മറുപടിയില്ലാതെയും കൂടുതൽ എതിർപ്പില്ലാതെയും വിട്ടു.",
        "0.69": "സംസ്കാരസമ്പന്നനായ ആ മനുഷ്യൻ വണങ്ങി പറഞ്ഞു: “ഗുരുവേ, എന്റെ ധിക്കാരം ക്ഷമിക്കണേ; അങ്ങയുടെ താമരപ്പാദധൂളിയുടെ സേവ എന്നേക്കും എനിക്ക് നൽകണേ.”",
        "0.70": "പിന്നെ, അളവില്ലാത്ത ജ്ഞാനമുള്ളവന്റെ ഭാഷ്യത്തിന്റെ വിശദീകരണവും, പണ്ഡിതപുത്രൻ (ത്രിവിക്രമൻ) അത് കേൾക്കലും, സജ്ജനങ്ങളുടെ സന്തോഷവും, ദുഷ്ടന്മാരിൽ മറ്റൊരു വികാരവും ഒന്നിച്ചു തുടങ്ങി.",
        "0.71": "ഗുരുവിന്റെ കൽപ്പന മാനിച്ച്, ഭാഷ്യത്തിന് ദുഷ്കരമായ ഒരു വ്യാഖ്യാനം (തത്ത്വപ്രദീപം) എഴുതിക്കൊണ്ട്, ഉത്തമ ത്രിവിക്രമൻ (‘ആറിന്റെ പകുതി’ — വിക്രമം) മഹാഗുരുവിനോട് പറഞ്ഞു:",
        "0.72": "“ഈ ഭാഷ്യമാകുന്ന സമുദ്രത്തിലെ യുക്തിയുടെ രത്നങ്ങൾ മഹാകവികൾ നിരന്തരം ശേഖരിച്ചാലും ഒരിക്കലും തീരുന്നില്ല; അതിന്റെ ആഴം അദ്ഭുതകരം!",
        "0.73": "അങ്ങയുടെ ഉപനിഷദ്ഭാഷ്യങ്ങളുടെ ഈ മന്ദിരങ്ങളിൽ, പത്ത് ഉപനിഷത്തുകൾ, ദേവന്മാർ ആഗ്രഹിക്കുന്ന ദേവതകളെപ്പോലെ, അവയുടെ അർത്ഥങ്ങളോടു ചേർന്ന് പൂർണ്ണ കൃപയോടെ നിലകൊള്ളുന്നു.",
        "0.74": "ഗീതാഭാഷ്യവും ഗീതാതാത്പര്യവുമായ ഈ രണ്ടിനാൽ, ആർക്കും തടുക്കാനാവാത്ത രശ്മികളാൽ (വാക്കുകളാൽ) ലോകം സൂര്യചന്ദ്രന്മാരെക്കാളും അധികം പ്രകാശിക്കപ്പെടുന്നു.",
        "0.75": "നിങ്ങളുടെ മനസ്സെന്ന മലയാൽ കടഞ്ഞെടുത്ത ഇതിഹാസപുരാണസമുദ്രത്തിൽ നിന്ന് ജനിച്ച ഭാരതതാത്പര്യനിർണ്ണയത്തിന്റെ അമൃത് ഏത് സജ്ജനമാണ് രുചിക്കാത്തത്?",
        "0.76": "മൂന്നു തരം ഭാഷകൾ അറിയാത്ത, പുരാണങ്ങളുടെ വഴിയിൽ സഞ്ചരിക്കുന്നവർക്ക്, നിങ്ങൾ ശ്രീ ഭാഗവത(താത്പര്യ)നിർണ്ണയത്തെ നല്ല കൂട്ടുകാരനാക്കി.",
        "0.77": "ദേവന്മാർ തണൽ തേടുന്ന ഏറ്റവും നല്ല ആഗ്രഹവൃക്ഷംപോലെ തന്ത്രസാരം ലഭിച്ചവന്റെ എല്ലാ ആഗ്രഹങ്ങളും സഫലമാകാതിരിക്കുമോ?",
        "0.78": "ഈ വഴി കാണാൻ ജനങ്ങൾക്കായി, കരുണയുടെ കണ്ണുകൾപോലെ നിങ്ങൾ പ്രമാണലക്ഷണവും (പ്രമാണങ്ങളെക്കുറിച്ച്) കഥാലക്ഷണവും (വാദത്തെക്കുറിച്ച്) രചിച്ചു.",
        "0.79": "ശത്രുക്കളുടെ തലയിൽ ഏകനായി കാൽ വെച്ച അർജുനനെപ്പോലെയുള്ള ഈ തത്ത്വനിർണ്ണയത്തെ ആരാണ് ആദരിക്കാത്തത്?",
        "0.80": "വാദം മുതലായ ചെറു പ്രകരണങ്ങൾ ചെറിയ തീപ്പൊരികളാണെങ്കിലും, അങ്ങ് എന്ന കാറ്റ് ഊതിയാൽ അവ എതിരാളികളുടെ ഉണങ്ങിയ പുല്ല് കത്തിക്കാൻ മതി.",
        "0.81": "ചെറിയ ഭാഷ്യസംഗ്രഹത്തിൽ (അനുഭാഷ്യം) അങ്ങ് അനന്തമായ അർത്ഥം വെളിപ്പെടുത്തി — കൃഷ്ണൻ തന്നെ വെളിപ്പെടുത്താൻ വായിൽ പ്രപഞ്ചം കാണിച്ചതുപോലെ അദ്ഭുതകരമായി.",
        "0.82": "പ്രഭോ, ലൗകിക കാവ്യത്തിലുള്ള അങ്ങയുടെ നൈപുണ്യം കാണിച്ച്, മറഞ്ഞിരുന്ന ഭാരതസംക്ഷേപത്തെ (യമകഭാരതം) ലോകത്തിന് അദ്ഭുതമാക്കി.",
        "0.83": "അങ്ങയുടെ ഉത്തമ കൃതികൾ, അനേകം നല്ല സൂക്തങ്ങൾ, സ്തോത്രങ്ങൾ, ശ്ലോകങ്ങൾ മുതലായവ — രത്നസമുദ്രമായ അങ്ങയിലെ രത്നനിരകൾ എണ്ണാനാവാത്തതുപോലെ — ആർക്ക് എണ്ണാനാകും?",
        "0.84": "ഇവയെ അളവിൽ ചെറുതെങ്കിലും അനന്തമായ അർത്ഥം നൽകുന്ന ആഗ്രഹരത്നങ്ങളായി കണക്കാക്കി, സജ്ജനസഭ ചെറുതെന്ന് കരുതുന്ന ചെറിയ മനസ്സുകളെ ഉറക്കെ പരിഹസിക്കുന്നു.",
        "0.85": "ഈ കൃതികൾ നിലനിൽക്കുന്നുവെങ്കിലും, ഞങ്ങൾ മറ്റൊന്നുകൂടി ആഗ്രഹിക്കുന്നു — ഇന്ദ്രാദികൾ ഉണ്ടായിരുന്നിട്ടും, പണ്ടത്തെ ദേവന്മാർ താരകനെ വധിച്ചവൻ (സ്കന്ദൻ) ആഗ്രഹിച്ചതുപോലെ.",
        "0.86": "ഈ ആഴമില്ലാത്ത കൃതികളിൽ നിന്ന് യുക്തികൾ ഞങ്ങളുടെ മനസ്സിന്റെ മന്ദതയാൽ എടുക്കാൻ പ്രയാസമാണ്; അതിനാൽ യുക്തിയുടെ ക്രമം വ്യക്തമായി അവതരിപ്പിക്കുന്ന ഒരു കൃതി രചിക്കൂ.”",
        "0.87": "ഇങ്ങനെ അപേക്ഷിക്കപ്പെട്ട മധ്വൻ അനുവ്യാഖ്യാനം രചിച്ചു — സജ്ജനങ്ങൾക്ക് അമൃത്, വ്യാജവാദികളുടെ അഹങ്കാരമലയ്ക്ക് വജ്രം, മായാവാദികളുടെ ഇരുട്ടിന് സൂര്യപ്രകാശം.",
        "0.88": "ഒരിക്കൽ, തടസ്സമില്ലാതെ എല്ലാം ഒന്നിച്ച് രചിച്ച്, കളിയായി നാലു ശിഷ്യന്മാരെക്കൊണ്ട് ഒരേസമയം, ഒരു സമയം നാല് (അധ്യായങ്ങൾ) വീതം എഴുതിച്ചു.",
        "0.89": "അദ്ദേഹം തന്നെ അവിടെ അവതരിപ്പിച്ച ‘യുക്തിമാല’ എന്ന ശബ്ദത്തിൽ, അദ്ദേഹം വ്യക്തമായ വിശദീകരണം (ന്യായവിവരണം) എഴുതി — മഹാകവികൾക്കുപോലും ദുഷ്കരമായ കാര്യം.",
        "0.90": "മാതാപിതാക്കൾ, മധ്വചന്ദ്രനുമായുള്ള നിരന്തര ബന്ധത്താൽ അവരുടെ മനസ്സ് ഇരുട്ടിലും വേദനയിലും നിന്ന് മുക്തമായി, വൈകുണ്ഠത്തിലേക്ക് പോയപ്പോൾ, ഇളയ സഹോദരൻ വീട്ടിൽ താമസിച്ചു.",
        "0.91": "പണവും കന്നുകാലികളും ധാന്യവുമായ സമ്പത്ത്, വിധിയുടെ പുരികചലനം മാത്രത്താൽ മറഞ്ഞുപോയപ്പോൾ, ആ വേദജ്ഞൻ വൈരാഗ്യം നേടി, വൈദിക ഗുരുക്കന്മാരുടെ രാജാവിന്റെ അടുത്തെത്തി.",
        "0.92": "സന്ന്യാസം ചോദിച്ച് അദ്ദേഹത്തിന്റെ പാദങ്ങളിൽ വീണ്ടും വീണ്ടും വണങ്ങിയപ്പോൾ, ഉചിതമായ സമയത്തിനായി കാത്തിരുന്ന ജ്ഞാനദൃഷ്ടിയുള്ളവൻ അദ്ദേഹത്തെ വീട്ടിലേക്ക് തിരിച്ചയച്ചു.",
        "0.93": "ഉറച്ച മനസ്സോടെ, സമയത്തിനായി കാത്തിരുന്ന്, അദ്ദേഹം ഭക്ഷണം കഴിക്കാതെയും ഉറങ്ങാതെയും ചിരിക്കാതെയും, രാമനെ ഓർക്കുന്ന ഭരതനെപ്പോലെ, മൂത്ത സഹോദരനെ ഓർത്തുകൊണ്ടിരുന്നു.",
        "0.94": "വേർപാടിൽ വേദനിച്ച രാജാവിനെ (ജയസിംഹനെ) ഏതോ വിധത്തിൽ തന്റെ രാജ്യത്ത് സ്ഥിരപ്പെടുത്തിയ ശേഷം, ഭഗവാൻ ശരത്കാലത്തിന്റെ അവസാനം തന്റെ ജന്മദേശത്തേക്ക് പോയി.",
        "0.95": "മധ്വൻ തന്റെ ഇളയ സഹോദരനെ സന്ന്യാസിയാക്കി: കുടുംബത്തിന്റെ ഇരുവശത്തും ശുദ്ധൻ, വേദജ്ഞൻ, നിർമ്മലൻ, മാതാപിതാക്കളുടെ കർമ്മങ്ങൾ ചെയ്തവൻ, ലൗകികസുഖങ്ങൾ അനുഭവിച്ചശേഷം വൈരാഗ്യം നേടിയവൻ.",
        "0.96": "ബ്രഹ്മത്തിനു തുല്യനായവൻ, പഞ്ചാഗ്നിതപസ്സ് ചെയ്യുന്ന സന്യാസിമാർപോലും അറിയാത്ത രഹസ്യങ്ങളുടെ രഹസ്യമായ ആ ബ്രഹ്മത്തെ അദ്ദേഹത്തിന് ഉപദേശിച്ചു.",
        "0.97": "പ്രേമാമൃതം നിറഞ്ഞ മുഖത്ത്, പുഞ്ചിരിയും ചെരിഞ്ഞ നോട്ടവും കൂടി, പ്രീതിതീർത്ഥർ അദ്ദേഹത്തിന് ‘ശ്രീ വിഷ്ണുതീർത്ഥർ’ എന്ന് പേര് നൽകി.",
        "0.98": "വേദാന്താചാര്യന്റെ സഹോദരൻ, വേദാന്തശാസ്ത്രം കേൾക്കുകയും ആവർത്തിക്കുകയും ധ്യാനിക്കുകയും ചെയ്ത് തന്റെ സമയം ഫലപ്രദമാക്കി.",
        "0.99": "ആത്മനിയന്ത്രണം, ഭക്തി, മാധുര്യം, സേവ മുതലായവയുടെ സമൃദ്ധമായ പോഷണത്താൽ, ഗുരുവിന്റെ കൃപയുടെ മുള അദ്ദേഹത്തിൽ വളർത്തി, വലിയ ആരോഗ്യമുള്ള വൃക്ഷമാക്കി.",
        "0.100": "അനന്തമതിയുടെ (മധ്വന്റെ) അതിരില്ലാത്ത കാരുണ്യമാകുന്ന ആഗ്രഹവൃക്ഷം കൈവശമുള്ളവന്റെ മഹത്വം മനുഷ്യർക്ക് പൂർണ്ണമായി വിവരിക്കാനാവില്ല; ആവേശത്താൽ അതിൽ അല്പം വിവരിക്കുന്നു.",
        "0.101": "പ്രഭാഷണത്തിൽ സമർത്ഥനും മന്ത്രങ്ങളിൽ പൂർണ്ണതയുള്ളവനുമായ അദ്ദേഹം മനസ്സിൽ ഉറപ്പിച്ചു: “മധ്വന്റെ ദാസന്മാരുടെ എണ്ണം എന്നോടുകൂടി അവസാനിക്കരുത് (അവയിൽ ഒന്നാമനാകണം).”",
        "0.102": "ഉത്തരദിക്കിലേക്ക് യാത്ര ചെയ്ത്, ഭൂമിയിൽ അലഞ്ഞു: പുണ്യജലങ്ങൾ വിഷ്ണുതീർത്ഥരെ ശുദ്ധമാക്കി; വിഷ്ണുതീർത്ഥർ പുണ്യജലങ്ങളെ ശുദ്ധമാക്കി.",
        "0.103": "മറഞ്ഞിരുന്ന്, ആഗ്രഹരഹിതരായ അനേകം തപസ്വികൾക്ക് സിദ്ധിസ്ഥലമായ ഹരിശ്ചന്ദ്രപർവതത്തിൽ എത്തി.",
        "0.104": "അസൂയയില്ലാത്ത ആ വീരൻ, അസൂയ ഉള്ളവനെപ്പോലെ, ഭക്ഷണം മുതലായവ ഉപേക്ഷിച്ചു; അവയെ ദ്വന്ദ്വങ്ങളുടെ ദുഃഖത്തിന്റെ അഗ്നിക്ക് ഇന്ധനമായി കണ്ടു.",
        "0.105": "ഭക്തരുടെ അപേക്ഷയാൽ, തപസ്വികളുടെ കിരീടമായവൻ പഞ്ചഗവ്യം അല്പം കുടിച്ചു, ഓരോ അഞ്ചാം ദിവസവും പർവതത്തിൽ നിന്ന് കൊണ്ടുവന്ന്.",
        "0.106": "അതും ഉപേക്ഷിച്ച്, ധീരനായവൻ എല്ലാ തപസ്വികളെയും കടന്ന തപസ്സു ചെയ്തു — നിലത്തു വീണ ബിൽവ ഇലകളിലും വെള്ളത്തിലും മാത്രം തൃപ്തനായി.",
        "0.107": "ആത്മനിയന്ത്രണമുള്ള, നന്നായി അച്ചടക്കമുള്ളവൻ, വിധിയാൽ ദുർഭാഗ്യമുള്ള തപസ്വികൾക്ക് ഒരു ദിവസംപോലും ഇരിക്കാനാവാത്ത ആ പാറമേൽ തനിക്കിഷ്ടമുള്ളത്രയും നേരം ഇരുന്നു.",
        "0.108": "വായുവിന്റെ അംശമായ ഇളയവൻ, പുറന്തള്ളൽ മുതലായവയാൽ പ്രാണനെ നിയന്ത്രിച്ച്, മനസ്സെന്ന സാരഥിയാൽ ഇന്ദ്രിയക്കുതിരകളെ വിഷയങ്ങളിൽ നിന്ന് പിന്തിരിപ്പിച്ചു.",
        "0.109": "മുരാരിയുടെ രൂപം സ്മരിച്ച്, ആന്തരാത്മാവിനെ അറിയുന്നവൻ ധ്യാനിച്ചു; എല്ലാ ദുഃഖങ്ങളെയും ശമിപ്പിക്കുന്നതും യോഗത്താൽ നേടുന്നതുമായ സമാധി പ്രാപിച്ചു.",
        "0.110": "ആനന്ദ സമുദ്രവും മറ്റു ഗുണങ്ങളുമുള്ള മുകുന്ദന്റെ മനോഹരരൂപത്തിൽ മുഴുകി, അദ്ഭുതത്തിന്റെ രത്നമായ അദ്ദേഹം മറ്റൊന്നും അറിഞ്ഞില്ല.",
        "0.111": "ആഗ്രഹവും ഭയവുമില്ലാത്ത അദ്ദേഹത്തിന്, സത്യജ്ഞാനത്തിന്റെ കണ്ണിൽ, തന്റെ യോഗത്തിന്റെ രത്നത്തിന് മോക്ഷരാജ്യത്തിൽ കുറഞ്ഞ ഒരു വിലയുമുണ്ടായിരുന്നില്ല.",
        "0.112": "മധ്വന്റെ ഇളയ സഹോദരന് അന്ന് മധ്വന്റെ ഭഗവാൻ നൽകിയ കൃപ, മനസ്സിന് അതീതമായതിനാലോ രഹസ്യമായതിനാലോ വിവരിക്കപ്പെടുന്നില്ല.",
        "0.113": "“ആഹാ, മഹാബോധന് (മധ്വന്) സേവിക്കുന്നതിന്റെ മഹത്വം ഇങ്ങനെയാണ്; ഈ യുഗത്തിൽ ഈ ഭാഗ്യവാൻ ഇത്രയും സിദ്ധി നേടിയല്ലോ!” എന്ന് ദേവന്മാർ സ്തുതിച്ചു.",
        "0.114": "അനിരുദ്ധതീർത്ഥർ എന്ന പേരുള്ള പ്രിയശിഷ്യൻ അദ്ദേഹത്തിന്റെ അടുത്ത് വന്നു — വ്രതങ്ങളിൽ കർക്കശൻ, ഇന്ദ്രിയങ്ങൾക്കതീതമായത് അറിയുന്നവൻ, പഠനത്തിന്റെ സമുദ്രം, യുക്തിശാസ്ത്രത്തിൽ നിപുണൻ.",
        "0.115": "അദ്ദേഹത്തിന്റെ അപേക്ഷയാൽ, ആ മഹാൻ വീണ്ടും രജതപീഠത്തിൽ (ഉഡുപ്പിയിൽ) എത്തി; സർവ്വജ്ഞൻതന്നെ കരുണയാൽ തന്റെ സ്വന്തക്കാരുടെ ഇടയിൽ തിരിച്ചെത്തിയതുപോലെ ജനങ്ങൾക്ക് തോന്നി.",
        "0.116": "അദ്ദേഹത്തിന്റെ ശിഷ്യൻ വ്യാസതീർത്ഥർ ആയിരുന്നു — വ്യാസന്റെ പാദങ്ങളിൽ അഭയം തേടിയവൻ, കവികളുടെ ആഭരണം, പണ്ഡിതരുടെ ശിരോമണി, തപസ്വികളിൽ ഉത്തമൻ, മധ്വന്റെ ലീലയിലെ ഓമനത്തത്തയെപ്പോലെയുള്ളവൻ.",
        "0.117": "അനുഗ്രഹം നൽകി, മഹാന്മാർക്കിടയിലും മഹത്തായ, ദൃഢമായ ദാസ്യം (ഭഗവാന്റെ) അദ്ദേഹത്തിന് നേടിക്കൊടുത്തു; തന്റെ ശക്തികളാൽ ജനങ്ങളെ അദ്ഭുതപ്പെടുത്തി.",
        "0.118": "ഹരിയെ പ്രസാദിപ്പിച്ച്, മറ്റുള്ളവർക്ക് നേടാൻ പ്രയാസമുള്ള മഹത്വത്തിലേക്കും, മറ്റുള്ളവർക്ക് കയറാൻ പ്രയാസമുള്ള, ഗുഹന് (കുമാരന്) പ്രിയമായ മഹാപർവതത്തിലേക്കും (കുമാരപർവ്വതം) അദ്ദേഹം കയറി.",
        "0.119": "എല്ലായിടത്തും പരന്ന മധ്വന്റെ ഗുണങ്ങളാൽ ആകർഷിക്കപ്പെട്ട്, ഗോദാവരിയിൽ നിന്ന് വന്ന ഒരാൾ ആ നല്ല ഹൃദയമുള്ളവന്റെ മറ്റൊരു ശിഷ്യനായി — പദ്മനാഭതീർത്ഥർ എന്ന പേരിൽ.",
        "0.120": "അദ്ദേഹത്തിന്റെ ശ്രവണം, മനനം, നിരന്തര ഭക്തി, വൈരാഗ്യം, ദിവസേനയുള്ള സേവ എന്നിവയിൽ പ്രസാദിച്ച ദൂരദർശി ഉടൻ മംഗളകരമായ ജ്ഞാനം നൽകി.",
        "0.121": "പണ്ഡിതശ്രേഷ്ഠനായ ആ തിമിംഗലം വേദാന്തസമുദ്രം ഒരിക്കലും വിട്ടില്ല; യുക്തിപ്രവാഹത്തിന്റെ ശക്തിയിൽ മറ്റു ശാസ്ത്രങ്ങളുടെ നദികളിൽ സഞ്ചരിച്ചെങ്കിലും.",
        "0.122": "തർക്കവാദികളിലെ സിംഹമായ അദ്ദേഹം, തന്റെ വിശദീകരണത്തിന്റെ ഗർജ്ജനത്താൽ, സ്വന്തം വൃത്തത്തിൽ വീരന്മാരെന്ന് കരുതിയ മായാവാദികളായ ഗ്രാമ നായ്ക്കളെ ഓടിച്ചു.",
        "0.123": "വ്യാജതർക്കക്കാരിലെ മദയാനകളായ യുക്തിയുടെ തലകൾ പിളർക്കുന്നതിൽ, ‘നാല് മുഖ’മുള്ളവനായിരുന്നിട്ടും (പാണ്ഡിത്യത്തിൽ ബ്രഹ്മാവിനു തുല്യൻ), അദ്ദേഹം വ്യക്തമായും ‘അഞ്ചു മുഖ’മുള്ളവനായി (സിംഹം) മാറി.",
        "0.124": "ആ ജ്ഞാനസമുദ്രത്തിൽ നിന്നാണ് ശ്രേഷ്ഠമായ അനുവ്യാഖ്യാനത്തിന്റെ മംഗളകരമായ, അമൂല്യമായ വ്യാഖ്യാനം — ന്യായരത്നാവലി — ഉണ്ടായത്.",
        "0.125": "“വേദം വിശദീകരിക്കുന്ന ഗുരുവിന്റെ ശിഷ്യൻ” എന്ന് ആദരിക്കപ്പെട്ട്, സഭയിൽ മര്യാദയുള്ളവനും വേദസാരമറിയുന്നവനുമായ അദ്ദേഹം, വേദത്തിന്റെ മുന്നിൽ തന്നെ അത് വിശദീകരിച്ചു.",
        "0.126": "ഈ രണ്ടുപേർക്കും മുമ്പും പിമ്പും, അനന്തബോധന്റെ (മധ്വന്റെ) ശിഷ്യന്മാരായി അനേകം ദേശങ്ങളിൽ നിന്നുള്ള മഹാതപസ്വികൾ ഇവിടെയുണ്ടായിരുന്നു.",
        "0.127": "(ശ്ലോകങ്ങൾ 127–128 അവരുടെ പേരുകൾ സൂചിപ്പിക്കുന്നു.) ഇന്ദ്രിയങ്ങളെ ജയിച്ച (ഹൃഷീകം) ഹൃഷീകേശതീർത്ഥർ; ജനനമരണാദികളെ തകർക്കുന്ന ജനാർദ്ദനൻ; നരസിംഹന്റെ പാദങ്ങളിൽ വിശ്രമിക്കുന്ന നരസിംഹൻ; ആ നാമം അഭ്യസിച്ച ഉപേന്ദ്രൻ;",
        "0.128": "‘ഉയരം കുറഞ്ഞവൻ’ എന്ന മറ്റൊരു വാക്കാൽ (വാമനൻ) അറിയപ്പെട്ടവൻ; ശ്രീരാമന്റെ പാദങ്ങളിൽ വിശ്രമിച്ച രാമൻ; ഇന്ദ്രിയങ്ങൾക്കതീതമായ ഗുണങ്ങളിൽ സമ്പന്നനായ അധോക്ഷജൻ: ഭക്തിയുടെയും വൈരാഗ്യത്തിന്റെയും സമുദ്രങ്ങൾ.",
        "0.129": "തങ്ങളുടെ പാദങ്ങളാൽ ഭൂമിയെ ശുദ്ധമാക്കി (സൂര്യൻ രശ്മികളാൽ എന്നപോലെ), ഹരിയുടെ ഭവനത്തിലേക്കുള്ള വഴി കാണിച്ച്, തെറ്റായ സിദ്ധാന്തങ്ങളുടെ ഇരുട്ട് അകറ്റി, അവർ ഭൂമിയിലിറങ്ങിയ സൂര്യന്മാരെപ്പോലെയായിരുന്നു.",
        "0.130": "മോക്ഷശാസ്ത്രമെന്ന അമൃതസമുദ്രത്തെ സേവിക്കുന്നതിൽ എപ്പോഴും ആനന്ദിച്ച്, ചക്രധാരിയുടെ പാദങ്ങളെ അവന്റെ ഏറ്റവും മനോഹരമായ വിഗ്രഹങ്ങളിൽ അവർ ആരാധിച്ചു.",
        "0.131": "മധ്വന്റെ ശിഷ്യന്മാരുടെ അനേകം ശിഷ്യന്മാരും, വീണ്ടും അവരുടെ ശിഷ്യന്മാരും, എല്ലാവരും നല്ല ഗുണങ്ങളാൽ അലങ്കരിക്കപ്പെട്ടവർ, ഭൂമിയെ സമൃദ്ധമായി അലങ്കരിച്ചു.",
        "0.132": "അവരെല്ലാം, സത്യമായ എല്ലാ ശാസ്ത്രങ്ങളും വിശദീകരിക്കുന്ന സന്തോഷത്തിന്റെ അമൃതസമുദ്രത്തിൽ എപ്പോഴും മുങ്ങി, വ്യാജതർക്കക്കാരുടെ വാദങ്ങൾ മുറിച്ചുകളഞ്ഞ് അലങ്കരിക്കപ്പെട്ടു.",
        "0.133": "ചിലർ പാണ്ഡിത്യത്തിൽ ദരിദ്രരെങ്കിലും വലിയ ഭക്തി നിറഞ്ഞവർ; മറ്റുള്ളവർ ചെറിയ ബുദ്ധിയുള്ളവരെങ്കിലും ഏറെ കേട്ടവരും മഹാഗുണങ്ങളുള്ളവരുമായിരുന്നു.",
        "0.134": "പല ഗൃഹസ്ഥരും അദ്ദേഹത്തിന്റെ പൂർണ്ണ കൃപ നേടി; അവരിൽ ലികുച കുടുംബത്തിലെ മൂന്ന് ശിരോമണികൾ മൂന്നു പുണ്യാഗ്നികൾപോലെ തിളങ്ങി.",
        "0.135": "ആ ഉത്തമ പണ്ഡിതന്മാർ മധ്വന്റെ കൽപ്പനയിൽ നിന്ന് അപൂർവ്വമായി മാത്രം വ്യതിചലിച്ചു; ശിഷ്യരെന്ന വയലുകളിൽ യഥാർത്ഥ വിദ്യയുടെ വിത്ത് വിതയ്ക്കുന്നതിൽ മാത്രം മുഴുകി.",
        "0.136": "ഗ്രാമത്തലവന്മാരും പ്രമുഖ ബ്രാഹ്മണരും പൂർണ്ണേക്ഷന്റെ (മധ്വന്റെ) ശിഷ്യന്മാരായി; സജ്ജനങ്ങളെ സംരക്ഷിക്കുന്നതിലൂടെ മാത്രം അവർക്ക് ഉത്തമാവസ്ഥ ലഭിക്കും.",
        "0.137": "അവരുടെ സേവനത്തിലും ഭക്തിയിലും മറ്റും പ്രസാദിച്ച്, ചിലർക്ക് യോഗികൾക്കുപോലും നേടാൻ പ്രയാസമുള്ള തന്റെ സ്വന്തം ലക്ഷ്യം അദ്ദേഹം നൽകി — രാമനു പ്രിയനായവൻ രാമനെപ്പോലെ.",
        "0.138": "ശിഷ്യരുടെയും ശിഷ്യരുടെ ശിഷ്യരുടെയും ഈ ഉത്തമത അദ്ദേഹത്തിന്റെ കാരുണ്യത്തിന്റെ ഉദയത്തിൽ നിന്നുണ്ടായതിനാൽ, ഭക്തിയാൽ എളുപ്പത്തിൽ ലഭിക്കുന്ന അദ്ദേഹത്തിന്റെ പാദങ്ങളാകുന്ന ആഗ്രഹവൃക്ഷം ആരാണ് ആഗ്രഹിക്കാത്തത്?",
        "0.139": "ഇങ്ങനെ ഭൂമിയിലെ സജ്ജനങ്ങളാൽ ആരാധിക്കപ്പെട്ട്, ഭഗവാൻ ശേഷശയ്യയിൽ (ചാതുർമാസ്യത്തിൽ) കിടക്കുമ്പോൾ, പൂർണ്ണജ്ഞാനിയായവൻ, തന്റെ ഭക്തരോടുള്ള സ്നേഹത്താൽ, കണ്വതീർത്ഥത്തിലെ കാറ്റുകളാൽ ശുദ്ധമായ ഗ്രാമത്തിൽ, മനോഹരമായ ഒരു മഠത്തിൽ താമസിച്ചു.",
        "0.140": "പണ്ഡിതിയുടെ അമൃതം പരത്തുന്ന, മനോഹര ചാരുതയുള്ള, ഭഗവാൻ ആനന്ദതീർത്ഥരുടെ ചന്ദ്രമുഖം ഇവിടെ കണ്ട ഭക്തർക്ക് — ദാസന്മാരുടെ സേവപോലും മനുഷ്യന് സംസാരത്തിന്റെ ചൂട് ശമിപ്പിക്കാൻ എന്ത് നൽകാത്തതാണ്?",
        "0.141": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പതിനഞ്ചാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "ഏറ്റവും നീണ്ട സർഗ്ഗം, അനുഷ്ടുപ് വൃത്തത്തിൽ. ലോകത്തിന്റെ യാഥാർത്ഥ്യത്തെയും ഭഗവാന്റെ സ്വഭാവത്തെയും കുറിച്ചുള്ള ത്രിവിക്രമ പണ്ഡിതനുമായുള്ള മധ്വന്റെ മഹാവാദം ഓരോ യുക്തിയും ക്രമത്തിൽ അവതരിപ്പിക്കപ്പെടുന്നു; ത്രിവിക്രമൻ മധ്വസിദ്ധാന്തം സ്വീകരിച്ച് ശിഷ്യനാകുന്നു. മധ്വന്റെ ഗ്രന്ഥങ്ങൾ തിരികെ ലഭിച്ചതും, മാതാപിതാക്കളുടെ അന്ത്യവും, സഹോദരന്റെ സന്ന്യാസവും, അദ്ദേഹത്തിന്റെ ഉപദേശം തുടർന്ന ശിഷ്യന്മാരും ഈ സർഗ്ഗം പറയുന്നു."
    },
    "sumadhva-vijaya-16": {
      "verses": {
        "0.0": "അപ്പോൾ ഇവിടെയുള്ള ഒരു പണ്ഡിതൻ, മധുസൂദനന്റെ പാദങ്ങൾ ആസ്വദിക്കുന്ന വേദാനുയായികളായ സജ്ജനങ്ങളോട്, ബന്ധത്തിന്റെയും മോചനത്തിന്റെയും മൂലമായ വേദാന്തം തന്നെ വിശദീകരിക്കുന്നതുപോലെ, വിശാലമനസ്കന്റെ മഹത്തായ മഹിമ വ്യക്തമായി പറഞ്ഞു.",
        "0.1": "ഗോമതീതീരത്തിനടുത്ത്, വേദങ്ങളെ വെറുക്കുന്ന, അധമവർണ്ണത്തിൽ പെട്ട ഒരു വാചാലനായ രാജാവ്, വേദങ്ങളുടെ മേന്മ സ്ഥാപിക്കുന്ന, വാഗ്മികളിൽ ഉത്തമനായ, ശുദ്ധകീർത്തിയുടെ ചന്ദ്രനായ സർവ്വജ്ഞനോട് ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.2": "“വാഗ്ദാനം ചെയ്ത ഫലം എപ്പോഴും പാളിപ്പോകുന്ന വാക്യം ഭ്രാന്തന്റെ വിളംബൽപോലെ പ്രമാണമല്ല; അത് വേദത്തിലെ എല്ലാ വാക്കുകളെയും എല്ലാ വിധത്തിലും പ്രമാണമല്ലാതാക്കുന്നതിന്റെ ഉദാഹരണമായി മാറുന്നു.”",
        "0.3": "“വേദത്തിൽ പറഞ്ഞ ഫലം ഒരാളുടെ യോഗ്യതയനുസരിച്ച് ലഭിക്കുന്നു” എന്ന് വിശാലമനസ്കൻ പറഞ്ഞപ്പോൾ, ആ ദുഷ്ടൻ മറുപടി പറഞ്ഞു: “ആ യോഗ്യത ഉള്ള യോഗ്യനായ ഒരാളെയും കാണാത്തതിനാൽ, കഴുതയുടെ കൊമ്പുപോലെ അങ്ങനെയൊരാൾ ഉണ്ടാകാനാവില്ല.”",
        "0.4": "ആ പരിഹാസം സഹിക്കാനാവാതെ, ഉന്നതൻ ഉടൻ തന്റെ രണ്ടു മൃദുവായ കൈകളിൽ ചെടികളുടെ വിത്തുകൾ എടുത്ത്, ഒരു വേദമന്ത്രത്താൽ അവയിൽ നിന്ന് മുളകളും ഇലകളും പൂക്കളും വിത്തുകളും ഉണ്ടാക്കി.",
        "0.5": "ഒരിക്കൽ രാത്രി വിശദീകരിക്കുമ്പോൾ വിളക്ക് അണഞ്ഞുപോയി; കാരുണ്യസമുദ്രമായവൻ തന്റെ വലിയ പെരുവിരലിലെ തിളങ്ങുന്ന നഖത്തിന്റെ മാത്രം വെളിച്ചത്തിൽ ശിഷ്യന്മാരെക്കൊണ്ട് വായന തുടർന്നു.",
        "0.6": "എവിടെയോ, ഉയർന്ന കരയിൽ നിന്ന് വീഴുന്ന പ്രവാഹത്തിന്റെ ശക്തിയെ താങ്ങാൻ കഴിയുന്ന ഒരു വലിയ പാറ ആ വിശാലനേത്രൻ കണ്ടു; കടവിനുവേണ്ടി ആയിരം പേർ കൊണ്ടുവന്നതായിരുന്നു, പക്ഷേ ശക്തി തീർന്ന് അവർ അത് ഉപേക്ഷിച്ചിരുന്നു; അദ്ദേഹം പറഞ്ഞു:",
        "0.7": "“ജനങ്ങളുടെ നന്മയ്ക്കായി ഈ പാറ എന്തുകൊണ്ട് എടുത്തുകൊണ്ടുപോയില്ല?” അവിടത്തെ ജനങ്ങൾ മറുപടി പറഞ്ഞു: “ഉത്തമ തപസ്വീ, ഒരു മനുഷ്യനും ഇത് എടുക്കാനാവില്ല; ഭീമൻ ശ്രമിച്ചാൽപ്പോലും അത് ഇളകിയേക്കാം, ഇളകാതിരിക്കാം.”",
        "0.8": "പർവതം വഹിച്ച വാനരനായിരുന്ന (ഹനുമാൻ) അവൻ, തന്റെ ശുദ്ധമായ താമരക്കൈകൊണ്ട് കളിയായി അത് എടുത്ത് അവിടെ സ്ഥാപിച്ചു; ഇന്നും തുംഗയിലെ ആ പാറ അദ്ദേഹത്തിന്റെ പ്രവൃത്തിക്ക് സാക്ഷ്യം പറയുന്നു.",
        "0.9": "ശിഷ്യന്മാരും തപസ്വികളും മറ്റുള്ളവരുമായ ജനക്കൂട്ടത്താൽ അലങ്കരിക്കപ്പെട്ട വഴിയിലൂടെ, ചൈതന്യമുള്ള സംവാദത്തോടെ, സർവ്വജ്ഞൻ ചന്ദ്രൻ സൂര്യനോടൊപ്പം വസിക്കുന്ന സമയത്ത് (അമാവാസി ദിനത്തിൽ) കടലിലേക്ക് പോയി.",
        "0.10": "കണ്വമഹർഷിക്ക് പ്രിയമായ കുളത്തിൽ മുങ്ങിയതിനാൽ ഇപ്പോഴും നനഞ്ഞ ശരീരങ്ങളോടെ, സൂര്യഗ്രഹണം കാരണം ഗ്രാമവാസികളെല്ലാം, ഇളയവരും മുതിർന്നവരും, അവിടെ വരുന്നുണ്ടായിരുന്നു.",
        "0.11": "പരിവാരസമേതനായ സർവ്വജ്ഞനെ കണ്ട സജ്ജനങ്ങൾ വിടർന്ന കണ്ണുകളോടും പുഞ്ചിരിക്കുന്ന മുഖങ്ങളോടും കൂടി സന്തോഷിച്ചു; മറ്റുള്ളവർ നെറ്റി ചുളിച്ച് അദ്ദേഹത്തെ ആക്ഷേപിച്ചു. അത് അദ്ഭുതമല്ല: ഇരുവരും സ്വന്തം സ്വഭാവം പിന്തുടരുന്നു.",
        "0.12": "“ഈ ലോകഗുരുവിനെ നിന്ദിക്കരുത്, നിന്ദിക്കരുത്!” എന്ന് അവരെ ശാസിക്കുന്നതുപോലെ, നദികളുടെ രാജാവായ കടൽ, ദുഷ്ടരെ ശിക്ഷിക്കാൻ കോപിച്ച്, തിരക്കൈകൾ ഉയർത്തി, അസ്വസ്ഥമായി, ഇടിമുഴക്കം പോലുള്ള ഭയങ്കര ഗർജ്ജനത്തോടെ മുന്നോട്ടു കുതിച്ചു.",
        "0.13": "സന്തോഷത്താൽ കുതിച്ചുചാടി, വേഗത്തിൽ മുന്നോട്ടു പാഞ്ഞ്, ആഴമേറിയ ഗർജ്ജനത്തോടെ സ്തുതിച്ച്, മനോഹര നുരകളാൽ പുഞ്ചിരിച്ച്, കരയിലെ കടൽ തിരമാലകളുടെ പല അവയവങ്ങളാൽ മധ്വനെ വണങ്ങുന്നതുപോലെ തോന്നി.",
        "0.14": "മധ്വനും കടലും ഒരുപോലെയായിരുന്നു: വാക്കിന്റെ (അല്ലെങ്കിൽ വെള്ളത്തിന്റെ) കളികളിൽ അതുല്യർ, ആഴത്തിൽ അഗാധർ, ലംഘിക്കാനാവാത്തവർ, അവയിൽ അനേകം ഗുണങ്ങളുടെ രത്നങ്ങൾ തിളങ്ങുന്നവർ; എന്നാൽ ഉത്തമ മനസ്സുള്ള അദ്ദേഹം ജനങ്ങൾക്ക് പ്രിയനാണ്, കടലോ ഉപ്പുരസമുള്ളതാണ് (ലവണ്യം, അഥവാ ഭംഗി) — അതാണ് വ്യത്യാസം.",
        "0.15": "കടൽത്തീരത്തെ വിശാലമായ ഇരിപ്പിടത്തിൽ, സമുദ്രത്തിന്റെ വേഗമുള്ള തിരക്കൈകളാൽ വൃത്തിയാക്കപ്പെട്ട്, യജമാനൻ ഐതരേയ ശാഖയിലെ സൂക്തങ്ങൾ വളരെനേരം, ഏറ്റവും മനോഹരമായ രീതിയിൽ വിശദീകരിച്ചു.",
        "0.16": "“അദ്ദേഹത്തിന്റെ സ്വരം ആഴത്താൽ കടലിന്റെ ഗർജ്ജനത്തെയും മറികടക്കുന്നു, എന്നിട്ടും അദ്ഭുതകരമായി കേൾക്കാൻ മധുരമാണ്. പൂർണ്ണചന്ദ്രമുഖമുള്ള ഈ ഭാഗ്യവാൻ ആരാണ്?” ഇങ്ങനെ ചിന്തിച്ച് ജനസമുദ്രം വേഗം അദ്ദേഹത്തെ ചുറ്റി.",
        "0.17": "“വേദത്തിന്റെ യഥാർത്ഥ അർത്ഥം പറയുന്നതിൽ നിപുണനായ ഇദ്ദേഹത്തെ വേദത്തിന്റെ ശത്രു എന്ന് വിളിച്ച അസൂയാലുക്കളായവരെ ധിക്കരിക്കുന്നു!” എന്ന് ജനങ്ങൾ ഉച്ചത്തിൽ വിളിച്ചു; അദ്ഭുതത്തോടെ അവർ കൂപ്പുകൈയോടെ വണങ്ങി.",
        "0.18": "ഭക്തിയോടെ വിശാലമനസ്കനെ ആദരിച്ച്, ദേവന്മാർപോലും സേവിക്കുന്ന അദ്ദേഹത്തിന്റെ പാദധൂളി വഹിച്ച്, ബ്രാഹ്മണസമൂഹങ്ങൾ മംഗളകരമായ സമയത്ത് നദികളുടെ രാജാവിൽ സ്നാനം ചെയ്തു; അവരുടെ സ്നാനത്താൽ ആ ജലം കൂടുതൽ ശുദ്ധമായി.",
        "0.19": "ആനക്കൂട്ടങ്ങൾപോലെ ജനക്കൂട്ടങ്ങളെ വീഴ്ത്തിയ, ശക്തരുടെ ശക്തമായ, തടുക്കാനാവാത്ത തിരമാലകളാൽ ആക്രമിക്കപ്പെട്ട് ഉരുണ്ടുപോയ അവിടെയുള്ള പലരും കടലിൽ പരിഹാസ്യരായി.",
        "0.20": "വിശാലമായ തിരമാലകൾ മറച്ച രൂപത്തോടെ, പൂർണ്ണജ്ഞാനിയായവൻ മുങ്ങുന്നത് കണ്ട ഒരു ദുഷ്ടൻ പരിഹസിച്ചു: “അയ്യോ, മൂന്നു ലോകങ്ങളെ ജയിച്ച ഈ പ്രസിദ്ധ ഗുരു ഒരു ചെറിയ തിരയുടെ കളിയിൽ വീഴുന്നല്ലോ!”",
        "0.21": "ചെറിയവരുടെ നിസ്സാരവാക്കുകൾ — മറ്റുള്ളവരെ മാത്രം ഇളക്കുന്നവ — അദ്ദേഹം ഗണ്യമാക്കിയില്ല; നായ്ക്കളെ കുരപ്പിക്കുന്ന കുറുനരികളുടെ ഓരിയിടൽ മഹാസിംഹം ശ്രദ്ധിക്കാത്തതുപോലെ.",
        "0.22": "വിശാലബുദ്ധിയുള്ളവൻ, ലോകങ്ങൾക്ക് ജനനവും പരിപാലനവും അന്തവും നൽകുന്ന തന്റെ നോട്ടം സമുദ്രത്തിൽ വീഴ്ത്തി; ആ ഭാരമേറിയവന്റെ മുന്നിൽ തോറ്റ സമുദ്രം ചലനം ഉപേക്ഷിച്ച്, നിശ്ചല തടാകംപോലെയായി.",
        "0.23": "മറ്റാർക്കും ചെയ്യാനാവാത്ത ഇത്തരം പ്രവൃത്തികളാൽ പോലും, ദുഷ്ടന്മാർ അദ്ദേഹത്തിന് ഉറച്ച ആദരവ് നേടിയില്ല, വീണ്ടും വെറുത്തു; ആ ഭാഗ്യദോഷിയും ദുഷിച്ച മനസ്സുള്ളവനുമായവനിൽ അത് യോജിച്ചതുതന്നെയായിരുന്നു.",
        "0.24": "സ്വന്തം ശക്തി കാണിക്കാൻ ഗണ്ഡവതൻ സഹോദരനോടൊപ്പം വന്നപ്പോൾ, ‘ഇദ്ദേഹം സേവ ചെയ്യാൻ യോഗ്യനാണ്’ എന്ന് പരീക്ഷകർ പറഞ്ഞതിനാൽ, യജമാനൻ അവനോട് സങ്കോചമില്ലാതെ തനിക്ക് അല്പം സേവ ചെയ്യാൻ കൽപ്പിച്ചു.",
        "0.25": "മുപ്പതു ശക്തരായ പുരുഷന്മാർ കൊണ്ടുവന്ന കൊടിമരം കാന്തവരത്തിലെ ശ്രീകണ്ഠേശ്വര ക്ഷേത്രത്തിൽ തനിയെ കൊണ്ടുപോയവനും, ഒരു തെങ്ങിൽ ഇളം ഗദകൊണ്ട് അടിച്ചപ്പോൾ, അത് കുലുങ്ങുന്നതനുസരിച്ച് തനിക്കിഷ്ടമുള്ളത്രയും തേങ്ങ കിട്ടിയവനും ഇവനായിരുന്നു.",
        "0.26": "ഇത്രയും ബലമുള്ള അദ്ദേഹവും മൂത്ത സഹോദരനും യജമാനന്റെ കഴുത്തിൽ രണ്ടു വശങ്ങളിൽ നിന്ന് ഒരുമിച്ച് പിടിച്ച്, അത് ഞെരിക്കാൻ പരമാവധി ശ്രമിച്ചു; എന്നാൽ പിടിവലി കൊണ്ട് അത് കൂടുതൽ കൂടുതൽ കഠിനമായതേയുള്ളൂ.",
        "0.27": "വിയർത്ത്, ക്ഷീണിച്ച്, ഗുരുവിന്റെ കൽപ്പനപ്രകാരം ശിഷ്യന്മാർ വീശിയിട്ടും, ഇരുവരും ഇരുമ്പിനെക്കാൾ കഠിനമായ ആ കഴുത്ത് വിട്ട് നിലത്തു വീണു; അതിനിടയിലും അത് വ്യക്തമായി സംസാരിച്ചുകൊണ്ടിരുന്നു.",
        "0.28": "ഇരുവരും സുഖം പ്രാപിച്ചപ്പോൾ, എങ്കിലും വിനയം വരാതെ നിന്നപ്പോൾ, നിർമ്മലഹൃദയനായവൻ അവരോട് നിലത്തുവച്ച തന്റെ വിരൽ ഉയർത്താൻ പറഞ്ഞു; വലിയ പരിശ്രമത്തോടെയും ബലത്തോടെയും പിടിച്ചിട്ടും അത് ഒന്നനങ്ങാൻ പോലും അവർക്കായില്ല.",
        "0.29": "പുഞ്ചിരിച്ചുകൊണ്ട്, അനായാസമായി ഒരു യുവ ബ്രഹ്മചാരിയുടെ മുകളിൽ കയറി അദ്ദേഹം നരസിംഹക്ഷേത്രം ചുറ്റി. ലഘിമ മുതലായ ശക്തികളുള്ളവനായ മധ്വൻ മൂന്നു ലോകങ്ങളിലെ അദ്ഭുത രത്നങ്ങളുടെ രാജാവായി.",
        "0.30": "അമ്പതു രാജഭടന്മാർ കഷ്ടിച്ചു കൊണ്ടുവന്ന മരഗോവണി വീട്ടിലേക്ക് ചുമന്നുകൊണ്ടുപോയ പൂർവ്വവതൻ, ഗുരുവിന്റെ തന്നെ കൽപ്പനപ്രകാരം, അദ്ദേഹത്തിന്റെ പ്രഭാഷണത്തിന്റെ ശബ്ദം നിശ്ശബ്ദമാക്കാൻ അദ്ദേഹത്തിന്റെ കഴുത്ത് ഞെരിക്കാൻ ശ്രമിച്ചു.",
        "0.31": "ശക്തനായ ആ മനുഷ്യൻ, ഉഗ്രമായ ദുശ്ശാഠ്യത്തോടെ, വിയർക്കുന്നതുവരെ പരിശ്രമിച്ചിട്ടും, യജമാനന്റെ പ്രഭാഷണ ശബ്ദം മുമ്പത്തേക്കാൾ ഉച്ചത്തിൽ മുഴങ്ങി; വിശാലമനസ്കന്റെ വിരൽ ഉയർത്താൻ പോലും അവന് കഴിഞ്ഞില്ല. ജനങ്ങൾ അദ്ഭുതം നിറഞ്ഞു.",
        "0.32": "മറ്റുള്ളവരും ശിവാഗ്നി മുതലായവരും, അതിലും വലിയ ശ്രമങ്ങളോടെ അദ്ദേഹത്തെ പരീക്ഷിച്ചു; അദ്ദേഹം അവരെ തള്ളിക്കളഞ്ഞില്ല; അദ്ദേഹത്തിൽ ഒരിടത്തും ബലക്കുറവ് കണ്ടില്ല; അവർ ഉറപ്പിച്ചു: “ഇദ്ദേഹം ഭീമൻ തന്നെയാണ്.”",
        "0.33": "ചൂണ്ടുകൊണ്ട് വീണ്ടുംവീണ്ടും പിടിച്ചു വലിച്ചിട്ടും അദ്ദേഹത്തിന്റെ ശരീരത്തിലെ ഒരു രോമംപോലും പറിഞ്ഞില്ല; അതിശക്തരുടെ മുഷ്ടിപ്രഹരങ്ങൾ അദ്ദേഹത്തിന്റെ മൃദുവായ മൂക്കിൻ തുമ്പിൽ പതിച്ചിട്ടും ചന്ദ്രമുഖത്തിന്റെ ശാന്തത ഇളകിയില്ല.",
        "0.34": "ദുർബലമായ നായ്ക്കളോട് സിംഹം എന്നപോലെ, ചെറിയ അരുവികളിലെ വെള്ളത്തോട് സമുദ്രം എന്നപോലെ, മിന്നാമിനുങ്ങുകളോട് സൂര്യൻ എന്നപോലെ, മനുഷ്യവേഷം കെട്ടിയ അദ്ദേഹം തന്റെ തരത്തിലുള്ള എതിരാളികളോടും പെരുമാറി.",
        "0.35": "വളരെക്കാലം ബലിയും നിവേദ്യവും ലഭിക്കാതിരുന്ന പരന്തി ക്ഷേത്രത്തിൽ, അളവില്ലാത്ത ജ്ഞാനമുള്ളവൻ എത്തി; ഗ്രാമത്തലവന്റെയും രാജാക്കന്മാരുടെയും സഹായത്താൽ, അര ദിവസത്തിനകം, സർവ്വജീവികൾക്കും സമൃദ്ധമായ നിവേദ്യങ്ങളോടെ അതിന്റെ ഐശ്വര്യം പുനഃസ്ഥാപിച്ചു.",
        "0.36": "ആരാധ്യരാൽപ്പോലും ആരാധിക്കപ്പെടുന്ന അദ്ദേഹം, ഭീമനായി സഹോദരന്മാരോടൊപ്പമിരുന്നപ്പോൾ, പാഞ്ചാലി അവരോടൊപ്പം ബലിജലം അർപ്പിക്കുമ്പോൾ, പണ്ട് അവിടെ അഞ്ചു രൂപങ്ങളിൽ മുരാരി സ്ഥാപിക്കപ്പെട്ട് ആരാധിക്കപ്പെട്ടതിനെ ഓർത്തു.",
        "0.37": "‘നദികൾക്കിടയിൽ’ എന്ന പേരുള്ള സരിദന്തരം പ്രദേശത്തേക്ക് വരാനിരിക്കെ, അവിടത്തെ കുളം വേനൽക്കാലത്ത് വറ്റിയെന്ന് കേട്ട അദ്ദേഹം, അത് നിറയ്ക്കാൻ ഉടൻ മേഘക്കൂട്ടത്തെക്കൊണ്ട് കനത്ത മഴ പെയ്യിച്ചു; ജനങ്ങൾ അദ്ഭുതപ്പെട്ടു.",
        "0.38": "ദുരുപദേശങ്ങളാലും ദുഷ്ടസംഘങ്ങളാലും പ്രേരിതനായ ഗ്രാമത്തലവൻ, ശൂദ്രരുടെ നേതാവ്, അദ്ദേഹത്തെ അടിക്കാൻ വന്നു; എന്നാൽ ഉദിക്കുന്ന സൂര്യനെപ്പോലെ പോകുന്ന അദ്ദേഹത്തെ കണ്ട് അദ്ഭുതപ്പെട്ട് വണങ്ങി.",
        "0.39": "മൂന്നു ലോകങ്ങളുടെ വൈദ്യനായ ഭഗവാന്റെ (വൈദ്യനാഥന്റെ) ഏറ്റവും ശ്രേഷ്ഠമായ പുണ്യസ്ഥലത്ത് പോയി, ആഴമുള്ള ഹൃദയമുള്ള മഹാനായവൻ, ഭക്തരുടെ ക്ഷേമത്തിനായി ‘ശ്രീകൃഷ്ണാമൃതമഹാർണ്ണവം’ എന്ന സദുപദേശങ്ങളുടെ സമാഹാരം രചിച്ചു.",
        "0.40": "പിന്നെ സമൃദ്ധിയുള്ള മറ്റൊരു ഗ്രാമത്തിലേക്ക് പോയപ്പോൾ, അവിടത്തെ അഹങ്കാരികളെ താഴ്ത്താൻ വേണ്ടി, ആരോ സർവ്വജ്ഞനോട് പറഞ്ഞു: “അവരുടെ പണ്ഡിതന്മാർ എവിടെ? അവർ കിണറ്റിലെ തവളകൾപോലെയാണ്!”",
        "0.41": "“സർവ്വജ്ഞനെങ്കിലും ഈ സന്ന്യാസി യജ്ഞത്തിന്റെ സൂക്ഷ്മതകൾ അധികം അറിയുന്നില്ല” എന്ന് ഉറച്ചു വിശ്വസിച്ച്, അവരിൽ ഒരാൾ അസൂയയാൽ, സഭയിൽ തിളങ്ങിയ അദ്ദേഹത്തോട്, വൈദികവാക്യത്തിലെ കർമ്മകാണ്ഡത്തിലെ ഒരു ദുഷ്കരഭാഗം ചോദിച്ചു.",
        "0.42": "സംശയത്തിന്റെ ഒരു നിഴലുമില്ലാതെ അദ്ദേഹം അത് വിശദീകരിച്ചു; യജമാനൻ ആറാം ദിവസം ചൊല്ലുന്ന നരാശംസിയിലെ വിവിധ മനോഹരമായ അന്ത്യമന്ത്രങ്ങളും പറഞ്ഞു — ഛന്ദസ്സുകളിൽ നിന്ന് ഒഴുകിയ സത്തയെ സംരക്ഷിക്കുന്നവ.",
        "0.43": "ഇത്രയും ഉത്തമമായ പാണ്ഡിത്യം കണ്ട എതിരാളിസംഘം മത്സരബുദ്ധിയാൽ മനസ്സിളകി, “ഇത് അതിന്റെ അർത്ഥമല്ല” എന്ന് പറഞ്ഞു; മഹാമനസ്കൻ “എങ്കിൽ നിങ്ങൾ പറയൂ” എന്ന് പറഞ്ഞപ്പോൾ, അവർ വേഗം ഓടിപ്പോയി.",
        "0.44": "പിന്നെ ഒരാൾ മഹാനാമ്നി ഭാഗത്തെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിച്ചു, അവിടെ മന്ത്രത്തിന്റെ ദിക്കുകളുടെ രൂപങ്ങളും അവയുടെ മുമ്പുള്ള കൂട്ടിച്ചേർക്കലുകളും പറയപ്പെടുന്നു; ആ വാക്കുകളുടെ മുഴുവൻ സമാഹാരത്തിന്റെയും അർത്ഥം അദ്ദേഹം വിശദീകരിച്ചു, നിലനിൽക്കാൻ അത് ഉടൻ എഴുതിവെപ്പിച്ചു.",
        "0.45": "ഉദിച്ച പൂർണ്ണചന്ദ്രനെപ്പോലെയുള്ള മധ്വനെ കണ്ട ദുഷ്ടസംഘം, എതിരാളിയാണെന്ന് കരുതി ദൂരെ നിന്ന് കുരച്ചോടുന്ന മെലിഞ്ഞ നായയെപ്പോലെ അസ്വസ്ഥരായി. അമൃതഖനിയെ അത് എന്ത് ദോഷം ചെയ്യാനാണ്?",
        "0.46": "ദരിദ്രരായ ഭക്തരുടെ ഭക്ഷണം, കുറച്ചുപേർക്ക് മാത്രം മതിയായതായിരുന്നത്, കരുണയുള്ള അദ്ദേഹം നാലിരട്ടിയാക്കി; ധനവാന്മാരെ തൃപ്തിപ്പെടുത്താൻ, വിശാലബുദ്ധിയുള്ളവൻ മുപ്പതു പേർക്ക് മതിയാകുന്ന ഭക്ഷണം കഴിച്ചു.",
        "0.47": "മഴയും മറ്റും അദ്ദേഹം നിയന്ത്രിച്ചു; ലോകത്തെ നിയന്ത്രിക്കുന്ന വായുവിൽ അതിൽ എന്ത് അദ്ഭുതം? എങ്കിലും ലോകഗുരുവിന്റെ പ്രവൃത്തികൾ ആവർത്തിച്ചു പറയുന്നത് എല്ലാ പ്രവൃത്തികളിലും ഉത്തമമായതിനാൽ ഞങ്ങൾ ഇവിടെ അത്തരം പ്രവൃത്തികൾ വിവരിക്കുന്നു.",
        "0.48": "ഇങ്ങനെ ബ്രാഹ്മണൻ പറഞ്ഞു. മധ്വന്റെ ബഹുമുഖ കഥ ഇവിടെ കഥകളിൽ മാത്രമല്ല ആദരിക്കപ്പെട്ടത്; പ്രധാന ദേവന്മാർതന്നെ നേരിട്ട് വിവരിച്ചു, സ്വർഗ്ഗസഭയിൽ ഗന്ധർവന്മാർ അവരുടെ സന്തോഷത്തിനായി പാടുകയും ചെയ്തു.",
        "0.49": "ആ കഥ, ശ്ലോകരൂപത്തിൽ, ‘കാക്ക’ എന്ന ദോഷമില്ലാത്ത മധുരസ്വരമുള്ള ഗന്ധർവന്മാർ, യോജിച്ച താനങ്ങളും മൂർച്ഛനകളും ചേർത്ത്, പഞ്ചമം മുതലായ സ്വരങ്ങൾ എടുത്ത്, സ്വർഗ്ഗീയമായ തിളക്കമുള്ള ഗാന്ധാരഗ്രാമം ഉണ്ടാക്കിക്കൊണ്ട് പാടി.",
        "0.50": "കിരീടമണിഞ്ഞ തലകൾ താഴ്ത്തി, ചെമ്പുവർണ്ണമുള്ള വിരൽത്തുമ്പുകൾ ചേർത്ത്, താമരമുഖങ്ങളിൽ പുഞ്ചിരിയോടെ, ഭക്തിയിൽ ഉറച്ച ദേവന്മാരുടെ നാഥന്മാർ, ദശാധിശനായ (മധ്വന്റെ) ഉത്തമജീവിതത്തിന്റെ ആ ഗാനം കേട്ടു.",
        "0.51": "പിന്നെ, മുറിയാത്ത ജ്ഞാനമുള്ളവന്റെ വിജയത്തിന്റെ മഹോത്സവത്തെ ആദരിച്ച്, അദ്ഭുതത്തോടെയും പുഞ്ചിരിയോടെയും, മഹർഷിമാരുടെയും ചെറിയ ദേവന്മാരുടെയും സംഘങ്ങളോടെ ദേവന്മാർ അദ്ദേഹത്തെ കാണാൻ പുറപ്പെട്ടു.",
        "0.52": "മുരാരിയുടെ ഗുണസമൂഹങ്ങളെ കാണാനുള്ള കണ്ണാടിയായി താൻ രചിച്ച സത്യശാസ്ത്രത്തെ സ്തുതിച്ച്, നക്ഷത്രപഥങ്ങളെ തങ്ങളുടെ പ്രഭയാൽ പ്രകാശിപ്പിച്ച്, അവർ സമൃദ്ധമായ മനോലീലയുള്ള അദ്ദേഹത്തെ കണ്ടു.",
        "0.53": "ആകാശത്തുനിന്ന്, ഭൂമിയുടെ ആ ഭാഗത്ത് വസിക്കുന്ന അദ്ദേഹത്തിന് സ്വർഗ്ഗാധിപന്മാർ വണങ്ങി — തന്റെ മനോഹര കീർത്തികൊണ്ട് ലോകങ്ങളെ അലങ്കരിച്ച്, അനേകം ശ്രേഷ്ഠ ശിഷ്യന്മാർക്കിടയിൽ ഐതരേയോപനിഷത്ത് വിശദീകരിച്ചുകൊണ്ടിരുന്നപ്പോൾ.",
        "0.54": "തങ്ങളുടെ ഗുരു — തിളങ്ങുന്നവൻ, ചന്ദ്രമുഖൻ, താമരക്കണ്ണുള്ളവൻ, ഗംഭീരസ്വരമുള്ളവൻ, ദിവ്യലക്ഷണങ്ങൾ നിറഞ്ഞവൻ, ഹരിയോടുള്ള സ്നേഹത്തിൽ എല്ലാ ആഗ്രഹങ്ങളും സഫലമായവൻ — കണ്ട് അവർ തൃപ്തരായി, വാക്കുകളാൽ അദ്ദേഹത്തെ ആരാധിച്ചു:",
        "0.55": "“നിങ്ങളുടെ രശ്മികളാൽ (വാക്കുകളാൽ) തെറ്റായ സിദ്ധാന്തങ്ങളുടെ ഇരുട്ട് അകറ്റി, മുകുന്ദന്റെ ഗുണസമൂഹം ഞങ്ങൾക്ക് കാണിച്ചുതന്നു; നിങ്ങളുടെ ഗുണങ്ങളാൽ പതിനാലു ലോകങ്ങളെയും കീഴടക്കി. ഗുരുവേ, നിങ്ങളുടെ കരുണയിൽ ഞങ്ങൾക്ക് അഭയം നൽകേണമേ.",
        "0.56": "വണങ്ങുന്നവരുടെ ക്ഷേമത്തിനായി ഭൂമിയിലിറങ്ങിയ പ്രാണന്റെ നാഥനായ അങ്ങേക്ക് നമസ്കാരം; ഗുണസമ്പന്നനും രാമന് പ്രിയനുമായ ഹനുമാനായ അങ്ങേക്ക് നമസ്കാരം, യജമാനനേ; ഏറ്റവും ശക്തനും കൃഷ്ണന് പ്രിയനും ഭാഗ്യവാനുമായ ഭീമനായ അങ്ങേക്ക് നമസ്കാരം; ശ്രീമദ് മധ്വാചാര്യരേ, ഞങ്ങൾക്ക് യഥാർത്ഥ ദർശനം നൽകേണമേ. ജയ, ജയ!”",
        "0.57": "ഇങ്ങനെ പറഞ്ഞ്, തങ്ങളുടെ ഗുരുവിന്റെ വിജയത്തിന്റെ ഈ മഹോത്സവം ആഘോഷിച്ചുകൊണ്ട്, മുഖ്യദേവന്മാർ എല്ലാവരും കാൺകെ, ഹരിക്ക് പ്രിയമുള്ളവരിൽ ശ്രേഷ്ഠനായ ശ്രീമദ് ആനന്ദതീർത്ഥരുടെ മേൽ സുഗന്ധമുള്ള പുഷ്പവൃഷ്ടി ചൊരിഞ്ഞു.",
        "0.58": "ഇങ്ങനെ, “ആനന്ദം” എന്ന വാക്കാൽ അടയാളപ്പെട്ട പതിനാറാം സർഗ്ഗം സമാപിച്ചു — ശ്രീ സുമധ്വവിജയം എന്ന മഹാകാവ്യത്തിൽ നിന്ന്; ത്രിവിക്രമ പണ്ഡിതാചാര്യരുടെ പുത്രനും കവികുലഭൂഷണനുമായ നാരായണ പണ്ഡിതാചാര്യർ രചിച്ചത്."
      },
      "summary": "അവസാന സർഗ്ഗം. മധ്വന്റെ പിൽക്കാല അദ്ഭുതങ്ങൾ വിവരിക്കപ്പെടുന്നു: നൂറുകണക്കിന് ആളുകൾക്ക് അനക്കാനാവാത്ത വലിയ പാറ ഉയർത്തുന്നത്, കോപിച്ച കടലിനെ ശാന്തമാക്കുന്നത്, മറ്റു പലതും; ഭീമനായിരുന്ന കാലത്തെ ഓർമ്മകളോടെ. ഐതരേയ ഉപനിഷത്ത് വിശദീകരിക്കുമ്പോൾ ആകാശത്തുനിന്ന് പുഷ്പവൃഷ്ടി ഉണ്ടാകുന്നു, ദേവന്മാർ സ്തുതിക്കുന്നു; പിന്നെ അദ്ദേഹം വ്യാസനോടൊപ്പമിരിക്കാൻ ബദരിയിലേക്ക് പിൻവാങ്ങുന്നു; ശിഷ്യന്മാർ അദ്ദേഹത്തെയും ഹരിയെയും ആരാധിക്കുന്നു."
    },
    "sundarakanda-01": {
      "verses": {
        "0.0": "രാവണൻ അപഹരിച്ചുകൊണ്ടുപോയ സീത പാർപ്പിക്കപ്പെട്ട സ്ഥലം കണ്ടെത്താൻ ശത്രുക്കളെ ദണ്ഡിപ്പിക്കുന്ന ഹനുമാൻ തീരുമാനിച്ചു; ചാരണന്മാർ സഞ്ചരിക്കുന്ന ആകാശമാർഗ്ഗത്തിലൂടെ അദ്ദേഹം യാത്ര തിരിച്ചു.",
        "0.1": "ചെയ്യാൻ പ്രയാസമുള്ളതും അതുല്യവുമായ ഒരു കർമ്മം ചെയ്യാൻ ആഗ്രഹിച്ച്, തല ഉയർത്തിയും കഴുത്തുയർത്തിയും ആ വാനരൻ ശ്രേഷ്ഠനായ കാളയെപ്പോലെ തിളങ്ങി.",
        "0.2": "അപ്പോൾ ശക്തനും ഉറച്ച മനസ്സുള്ളവനുമായവൻ, വൈഡൂര്യംപോലെ നിറമുള്ള, വെള്ളംപോലെ തിളങ്ങുന്ന പുൽമൈതാനങ്ങളിലൂടെ സുഖമായി സഞ്ചരിച്ചു.",
        "0.3": "ബുദ്ധിമാനായ അദ്ദേഹം പക്ഷികളെ ഭയപ്പെടുത്തി, നെഞ്ചുകൊണ്ട് മരങ്ങൾ വീഴ്ത്തി, പൂർണ്ണശക്തി പ്രാപിച്ച സിംഹത്തെപ്പോലെ അനേകം മൃഗങ്ങളെ കൊന്നു.",
        "0.4": "ആ പർവതം നീല, ചുവപ്പ്, മഞ്ചട്ടിനിറമുള്ള ചുവപ്പ്, താമരനിറം, വെളുപ്പ്, കറുപ്പ് എന്നിവയായ, ശുദ്ധവും സ്വാഭാവികവുമായ ധാതുരേഖകളാൽ അലങ്കരിക്കപ്പെട്ടിരുന്നു.",
        "0.5": "രൂപം മാറ്റാൻ കഴിവുള്ള യക്ഷന്മാരും കിന്നരന്മാരും ഗന്ധർവന്മാരും ദേവതുല്യരായ മറ്റു ജീവികളും, സർപ്പങ്ങളും, അവരുടെ പരിവാരങ്ങളോടൊപ്പം അവിടെ നിരന്തരം സഞ്ചരിച്ചു.",
        "0.6": "മികച്ച ആനകൾ നിറഞ്ഞ ആ മഹാപർവതത്തിന്റെ അടിവാരത്തിൽ നിന്ന ഏറ്റവും ഉത്തമ വാനരൻ, ഒരു തടാകത്തിൽ നിൽക്കുന്ന ആനയെപ്പോലെ തോന്നി.",
        "0.7": "സൂര്യനെയും മഹേന്ദ്രനെയും വായുവിനെയും സ്വയംഭൂവായ ബ്രഹ്മാവിനെയും സർവ്വഭൂതങ്ങളെയും കൂപ്പുകൈയോടെ വണങ്ങി അദ്ദേഹം യാത്ര തിരിക്കാൻ മനസ്സുറപ്പിച്ചു.",
        "0.8": "കിഴക്കോട്ട് തിരിഞ്ഞ് തന്റെ പിതാവായ വായുവിനെ വണങ്ങി; പിന്നെ ആ സമർത്ഥൻ ദക്ഷിണദിക്കിലേക്ക് പോകാൻ ശരീരം വളർത്താൻ തുടങ്ങി.",
        "0.9": "മുഖ്യ വാനരന്മാർ നോക്കിനിൽക്കെ, കുതിച്ചുചാടാൻ തീരുമാനിച്ച അദ്ദേഹം, രാമന്റെ വിജയത്തിനായി, പൗർണ്ണമിയിലും അമാവാസിയിലും സമുദ്രം ഉയരുന്നതുപോലെ വളർന്നു.",
        "0.10": "സമുദ്രം ചാടിക്കടക്കാൻ ആഗ്രഹിച്ച്, അളവില്ലാതെ വളർന്ന ശരീരത്തോടെ, കൈകാലുകൾകൊണ്ട് അദ്ദേഹം പർവതത്തെ അമർത്തി.",
        "0.11": "വാനരന്റെ അമർത്തലിൽ പർവതം ഒരു നിമിഷം കുലുങ്ങി, അതിന്റെ മരങ്ങളുടെ പുഷ്പിച്ച അഗ്രങ്ങളിൽ നിന്ന് എല്ലാ പൂക്കളും കൊഴിഞ്ഞുവീണു.",
        "0.12": "മരങ്ങളിൽ നിന്ന് പൊഴിഞ്ഞ സുഗന്ധപുഷ്പങ്ങളുടെ കൂട്ടം മൂടിയതിനാൽ പർവതം പൂക്കൾകൊണ്ടുണ്ടാക്കിയതുപോലെ കാണപ്പെട്ടു.",
        "0.13": "ആ ഉത്തമ ശക്തനാൽ അമർത്തപ്പെട്ട പർവതം, മദമിളകിയ ആന മദജലം ഒഴുക്കുന്നതുപോലെ വെള്ളം ഒഴുക്കി.",
        "0.14": "ആ മഹാശക്തനാൽ അമർത്തപ്പെട്ട മഹേന്ദ്രപർവതം സ്വർണ്ണരേഖകളും കറുത്ത അഞ്ജനവും വെള്ളിയുടെ അയിരും ചൊരിഞ്ഞു.",
        "0.15": "ചുവന്ന ആർസനിക് രേഖകളുള്ള വലിയ പാറകളും പർവതം എറിഞ്ഞുകളഞ്ഞു; മധ്യത്തിലെ ജ്വാലയിൽ നിന്ന് പുകച്ചുരുളുകൾ ഉയരുന്ന അഗ്നിപോലെ.",
        "0.16": "വാനരൻ എല്ലാ വശത്തുനിന്നും പർവതത്തെ അമർത്തിയപ്പോൾ, അതിന്റെ ഗുഹകളിൽ വസിച്ചിരുന്ന ജീവികൾ പരുഷമായ സ്വരത്തിൽ നിലവിളിച്ചു.",
        "0.17": "പർവതം തകർക്കപ്പെട്ടതിനാൽ ഉണ്ടായ ആ ജീവികളുടെ മഹാകോലാഹലം ഭൂമിയെയും ദിക്കുകളെയും വനങ്ങളെയും നിറച്ചു.",
        "0.18": "വ്യക്തമായ സ്വസ്തികചിഹ്നങ്ങളുള്ള വിശാലമായ പത്തികളോടുകൂടിയ സർപ്പങ്ങൾ ഭയങ്കരമായ തീ തുപ്പി, കൊമ്പുകൾകൊണ്ട് പാറകൾ കടിച്ചു.",
        "0.19": "കോപവും വിഷവുമുള്ള ആ സർപ്പങ്ങളുടെ കടിയേറ്റ വലിയ പാറകൾ ജ്വലിച്ച് ആയിരം കഷണങ്ങളായി പിളർന്നു.",
        "0.20": "ആ പർവതത്തിൽ വളരുന്ന അനേകം ഔഷധസസ്യങ്ങൾ വിഷത്തിന് പ്രതിവിധിയാണെങ്കിലും, സർപ്പവിഷത്തെ നിർവീര്യമാക്കാൻ അവയ്ക്ക് കഴിഞ്ഞില്ല.",
        "0.21": "ദുരാത്മാക്കളാൽ പർവതം പിളരുകയാണെന്ന് കരുതി, ഭയന്ന വിദ്യാധരന്മാരും തപസ്വികളും തങ്ങളുടെ സ്ത്രീകളോടൊപ്പം അതിൽ നിന്ന് ആകാശത്തേക്ക് പറന്നുയർന്നു.",
        "0.22": "പാനസ്ഥലങ്ങളിൽ സ്വർണ്ണപാനപാത്രങ്ങളും വിലയേറിയ പാത്രങ്ങളും സ്വർണ്ണജലപാത്രങ്ങളും ഉപേക്ഷിച്ച്,",
        "0.23": "നക്കിത്തിന്നാനുള്ള വിവിധ രുചിവിഭവങ്ങളും, പലതരം മാംസവും, കാളത്തോൽ പരിചകളും, സ്വർണ്ണപ്പിടിയുള്ള വാളുകളും ഉപേക്ഷിച്ച്,",
        "0.24": "മദ്യലഹരിയിൽ, കഴുത്തിൽ മാലകളണിഞ്ഞ്, ചുവന്ന മാലകളും ലേപനങ്ങളും ധരിച്ച്, താമരപോലെ ചുവന്ന കണ്ണുകളോടെ അവർ ആകാശത്തേക്ക് ഉയർന്നു.",
        "0.25": "മാലയും കണങ്കാൽവളയും തോൾവളയും വളകളും ധരിച്ച അവരുടെ സ്ത്രീകൾ, കാമുകന്മാരോടൊപ്പം ആകാശത്ത് അദ്ഭുതത്തോടെയും പുഞ്ചിരിയോടെയും നിന്നു.",
        "0.26": "തങ്ങളുടെ വലിയ മായാവിദ്യ പ്രകടിപ്പിച്ച്, വിദ്യാധരന്മാരും മഹർഷിമാരും ആകാശത്ത് ഒന്നിച്ചുനിന്ന് പർവതത്തെ നോക്കി.",
        "0.27": "അപ്പോൾ, ആകാശത്ത് നിൽക്കുന്ന ശുദ്ധമനസ്സുള്ള മഹർഷിമാരുടെയും ചാരണന്മാരുടെയും സിദ്ധന്മാരുടെയും വാക്കുകൾ അവർ കേട്ടു:",
        "0.28": "“പർവതംപോലെ വലിയവനും അതിവേഗമുള്ളവനുമായ ഈ വായുപുത്രൻ ഹനുമാൻ, വരുണന്റെ വാസസ്ഥലമായ സമുദ്രം കടക്കാൻ ആഗ്രഹിക്കുന്നു.",
        "0.29": "രാമന്റെയും വാനരന്മാരുടെയും കാര്യത്തിനായി ദുഷ്കരമായ ഒരു കർമ്മം ചെയ്യാൻ ആഗ്രഹിച്ച്, പ്രയാസത്തോടെ മാത്രം എത്താവുന്ന സമുദ്രത്തിന്റെ അക്കരെ എത്താൻ അവൻ ശ്രമിക്കുന്നു.”",
        "0.30": "തപസ്വികളുടെ ഈ വാക്കുകൾ കേട്ട വിദ്യാധരന്മാർ, പർവതത്തിനുമുകളിൽ വാനരന്മാരിൽ അളവില്ലാത്ത ആ കാളയെ കണ്ടു.",
        "0.31": "സ്വയം ഒരു പർവതംപോലെ അദ്ദേഹം മുടി കുടഞ്ഞു, ശരീരം വിറപ്പിച്ചു, ശക്തനായ മഴമേഘംപോലെ ഒരു മഹാഗർജ്ജനം മുഴക്കി.",
        "0.32": "ചാടാൻ തുടങ്ങിയപ്പോൾ, പക്ഷിരാജാവായ ഗരുഡൻ സർപ്പത്തെ എറിയുന്നതുപോലെ, വൃത്താകൃതിയുള്ള, രോമാവൃതമായ, ക്രമമായി ചുരുങ്ങുന്ന തന്റെ വാൽ അദ്ദേഹം ചുഴറ്റി.",
        "0.33": "വേഗമുള്ളവന്റെ പുറത്ത് പിന്നിലേക്ക് ചുരുണ്ട അവന്റെ വാൽ, ഗരുഡൻ കൊണ്ടുപോകുന്ന ഒരു വലിയ സർപ്പംപോലെ കാണപ്പെട്ടു.",
        "0.34": "വാനരൻ വലിയ ഇരുമ്പുദണ്ഡുകൾപോലുള്ള തന്റെ ബാഹുക്കളെ ഉറപ്പിച്ചു, അരക്കെട്ട് മുറുക്കി, പാദങ്ങൾ ഉള്ളിലേക്ക് വലിച്ചു.",
        "0.35": "ബാഹുക്കളും കഴുത്തും ഒതുക്കി, മഹിമയുള്ള വീരൻ തന്റെ ഊർജ്ജവും ബലവും പരാക്രമവും ഒരുമിച്ചു വിളിച്ചുകൂട്ടി.",
        "0.36": "തന്റെ വഴിയിൽ ദൂരെ നോക്കി, കണ്ണുകൾ ആകാശത്തേക്ക് ഉറപ്പിച്ച്, ഹൃദയത്തിൽ ശ്വാസം അടക്കിനിർത്തി.",
        "0.37": "കാലുകൾ ഉറപ്പിച്ചു നിർത്തി, ചെവികൾ പിന്നോട്ട് മടക്കി, കുതിച്ചുയരാൻ ഒരുങ്ങിയ വാനരഗജൻ ഹനുമാൻ,",
        "0.38": "വാനരശ്രേഷ്ഠനായ അദ്ദേഹം വാനരന്മാരോട് ഈ വാക്കുകൾ പറഞ്ഞു: “രാഘവൻ അയച്ച ബാണം കാറ്റിന്റെ വേഗത്തിൽ പായുന്നതുപോലെ,",
        "0.39": "രാവണൻ ഭരിക്കുന്ന ലങ്കയിലേക്ക് ഞാൻ പോകും. ജനകപുത്രിയെ ലങ്കയിൽ കണ്ടെത്തിയില്ലെങ്കിൽ,",
        "0.40": "അതേ വേഗത്തിൽ ഞാൻ ദേവന്മാരുടെ ലോകത്തേക്ക് പോകും; എന്റെ എല്ലാ പരിശ്രമത്തിനു ശേഷവും സ്വർഗ്ഗത്തിലും സീതയെ കണ്ടെത്തിയില്ലെങ്കിൽ,",
        "0.41": "രാക്ഷസരാജാവായ രാവണനെ ബന്ധിച്ച് ഇവിടെ കൊണ്ടുവരും. എല്ലാവിധത്തിലും ഞാൻ സീതയോടൊപ്പം വിജയിച്ചു മടങ്ങും;",
        "0.42": "അല്ലെങ്കിൽ രാവണനോടൊപ്പം ലങ്കയെത്തന്നെ പിഴുതെടുത്ത് കൊണ്ടുവരും.” ഇങ്ങനെ പറഞ്ഞ്, വാനരശ്രേഷ്ഠനായ ഹനുമാൻ,",
        "0.43": "വേഗമുള്ളവൻ, സംശയമില്ലാതെ വലിയ വേഗത്തോടെ കുതിച്ചുയർന്നു; ആ വാനരഗജൻ തന്നെ സുപർണ്ണനായ (ഗരുഡൻ) ആണെന്ന് കരുതി.",
        "0.44": "ശക്തിയോടെ കുതിച്ചുയർന്നപ്പോൾ, പർവതത്തിൽ വളർന്ന മരങ്ങൾ അദ്ദേഹത്തിന്റെ വേഗതയാൽ വലിക്കപ്പെട്ട്, ശാഖകൾ ഒതുക്കി, അദ്ദേഹത്തോടൊപ്പം ചുറ്റും പറന്നുയർന്നു.",
        "0.45": "തുടയുടെ ശക്തിയോടെ, ആവേശഭരിതരായ കുരുവികൾ നിറഞ്ഞ പൂക്കളുള്ള മരങ്ങളെ വഹിച്ചുകൊണ്ട് അദ്ദേഹം തെളിഞ്ഞ ആകാശത്തിലൂടെ മുന്നോട്ടു പോയി.",
        "0.46": "തുടയുടെ ശക്തിയാൽ ഉയർത്തപ്പെട്ട മരങ്ങൾ, ദൂരയാത്ര പുറപ്പെടുന്ന പ്രിയനെ ബന്ധുക്കൾ അനുഗമിക്കുന്നതുപോലെ, കുറച്ചുനേരം വാനരനെ പിന്തുടർന്നു.",
        "0.47": "തുടയുടെ ശക്തിയാൽ പിഴുതെടുക്കപ്പെട്ട സാലവൃക്ഷങ്ങളും മറ്റു മനോഹരമായ മരങ്ങളും, സൈനികർ രാജാവിനെ പിന്തുടരുന്നതുപോലെ ഹനുമാനെ അനുഗമിച്ചു.",
        "0.48": "പൂത്തുനിൽക്കുന്ന മുകുളങ്ങളുള്ള അനേകം മരങ്ങളോടൊപ്പം പർവതംപോലെ ഉയർന്ന ഹനുമാൻ അദ്ഭുതകരമായ കാഴ്ചയായിരുന്നു.",
        "0.49": "ഭാരമേറിയ മരങ്ങൾ ഉപ്പുവെള്ളമുള്ള കടലിൽ മുങ്ങി; മഹേന്ദ്രനെ ഭയന്ന് വരുണന്റെ ലോകത്ത് മുങ്ങിയ ചിറകുള്ള പർവതങ്ങളെപ്പോലെ.",
        "0.50": "അനേകം പൂക്കളും മുകുളങ്ങളും തളിരുകളും വിതറി, മിന്നാമിനുങ്ങുകൾ തിളങ്ങുന്ന പർവതംപോലെ മേഘസദൃശനായ വാനരൻ പ്രകാശിച്ചു.",
        "0.51": "വേഗത്താൽ മോചിതരായ മരങ്ങൾ പൂക്കൾ പൊഴിച്ച് വെള്ളത്തിൽ വീണു; യാത്രയയപ്പിനുശേഷം തിരിച്ചുപോകുന്ന സുഹൃത്തുക്കളെപ്പോലെ.",
        "0.52": "വാനരന്റെ കാറ്റിൽ ഇളകി, മരങ്ങളുടെ ഭാരം കുറഞ്ഞ വർണ്ണശബളമായ പൂക്കൾ കടലിൽ വീണു; നക്ഷത്രങ്ങൾ വിതറിയ ആകാശംപോലെ മഹാസമുദ്രം തിളങ്ങി.",
        "0.53": "പലനിറങ്ങളിലുള്ള സുഗന്ധപുഷ്പങ്ങളാൽ മൂടപ്പെട്ട വാനരൻ, മിന്നൽപ്പിണരുകളാൽ അലങ്കരിച്ച ഉയർന്നുവരുന്ന മേഘംപോലെ കാണപ്പെട്ടു.",
        "0.54": "അദ്ദേഹത്തിന്റെ വേഗത്താൽ ഇളകിയ പൂക്കളാൽ മൂടപ്പെട്ട വെള്ളം, ഉയർന്നുവന്ന മനോഹരനക്ഷത്രങ്ങളോടു കൂടിയ ആകാശംപോലെ തോന്നി.",
        "0.55": "ആകാശത്ത് നീട്ടിയ അദ്ദേഹത്തിന്റെ ബാഹുക്കൾ, പർവതശിഖരത്തിൽ നിന്ന് പുറത്തുവരുന്ന രണ്ടു പഞ്ചഫണ സർപ്പങ്ങൾപോലെ തോന്നി.",
        "0.56": "ആ മഹാവാനരൻ, തിരമാലകളിളകുന്ന സമുദ്രത്തെ കുടിച്ചുവറ്റിക്കുന്നതുപോലെയും, ആകാശത്തെ കുടിക്കാൻ ദാഹിക്കുന്നതുപോലെയും തോന്നി.",
        "0.57": "വായുവിന്റെ പാത പിന്തുടരുമ്പോൾ, മിന്നൽപോലെ തിളങ്ങുന്ന അദ്ദേഹത്തിന്റെ കണ്ണുകൾ, പർവതത്തിലെ രണ്ടു തീജ്വാലകൾപോലെ ജ്വലിച്ചു.",
        "0.58": "മഞ്ഞനിറമുള്ളവരിൽ ശ്രേഷ്ഠന്റെ വലുതും വൃത്താകൃതിയുള്ളതും ചെമ്പുനിറമുള്ളതുമായ കണ്ണുകൾ, ഉദിച്ചുനിൽക്കുന്ന ചന്ദ്രനും സൂര്യനും ഒരുമിച്ച് തിളങ്ങുന്നതുപോലെ പ്രകാശിച്ചു.",
        "0.59": "ചെമ്പുപോലുള്ള മൂക്കുള്ള അദ്ദേഹത്തിന്റെ മുഖം, സന്ധ്യാവേളയിൽ തൊട്ട സൂര്യബിംബംപോലെ ചുവന്ന് തിളങ്ങി.",
        "0.60": "ആകാശത്തിലൂടെ പറക്കുമ്പോൾ വായുപുത്രന്റെ ചുരുണ്ട വാൽ, ഉയർത്തിപ്പിടിച്ച ഇന്ദ്രന്റെ കൊടിപോലെ തിളങ്ങി.",
        "0.61": "വൃത്താകൃതിയിൽ ചുരുണ്ട വാലും വെളുത്ത പല്ലുകളുമായി, പ്രഭാവലയമുള്ള സൂര്യനെപ്പോലെ വായുപുത്രനായ ആ ബുദ്ധിമാൻ തിളങ്ങി.",
        "0.62": "ആഴത്തിൽ ചുവന്ന പിൻഭാഗങ്ങളോടെ ആ മഹാവാനരൻ, ചുവന്ന മഞ്ചട്ടിയുടെ ഒരു വലിയ ഞരമ്പ് കാണിച്ചു പിളർന്ന പർവതംപോലെ തിളങ്ങി.",
        "0.63": "സമുദ്രത്തിനു മുകളിലൂടെ പറക്കുമ്പോൾ, വാനരസിംഹത്തിന്റെ കക്ഷങ്ങളിൽ കുടുങ്ങിയ കാറ്റ് ഇടിമുഴക്കംപോലെ ഗർജ്ജിച്ചു.",
        "0.64": "വടക്കുനിന്ന് വീഴുന്ന ഉൽക്ക അതിന്റെ വാലോടെ കാണുന്നതുപോലെ, ആ വാനരഗജൻ കാണപ്പെട്ടു.",
        "0.65": "സൂര്യൻ അതിന്റെ പഥത്തിൽ നീണ്ടുനിൽക്കുന്നതുപോലെ നീട്ടി, അരഞ്ഞാണം കെട്ടി ബന്ധിക്കപ്പെടുന്ന വലിയ ആനപോലെ വാനരൻ തിളങ്ങി.",
        "0.66": "ശരീരം മുകളിലും നിഴൽ താഴെ സമുദ്രത്തിൽ മുങ്ങിയും, വാനരൻ കാറ്റാൽ നയിക്കപ്പെടുന്ന കപ്പൽപോലെ തോന്നി.",
        "0.67": "മഹാവാനരൻ കടന്നുപോയ സമുദ്രത്തിന്റെ ഏതു ഭാഗവും, അദ്ദേഹത്തിന്റെ ശരീരത്തിന്റെ ശക്തിയാൽ ഭ്രാന്തുപിടിച്ചതുപോലെ തോന്നി.",
        "0.68": "പർവതസമാനമായ തിരമാലക്കൂട്ടങ്ങളെ നെഞ്ചുകൊണ്ട് അടിച്ചുകൊണ്ട്, വേഗമേറിയ മഹാവാനരൻ മുന്നോട്ടു കുതിച്ചു.",
        "0.69": "വാനരൻ ഉയർത്തിയ മഹാവായുവും മേഘങ്ങളിൽ നിന്നുള്ള കാറ്റും ഒന്നിച്ച്, ഭയങ്കരമായി ഗർജ്ജിക്കുന്ന സമുദ്രത്തെ ശക്തമായി ഇളക്കി.",
        "0.70": "ഉപ്പുവെള്ളമുള്ള സമുദ്രത്തിലെ വലിയ തിരമാലകളെ വലിച്ചുകൊണ്ട്, വാനരവ്യാഘ്രം ആകാശവും ഭൂമിയും വേർപെടുത്തുന്നതുപോലെ പറന്നു.",
        "0.71": "മേരുവും മന്ദരവും പോലെ മഹാസമുദ്രത്തിൽ ഉയർന്ന തിരമാലകളെ, എണ്ണുന്നതുപോലെ, വേഗമേറിയവൻ കടന്നുപോയി.",
        "0.72": "അദ്ദേഹത്തിന്റെ വേഗത്താൽ ഉയർത്തപ്പെട്ട വെള്ളം മേഘങ്ങളെ തൊട്ട്, ആകാശത്ത് തൂങ്ങിക്കിടന്ന്, വ്യാപിക്കുന്ന ശരത്കാലമേഘങ്ങൾ പോലെ തിളങ്ങി.",
        "0.73": "തിമിംഗലങ്ങളും മുതലകളും മീനുകളും ആമകളും വസ്ത്രം വലിച്ചുമാറ്റപ്പെട്ട മനുഷ്യശരീരങ്ങൾപോലെ പുറത്ത് കിടന്നു.",
        "0.74": "ആകാശത്ത് കുതിച്ചുപായുന്ന വാനരവ്യാഘ്രത്തെ കണ്ട കടൽസർപ്പങ്ങൾ അദ്ദേഹത്തെ സുപർണ്ണനായ (ഗരുഡൻ) എന്ന് കരുതി.",
        "0.75": "പത്തു യോജന വീതിയും മുപ്പതു യോജന നീളവുമുള്ള വാനരസിംഹത്തിന്റെ നിഴൽ, അദ്ദേഹത്തിന്റെ വേഗത്താൽ കൂടുതൽ മനോഹരമായി.",
        "0.76": "വായുപുത്രനെ പിന്തുടർന്ന്, ഉപ്പുവെള്ളമുള്ള കടലിൽ വീണ ആ നിഴൽ, ഇടതൂർന്ന വെളുത്ത മേഘങ്ങളുടെ നിര പോലെ തിളങ്ങി.",
        "0.77": "പ്രകാശമുള്ള, വലിയ ശരീരമുള്ള മഹാവാനരൻ, ചിറകുള്ള പർവതംപോലെ വായുവിന്റെ താങ്ങില്ലാത്ത പാതയിൽ തിളങ്ങി.",
        "0.78": "ശക്തനായ ആനയായ വാനരൻ ഏതു വഴിയിലൂടെ പാഞ്ഞുപോയാലും, അവിടത്തെ സമുദ്രം പെട്ടെന്ന് ഒരു കുഴിപോലെ പൊള്ളയായതുപോലെ തോന്നി.",
        "0.79": "പക്ഷികളുടെ പറക്കുന്ന പാതയിൽ പക്ഷിരാജാവിനെപ്പോലെ നീങ്ങിയ ഹനുമാൻ, കാറ്റ് എന്നപോലെ മേഘക്കൂട്ടങ്ങളെ തന്നോടൊപ്പം വലിച്ചുകൊണ്ടുപോയി.",
        "0.80": "വാനരൻ വലിച്ചുകൊണ്ടുപോയ വലിയ മേഘങ്ങൾ — വെള്ള, റോസ്, നീല, ചുവപ്പ് — ശോഭയോടെ തിളങ്ങി.",
        "0.81": "മേഘക്കൂട്ടങ്ങളിൽ കയറിയും വീണ്ടും വീണ്ടും പുറത്തുവന്നും, ചന്ദ്രനെപ്പോലെ ഒളിച്ചും തെളിഞ്ഞും അദ്ദേഹം കാണപ്പെട്ടു.",
        "0.82": "വേഗത്തിൽ പറക്കുന്ന ആ വാനരനെ കണ്ട ദേവന്മാരും ഗന്ധർവന്മാരും ചാരണന്മാരും അദ്ദേഹത്തിന്റെ മേൽ പുഷ്പവൃഷ്ടി ചൊരിഞ്ഞു.",
        "0.83": "പറക്കുമ്പോൾ സൂര്യൻ ആ വാനരനാഥനെ ചുട്ടില്ല; രാമന്റെ ദൗത്യത്തിന്റെ വിജയത്തിനായി കാറ്റും അദ്ദേഹത്തെ സഹായിച്ചു.",
        "0.84": "ആകാശത്തിലൂടെ പറക്കുമ്പോൾ മഹർഷിമാർ അദ്ദേഹത്തെ സ്തുതിച്ചു; ദേവന്മാരും ഗന്ധർവന്മാരും വനവാസിയെ പ്രകീർത്തിച്ചു പാടി.",
        "0.85": "ക്ഷീണം പെട്ടെന്ന് അകന്ന ആ ഉത്തമവാനരനെ കണ്ട നാഗന്മാരും യക്ഷന്മാരും വിവിധ രാക്ഷസരും എല്ലാവരും അദ്ദേഹത്തെ സ്തുതിച്ചു.",
        "0.86": "ആകാശത്തിലൂടെ വാനരവ്യാഘ്രമായ ഹനുമാൻ പറന്നപ്പോൾ, ഇക്ഷ്വാകുവംശത്തെ ബഹുമാനിക്കാൻ ആഗ്രഹിച്ച സമുദ്രം ആലോചിച്ചു:",
        "0.87": "“വാനരപ്രഭുവായ ഹനുമാനെ ഞാൻ സഹായിച്ചില്ലെങ്കിൽ, അതേക്കുറിച്ച് സംസാരിക്കുന്ന എല്ലാവരും എന്നെ കുറ്റപ്പെടുത്തും.",
        "0.88": "ഇക്ഷ്വാകു വംശത്തിലെ പ്രഭുവായ സഗരനാൽ ഞാൻ മഹത്വം നേടി; ഇവൻ ഇക്ഷ്വാകുക്കളുടെ സഹായിയാണ്; അതിനാൽ ഇവനെ ക്ഷീണിക്കാൻ അനുവദിക്കരുത്.",
        "0.89": "വാനരന് വിശ്രമിക്കാൻ ഞാൻ ഏർപ്പാട് ചെയ്യണം; എന്റെ മുകളിൽ വിശ്രമിച്ചാൽ ശേഷിച്ച ദൂരം അവൻ സന്തോഷത്തോടെ താണ്ടും.”",
        "0.90": "ഈ നല്ല തീരുമാനമെടുത്ത്, സമുദ്രം തന്റെ ജലത്തിൽ ഒളിച്ചിരിക്കുന്ന, സ്വർണ്ണഹൃദയമുള്ള ഉത്തമ പർവതമായ മൈനാകത്തോട് സംസാരിച്ചു.",
        "0.91": "“പാതാളത്തിൽ വസിക്കുന്ന അസുരസേനകൾക്കെതിരെ തടസ്സമായി മഹാദേവന്മാരുടെ രാജാവ് നിന്നെ ഇവിടെ സ്ഥാപിച്ചു.",
        "0.92": "അളവില്ലാത്ത പാതാളത്തിന്റെ കവാടം കാക്കുന്നവനായി, പ്രസിദ്ധമായ ശക്തിയുള്ള ആ അസുരന്മാർ വീണ്ടും ഉയരാതിരിക്കാൻ നീ നിൽക്കുന്നു.",
        "0.93": "പർവതമേ, നിനക്ക് വശങ്ങളിലേക്കും മുകളിലേക്കും താഴേക്കും വളരാനുള്ള ശക്തിയുണ്ട്; അതിനാൽ ഞാൻ നിന്നോട് അപേക്ഷിക്കുന്നു: ഉയരൂ, പർവതശ്രേഷ്ഠാ!",
        "0.94": "രാമന്റെ ദൗത്യത്തിൽ ഉറച്ച, ഭയങ്കരകർമ്മങ്ങളുള്ള ആ ധീരനായ വാനരവ്യാഘ്രം ഹനുമാൻ ആകാശത്ത് ഉയർന്ന് നിനക്കു മുകളിലൂടെ വരുന്നു.",
        "0.95": "അദ്ദേഹം ഇക്ഷ്വാകു വംശത്തെ സേവിക്കുന്നതിനാൽ ഞാൻ സഹായിക്കണം. ഇക്ഷ്വാകുക്കൾ എന്റെ ആരാധനയ്ക്കു യോഗ്യരാണ്; നിനക്കും അവർ അത്യന്തം ആദരണീയരാണ്.",
        "0.96": "ഞങ്ങൾക്ക് നിന്റെ സഹായം നൽകൂ, അങ്ങനെ ഞങ്ങളുടെ കടമ മുടങ്ങാതിരിക്കട്ടെ; ചെയ്യാതെ വിട്ട കടമ സജ്ജനങ്ങളുടെ അപ്രീതി ഉണർത്തും.",
        "0.97": "വെള്ളത്തിന് മുകളിൽ ഉയരൂ; ഈ വാനരൻ നിന്റെ മുകളിൽ വിശ്രമിക്കട്ടെ; ചാടുന്നവരിൽ ഉത്തമനായ ഇവൻ ഞങ്ങളുടെ അതിഥിയും ആദരിക്കപ്പെടേണ്ടവനുമാണ്.",
        "0.98": "ദേവന്മാരും ഗന്ധർവന്മാരും സേവിക്കുന്ന, വലിയ സ്വർണ്ണഹൃദയമുള്ളവനേ! നിന്റെ മുകളിൽ വിശ്രമിച്ചശേഷം ഹനുമാൻ ശേഷിച്ച വഴി താണ്ടും.",
        "0.99": "കകുൽസ്ഥന്റെ (രാമന്റെ) കാരുണ്യവും മൈഥിലിയുടെ (സീതയുടെ) പ്രവാസവും വാനരപ്രഭുവിന്റെ പ്രയത്നവും പരിഗണിച്ച്, നീ ഉയരണം.”",
        "0.100": "ഉപ്പുവെള്ളമുള്ള സമുദ്രത്തിന്റെ വാക്കുകൾ കേട്ട്, വലിയ മരങ്ങളും വള്ളികളും മൂടിയ സ്വർണ്ണഹൃദയമുള്ള മൈനാകം വേഗത്തിൽ വെള്ളത്തിൽ നിന്ന് ഉയർന്നു.",
        "0.101": "സമുദ്രജലം പിളർത്തി, ജ്വലിക്കുന്ന സൂര്യൻ മഴമേഘത്തെ പിളർക്കുന്നതുപോലെ, അദ്ദേഹം വളരെ ഉയരത്തിൽ ഉയർന്നു.",
        "0.102": "ഒരു നിമിഷത്തിനുള്ളിൽ, വെള്ളത്താൽ മൂടപ്പെട്ടിരുന്ന ആ മഹാപർവതം സമുദ്രം കൽപ്പിച്ചതുപോലെ തന്റെ ശിഖരങ്ങൾ കാണിച്ചു.",
        "0.103": "കിന്നരന്മാരും മഹാസർപ്പങ്ങളും വസിക്കുന്ന അതിന്റെ സ്വർണ്ണശിഖരങ്ങൾ, ഉദിക്കുന്ന സൂര്യനെപ്പോലെ തിളങ്ങി, ആകാശത്തെ തൊടുന്നതുപോലെ തോന്നി.",
        "0.104": "ഉയർന്നുവന്ന പർവതത്തിന്റെ സ്വർണ്ണശിഖരങ്ങളാൽ, വാൾപോലെ ഇരുണ്ടിരുന്ന ആകാശം സ്വർണ്ണപ്രഭ കൈവരിച്ചു.",
        "0.105": "തിളങ്ങുന്ന, ദീപ്തമായ സ്വർണ്ണശിഖരങ്ങളോടെ ആ ഉത്തമപർവതം നൂറു സൂര്യന്മാരെപ്പോലെ തോന്നി.",
        "0.106": "ഉപ്പുവെള്ളമുള്ള കടലിന്റെ നടുവിൽ മുന്നിൽ പെട്ടെന്ന് ഉയർന്ന അതിനെ കണ്ട ഹനുമാൻ, “ഇതാണ് ഒരു തടസ്സം” എന്ന് നിശ്ചയിച്ചു.",
        "0.107": "വേഗമുള്ള മഹാവാനരൻ, കാറ്റ് മേഘത്തെ ഓടിക്കുന്നതുപോലെ, ആ ഉയർന്നുനിൽക്കുന്ന പർവതത്തെ നെഞ്ചുകൊണ്ട് ഇടിച്ചുതള്ളി.",
        "0.108": "വാനരൻ തള്ളിയപ്പോൾ മഹാപർവതം അദ്ദേഹത്തിന്റെ വേഗം മനസ്സിലാക്കി, സന്തോഷിച്ച് ആർത്തുവിളിച്ചു.",
        "0.109": "വീരന്റെ അരികിൽ ആകാശത്തേക്ക് ഉയർന്ന പർവതം, സന്തോഷത്തോടെയും ആഹ്ലാദത്തോടെയും വാനരനോട് സംസാരിച്ചു.",
        "0.110": "മനുഷ്യരൂപമെടുത്ത് സ്വന്തം ശിഖരത്തിൽ നിന്ന് അദ്ദേഹം പറഞ്ഞു: “ഹേ വാനരശ്രേഷ്ഠാ, നീ ഈ ദുഷ്കരകർമ്മം സാധിച്ചിരിക്കുന്നു.",
        "0.111": "എന്റെ ശിഖരങ്ങളിൽ ഇറങ്ങി സുഖമായി വിശ്രമിക്കൂ; പിന്നീട് യാത്ര തുടരൂ. രാഘവവംശത്തിൽ ജനിച്ചവരാൽ സമുദ്രം വലുതാക്കപ്പെട്ടിട്ടുണ്ട്.",
        "0.112": "അതിനാൽ, രാമന്റെ ക്ഷേമത്തിൽ വ്യാപൃതനായ നിന്നെ സമുദ്രം പ്രത്യുപകാരമായി ആദരിക്കുന്നു; ചെയ്ത ഉപകാരത്തിന് തിരിച്ചുപകരം നൽകുന്നത് ശാശ്വത ധർമ്മമാണ്.",
        "0.113": "ആ ഉപകാരത്തിന് പകരം നൽകാൻ ആഗ്രഹിച്ച്, അദ്ദേഹം നിന്നിൽ നിന്ന് ആദരത്തിന് അർഹനാണ്; നിന്റെ പേരിൽ വലിയ ബഹുമാനത്തോടെ അദ്ദേഹം എന്നെ മുന്നോട്ട് പ്രേരിപ്പിച്ചു.",
        "0.114": "അദ്ദേഹം പറഞ്ഞു: ‘നൂറു യോജന താണ്ടാൻ ഈ വാനരൻ ആകാശത്തേക്ക് ചാടിയിരിക്കുന്നു; നിന്റെ ചരിവുകളിൽ അവൻ വിശ്രമിച്ച്, പിന്നീട് ശേഷിച്ച വഴി പോകട്ടെ.’",
        "0.115": "വാനരശ്രേഷ്ഠാ, നിൽക്കൂ; എന്റെ മുകളിൽ വിശ്രമിച്ച് പോകൂ. ഇവിടെ സുഗന്ധവും മധുരവുമുള്ള വേരുകളും കിഴങ്ങുകളും പഴങ്ങളും ധാരാളമുണ്ട്.",
        "0.116": "വാനരശ്രേഷ്ഠാ, അവ രുചിച്ച് ഉന്മേഷത്തോടെ പോകൂ. മൂന്നു ലോകങ്ങളിൽ പ്രസിദ്ധനും ഗുണസമ്പന്നനുമായ നിന്നോടും ഞങ്ങൾക്ക് ഒരു ബന്ധമുണ്ട്.",
        "0.117": "വായുപുത്രാ, കുതിച്ചുചാടുന്ന വാനരന്മാരിൽ എല്ലാവരിലും നിന്നെയാണ് ഞാൻ ഉത്തമനായി കാണുന്നത്, വാനരഗജാ.",
        "0.118": "ധർമ്മം അറിയാൻ ആഗ്രഹിക്കുന്നവന് ഒരു സാധാരണ അതിഥിപോലും ആദരവ് അർഹിക്കുന്നു; നിന്നെപ്പോലെയുള്ളവന് പിന്നെ എത്രയധികം!",
        "0.119": "മഹാത്മാവായ വായുവിന്റെ പുത്രനും ദേവന്മാരിൽ ശ്രേഷ്ഠനും അദ്ദേഹത്തിന് തുല്യവേഗമുള്ളവനുമാണ് നീ, വാനരഗജാ.",
        "0.120": "ധർമ്മജ്ഞനായ നീ ആദരിക്കപ്പെടുമ്പോൾ വായു ആദരിക്കപ്പെടുന്നു; അതിനാൽ നീ എന്റെ ആരാധനയ്ക്ക് യോഗ്യനാണ്. കാരണം കേൾക്കൂ.",
        "0.121": "പ്രിയനേ, പണ്ട് കൃതയുഗത്തിൽ പർവതങ്ങൾക്ക് ചിറകുണ്ടായിരുന്നു; ഗരുഡനെപ്പോലെ വേഗത്തിൽ അവ എല്ലാ ദിക്കുകളിലേക്കും പറന്നു.",
        "0.122": "അവ പറന്നുനടക്കുമ്പോൾ, ദേവസംഘങ്ങളും മഹർഷിമാരും എല്ലാ ജീവികളും തങ്ങളുടെ മേൽ വീഴുമെന്ന് ഭയന്നു.",
        "0.123": "അപ്പോൾ ആയിരം കണ്ണുള്ള ശതക്രതു (ഇന്ദ്രൻ) കോപിച്ച്, വജ്രംകൊണ്ട് ആ പർവതങ്ങളുടെ ചിറകുകൾ ലക്ഷക്കണക്കിന് മുറിച്ചുകളഞ്ഞു.",
        "0.124": "കോപാകുലനായ ദേവനാഥൻ, വജ്രം ഉയർത്തി എന്റെ നേരെ വന്നു; പെട്ടെന്ന് മഹാത്മാവായ വായു എന്നെ ദൂരെ എറിഞ്ഞു.",
        "0.125": "ഉത്തമവാനരാ, ഈ ഉപ്പുവെള്ള സമുദ്രത്തിൽ എറിയപ്പെട്ട ഞാൻ, ചിറകുകൾ അക്ഷതമായി, നിന്റെ പിതാവിനാൽ സംരക്ഷിക്കപ്പെട്ട് സമ്പൂർണ്ണനായി നിലനിന്നു.",
        "0.126": "അതിനാൽ ഞാൻ നിന്നെ ആദരിക്കുന്നു; നിന്റെ വിലയിൽ എന്നിൽ നിന്ന് ബഹുമാനത്തിന് നീ അർഹനാണ്, വായുപുത്രാ. ഇതാണ് വാനരശ്രേഷ്ഠാ, നിന്നോടുള്ള എന്റെ ബന്ധം — വലിയ മൂല്യമുള്ള ഒരു ബന്ധം.",
        "0.127": "ഇപ്പോൾ ഈ അവസരം വന്നിരിക്കുന്നു; ജ്ഞാനിയേ, സമുദ്രത്തിനും എനിക്കും നീ സന്തോഷം നൽകണം.",
        "0.128": "നിന്റെ ക്ഷീണം നീക്കി, ഞങ്ങളുടെ ആതിഥ്യം സ്വീകരിക്കൂ, വാനരശ്രേഷ്ഠാ; എന്റെ സ്നേഹവും സ്വീകരിക്കൂ; നിന്നെ കാണുന്നതിൽ ഞാൻ സന്തുഷ്ടനാണ്.",
        "0.129": "ഇങ്ങനെ പറയപ്പെട്ടപ്പോൾ, വാനരശ്രേഷ്ഠൻ ആ ഉത്തമപർവതത്തോടു പറഞ്ഞു: “ഞാൻ സന്തുഷ്ടനാണ്; നിന്റെ ആതിഥ്യം പൂർണ്ണമായി സ്വീകരിച്ചിരിക്കുന്നു. ഒരു വിദ്വേഷവും അവശേഷിക്കരുത്.",
        "0.130": "എന്റെ ദൗത്യത്തിന്റെ സമയം അടുത്തു, ദിവസം കടന്നുപോകുന്നു; വഴിയിൽ നിൽക്കില്ലെന്ന് ഞാൻ പ്രതിജ്ഞ ചെയ്തിട്ടുണ്ട്.”",
        "0.131": "ഇങ്ങനെ പറഞ്ഞ്, വാനരകാളയായ അദ്ദേഹം കൈകൊണ്ട് പർവതത്തെ തൊട്ടു; പുഞ്ചിരിക്കുന്നതുപോലെ ആകാശത്തേക്ക് ഉയർന്ന് യാത്ര തുടർന്നു.",
        "0.132": "പർവതവും മഹാസമുദ്രവും വലിയ ആദരവോടെ അദ്ദേഹത്തെ നോക്കി; യോജിച്ച അനുഗ്രഹങ്ങളോടെ അദ്ദേഹം ആദരിക്കപ്പെടുകയും അഭിവാദനം ചെയ്യപ്പെടുകയും ചെയ്തു.",
        "0.133": "പിന്നെ, വളരെ ഉയരത്തിൽ പോയി, പർവതത്തെയും മഹാസമുദ്രത്തെയും പിന്നിലാക്കി, തന്റെ പിതാവിന്റെ പാത പിന്തുടർന്ന് തെളിഞ്ഞ ആകാശത്തിലൂടെ മുന്നോട്ടു പോയി.",
        "0.134": "കൂടുതൽ ഉയർന്നുപോയി പർവതത്തെ തിരിഞ്ഞുനോക്കി, താങ്ങില്ലാതെ വായുപുത്രൻ മുന്നോട്ടു പോയി.",
        "0.135": "ഹനുമാന്റെ ഈ രണ്ടാമത്തെ അതിദുഷ്കരമായ കർമ്മം കണ്ട്, എല്ലാ ദേവന്മാരും സിദ്ധന്മാരും മഹർഷിമാരും അദ്ദേഹത്തെ സ്തുതിച്ചു.",
        "0.136": "സ്വർണ്ണഹൃദയമുള്ള സുനഭന്റെ (മൈനാകത്തിന്റെ) പ്രവൃത്തിയിൽ അവിടെയുണ്ടായിരുന്ന ദേവന്മാർ സന്തോഷിച്ചു; ആയിരം കണ്ണുള്ള വാസവനും (ഇന്ദ്രൻ) സന്തോഷിച്ചു.",
        "0.137": "ശചിയുടെ നാഥനായ ആ ജ്ഞാനി തന്നെ സന്തോഷം മൂലം, വികാരത്താൽ ഇടറിയ സ്വരത്തിൽ പർവതശ്രേഷ്ഠനായ സുനഭനോട് പറഞ്ഞു:",
        "0.138": "“ഹിരണ്യനാഭാ, പർവതങ്ങളുടെ നാഥാ, നിന്നിൽ ഞാൻ വളരെ സന്തുഷ്ടനാണ്. ഭയത്തിൽ നിന്ന് ഞാൻ നിനക്ക് മോചനം നൽകുന്നു; സൗമ്യനേ, നിനക്ക് ഇഷ്ടമുള്ളിടത്തേക്ക് പോകാം.",
        "0.139": "ഭയം നിറഞ്ഞ നൂറു യോജന ധൈര്യത്തോടെ കടക്കുന്ന ധീരനായ ഹനുമാനെ നീ വലിയ സഹായം ചെയ്തു.",
        "0.140": "ഈ വാനരൻ ദശരഥപുത്രനായ രാമന്റെ നന്മയ്ക്കു മാത്രമാണ് പോകുന്നത്; നിനക്ക് കഴിയുംവിധം അവനെ ആദരിച്ചതിലൂടെ നീ എന്നെ യഥാർത്ഥത്തിൽ സന്തോഷിപ്പിച്ചിരിക്കുന്നു.”",
        "0.141": "ദേവന്മാരുടെ നാഥനായ ശതക്രതു ഇങ്ങനെ സന്തുഷ്ടനായതു കണ്ട്, ആ മഹാപർവതം വലിയ ആനന്ദം അനുഭവിച്ചു.",
        "0.142": "ആ വരം ലഭിച്ചശേഷം പർവതം അവിടെത്തന്നെ നിലനിന്നു; ഹനുമാൻ ഒരു നിമിഷംകൊണ്ട് ആ സമുദ്രഭാഗം കടന്നുപോയി.",
        "0.143": "അപ്പോൾ ദേവന്മാർ ഗന്ധർവന്മാർ, സിദ്ധന്മാർ, മഹർഷിമാർ എന്നിവരോടൊപ്പം, സൂര്യതേജസ്സുള്ള നാഗമാതാവായ സുരസയോടു പറഞ്ഞു:",
        "0.144": "“കാറ്റിന്റെ മഹത്വമുള്ള പുത്രൻ, ഹനുമാൻ എന്ന പേരുള്ളവൻ, സമുദ്രത്തിന് മുകളിലൂടെ പറക്കുന്നു; അവന്റെ വഴിയിൽ ഒരു നിമിഷം തടസ്സം വയ്ക്കൂ.",
        "0.145": "പർവതംപോലെ വലിയ, ഭയങ്കര കോമ്പല്ലുകളും ചെമ്പൻ കണ്ണുകളും ആകാശംവരെ എത്തുന്ന വായുമുള്ള ഭയങ്കര രാക്ഷസരൂപം സ്വീകരിക്കൂ.",
        "0.146": "അവന്റെ ബലവും പരാക്രമവും ഞങ്ങൾക്ക് കൂടുതൽ അറിയണം: ഏതെങ്കിലും വിധത്തിൽ അവൻ നിന്നെ കീഴടക്കുമോ, അതോ അവൻ പരിഭ്രമിക്കുമോ?”",
        "0.147": "ദേവന്മാർ ഇങ്ങനെ പറയുകയും ആദരിക്കുകയും ചെയ്ത സുരസ ദേവി, സമുദ്രമധ്യത്തിൽ രാക്ഷസശരീരം സ്വീകരിച്ച്,",
        "0.148": "എല്ലാവർക്കും ഭയവും വികൃതവും വിരൂപവുമായ രൂപത്തിൽ, പറക്കുന്ന ഹനുമാനെ തടഞ്ഞുനിർത്തി പറഞ്ഞു:",
        "0.149": "“വാനരശ്രേഷ്ഠാ, ദേവന്മാർ നിന്നെ എനിക്ക് ഭക്ഷണമായി നിശ്ചയിച്ചിരിക്കുന്നു; ഞാൻ നിന്നെ തിന്നും. എന്റെ ഈ വായിൽ പ്രവേശിക്കൂ.”",
        "0.150": "“ഈ വരം ബ്രഹ്മാവ് പണ്ടേ എനിക്ക് നൽകിയതാണ്” എന്ന് അവൾ വേഗം പറഞ്ഞു; വിശാലമായ വായ് തുറന്ന്, വായുപുത്രന്റെ മുന്നിൽ നിന്നു.",
        "0.151": "സുരസ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, ഹനുമാൻ പ്രസന്നമായ മുഖത്തോടെ പറഞ്ഞു: “ദശരഥപുത്രനായ രാമൻ, സഹോദരൻ ലക്ഷ്മണനോടും ഭാര്യ വൈദേഹിയോടുമൊപ്പം ദണ്ഡകാരണ്യത്തിൽ പ്രവേശിച്ചു.",
        "0.152": "അദ്ദേഹം മറ്റൊരിടത്ത് വ്യാപൃതനായിരിക്കെ, രാക്ഷസരുമായി ശത്രുത ഉണ്ടാക്കിയതിനാൽ, അദ്ദേഹത്തിന്റെ പ്രസിദ്ധയായ ഭാര്യ സീതയെ രാവണൻ അപഹരിച്ചു.",
        "0.153": "രാമന്റെ കൽപ്പനപ്രകാരം ദൂതനായി ഞാൻ അവളുടെ അടുത്തേക്ക് പോകുന്നു. അദ്ദേഹത്തിന്റെ രാജ്യത്ത് വസിക്കുന്ന നീ രാമനെ സഹായിക്കണം.",
        "0.154": "അല്ലെങ്കിൽ, മൈഥിലിയെയും അക്ഷീണകർമ്മിയായ രാമനെയും കണ്ടശേഷം, ഞാൻ നിന്റെ വായിലേക്ക് തിരിച്ചുവരും — ഞാൻ നിനക്ക് സത്യം ചെയ്യുന്നു.”",
        "0.155": "ഹനുമാൻ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, ഏതു രൂപവും സ്വീകരിക്കാൻ കഴിവുള്ള സുരസ പറഞ്ഞു: “എന്നെ മറികടന്ന് ആരും കടന്നുപോകില്ല; ഇതാണ് എന്റെ വരം.”",
        "0.156": "അദ്ദേഹം മുന്നോട്ടു പോകുന്നത് കണ്ട്, ഹനുമാന്റെ ശക്തി പരീക്ഷിക്കാൻ ആഗ്രഹിച്ച നാഗമാതാവായ സുരസ പറഞ്ഞു:",
        "0.157": "“വാനരശ്രേഷ്ഠാ, ഇന്ന് നീ മുന്നോട്ടു പോകുന്നതിന് മുമ്പ് എന്റെ വായിൽ പ്രവേശിക്കണം; ഈ വരം ബ്രഹ്മാവ് പണ്ടേ എനിക്ക് നൽകിയതാണ്.”",
        "0.158": "ഇങ്ങനെ വേഗത്തിൽ പറഞ്ഞ്, വിശാലമായ വായ് തുറന്ന് അവൾ വായുപുത്രന്റെ മുന്നിൽ നിന്നു. സുരസ ഇങ്ങനെ പറഞ്ഞപ്പോൾ വാനരകാളയ്ക്ക് കോപം വന്നു",
        "0.159": "“എങ്കിൽ എന്നെ ഉൾക്കൊള്ളാൻ പാകത്തിൽ നിന്റെ വായ് വലുതാക്കൂ!” എന്ന് പറഞ്ഞു. പത്തു യോജന നീണ്ടുനിന്ന സുരസയോട് കോപത്തോടെ ഇങ്ങനെ പറഞ്ഞ്,",
        "0.160": "ഹനുമാൻ പത്തു യോജന വീതിയുള്ളവനായി. മേഘസദൃശനും പത്തു യോജന വലുപ്പമുള്ളവനുമായ അദ്ദേഹത്തെ കണ്ട സുരസ തന്റെ വായ് ഇരുപതു യോജന വീതിയുള്ളതാക്കി.",
        "0.161": "അപ്പോൾ ഹനുമാൻ കോപത്തോടെ മുപ്പതു യോജനയായി വളർന്നു; സുരസ വായ് നാൽപ്പതു യോജന ഉയരമുള്ളതാക്കി.",
        "0.162": "വീരനായ ഹനുമാൻ അമ്പതു യോജന ഉയരമുള്ളവനായി; സുരസ വായ് അറുപതു യോജന ഉയരത്തിൽ തുറന്നു.",
        "0.163": "ഉടൻ വീരനായ ഹനുമാൻ എഴുപതു യോജന ഉയരമുള്ളവനായി; സുരസ വായ് എൺപതു യോജന ഉയരത്തിൽ തുറന്നു.",
        "0.164": "അഗ്നിപോലെ ജ്വലിച്ച ഹനുമാൻ തൊണ്ണൂറു യോജന ഉയരമുള്ളവനായി; സുരസ വായ് നൂറു യോജന വീതിയിൽ തുറന്നു.",
        "0.165": "നീണ്ട നാവുള്ള, നരകംപോലെ ഭയങ്കരമായ സുരസയുടെ വിശാലമായ വായ് കണ്ട, ബുദ്ധിമാനായ വായുപുത്രൻ,",
        "0.166": "മേഘംപോലെ ശരീരം ചുരുക്കി; അപ്പോൾത്തന്നെ ഹനുമാൻ ഒരു തള്ളവിരലിന്റെ വലിപ്പമായി.",
        "0.167": "അവളുടെ വായിൽ കടന്ന്, പുറത്തുവന്ന്, ശക്തനും മഹിമയുള്ളവനുമായ അദ്ദേഹം ആകാശത്ത് നിന്ന് പറഞ്ഞു:",
        "0.168": "“ദക്ഷപുത്രീ, നിനക്ക് നമസ്കാരം; ഞാൻ നിന്റെ വായിൽ പ്രവേശിച്ചു. വൈദേഹി ഇരിക്കുന്നിടത്തേക്ക് ഞാൻ പോകും; നിന്റെ വരം സത്യമായി.”",
        "0.169": "രാഹുവിന്റെ താടിയെല്ലുകളിൽ നിന്ന് ചന്ദ്രൻ എന്നപോലെ, തന്റെ വായിൽ നിന്ന് പുറത്തുവന്ന വാനരനെ കണ്ട സുരസാദേവി സ്വന്തം രൂപത്തിൽ അദ്ദേഹത്തോട് പറഞ്ഞു:",
        "0.170": "“സൗമ്യനേ, വാനരശ്രേഷ്ഠാ, നിന്റെ ലക്ഷ്യസിദ്ധിക്കായി നീ ഇഷ്ടമുള്ളിടത്തേക്ക് പോകൂ; മഹാത്മാവായ രാഘവനെ വൈദേഹിയോടു ചേർക്കൂ.”",
        "0.171": "ഹനുമാന്റെ ഈ മൂന്നാമത്തെ അതിദുഷ്കരമായ കർമ്മം കണ്ട്, എല്ലാ ജീവികളും “നന്നായി! നന്നായി!” എന്ന് വിളിച്ച് വാനരനെ സ്തുതിച്ചു.",
        "0.172": "അജയ്യമായ സമുദ്രത്തിൽ, വരുണന്റെ വാസസ്ഥലത്ത് എത്തി, അദ്ദേഹം ആകാശത്ത് പ്രവേശിച്ച്, ഗരുഡനെപ്പോലെ വേഗത്തിൽ മുന്നോട്ടു പോയി;",
        "0.173": "മഴയുടെ പ്രവാഹങ്ങൾ സേവിക്കുന്നതും പക്ഷികൾ നിറഞ്ഞതുമായ ആകാശത്തിലൂടെ — സംഗീതജ്ഞരുടെ പാത, ഐരാവതം സഞ്ചരിക്കുന്ന വഴി —",
        "0.174": "സിംഹം, ആന, കടുവ, പക്ഷി, സർപ്പം എന്നിവ വലിക്കുന്ന തിളങ്ങുന്ന വിമാനങ്ങളാൽ അലങ്കരിക്കപ്പെട്ട്, പറന്നും മടങ്ങിയും;",
        "0.175": "അഗ്നിപോലെ പ്രകാശിക്കുന്നവരും, മിന്നലിന്റെ സ്പർശമുള്ളവരും, സ്വർഗ്ഗം നേടിയ പുണ്യവാന്മാരുമായ ജീവികളാൽ തിളങ്ങുന്ന വഴിയിലൂടെ;",
        "0.176": "ഹവിസ്സ് വഹിക്കുന്ന അഗ്നിയാൽ സേവിക്കപ്പെട്ടതും, ഗ്രഹങ്ങൾ, നക്ഷത്രങ്ങൾ, ചന്ദ്രൻ, സൂര്യൻ, താരസമൂഹങ്ങൾ എന്നിവയാൽ അലങ്കരിക്കപ്പെട്ടതുമായ വഴിയിലൂടെ;",
        "0.177": "മഹർഷിമാർ, ഗന്ധർവന്മാർ, നാഗന്മാർ, യക്ഷന്മാർ എന്നിവരുടെ സമൂഹങ്ങളാൽ നിറഞ്ഞ, വിശാലവും പരിശുദ്ധവും തുറന്നതും വിശ്വാവസുവിനാൽ സേവിക്കപ്പെട്ടതുമായ വഴിയിലൂടെ;",
        "0.178": "ദേവേന്ദ്രന്റെ ആന കടന്നുപോകുന്ന, ചന്ദ്രസൂര്യന്മാരുടെ ശുഭകരമായ പാത, ജീവലോകങ്ങളുടെ മേലാപ്പ്, ബ്രഹ്മാവ് വിരിച്ചത് —",
        "0.179": "വീരന്മാർ പലപ്പോഴും സഞ്ചരിക്കുന്നതും വിദ്യാധരന്മാരുടെ സമൂഹങ്ങൾ നിറഞ്ഞതുമായ ആ വായുപാതയിലൂടെ വായുപുത്രൻ ഗരുഡനെപ്പോലെ പോയി.",
        "0.180": "കാറ്റുപോലെ ഹനുമാൻ മേഘക്കൂട്ടങ്ങളെ വലിച്ചുകൊണ്ടുപോയി — കറുത്ത അകിൽപോലെ ഇരുണ്ടവയും, ചുവപ്പും മഞ്ഞയും വെളുപ്പുമുള്ളവയും.",
        "0.181": "വാനരൻ വലിച്ചുകൊണ്ടുപോയ വലിയ മേഘങ്ങൾ തിളങ്ങി; മേഘക്കൂട്ടങ്ങളിൽ പ്രവേശിച്ച് വീണ്ടും വീണ്ടും പുറത്തുവന്ന്,",
        "0.182": "പുറത്തുവന്നും അകത്തുപോയും എല്ലായിടത്തും കാണപ്പെട്ട വായുപുത്രൻ ഹനുമാൻ മഴക്കാലത്തെ ചന്ദ്രനെപ്പോലെ പ്രകാശിച്ചു.",
        "0.183": "താങ്ങില്ലാത്ത ആകാശത്തേക്ക് ചിറകുള്ള പർവതരാജാവെന്നപോലെ അദ്ദേഹം ഉയർന്നു. അദ്ദേഹം പറക്കുന്നതു കണ്ട് സിംഹിക എന്ന പേരുള്ള ഒരു രാക്ഷസി,",
        "0.184": "വലുതും ഇഷ്ടം പോലെ രൂപം മാറ്റാൻ കഴിവുള്ളവളും, ചിന്തിച്ചു: “ഇന്ന്, വളരെനാൾകഴിഞ്ഞ്, ഞാൻ വേണ്ടുവോളം ഭക്ഷിക്കും.",
        "0.185": "ഈ വലിയ ജീവി ഒടുവിൽ എന്റെ അധീനതയിൽ വന്നിരിക്കുന്നു.” ഇങ്ങനെ ചിന്തിച്ച് അവൾ അദ്ദേഹത്തിന്റെ നിഴൽ പിടിച്ചു.",
        "0.186": "നിഴൽ പിടിക്കപ്പെട്ടപ്പോൾ വാനരൻ ചിന്തിച്ചു: “പെട്ടെന്ന് ഞാൻ തടയപ്പെട്ടിരിക്കുന്നു; എന്റെ പരാക്രമം തളർന്നിരിക്കുന്നു;",
        "0.187": "എതിർക്കാറ്റിൽപ്പെട്ട കടലിലെ വലിയ കപ്പൽപോലെ.” ഇടത്തോട്ടും മുകളിലേക്കും താഴേക്കും നോക്കിയ വാനരൻ,",
        "0.188": "ഉപ്പുവെള്ളമുള്ള കടലിൽ നിന്ന് ഉയർന്ന ഒരു വലിയ ജീവിയെ കണ്ടു. ആ വികൃതമുഖജീവിയെ കണ്ട വായുപുത്രൻ ചിന്തിച്ചു:",
        "0.189": "“വാനരരാജാവ് (സുഗ്രീവൻ) വിവരിച്ച അദ്ഭുതരൂപിയായ ജീവി ഇതുതന്നെയാവണം — നിഴൽ പിടിക്കുന്ന മഹാശക്തി; സംശയമില്ല.”",
        "0.190": "അവളെ സിംഹികയെന്ന് ശരിയായി തിരിച്ചറിഞ്ഞ ബുദ്ധിമാനായ വാനരൻ, വർഷകാലത്തെ മേഘംപോലെ ശരീരം വലുതാക്കി.",
        "0.191": "വാനരന്റെ ശരീരം വളരുന്നത് കണ്ട അവൾ, പാതാളത്തിനും ആകാശത്തിനും ഇടയിലുള്ള ഇടത്ര വലിയ വായ് തുറന്നു.",
        "0.192": "മേഘക്കൂട്ടംപോലെ ഗർജ്ജിച്ച് അവൾ വാനരന്റെ നേരെ കുതിച്ചു. അപ്പോൾ അവളുടെ വലിയതും വികൃതവുമായ വായ് അദ്ദേഹം കണ്ടു.",
        "0.193": "ബുദ്ധിമാനായ മഹാവാനരൻ അവളുടെ ശരീരത്തിന്റെ വലിപ്പവും മർമ്മസ്ഥാനങ്ങളും വിലയിരുത്തി. വജ്രംപോലെ ഉറപ്പുള്ള വാനരൻ ആ വികൃതവായിലേക്ക്,",
        "0.194": "വീണ്ടും ശരീരം ചുരുക്കി, മഹാവാനരൻ ചാടിക്കയറി. സിദ്ധന്മാരും ചാരണന്മാരും അദ്ദേഹം അവളുടെ വായിലേക്ക് താഴുന്നത് കണ്ടു,",
        "0.195": "രാഹു ചന്ദ്രഗ്രഹണസമയത്ത് പൂർണ്ണചന്ദ്രനെ വിഴുങ്ങുന്നതുപോലെ. പിന്നെ, മൂർച്ചയുള്ള നഖങ്ങളാൽ അവളുടെ ഉൾഭാഗങ്ങൾ പറിച്ചെടുത്ത്, വാനരൻ",
        "0.196": "ചിന്തപോലെ വേഗമുള്ള പരാക്രമത്തോടെ വേഗത്തിൽ പുറത്തുചാടി. ഭാഗ്യവും ഉറപ്പും വൈദഗ്ധ്യവും കൊണ്ട് അവളെ അടിച്ചുവീഴ്ത്തി,",
        "0.197": "ആത്മനിയന്ത്രണമുള്ള വാനരശ്രേഷ്ഠൻ വേഗത്തിൽ വീണ്ടും വളർന്നു. ഹനുമാൻ അവളുടെ ഹൃദയം പറിച്ചെടുത്തതോടെ, അവൾ പ്രഹരമേറ്റ് വെള്ളത്തിൽ വീണു; അവളുടെ നാശത്തിനായി സ്വയംഭൂവായ ബ്രഹ്മാവ് തന്നെ ഹനുമാനെ സൃഷ്ടിച്ചിരുന്നു.",
        "0.198": "വാനരൻ വേഗത്തിൽ വധിച്ച് വീണുകിടക്കുന്ന സിംഹികയെ കണ്ട ആകാശത്ത് സഞ്ചരിക്കുന്ന ജീവികൾ, ആ വാനരശ്രേഷ്ഠനോട് പറഞ്ഞു:",
        "0.199": "“ഇന്ന് നീ ഭയങ്കരമായ ഒരു കർമ്മം ചെയ്തു: ഒരു വലിയ ജീവിയെ നീ വധിച്ചു. നിന്റെ ഉദ്ദേശിച്ച ലക്ഷ്യം യാതൊരു ദോഷവുമില്ലാതെ നിറവേറ്റുക, ചാടുന്നവരിൽ ഉത്തമനേ.",
        "0.200": "വാനരപ്രഭോ, നിന്നെപ്പോലെ സ്ഥൈര്യം, ദർശനം, ബുദ്ധി, സാമർത്ഥ്യം എന്നീ നാലു ഗുണങ്ങളുള്ളവൻ ഒരിക്കലും കാര്യങ്ങളിൽ പരാജയപ്പെടുന്നില്ല.”",
        "0.201": "അവരുടെ ആദരവ് ലഭിച്ച്, ലക്ഷ്യം നിറവേറ്റിയ വന്ദ്യനായ വാനരൻ, സർപ്പഭോജിയായ ഗരുഡനെപ്പോലെ ആകാശത്ത് പ്രവേശിച്ച് മുന്നോട്ടു പോയി.",
        "0.202": "ദൂരത്തിന്റെ ഏറെ ഭാഗവും കടന്ന്, ചുറ്റും നോക്കി, നൂറു യോജനയുടെ അവസാനത്തിൽ വനനിരകൾ കണ്ടു.",
        "0.203": "ഇറങ്ങുമ്പോൾത്തന്നെ, വിവിധതരം വൃക്ഷങ്ങളാൽ അലങ്കരിക്കപ്പെട്ട ഒരു ദ്വീപും മലയ പർവതത്തിലെ തോപ്പുകളും ആ ഉത്തമ വാനരൻ കണ്ടു.",
        "0.204": "അദ്ദേഹം കടലും ചതുപ്പുനിലവും അവിടെ വളരുന്ന വൃക്ഷങ്ങളും, സമുദ്രത്തിന്റെ ഭാര്യമാരായ നദീമുഖങ്ങളും കണ്ടു.",
        "0.205": "ആകാശം മറയ്ക്കുന്നതുപോലെ ഒരു വലിയ മേഘംപോലെ സ്വയം കണ്ട ബുദ്ധിമാനും ആത്മനിയന്ത്രണമുള്ളവനുമായ അദ്ദേഹം ഒരു തീരുമാനമെടുത്തു.",
        "0.206": "ബുദ്ധിമാനായ അദ്ദേഹം ചിന്തിച്ചു: “രാക്ഷസർ എന്റെ വലുതാക്കിയ ശരീരവും വേഗവും കണ്ടാൽ എന്നെക്കുറിച്ച് കൗതുകം തോന്നും.”",
        "0.207": "അപ്പോൾ, പർവതസമാനമായ ശരീരം ചുരുക്കി, ആത്മനിയന്ത്രണമുള്ളവൻ മോഹത്തിൽ നിന്ന് മോചിതനെന്നപോലെ സ്വാഭാവിക രൂപത്തിലേക്ക് മടങ്ങി.",
        "0.208": "ആ രൂപം വളരെ ചുരുക്കി, ഹനുമാൻ മൂന്നു ചുവടു വെച്ച് ബലിയുടെ ശക്തി നീക്കിയ ഹരി (വിഷ്ണു) എന്നപോലെ സ്വാഭാവിക അവസ്ഥയിൽ നിന്നു.",
        "0.209": "പല മനോഹര രൂപങ്ങൾ സ്വീകരിക്കാൻ കഴിവുള്ള അദ്ദേഹം, മറ്റാർക്കും എത്താനാകാത്ത സമുദ്രത്തിന്റെ അക്കരെയെത്തി; രൂപം വീണ്ടെടുത്ത്, തന്നെക്കുറിച്ചും തന്റെ ദൗത്യത്തെക്കുറിച്ചും ചിന്തിച്ചു.",
        "0.210": "അപ്പോൾ മഹാത്മാവ്, വലിയ മേഘക്കൂട്ടംപോലെ, കേതകം, ഉദ്ദാലകം, തെങ്ങ് മരങ്ങളോടുകൂടിയ, സമൃദ്ധമായ അനേകം ശിഖരങ്ങളുള്ള ലംബപർവതത്തിന്റെ മുകളിൽ ഇറങ്ങി.",
        "0.211": "തീരത്ത് എത്തി, വലിയ പർവതത്തിന്റെ മുകളിൽ ലങ്ക കണ്ടപ്പോൾ, വാനരൻ തന്റെ രൂപം കുടഞ്ഞുകളഞ്ഞ്, മൃഗങ്ങളെയും പക്ഷികളെയും ഭയപ്പെടുത്തി ആ പർവതത്തിൽ ഇറങ്ങി.",
        "0.212": "വലിയ തിരമാലകളാൽ അലങ്കരിക്കപ്പെട്ടതും ദാനവരും സർപ്പങ്ങളും നിറഞ്ഞതുമായ സമുദ്രം തന്റെ ശക്തിയാൽ കടന്ന്, അദ്ദേഹം അതിന്റെ തീരത്തിറങ്ങി; അമരാവതി പോലെയുള്ള ദേവനഗരമായ ലങ്കയെ കണ്ടു.",
        "0.213": "ഇങ്ങനെ, വാൽമീകിയുടെ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ ആദ്യ സർഗ്ഗം സമാപിച്ചു — മുനിയുടെ ആദ്യകാവ്യം."
      },
      "summary": "മഹേന്ദ്രപർവതത്തിൽ നിന്ന് ഹനുമാൻ ദേവന്മാരെ വണങ്ങി ലങ്ക ലക്ഷ്യമാക്കി ആകാശത്തേക്ക് കുതിക്കുന്നു. മൈനാകപർവതം കടലിൽ നിന്ന് ഉയർന്ന് അദ്ദേഹത്തിന് വിശ്രമം നൽകുന്നു; ദേവന്മാരുടെ നിർദ്ദേശപ്രകാരം സുരസ അദ്ദേഹത്തെ പരീക്ഷിക്കുന്നു; നിഴൽ പിടിക്കുന്ന സിംഹികയെ വധിച്ച ശേഷം അദ്ദേഹം അക്കരെ ഇറങ്ങുന്നു."
    },
    "sundarakanda-02": {
      "verses": {
        "0.0": "ജയിക്കാനാവാത്ത സമുദ്രം കടന്ന ശക്തൻ, ത്രികൂടത്തിന്റെ ചരിവിൽ സുഖമായി നിന്ന് ലങ്കയെ നോക്കി.",
        "0.1": "അവിടെ മരങ്ങളിൽ നിന്ന് വീണ പൂക്കളാൽ മൂടപ്പെട്ട ധീരനായ വാനരൻ, പൂക്കൾകൊണ്ടുണ്ടാക്കിയതുപോലെ കാണപ്പെട്ടു.",
        "0.2": "നൂറു യോജന താണ്ടിയിട്ടും, ഉത്തമ വീര്യമുള്ള ആ മഹാവാനരന് ശ്വാസം മുട്ടുകയോ ക്ഷീണം തോന്നുകയോ ചെയ്തില്ല.",
        "0.3": "“എനിക്ക് നൂറുകണക്കിന് യോജന താണ്ടാൻ കഴിയും; പിന്നെ നൂറെന്ന് കണക്കാക്കുന്ന സമുദ്രത്തിന്റെ വിസ്തൃതിയെക്കുറിച്ച് എന്തു പറയാൻ?” എന്ന് അദ്ദേഹം ചിന്തിച്ചു.",
        "0.4": "വീരന്മാരിൽ ഉത്തമനും ചാടുന്നവരിൽ മുമ്പനുമായ ആ വാനരൻ, വലിയ സമുദ്രം കടന്ന്, വേഗത്തിൽ ലങ്കയെ ലക്ഷ്യമാക്കി നീങ്ങി.",
        "0.5": "ഇരുണ്ട പച്ചപ്പുല്മേടുകളിലൂടെയും, തേനുള്ള സുഗന്ധവനങ്ങളിലൂടെയും, ഇടതൂർന്ന മരങ്ങളുള്ള പ്രദേശങ്ങളിലൂടെയും അദ്ദേഹം കടന്നുപോയി.",
        "0.6": "തേജസ്സുള്ള ഹനുമാൻ, വാനരശ്രേഷ്ഠൻ, മരങ്ങൾ നിറഞ്ഞ കുന്നുകൾക്കും പൂത്തുനിൽക്കുന്ന വനനിരകൾക്കും മുകളിലൂടെ പറന്നു.",
        "0.7": "ആ പർവതത്തിൽ നിന്നുകൊണ്ട് വായുപുത്രൻ വനങ്ങളും തോപ്പുകളും കണ്ടു; പർവതശിഖരത്തിൽ സ്ഥാപിതമായ ലങ്കയെയും കണ്ടു.",
        "0.8": "സരളം, കർണ്ണികാരം, പൂത്തുനിൽക്കുന്ന ഈന്തപ്പനകൾ, പ്രിയാലം, മുചുലിന്ദം, കുടജം, കേതകം എന്നീ വൃക്ഷങ്ങൾ അദ്ദേഹം കണ്ടു.",
        "0.9": "സുഗന്ധമുള്ള പ്രിയംഗു, നീപം, സപ്തച്ഛദം എന്നീ വൃക്ഷങ്ങളും, അസനം, കോവിദാരം, പൂത്തുനിൽക്കുന്ന കരവീരം എന്നിവയും കണ്ടു.",
        "0.10": "പൂക്കൂട്ടങ്ങൾ നിറഞ്ഞതോ ഇനിയും മൊട്ടുകളായതോ ആയ മരങ്ങൾ, പക്ഷികൾ നിറഞ്ഞവ, കാറ്റിൽ മുകൾ ആടുന്നവ;",
        "0.11": "അരയന്നങ്ങളും കാരണ്ഡവ താറാവുകളും നിറഞ്ഞ കുളങ്ങൾ, താമരകളും ആമ്പലുകളും മൂടിയവ, അനേകം മനോഹര ഉല്ലാസോദ്യാനങ്ങളും തടാകങ്ങളും;",
        "0.12": "എല്ലാ ഋതുക്കളിലും ഫലവും പൂവും നൽകുന്ന അനേകം മരങ്ങൾ നിറഞ്ഞ മനോഹരമായ തോട്ടങ്ങൾ — ഇവയെല്ലാം ആ വാനരഗജൻ കണ്ടു.",
        "0.13": "താമരകളും ആമ്പലുകളും നിറഞ്ഞ കിടങ്ങുകളാൽ അലങ്കരിക്കപ്പെട്ട, രാവണൻ ഭരിക്കുന്ന ലങ്കയെ ആ തേജസ്വി സമീപിച്ചു.",
        "0.14": "സീതയുടെ അപഹരണം മുതൽ രാവണൻ കർശനമായി കാത്തുസൂക്ഷിച്ചതും, ഭയങ്കര വില്ലുകൾ ധരിച്ച രാക്ഷസന്മാർ ചുറ്റും പട്രോളിംഗ് നടത്തുന്നതുമായ നഗരം;",
        "0.15": "സ്വർണ്ണമതിലിനാൽ ചുറ്റപ്പെട്ട, മനോഹരമായ വലിയ നഗരം; പർവതങ്ങൾപോലെയുള്ള ഭവനങ്ങൾ, ശരത്കാലമേഘങ്ങൾപോലെ;",
        "0.16": "നൂറുകണക്കിന് ഗോപുരങ്ങളുള്ള, കൊടികളും പതാകകളും കൊണ്ടലങ്കരിച്ച, ഉയർന്ന വെളുത്ത വീഥികളാൽ ചുറ്റപ്പെട്ട;",
        "0.17": "ദിവ്യമായ സ്വർണ്ണ കമാനങ്ങൾ, വള്ളികളുടെ നിരകൾ തിളങ്ങുന്ന — ദേവന്മാർ ദേവനഗരം കാണുന്നതുപോലെ ഹനുമാൻ ലങ്കയെ കണ്ടു.",
        "0.18": "ഉത്തമനായ വാനരൻ, ആകാശത്ത് ഒഴുകുന്ന നഗരംപോലെ, മനോഹരമായ വെള്ള മാളികകളോടുകൂടിയ ലങ്കയെ പർവതശിഖരത്തിൽ കണ്ടു.",
        "0.19": "രാക്ഷസരാജാവ് ഭരിക്കുന്നതും വിശ്വകർമ്മാവ് നിർമ്മിച്ചതുമായ അത്, ഹനുമാന് ആകാശത്ത് ഒഴുകുന്നതുപോലെ തോന്നി.",
        "0.20": "അതിന്റെ കോട്ടകളും മതിലുകളും അരക്കെട്ടുകളായിരുന്നു; വിശാലമായ വെള്ളവും വനങ്ങളും വസ്ത്രമായിരുന്നു; ശതഘ്നികളും കുന്തങ്ങളും മുടിയും; ഗോപുരങ്ങൾ കാതിലെ ആഭരണങ്ങളും.",
        "0.21": "വിശ്വകർമ്മാവ് മനസ്സിന്റെ ശക്തിയാൽ നിർമ്മിച്ചതുപോലെയുള്ള ലങ്കയെ കണ്ട വാനരൻ വടക്കേ ഗോപുരത്തിലെത്തി ചിന്തിച്ചു.",
        "0.22": "ആ ഗോപുരം കൈലാസത്തിലെ കുബേരന്റെ വാസസ്ഥലംപോലെ, ആകാശത്തെ ഉരസുന്നതുപോലെ, ഉയർന്ന മാളികകളാൽ അതിനെ താങ്ങിനിർത്തുന്നതുപോലെ തോന്നി.",
        "0.23": "സർപ്പങ്ങൾ നിറഞ്ഞ ഭോഗവതിപോലെ ഭയങ്കരരായ രാക്ഷസന്മാരാൽ നിറഞ്ഞ നഗരം — ചിന്തിക്കാനാവാത്തതും, നന്നായി നിർമ്മിച്ചതും, വ്യക്തമായി ക്രമീകരിച്ചതും, ഒരിക്കൽ കുബേരന്റെ വാസസ്ഥലവുമായിരുന്നു.",
        "0.24": "വിഷസർപ്പങ്ങൾ കാക്കുന്ന ഗുഹപോലെ, കുന്തവും കോടാലിയും ഏന്തിയ, ധീരരും കോമ്പല്ലുള്ളവരും ഭയങ്കരരുമായ അനേകം രാക്ഷസന്മാർ അത് കാത്തുനിന്നു.",
        "0.25": "അതിന്റെ ശക്തമായ പ്രതിരോധവും, അത് ചുറ്റിയ സമുദ്രവും, ഭയങ്കര ശത്രു രാവണനെയും കണ്ടപ്പോൾ വാനരൻ ചിന്തിച്ചു:",
        "0.26": "“വാനരന്മാർ ഇവിടെ വന്നാലും അത് വ്യർത്ഥമാകും; യുദ്ധത്തിൽ ഈ ലങ്കയെ ദേവന്മാർക്കുപോലും കീഴടക്കാനാവില്ല.",
        "0.27": "രാവണൻ ഭരിക്കുന്ന ഈ പരുക്കനും അജയ്യവുമായ ലങ്കയിൽ എത്തിയാൽത്തന്നെ, ബാഹുബലമുള്ള രാഘവന് എന്ത് ചെയ്യാനാകും?",
        "0.28": "രാക്ഷസന്മാരുടെ അടുത്ത് സമാധാനസന്ധിക്കോ, സമ്മാനങ്ങൾക്കോ, ഭിന്നിപ്പിനോ, ഇടമില്ല; യുദ്ധവും ഒരു മാർഗ്ഗമായി കാണുന്നില്ല.",
        "0.29": "വേഗമുള്ള വാനരന്മാരിൽ നാലുപേർക്കുമാത്രമേ ഇവിടെ എത്താൻ കഴിയൂ: വാലിപുത്രൻ (അംഗദൻ), നീലൻ, ഞാൻ, നമ്മുടെ ജ്ഞാനിയായ രാജാവ് (സുഗ്രീവൻ).",
        "0.30": "ആദ്യം വൈദേഹി ജീവിച്ചിരിപ്പുണ്ടോ ഇല്ലയോ എന്ന് ഞാൻ കണ്ടുപിടിക്കട്ടെ; ജനകപുത്രിയെ കണ്ടശേഷം അവിടെ എന്തു ചെയ്യണമെന്ന് ഞാൻ ആലോചിക്കാം.”",
        "0.31": "പിന്നെ ആ പർവതശിഖരത്തിൽ നിന്നുകൊണ്ട്, വാനരഗജൻ രാമന്റെ കാര്യം എങ്ങനെ വിജയിക്കുമെന്ന് കുറച്ചുനേരം ചിന്തിച്ചു.",
        "0.32": "“ക്രൂരരും ശക്തരുമായ രാക്ഷസന്മാർ കാക്കുന്ന രാക്ഷസ നഗരത്തിൽ ഈ രൂപത്തിൽ എനിക്ക് പ്രവേശിക്കാനാവില്ല.",
        "0.33": "രാക്ഷസന്മാർക്ക് വലിയ ഊർജ്ജവും വീര്യവും ബലവുമുണ്ട്; ജാനകിയെ തിരയുമ്പോൾ ഞാൻ അവരെയെല്ലാം ഒഴിവാക്കണം.",
        "0.34": "ലങ്കയിൽ പ്രവേശിച്ച് എന്റെ വലിയ ദൗത്യം നിറവേറ്റാൻ ഏറ്റവും യോജിച്ച സമയം രാത്രിയാണ്; എന്റെ രൂപം ഏതാണ്ട് കാണാനാകാത്തതായിരിക്കണം.”",
        "0.35": "ദേവന്മാർക്കും ദാനവന്മാർക്കും പോലും കീഴടക്കാനാവാത്ത ആ നഗരം കണ്ട് ഹനുമാൻ വീണ്ടും വീണ്ടും നെടുവീർപ്പിട്ട് ചിന്തിച്ചു:",
        "0.36": "“ദുഷ്ടനായ രാക്ഷസരാജാവ് രാവണൻ കാണാതെ, മൈഥിലിയായ ജനകപുത്രിയെ ഞാൻ ഏത് മാർഗ്ഗത്തിൽ കാണും?",
        "0.37": "സ്വയം അറിയപ്പെട്ട രാമന്റെ കാര്യം എങ്ങനെ നശിച്ചുപോകാതിരിക്കും? ജനകപുത്രിയെ ഏകാന്തസ്ഥലത്ത് ഞാൻ മാത്രം തനിച്ചു എങ്ങനെ കാണും?",
        "0.38": "ദേശത്തിനും കാലത്തിനും യോജിക്കാത്തപ്പോൾ നിറവേറ്റപ്പെട്ട ലക്ഷ്യങ്ങൾപോലും നശിക്കുന്നു; കഴിവില്ലാത്ത ദൂതന്റെ കൈകളിൽ വീണാൽ — സൂര്യോദയത്തിൽ ഇരുട്ട് നശിക്കുന്നതുപോലെ.",
        "0.39": "ശരിയും തെറ്റും സംബന്ധിച്ച് ഉറച്ച തീർപ്പുപോലും തിളങ്ങുന്നില്ല; സ്വയം മിടുക്കരെന്ന് കരുതുന്ന ദൂതന്മാർ ദൗത്യങ്ങൾ നശിപ്പിക്കുന്നു.",
        "0.40": "കാര്യം എങ്ങനെ നശിക്കാതിരിക്കും? തെറ്റ് എങ്ങനെ സംഭവിക്കാതിരിക്കും? സമുദ്രം ചാടിക്കടന്ന എന്റെ ചാട്ടം എങ്ങനെ വ്യർത്ഥമാകാതിരിക്കും?",
        "0.41": "രാവണന്റെ നാശം ആഗ്രഹിക്കുന്ന രാമന്റെ ഈ ദൗത്യം, ഞാൻ രാക്ഷസന്മാരുടെ കണ്ണിൽപ്പെട്ടാൽ, ഒന്നുമല്ലാതായിപ്പോകും.",
        "0.42": "രാക്ഷസരൂപത്തിൽപോലും ഇവിടെ രാക്ഷസന്മാർ തിരിച്ചറിയാതെ ആർക്കും ഒളിച്ചിരിക്കാനാവില്ല — മറ്റേതു രൂപത്തിൽ പറയാനെന്ത്?",
        "0.43": "ഇവിടെ കാറ്റുപോലും ശ്രദ്ധിക്കപ്പെടാതെ ചലിക്കുമെന്ന് തോന്നുന്നില്ല; ഭയങ്കരകർമ്മികളായ ഈ രാക്ഷസന്മാരിൽ നിന്ന് ഒന്നും രക്ഷപ്പെടുന്നില്ല.",
        "0.44": "ഞാൻ എന്റെ സ്വന്തം രൂപത്തിൽ ഇവിടെ നിന്നാൽ നശിച്ചുപോകും; യജമാനന്റെ ഉദ്ദേശ്യവും പരാജയപ്പെടും.",
        "0.45": "അതിനാൽ, രാത്രിയിൽ, സ്വന്തം രൂപത്തിൽ തന്നെ എന്നാൽ ചെറുതാക്കി, രാഘവന്റെ കാര്യസിദ്ധിക്കായി ഞാൻ ലങ്കയിലേക്ക് ചാടും.",
        "0.46": "പ്രവേശിക്കാൻ ദുഷ്കരമായ രാവണന്റെ നഗരത്തിൽ രാത്രിയിൽ കടന്ന്, ഓരോ വീടും പരിശോധിച്ച് ഞാൻ ജനകപുത്രിയെ കണ്ടെത്തും.”",
        "0.47": "ഇങ്ങനെ തീരുമാനിച്ച്, വൈദേഹിയെ കാണാൻ ആഗ്രഹിച്ച വീരനായ വാനരൻ ഹനുമാൻ സൂര്യാസ്തമയത്തിനായി കാത്തിരുന്നു.",
        "0.48": "സൂര്യൻ അസ്തമിച്ചപ്പോൾ, രാത്രിയിൽ വായുപുത്രൻ ശരീരം ചുരുക്കി, ഒരു പൂച്ചയുടെ വലിപ്പത്തിലായി — അദ്ഭുതകരമായ കാഴ്ച.",
        "0.49": "സന്ധ്യാസമയത്ത് വീരനായ ഹനുമാൻ വേഗത്തിൽ ചാടി, നന്നായി ക്രമീകരിച്ച വീഥികളുള്ള മനോഹര നഗരത്തിൽ പ്രവേശിച്ചു;",
        "0.50": "നിരനിരയായുള്ള കൊട്ടാരങ്ങൾ നിറഞ്ഞത്, സ്വർണ്ണത്തൂണുകളും സ്വർണ്ണജാലകങ്ങളുമുള്ളത് — ഗന്ധർവന്മാരുടെ നഗരംപോലെ.",
        "0.51": "ഏഴും എട്ടും നിലകളുള്ള വീടുകളുള്ള, സ്ഫടികം പതിച്ച തറകളും സ്വർണ്ണാലങ്കാരവുമുള്ള ആ മഹാനഗരം അദ്ദേഹം കണ്ടു.",
        "0.52": "അവിടത്തെ രാക്ഷസന്മാരുടെ മാളികകൾ വൈഡൂര്യം പതിച്ച തറകളോടെയും മുത്തുമാലകളുടെ വലയങ്ങളാൽ അലങ്കരിച്ചും തിളങ്ങി.",
        "0.53": "രാക്ഷസന്മാരുടെ വിവിധവർണ്ണ സ്വർണ്ണ കമാനങ്ങൾ ലങ്കയെ പ്രകാശിപ്പിച്ചു; എല്ലാ വശങ്ങളിലും അലങ്കരിക്കപ്പെട്ടിരുന്നു.",
        "0.54": "ചിന്തിക്കാനാവാത്ത, രൂപത്തിൽ അദ്ഭുതമായ ലങ്കയെ കണ്ട മഹാവാനരൻ ദുഃഖിച്ചും സന്തോഷിച്ചും, വൈദേഹിയെ കാണാൻ ആഗ്രഹിച്ചു.",
        "0.55": "വെള്ള ആകാശമാളികകളാൽ മാലയണിഞ്ഞ, വിലയേറിയ സ്വർണ്ണജാലകങ്ങളുള്ള കമാനങ്ങളോടുകൂടിയ, രാവണന്റെ ബാഹുബലത്താൽ സംരക്ഷിക്കപ്പെട്ട, ഭയങ്കരശക്തിയുള്ള രാത്രിസഞ്ചാരികളാൽ നന്നായി കാക്കപ്പെട്ട ആ മഹാനഗരം അദ്ദേഹം കണ്ടു.",
        "0.56": "ചന്ദ്രനും സഹായം നൽകുന്നതുപോലെ നക്ഷത്രസമൂഹങ്ങൾക്കിടയിൽ പ്രകാശിച്ച്, ആയിരക്കണക്കിന് രശ്മികളോടെ ഉദിച്ചു; ലോകങ്ങളുടെ മേൽ നിലാവിന്റെ മേലാപ്പ് വിരിച്ചു.",
        "0.57": "ഉദിച്ചുയർന്ന് തിളങ്ങുന്ന ചന്ദ്രനെ വീരനായ വാനരൻ കണ്ടു — ശംഖുപോലെ പ്രകാശമുള്ള, പാലും താമരത്തണ്ടിന്റെ നാരും പോലെ വെളുത്ത, തടാകത്തിൽ ഒഴുകുന്ന ഹംസംപോലെ.",
        "0.58": "ഇങ്ങനെ, വാൽമീകിയുടെ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ രണ്ടാം സർഗ്ഗം സമാപിച്ചു — മുനിയുടെ ആദ്യകാവ്യം."
      },
      "summary": "ത്രികൂടപർവതത്തിന്റെ ശിഖരത്തിൽ നിന്ന് ഹനുമാൻ ശോഭയുള്ള, നന്നായി കാക്കപ്പെട്ട ലങ്കാനഗരത്തെ നോക്കുന്നു. അകത്തുകടക്കാൻ കാണാതെ എങ്ങനെയെന്ന് ആലോചിച്ച്, ചെറിയ രൂപത്തിൽ രാത്രിയിൽ പ്രവേശിക്കാൻ അദ്ദേഹം തീരുമാനിക്കുന്നു; ചന്ദ്രൻ ഉദിക്കുന്നു."
    },
    "sundarakanda-03": {
      "verses": {
        "0.0": "ഉയർന്നുനിൽക്കുന്ന മേഘംപോലെ ഉയരമുള്ള ലംബപർവതത്തിന്റെ ശിഖരത്തിൽ നിന്ന്, ധൈര്യം സംഭരിച്ച ബുദ്ധിമാനായ വായുപുത്രൻ ഹനുമാൻ,",
        "0.1": "മനോഹരമായ വനങ്ങളും ജലാശയങ്ങളുമുള്ള, രാവണൻ ഭരിക്കുന്ന ലങ്കയിൽ, മഹാമനസ്കനായ വാനരഗജൻ രാത്രിയിൽ പ്രവേശിച്ചു.",
        "0.2": "ശരത്കാലമേഘങ്ങൾപോലെ മാളികകളാൽ അലങ്കരിക്കപ്പെട്ട, സമുദ്രംപോലെ മുഴങ്ങുന്ന, സമുദ്രകാറ്റിനാൽ വീശപ്പെട്ട നഗരം.",
        "0.3": "വിതപവതി (കുബേരന്റെ നഗരം) പോലെ നന്നായി ഭക്ഷണം കിട്ടിയ സൈനികരാൽ നിറഞ്ഞ, മനോഹരമായ കമാനങ്ങളും ഗോപുരങ്ങളും വെള്ള കവാടങ്ങളുമുള്ള നഗരം.",
        "0.4": "മനോഹരമായ ഭോഗവതിപോലെ സർപ്പങ്ങളാൽ കാക്കപ്പെട്ടതും സഞ്ചരിക്കപ്പെട്ടതും, മിന്നൽ പ്രകാശിപ്പിച്ച മേഘങ്ങൾ നിറഞ്ഞതും, നക്ഷത്രസമൂഹങ്ങളാൽ സേവിക്കപ്പെടുന്നതുമായ നഗരം.",
        "0.5": "അമരാവതിപോലെ ഭയങ്കരമായ കാറ്റുകളാൽ ഇരമ്പുന്നതും, വലിയ സ്വർണ്ണമതിലിനാൽ ചുറ്റപ്പെട്ടതുമായ നഗരം.",
        "0.6": "ചെറിയ മണികളുടെ ചരടുകളാൽ മുഴങ്ങുന്ന കൊടികളാൽ അലങ്കരിക്കപ്പെട്ടതുമായ നഗരം. അവിടെ എത്തി സന്തോഷിച്ച അദ്ദേഹം പെട്ടെന്ന് മതിലിലേക്ക് ചാടിക്കയറി.",
        "0.7": "വിസ്മയം നിറഞ്ഞ മനസ്സോടെ അദ്ദേഹം ചുറ്റും നഗരം നോക്കി — വൈഡൂര്യവേദികളോടുകൂടിയ സ്വർണ്ണകവാടങ്ങൾ;",
        "0.8": "വജ്രം, സ്ഫടികം, മുത്ത് എന്നിവകൊണ്ട് അലങ്കരിച്ചത്, രത്നം പതിച്ച തറകളോടെ, ശുദ്ധസ്വർണ്ണംകൊണ്ടുള്ള ഗോപുരങ്ങളും, ശുദ്ധമായ വെള്ളിയും ഉള്ളത്;",
        "0.9": "വൈഡൂര്യപ്പടവുകളോടും, സ്ഫടികപ്പൊടി വിതറിയ അകത്തളങ്ങളോടും, മനോഹര സഭാമണ്ഡപങ്ങളോടും, ആകാശത്തേക്ക് ഉയരുന്നതുപോലെ തോന്നിക്കുന്ന മഹാമന്ദിരങ്ങളോടും കൂടിയത്;",
        "0.10": "കുരുകുകളുടെയും മയിലുകളുടെയും ശബ്ദം മുഴങ്ങുന്ന, രാജഹംസങ്ങൾ സഞ്ചരിക്കുന്ന, സംഗീതവും ആഭരണങ്ങളുടെ കിലുക്കവും എല്ലായിടത്തും മുഴങ്ങുന്ന നഗരം.",
        "0.11": "ഇന്ദ്രന്റെ തലസ്ഥാനംപോലെ ആ നഗരത്തെ, ആകാശത്തേക്ക് ഉയരുന്നതുപോലെ ലങ്കയെ കണ്ട വാനരൻ ഹനുമാൻ സന്തോഷിച്ചു.",
        "0.12": "രാക്ഷസരാജാവിന്റെ ആ തിളക്കമുള്ള, തുല്യതയില്ലാത്ത, സമൃദ്ധമായ നഗരം കണ്ട ധീരൻ ചിന്തിച്ചു:",
        "0.13": "“കൈയിൽ ആയുധം ഉയർത്തിയ രാവണന്റെ സൈന്യം കാക്കുന്ന ഈ നഗരം മറ്റാരും ബലമായി കീഴടക്കാനാവില്ല.",
        "0.14": "കുമുദനും അംഗദനും, മഹാവാനരനായ സുഷേണനും, മൈന്ദനും ദ്വിവിദനും ഈ നാട്ടിലേക്ക് പ്രവേശിക്കാൻ കഴിഞ്ഞേക്കാം.",
        "0.15": "വിവസ്വാന്റെ പുത്രനും (സുഗ്രീവൻ), വാനരൻ കുശപർവ്വനും, വാനരപ്രമുഖൻ ഋക്ഷനും, എനിക്കും കഴിഞ്ഞേക്കാം.”",
        "0.16": "അപ്പോൾ, ശക്തമായ ബാഹുക്കളുള്ള രാഘവന്റെ പരാക്രമവും ലക്ഷ്മണന്റെ വീര്യവും ഓർത്ത് വാനരൻ സന്തോഷിച്ചു.",
        "0.17": "അലങ്കരിക്കപ്പെട്ട ഒരു യുവതിപോലെ — രത്നങ്ങൾ വസ്ത്രമായി, സംഭരണശാലകൾ കാതിലെ ആഭരണമായി, ആയുധശാലകൾ സ്തനങ്ങളായി — രാക്ഷസരാജാവിന്റെ നഗരത്തെ മഹാവാനരൻ കണ്ടു.",
        "0.18": "വിളക്കുകളും തിളങ്ങുന്ന മഹാഗ്രഹങ്ങളും അതിന്റെ ഇരുട്ട് നീക്കിയിരുന്ന ആ രാക്ഷസരാജനഗരം മഹാവാനരൻ കണ്ടു.",
        "0.19": "അപ്പോൾ നഗരം തന്നെ, സ്വന്തം രൂപത്തിൽ, വായുപുത്രനായ മഹാവാനരൻ പ്രവേശിക്കുന്നത് കണ്ടു.",
        "0.20": "രാവണൻ ഭരിക്കുന്ന ലങ്ക, ആ ഉത്തമ വാനരനെ കണ്ടപ്പോൾ, വികൃതമുഖിയായി സ്വയം ഉയർന്നു.",
        "0.21": "ധീരനായ വായുപുത്രന്റെ മുന്നിൽ നിന്ന് അവൾ ഉച്ചത്തിൽ ഗർജ്ജിച്ച് അദ്ദേഹത്തോട് പറഞ്ഞു:",
        "0.22": "“വനവാസിയേ, നീ ആരാണ്? എന്ത് കാര്യത്തിനാണ് ഇവിടെ വന്നത്? ജീവൻ ഇപ്പോഴും നിൽക്കുമ്പോൾ സത്യം പറയൂ.",
        "0.23": "വാനരാ, ഈ ലങ്കയിൽ നിനക്ക് പ്രവേശിക്കാനാവില്ല; രാവണന്റെ സൈന്യം എല്ലാ വശങ്ങളിലും ഇതിനെ കാക്കുന്നു.”",
        "0.24": "അപ്പോൾ തന്റെ മുന്നിൽ നിന്ന ലങ്കയോട് ധീരനായ ഹനുമാൻ പറഞ്ഞു: “നീ ചോദിച്ച സത്യം ഞാൻ പറയാം.",
        "0.25": "എന്നാൽ നഗരകവാടത്തിൽ നിൽക്കുന്ന, വികൃതമായ കണ്ണുകളുള്ള നീ ആരാണ്? ക്രൂരേ, കോപത്തോടെ നീ എന്നെ എന്തിന് ഭീഷണിപ്പെടുത്തുന്നു?”",
        "0.26": "ഹനുമാന്റെ വാക്കുകൾ കേട്ട്, ഏതു രൂപവും സ്വീകരിക്കാൻ കഴിവുള്ള ലങ്ക കോപത്തോടെ വായുപുത്രനോട് കഠിനവാക്കുകൾ പറഞ്ഞു:",
        "0.27": "“ഞാൻ അജയ്യയാണ്; മഹാരാക്ഷസരാജാവായ രാവണന്റെ കല്പനയ്ക്കായി കാത്തുനിന്ന് ഈ നഗരം കാക്കുന്നു.",
        "0.28": "എന്നെ അവഗണിച്ച് നിനക്ക് ഈ നഗരത്തിൽ പ്രവേശിക്കാനാവില്ല; ഇന്ന് എന്നാൽ കൊല്ലപ്പെട്ട്, ജീവനില്ലാതെ നീ ഉറങ്ങും.",
        "0.29": "വാനരാ, ഞാൻ തന്നെ ലങ്കാനഗരം; എല്ലാ വശത്തുനിന്നും ഞാൻ ഇതിനെ കാക്കുന്നു. അതുകൊണ്ടാണ് ഇത് നിന്നോട് പറഞ്ഞത്.”",
        "0.30": "ലങ്കയുടെ വാക്കുകൾ കേട്ട വായുപുത്രൻ, വാനരശ്രേഷ്ഠൻ ഹനുമാൻ, മറ്റൊരു പർവതംപോലെ ഉറച്ചും ജാഗ്രതയോടെയും നിന്നു.",
        "0.31": "സ്ത്രീരൂപത്തിൽ വികൃതമായ അവളെ കണ്ട്, ബുദ്ധിമാനും ധീരനുമായ വാനരഗജൻ പറഞ്ഞു:",
        "0.32": "“ലങ്കയുടെ ഗോപുരങ്ങളും മതിലുകളും കമാനങ്ങളുമുള്ള നഗരം കാണാനാണ് ഞാൻ ഇവിടെ വന്നത്; എനിക്ക് വലിയ കൗതുകമുണ്ട്.",
        "0.33": "ലങ്കയിലെ വനങ്ങളും തോപ്പുകളും കാടുകളും, ചുറ്റിലുമുള്ള പ്രധാന മാളികകളും കാണാനാണ് ഞാൻ വന്നത്.”",
        "0.34": "അദ്ദേഹത്തിന്റെ വാക്കുകൾ കേട്ട്, ഏതു രൂപവും സ്വീകരിക്കാൻ കഴിയുന്ന ലങ്ക വീണ്ടും കഠിനവാക്കുകൾ പറഞ്ഞു:",
        "0.35": "“മൂഢാ, വാനരരിൽ അധമനേ, എന്നെ തോൽപ്പിക്കാതെ, രാക്ഷസപ്രഭു ഭരിക്കുന്ന ഈ നഗരം നിനക്ക് ഇന്ന് കാണാനാവില്ല.”",
        "0.36": "അപ്പോൾ വാനരവ്യാഘ്രം രാത്രിസഞ്ചാരിയോട് പറഞ്ഞു: “നല്ല സ്ത്രീയേ, ഈ നഗരം കണ്ട ശേഷം ഞാൻ വന്ന വഴിയിലേക്ക് മടങ്ങിപ്പോകാം.”",
        "0.37": "അപ്പോൾ ലങ്ക ഭയങ്കര ഗർജ്ജനത്തോടെ, തന്റെ കൈപ്പത്തികൊണ്ട് ഉത്തമ വാനരനെ വേഗത്തിൽ അടിച്ചു.",
        "0.38": "ലങ്കയുടെ കഠിനപ്രഹരമേറ്റ്, വായുപുത്രനായ ധീരനായ വാനരവ്യാഘ്രം ഉച്ചത്തിൽ ഗർജ്ജിച്ചു.",
        "0.39": "അപ്പോൾ കോപം കൊണ്ട് നിറഞ്ഞ ഹനുമാൻ ഇടതുകൈയുടെ വിരലുകൾ മുറുക്കി, അവളെ മുഷ്ടികൊണ്ട് ഇടിച്ചു.",
        "0.40": "“ഇവൾ ഒരു സ്ത്രീയാണ്” എന്ന് കരുതി അദ്ദേഹം കോപം അടക്കി; എങ്കിലും ആ പ്രഹരമേറ്റ്, വികൃതമായ രാത്രിസഞ്ചാരി, അവയവങ്ങൾ കുലുങ്ങി, പെട്ടെന്ന് നിലത്തു വീണു.",
        "0.41": "അവൾ വീണുകിടക്കുന്നത് കണ്ട തേജസ്വിയായ വീരൻ ഹനുമാന്, അവൾ ഒരു സ്ത്രീയാണെന്ന് ചിന്തിച്ച് അനുകമ്പ തോന്നി.",
        "0.42": "പിന്നെ അത്യന്തം കുലുങ്ങിയ ലങ്ക, അഭിമാനം നഷ്ടപ്പെട്ട്, ഇടറുന്ന സ്വരത്തിൽ വാനരനായ ഹനുമാനോട് പറഞ്ഞു:",
        "0.43": "“കരുണ കാണിക്കൂ, ബലവാനായ ബാഹുവുള്ളവനേ; വാനരശ്രേഷ്ഠാ, എന്നെ വെറുതെ വിടൂ. സൗമ്യനേ, ശക്തരും വീരന്മാരുമായവർ മാന്യതയുടെ നിയമങ്ങൾ പാലിക്കുന്നു.",
        "0.44": "വാനരാ, ഞാൻ തന്നെ ലങ്കാനഗരം; ഹേ മഹാവീരാ, നിന്റെ വീര്യത്താൽ ഞാൻ കീഴടക്കപ്പെട്ടിരിക്കുന്നു.",
        "0.45": "വാനരപ്രഭോ, എന്നിൽ നിന്ന് ഈ സത്യം കേൾക്കൂ — സ്വയംഭൂ തന്നെ പണ്ട് എനിക്ക് നൽകിയ വരം:",
        "0.46": "‘ഏതെങ്കിലും വാനരൻ തന്റെ പരാക്രമത്താൽ നിന്നെ കീഴടക്കുമ്പോൾ, അപ്പോൾ രാക്ഷസർക്ക് ആപത്ത് വന്നെത്തിയെന്ന് അറിയണം.’",
        "0.47": "ആ നിശ്ചിത സമയം, സൗമ്യനേ, നിന്റെ വരവോടെ ഇന്ന് വന്നെത്തിയിരിക്കുന്നു; സ്വയംഭൂവിനാൽ നിശ്ചയിക്കപ്പെട്ടത് ഇത് സത്യമാണ്, മാറ്റാനാവില്ല.",
        "0.48": "സീത കാരണം, ദുഷ്ടനായ രാജാവ് രാവണനും എല്ലാ രാക്ഷസർക്കും നാശം വന്നെത്തിയിരിക്കുന്നു.",
        "0.49": "അതിനാൽ, ഉത്തമ വാനരാ, രാവണൻ ഭരിക്കുന്ന നഗരത്തിൽ പ്രവേശിക്കൂ; ഇവിടെ നീ ആഗ്രഹിക്കുന്ന കർമ്മങ്ങൾ നിർവ്വഹിക്കൂ.",
        "0.50": "വാനരപ്രഭോ, രാക്ഷസപ്രമുഖൻ ഭരിക്കുന്നതും ശാപമേറ്റതുമായ ഈ മനോഹരനഗരത്തിൽ പ്രവേശിക്കൂ; സ്വതന്ത്രമായി എവിടെയും സഞ്ചരിച്ച്, ജനകന്റെ സദ്ഗുണവതിയായ പുത്രിയെ നിനക്കിഷ്ടമുള്ളതുപോലെ അന്വേഷിച്ചുകൊള്ളൂ.”",
        "0.51": "ഇങ്ങനെ, വാൽമീകിയുടെ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ മൂന്നാം സർഗ്ഗം സമാപിച്ചു — മുനിയുടെ ആദ്യകാവ്യം."
      },
      "summary": "ഹനുമാൻ രാത്രിയിൽ നഗരകവാടത്തെ സമീപിക്കുമ്പോൾ, നഗരത്തിന്റെ കാവൽദേവതയായ ലങ്ക അദ്ദേഹത്തെ തടഞ്ഞ് പ്രഹരിക്കുന്നു. മുഷ്ടിപ്രഹരത്താൽ അവളെ വീഴ്ത്തുന്നു; വാനരനാൽ അവളുടെ പരാജയം രാക്ഷസരുടെ അന്ത്യത്തിന്റെ അടയാളമായിരിക്കുമെന്ന ബ്രഹ്മാവിന്റെ വാക്ക് ഓർത്ത്, അവൾ അദ്ദേഹത്തെ പ്രവേശിക്കാൻ അനുവദിക്കുന്നു."
    },
    "sundarakanda-04": {
      "verses": {
        "0.0": "ഏതു രൂപവും സ്വീകരിക്കാൻ കഴിവുള്ള ആ ഉത്തമ ലങ്കയെ തന്റെ വീര്യത്താൽ കീഴടക്കിയ തേജസ്വിയായ ഹനുമാൻ, വാനരശ്രേഷ്ഠൻ,",
        "0.1": "ബലശാലി ഗോപുരത്തിലൂടെയല്ല, മതിൽ ചാടിക്കടന്നു; രാത്രിയിൽ ആ മഹാമനസ്കനായ വാനരഗജൻ ലങ്കയിൽ പ്രവേശിച്ചു.",
        "0.2": "വാനരരാജാവിന്റെ സുഹൃത്തായ അദ്ദേഹം ലങ്കാനഗരത്തിൽ പ്രവേശിച്ചപ്പോൾ, ശത്രുക്കളുടെ തലകളിൽ ഇടതുകാൽ വെച്ചതുപോലെ തോന്നി.",
        "0.3": "രാത്രിയിൽ പ്രവേശിച്ച ധൈര്യമുള്ള വായുപുത്രൻ, ചിതറിക്കിടക്കുന്ന പൂക്കളാൽ തിളങ്ങുന്ന വലിയ രാജവീഥി സ്വീകരിച്ചു.",
        "0.4": "ചിരിയും ഉച്ചത്തിലുള്ള ആരവങ്ങളും സംഗീതശബ്ദവും നിറഞ്ഞ ആ മനോഹര ലങ്കാനഗരത്തിലൂടെ അദ്ദേഹം സഞ്ചരിച്ചു.",
        "0.5": "വജ്രവും അങ്കുശവും ചിഹ്നങ്ങളുള്ള, വജ്രജാലകങ്ങളാൽ അലങ്കരിക്കപ്പെട്ട, മേഘസമാനമായ മാളികകളോടെ നഗരം മേഘങ്ങളുള്ള ആകാശംപോലെ തിളങ്ങി.",
        "0.6": "താമരയും സ്വസ്തികവും ചേർന്ന രൂപങ്ങളിൽ പണിതതും, വെള്ള മേഘംപോലെ പലനിറമുള്ളതുമായ രാക്ഷസന്മാരുടെ തിളങ്ങുന്ന മാളികകളാൽ ലങ്ക പ്രകാശിച്ചു.",
        "0.7": "എല്ലാ വശങ്ങളിലും നന്നായി അലങ്കരിക്കപ്പെട്ട ‘വർദ്ധമാനം’ എന്ന മാളികകളോടെ; പലനിറമുള്ള മാലകളും ആഭരണങ്ങളും അണിഞ്ഞ ആ നഗരം, വാനരരാജാവിന്റെ സുഹൃത്ത്,",
        "0.8": "രാഘവന്റെ കാര്യത്തിനായി സഞ്ചരിച്ചുകൊണ്ട് കണ്ടു, സന്തോഷിച്ചു. ഓരോ വീടും സന്ദർശിച്ച് ആ വാനരഗജൻ കണ്ടു:",
        "0.9": "പലതരം രൂപങ്ങളിലും ആകൃതികളിലും ഉള്ള മാളികകൾ പലയിടത്തും. മൂന്നു സ്വരസ്ഥാനങ്ങളിൽ സ്വരം ചേർത്ത മധുരഗാനം അദ്ദേഹം കേട്ടു;",
        "0.10": "സ്വർഗ്ഗത്തിലെ അപ്സരസ്സുകളെപ്പോലെ പ്രേമബദ്ധരായ സ്ത്രീകൾ പാടുന്നത്. അരഞ്ഞാണങ്ങളുടെയും കണങ്കാൽ തളകളുടെയും കിലുക്കം കേട്ടു;",
        "0.11": "വലിയവരുടെ മാളികകളിലെ പടവുകളിൽ കാൽപ്പെരുമാറ്റവും, ഇവിടെയും അവിടെയും തോളിൽ തട്ടുന്ന ശബ്ദവും ഉച്ചത്തിലുള്ള ആക്രോശങ്ങളും.",
        "0.12": "രാക്ഷസരുടെ ഭവനങ്ങളിൽ ചിലർ മന്ത്രം ചൊല്ലുന്നത് കേട്ടു; വേദപാരായണത്തിൽ മുഴുകിയ യാതുധാനന്മാരെയും കണ്ടു;",
        "0.13": "രാവണനെ സ്തുതിച്ചുകൊണ്ട് സ്തോത്രങ്ങൾ ഗർജ്ജിക്കുന്ന രാക്ഷസന്മാരെയും കണ്ടു. രാജവീഥി കൈയടക്കിയ വലിയ രാക്ഷസസൈന്യത്തെയും കണ്ടു.",
        "0.14": "മധ്യകാവൽപ്പുരയിൽ രാക്ഷസരാജാവിന്റെ അനേകം ചാരന്മാരെ കണ്ടു — ചിലർ വ്രതമെടുത്തവർ, ചിലർ ജടമുടിയുള്ളവർ, ചിലർ മുണ്ഡനം ചെയ്തവർ, ചിലർ പശുത്തോൽ ധരിച്ചവർ;",
        "0.15": "ചിലർ ദർഭപ്പുല്ലിന്റെ പിടികളോ അഗ്നിപാത്രങ്ങളോ ആയുധമാക്കിയവർ, ചിലർ കൈയിൽ ചുറ്റികയും ഗദയുമേന്തിയവർ, ദണ്ഡധാരികളും;",
        "0.16": "ഒറ്റക്കണ്ണുള്ളവരും അനേകം ചെവിയുള്ളവരും, തൂങ്ങുന്ന വയറും സ്തനങ്ങളുമുള്ളവരും, ഭയങ്കരരും, വക്രമുഖരും, വിരൂപരും, കുള്ളന്മാരും;",
        "0.17": "വില്ലാളികളും വാൾപ്പടയാളികളും, ശതഘ്നികളും ഉലക്കകളും ആയുധമാക്കിയവരും, സൂക്ഷ്മമായ ഇരുമ്പുദണ്ഡുകൾ പിടിച്ചവരും, വിവിധവർണ്ണ കവചങ്ങളിൽ തിളങ്ങുന്നവരും;",
        "0.18": "അധികം തടിച്ചവരോ മെലിഞ്ഞവരോ അല്ലാത്തവർ, അധികം ഉയരമുള്ളവരോ കുള്ളന്മാരോ അല്ലാത്തവർ, അധികം വെളുത്തവരോ കറുത്തവരോ അല്ലാത്തവർ, കൂനന്മാരോ കുള്ളന്മാരോ അല്ലാത്തവർ;",
        "0.19": "വിരൂപരും പലരൂപമുള്ളവരും, സുന്ദരരും തിളങ്ങുന്നവരും, പതാകകളും കൊടികളും പലതരം ആയുധങ്ങളും വഹിക്കുന്നവർ;",
        "0.20": "കുന്തങ്ങളും വൃക്ഷങ്ങളുമേന്തിയവരെയും, പട്ടിശവും വജ്രവും വഹിക്കുന്നവരെയും, കവണയും കുടുക്കും കൈയിൽ പിടിച്ചവരെയും ആ വാനരൻ കണ്ടു.",
        "0.21": "പലരും മാലകളും ലേപനങ്ങളും മനോഹരമായ ആഭരണങ്ങളും അണിഞ്ഞിരുന്നു; പലവിധത്തിൽ വസ്ത്രം ധരിച്ച്, ഇഷ്ടം പോലെ സഞ്ചരിക്കുന്നവർ;",
        "0.22": "ശക്തരായവർ മൂർച്ചയുള്ള കുന്തങ്ങളും വജ്രങ്ങളും വഹിച്ചു. ഒരു ലക്ഷം പേരടങ്ങിയ മധ്യകാവൽപ്പടയെ, ജാഗ്രതയോടെ ഉറച്ചുനിൽക്കുന്നത് വാനരൻ കണ്ടു.",
        "0.23": "രാക്ഷസരാജാവ് അന്തഃപുരത്തിനു മുന്നിൽ നിയോഗിച്ചവർ. പിന്നെ സ്വർണ്ണത്തിന്റെ മനോഹര കമാനങ്ങളുള്ള ആ കൊട്ടാരം കണ്ട്,",
        "0.24": "രാക്ഷസരാജാവിന്റെ പ്രസിദ്ധമായ കൊട്ടാരം, പർവതശിഖരത്തിൽ സ്ഥാപിതമായത്, വെള്ളത്താമരകൾ അലങ്കരിച്ച കിടങ്ങുകളാൽ ചുറ്റപ്പെട്ടത്,",
        "0.25": "ഉയർന്ന മതിലിനാൽ ചുറ്റപ്പെട്ട — ആ മഹാവാനരൻ അതിനെ കണ്ടു; സ്വർഗ്ഗംപോലെ ദിവ്യമായി, ദിവ്യശബ്ദങ്ങൾ മുഴങ്ങുന്നതായി;",
        "0.26": "കുതിരകളുടെ ഹേഷാരവങ്ങളും ആഭരണങ്ങളുടെ കിലുക്കവും പ്രതിധ്വനിക്കുന്നതായി; രഥങ്ങളും വണ്ടികളും ആകാശവാഹനങ്ങളും മികച്ച കുതിരകളും ആനകളും ഉള്ളതായി;",
        "0.27": "വെള്ള മേഘക്കൂട്ടംപോലെ നാലു കൊമ്പുള്ള ആനകളോടെ, മനോഹരമായ കവാടങ്ങൾ അലങ്കരിക്കപ്പെട്ടതായി, ഉത്സാഹഭരിതമായ മൃഗങ്ങളും പക്ഷികളും ഉള്ളതായി;",
        "0.28": "ആയിരക്കണക്കിന് ശക്തരായ യാതുധാനന്മാർ കാക്കുന്നത് — ആ വാനരൻ രാക്ഷസപ്രഭുവിന്റെ സംരക്ഷിത കൊട്ടാരത്തിൽ പ്രവേശിച്ചു.",
        "0.29": "സ്വർണ്ണം വലയം ചെയ്ത, ഉള്ളിൽ വിലയേറിയ മുത്തുകളും രത്നങ്ങളും കൊണ്ട് അലങ്കരിക്കപ്പെട്ട, വിലപ്പെട്ട കറുത്ത അകിലിന്റെയും ചന്ദനത്തിന്റെയും സുഗന്ധം നിറഞ്ഞ രാവണന്റെ അന്തഃപുരത്തിൽ അദ്ദേഹം പ്രവേശിച്ചു.",
        "0.30": "ഇങ്ങനെ, വാൽമീകിയുടെ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ നാലാം സർഗ്ഗം സമാപിച്ചു — മുനിയുടെ ആദ്യകാവ്യം."
      },
      "summary": "ഹനുമാൻ ലങ്കയിൽ പ്രവേശിച്ച് അതിന്റെ വീഥികളിലൂടെ സഞ്ചരിക്കുന്നു; മഹാമന്ദിരങ്ങളും സംഗീതവും ഉത്സവവും, എല്ലാത്തരം ആയുധങ്ങളുമേന്തിയ പലതരം രാക്ഷസന്മാരും കാണുന്നു. കാവൽക്കാരെ കടന്ന് രാവണന്റെ അന്തഃപുരത്തിലേക്ക് അദ്ദേഹം വഴി കണ്ടെത്തുന്നു."
    },
    "sundarakanda-05": {
      "verses": {
        "0.0": "അപ്പോൾ ബുദ്ധിമാനായ വാനരൻ, ആകാശമധ്യത്തിൽ തിളങ്ങുന്ന ചന്ദ്രനെ കണ്ടു — പശുത്തൊഴുത്തിൽ മദിച്ചു നടക്കുന്ന കാളയെപ്പോലെ, ഭൂമിയിൽ വീണ്ടും വീണ്ടും നിലാവിന്റെ മേലാപ്പ് ചൊരിഞ്ഞുകൊണ്ട്.",
        "0.1": "തണുത്ത രശ്മികളുള്ള ചന്ദ്രൻ ലോകത്തിന്റെ പാപം നീക്കി, മഹാസമുദ്രത്തെ ഉയർത്തി, എല്ലാ ജീവികളെയും പ്രകാശിപ്പിച്ചുകൊണ്ട് മുന്നോട്ടു വരുന്നതായി അദ്ദേഹം കണ്ടു.",
        "0.2": "മന്ദരപർവതത്തിലും, സന്ധ്യയിൽ സമുദ്രത്തിലും, താമരയിലെ ജലത്തിലും ഭൂമിയിൽ തിളങ്ങുന്ന ആ പ്രഭ, മനോഹരമായ ചന്ദ്രനിലും തിളങ്ങി.",
        "0.3": "വെള്ളിക്കൂട്ടിലെ അരയന്നംപോലെ, മന്ദരപർവതത്തിലെ ഗുഹയിലെ സിംഹംപോലെ, അഹങ്കാരമുള്ള ആനപ്പുറത്തെ വീരനെപ്പോലെ, ആകാശത്ത് ചന്ദ്രൻ തിളങ്ങി.",
        "0.4": "പൂർണ്ണകൊമ്പുകളോടെ ചന്ദ്രൻ, മൂർച്ചയുള്ള കൊമ്പുള്ള നിൽക്കുന്ന കാളയെപ്പോലെയും, ഉയർന്ന ശിഖരങ്ങളുള്ള മഹാവെള്ളിമലപോലെയും, സ്വർണ്ണം പൊതിഞ്ഞ കൊമ്പുകളുള്ള ആനപോലെയും തിളങ്ങി.",
        "0.5": "തണുത്ത മൂടൽമഞ്ഞിന്റെയും മഞ്ഞിന്റെയും ചെളിയിൽ നിന്ന് മുക്തനായി, മഹാഗ്രഹത്തിന്റെ പിടിയുടെ കറയില്ലാതെ, മനോഹരമായ തേജസ്സിന്റെ ഇരിപ്പിടമെന്നപോലെ തന്റെ അടയാളം ശുദ്ധമാക്കി, മുയൽ-അടയാളമുള്ള ഭാഗ്യവാൻ ചന്ദ്രൻ പ്രകാശിച്ചു.",
        "0.6": "പാറപ്പുറത്ത് സിംഹം തിളങ്ങുന്നതുപോലെ, മഹാവനത്തിലെ ഉന്നത ആനപോലെ, രാജ്യം നേടിയ രാജാവുപോലെ, ചന്ദ്രൻ തന്റെ പ്രഭയിൽ തിളങ്ങി.",
        "0.7": "ഭാഗ്യകരമായ സന്ധ്യ സ്വർഗ്ഗംപോലെ തിളങ്ങി — ചന്ദ്രോദയത്തിന്റെ ശോഭയാൽ അതിന്റെ ഇരുട്ട് അകന്നിരുന്നു; മാംസഭോജികളായ രാക്ഷസരുടെ ദുഷ്ടത വർദ്ധിച്ചു; പ്രണയികളുടെ ഹൃദയങ്ങൾ പ്രിയരാൽ ഇളകി.",
        "0.8": "ചെവിക്കിമ്പമുള്ള വീണാനാദം തുടങ്ങി; ഉത്തമ സ്ത്രീകൾ ഭർത്താക്കന്മാരുടെ അരികിൽ ഉറങ്ങി; ഏറ്റവും ഭയങ്കരമായ നടപ്പുള്ള രാത്രിസഞ്ചാരികൾ സഞ്ചരിക്കാൻ പുറപ്പെട്ടു.",
        "0.9": "മദ്യപരും അശ്രദ്ധരുമായവരാൽ നിറഞ്ഞ, രഥങ്ങളും കുതിരകളും ഉത്തമ ഇരിപ്പിടങ്ങളും കൊണ്ട് തിങ്ങിയ, സൈനികമഹിമയാൽ നിറഞ്ഞ ഭവനങ്ങൾ ബുദ്ധിമാനായ വാനരൻ കണ്ടു.",
        "0.10": "അവർ പരസ്പരം കഠിനമായി പരിഹസിച്ചു, കരുത്തുള്ള ബാഹുക്കൾ വീശി, മദ്യലഹരിയിലുള്ള ജൽപനം ചൊരിഞ്ഞു; മദ്യപർ പരസ്പരം ശകാരിച്ചു.",
        "0.11": "രാക്ഷസന്മാർ നെഞ്ച് വിരിച്ചു, പ്രിയമാരുടെ മേൽ കൈകാലുകൾ എറിഞ്ഞു, പലവിധ രൂപങ്ങൾ സ്വീകരിച്ചു, ശക്തമായ വില്ലുകൾ വലിച്ചു.",
        "0.12": "ലേപനം പുരട്ടുന്ന സ്ത്രീകളെയും, ഉറങ്ങുന്നവരെയും, മനോഹരമുഖങ്ങളോടെ ചിരിക്കുന്ന ചിലരെയും, കോപത്താൽ നെടുവീർപ്പിടുന്ന മറ്റു ചിലരെയും അദ്ദേഹം കണ്ടു.",
        "0.13": "കോലാഹലമിടുന്ന വലിയ ആനകളോടും, ബഹുമാനിക്കപ്പെട്ട പ്രഭുക്കന്മാരോടും, ദീർഘനിശ്വാസമിടുന്ന വീരന്മാരോടും കൂടി, ചീറ്റുന്ന സർപ്പങ്ങളുള്ള തടാകംപോലെ നഗരം തിളങ്ങി.",
        "0.14": "ആ നഗരത്തിൽ, ബുദ്ധിമാന്മാരും വാചാലരുമായ, വിശ്വാസികളും ലോകനേതാക്കളും, വിവിധതരക്കാരും മനോഹര നാമങ്ങളുള്ളവരുമായ യാതുധാനന്മാരെ അദ്ദേഹം കണ്ടു.",
        "0.15": "അവർ സുന്ദരരും, അവരുടെ പ്രകൃതിക്ക് യോജിച്ച അനേകം ഗുണങ്ങളുള്ളവരും, തിളക്കമുള്ളവരും വെളുത്തവരുമായിരിക്കുന്നതു കണ്ട് അദ്ദേഹം സന്തോഷിച്ചു; വിരൂപരായ ചിലരെയും അദ്ദേഹം കണ്ടു.",
        "0.16": "പിന്നെ അവിടത്തെ സ്ത്രീകളെ അദ്ദേഹം കണ്ടു — ഉത്തമർക്ക് യോഗ്യരായവർ, ശുദ്ധഹൃദയർ, കുലീനർ, തങ്ങളുടെ പ്രിയന്മാരോടും മദ്യത്തോടും ഭക്തിയുള്ളവർ, നല്ല സ്വഭാവമുള്ളവർ, നക്ഷത്രങ്ങൾപോലെ.",
        "0.17": "ലജ്ജയാൽ മറഞ്ഞിരുന്നാലും തിളങ്ങുന്ന സ്ത്രീകളെ, അർദ്ധരാത്രിയിൽ തങ്ങളുടെ കാമുകന്മാരാൽ ആലിംഗനം ചെയ്യപ്പെട്ടവരെ, ചിലർ സ്ത്രീകളാൽ ആലിംഗനം ചെയ്യപ്പെട്ടവരെ — പക്ഷികളെ പക്ഷികൾ ചേർത്തുപിടിക്കുന്നതുപോലെ.",
        "0.18": "മറ്റു ചിലർ മാളികയുടെ മട്ടുപ്പാവുകളിൽ ഇരുന്ന്, പ്രിയന്മാരുടെ മടിയിൽ സുഖമായി ചാരിക്കിടന്നു; ഭർത്താക്കന്മാരോടും ധർമ്മത്തോടും ഭക്തിയുള്ള മറ്റു ചിലരെ, പ്രണയം ബാധിച്ചവരായി ബുദ്ധിമാനായവൻ കണ്ടു.",
        "0.19": "ചിലർ മൂടുപടമില്ലാതെ, സ്വർണ്ണരേഖകളുടെ നിറമുള്ളവരായിരുന്നു; ചിലർ വിലയേറിയവരും ശുദ്ധസ്വർണ്ണത്തിന്റെ നിറമുള്ളവരും; പ്രിയന്മാരിൽ നിന്ന് വേർപിരിഞ്ഞ ചിലർ, അംഗങ്ങളിൽ മനോഹരമായിരുന്നെങ്കിലും ചന്ദ്രനെപ്പോലെ വിളറിയിരുന്നു.",
        "0.20": "പിന്നെ വാനരശ്രേഷ്ഠൻ തങ്ങളുടെ വീടുകളിൽ മനോഹര സ്ത്രീകളെ കണ്ടു — ഹൃദയത്തിനിഷ്ടമായ പ്രിയന്മാരെ നേടിയതിൽ സന്തുഷ്ടരും, സ്നേഹവും നല്ല സന്തോഷവും നിറഞ്ഞവരുമായി.",
        "0.21": "ചന്ദ്രപ്രഭയുള്ള മുഖങ്ങളുടെ നിരകളും, വളഞ്ഞതും നീണ്ട കണ്ണിമകളുള്ളതുമായ മനോഹര കണ്ണുകളുടെ നിരകളും, മിന്നൽമാലകൾപോലെ മനോഹരമായ ആഭരണങ്ങളുടെ നിരകളും അദ്ദേഹം കണ്ടു.",
        "0.22": "എന്നാൽ അദ്ദേഹം സീതയെ കണ്ടില്ല — അത്യുത്കൃഷ്ട കുലത്തിൽ ജനിച്ചവൾ, ശരിയായ വഴി പാലിക്കുന്ന രാജകുലത്തിൽ പിറന്നവൾ, നന്നായി വളർന്ന പൂവിടുന്ന വള്ളിപോലെ മെലിഞ്ഞവൾ, മനസ്സിൽ ജനിച്ചവൾ.",
        "0.23": "ശാശ്വത മാർഗ്ഗം പാലിക്കുന്നവൾ, കണ്ണുകൾ രാമനിൽ ഉറപ്പിച്ചവൾ, അദ്ദേഹത്തോടുള്ള സ്നേഹത്താൽ നിറഞ്ഞവൾ, ഭർത്താവിന്റെ മഹത്തായ ഹൃദയത്തിൽ പ്രവേശിച്ചവൾ, മറ്റെല്ലാ സ്ത്രീകൾക്കും മീതെ എപ്പോഴും വേറിട്ടു നിൽക്കുന്നവൾ —",
        "0.24": "ദുഃഖത്തിന്റെ ചൂടിൽ വേദനിച്ചവൾ, കണ്ണീരിനാൽ തൊണ്ട ഇടറിയവൾ, ഒരിക്കൽ വിലയേറിയ മാല ധരിച്ചവൾ, മനോഹര കൺപീലികളും മധുരസ്വരവുമുള്ളവൾ, കാട്ടിൽ നൃത്തം ചെയ്യുന്ന മയിൽപ്പിടപോലെ —",
        "0.25": "മങ്ങിയ രൂപരേഖയുള്ള ഇളംചന്ദ്രക്കല പോലെ, പൊടി പുരണ്ട സ്വർണ്ണരേഖ പോലെ, സുഖപ്പെട്ട മുറിവിന്റെ പാടുപോലെ, കാറ്റാൽ വളഞ്ഞ മേഘനിര പോലെ —",
        "0.26": "മനുഷ്യരുടെ നാഥനും വാഗ്മികളിൽ ഉത്തമനുമായ രാമന്റെ ഭാര്യ സീതയെ കാണാതെ, വാനരൻ വളരെനേരം ദുഃഖത്താൽ പീഡിതനായി, പെട്ടെന്ന് മങ്ങിയതുപോലെ നിന്നു.",
        "0.27": "ഇങ്ങനെ, വാൽമീകിയുടെ ശ്രീമദ് രാമായണത്തിലെ സുന്ദരകാണ്ഡത്തിലെ അഞ്ചാം സർഗ്ഗം സമാപിച്ചു — മുനിയുടെ ആദ്യകാവ്യം."
      },
      "summary": "പൂർണ്ണചന്ദ്രൻ ലങ്കയുടെ മുകളിൽ പ്രകാശിക്കുന്നതായി കവി വർണ്ണിക്കുന്നു. ഹനുമാൻ വീടുതോറും തിരയുന്നു; രാക്ഷസന്മാരെയും അവരുടെ സ്ത്രീകളെയും സുഖമായി കഴിയുന്നവരായി കാണുന്നു, എന്നാൽ സീതയെ എവിടെയും കണ്ടെത്താതെ ദുഃഖിതനാകുന്നു."
    }
  },
};
